/** Name of engine
 *  @type {string}
 *  @default
 *  @memberof Engine */
const engineName = 'LittleJS';

/** Version of engine
 *  @type {string}
 *  @default
 *  @memberof Engine */
const engineVersion = '1.25.0';

/** Frames per second to update
 *  @type {number}
 *  @default
 *  @memberof Engine */
const frameRate = 60;

/** How many seconds the update covers: 1/60 with the fixed time step, or with engineVariableStep the time of the
 *  display frame it runs on, times timeScale; while paused it keeps the last update's
 *  @type {number}
 *  @default 1/60
 *  @memberof Engine */
let timeDelta = 1/frameRate;

/** Array containing all engine objects
 *  @type {Array<EngineObject>}
 *  @memberof Engine */
let engineObjects = [];

/** Array with only objects set to collide with other objects this frame (for optimization)
 *  @type {Array<EngineObject>}
 *  @memberof Engine */
let engineObjectsCollide = [];

// the same objects with the static ones last, the order 2D physics checks them in
let engineObjectsCollideStaticLast = [];

/** Current update frame, used to calculate time
 *  @type {number}
 *  @memberof Engine */
let frame = 0;

/** Current engine time since start in seconds
 *  @type {number}
 *  @memberof Engine */
let time = 0;

/** Actual clock time since start in seconds (not affected by pause, timescale, or frame rate clamping; the debug speed keys scale it in debug builds)
 *  @type {number}
 *  @memberof Engine */
let timeReal = 0;

/** Is the game paused? Causes time and objects to not be updated
 *  @type {boolean}
 *  @default false
 *  @memberof Engine */
let paused = false;

/** Get if game is paused
 *  @return {boolean}
 *  @memberof Engine */
function getPaused() { return paused; }

/** Set if game is paused
 *  @param {boolean} [isPaused]
 *  @memberof Engine */
function setPaused(isPaused=true) { paused = isPaused; }

// Engine internal variables
let frameTimeLastMS = 0, frameTimeBufferMS = 0, averageFPS = 0;

// delta smoothing, after Time Delta Smoothing by Frank Force (2013): a frame is on screen for whole display frames,
// so each delta is rounded to them and the rest is carried to the next, keeping the total real time; the frame
// length is estimated from recent frames and kept internal, since the browser does not say what it is
const frameDeltaHistory = [];
let frameIntervalMS = 1e3 / 60, frameDeltaCarryMS = 0, frameDeltaCarryAverageMS = 0, frameDeltaSmoothing = true;
function engineSmoothDelta(deltaMS)
{
    if (!(deltaMS > 0)) return 0;
    if (deltaMS < 250) // a gap from a hidden tab is not a display frame
    {
        frameDeltaHistory.push(deltaMS);
        frameDeltaHistory.length > 64 && frameDeltaHistory.shift();

        // the frames each delta held are counted in the last estimate or in the lower quartile of the last 16,
        // whichever the deltas fit better: the quartile is one frame even when a busy game misses most of them, and
        // it takes over when the window moves to a display with another refresh rate, or the estimate went wrong
        const recent = frameDeltaHistory.slice(-16).sort((a, b)=> a - b);
        const [lastMS, lastOff] = engineFrameFit(frameIntervalMS);
        const [quartileMS, quartileOff] = engineFrameFit(recent[recent.length >> 2]);
        frameIntervalMS = lastOff <= quartileOff ? lastMS : quartileMS;

        // deltas far from whole frames mean the display has no fixed refresh, with a margin so it does not flip
        frameDeltaSmoothing = min(lastOff, quartileOff) < (frameDeltaSmoothing ? .2 : .12);
    }

    if (!frameDeltaSmoothing)
    {
        // deltas that are not whole frames of one length, like a variable refresh display, are the frame times
        // as they are, with any carry paid, and smoothing starts over once they fit again
        const rawMS = deltaMS + frameDeltaCarryMS;
        frameDeltaCarryMS = min(rawMS, 0);
        frameDeltaCarryAverageMS = 0;
        return max(rawMS, 0);
    }

    // whole frames, 0 for one that came early or 2 after one was missed, the carry stays within half a frame; a
    // little of its slow average is paid each frame, so jitter can not hold it at half a frame and flip every frame
    const pullMS = frameDeltaCarryAverageMS / 32;
    frameDeltaCarryMS += deltaMS;
    const frames = round((frameDeltaCarryMS - pullMS) / frameIntervalMS);
    if (frames < 1)
        return 0; // the carry keeps it
    const smoothMS = frames * frameIntervalMS + pullMS;
    frameDeltaCarryMS -= smoothMS;
    frameDeltaCarryAverageMS += (frameDeltaCarryMS - frameDeltaCarryAverageMS) / 32;
    return smoothMS;
}

// fit the delta history as whole frames of about unitMS: the frame length is the least squares slope of time over
// frames held, so jitter and whole ms timestamps average out, with how far the deltas are from whole frames
function engineFrameFit(unitMS)
{
    let timeMS = 0, frames = 0, offMS = 0, sumF = 0, sumT = 0, sumFF = 0, sumFT = 0;
    const count = frameDeltaHistory.length;
    for (const d of frameDeltaHistory)
    {
        const held = max(1, round(d / unitMS));
        timeMS += d;
        frames += held;
        offMS += abs(d - held * unitMS);
        sumF += frames, sumT += timeMS, sumFF += frames * frames, sumFT += frames * timeMS;
    }
    const spread = count * sumFF - sumF * sumF;
    return [spread ? (count * sumFT - sumF * sumT) / spread : unitMS, offMS / count / unitMS];
}

// where the fixed step's time counts from, moved when the variable step hands back so time goes on from there
let timeFixedStart = 0, frameFixedStart = 0;
let windowWidthLast = 0, windowHeightLast = 0, windowPixelRatioLast = 0;
let engineUpdateInternal; // assigned by engineInit so engineStep can drive it
let engineFrameScheduled = false; // a frame of the loop is asked for and has not run yet
let engineFrameErrorLast; // the last error a release build's loop went on past, as text

// the pairs of objects asked about a collision this update, so the other's own physics does not ask again: each
// asker's others, with true for a pair both said to resolve, and false for one left overlapping, ignored or only
// nudged apart; a map for each asker so the lookup stays quick when many objects pile up on one spot
const engineObjectsCollidePairs = new Map;
function engineObjectsCollidePairAnswer(asker, other)
{ return engineObjectsCollidePairs.get(asker)?.get(other); }
function engineObjectsCollidePairAdd(asker, other, resolve=false)
{
    let others = engineObjectsCollidePairs.get(asker);
    others || engineObjectsCollidePairs.set(asker, others = new Map);
    others.set(other, resolve);
}
let engineInitialized = false; // engineInit ran, with or without a canvas
// the loads startup waits for, each counted for the loading screen, and how many are done; undefined once the game
// loop starts
let engineLoads, engineLoadsDone = 0;
let engineObjectsUpdateCount = 0; // passes of engineObjectsUpdate so far, how a child knows it moved this pass
const engineChildStack = []; // the children being updated, taken off the live lists so one leaving does not skip the next
let showEngineVersion = true;

///////////////////////////////////////////////////////////////////////////////
// plugin hooks

const pluginList = [];
class EnginePlugin
{
    constructor(update, render, glContextLost, glContextRestored, preRender)
    {
        this.update = update;
        this.render = render;
        this.glContextLost = glContextLost;
        this.glContextRestored = glContextRestored;
        this.preRender = preRender;
    }
}

/**
 * @callback PluginCallback - Update or render function for a plugin
 * @memberof Engine
 */

/** Add a new update function for a plugin
 *  - update runs on every fixed tick, paused and timeScale 0 included; a plugin that simulates should skip those
 *  @param {PluginCallback} [update]
 *  @param {PluginCallback} [render]
 *  @param {PluginCallback} [glContextLost]
 *  @param {PluginCallback} [glContextRestored]
 *  @param {PluginCallback} [preRender] - Called after the canvas is cleared and before gameRender
 *  @memberof Engine */
function engineAddPlugin(update, render, glContextLost, glContextRestored, preRender)
{
    // make sure plugin functions are unique
    ASSERT(!pluginList.find(p=>
        p.update === update && p.render === render &&
        p.glContextLost === glContextLost &&
        p.glContextRestored === glContextRestored &&
        p.preRender === preRender));

    const plugin = new EnginePlugin(update, render, glContextLost, glContextRestored, preRender);
    pluginList.push(plugin);
}

///////////////////////////////////////////////////////////////////////////////
// Main Engine Functions

/** Add something the game loads to what startup waits for: while engineInit and gameInit run, the game loop starts
 *  once it is done, and the loading screen counts it; images from loadTexture and sounds from files are added on
 *  their own, and a load that fails counts as done; after startup it does nothing
 *  @param {Promise<any>} promise
 *  @return {Promise<any>} - The same promise
 *  @example
 *  async function gameInit() { level = await engineAddLoad(fetchJSON('level.json')); }
 *  @memberof Engine */
function engineAddLoad(promise)
{
    if (engineLoads)
    {
        engineLoads.push(promise);
        const done = ()=> { ++engineLoadsDone; };
        promise.then(done, done);
    }
    return promise;
}

// wait for every load, the ones added while waiting too, drawing the loading screen each frame meanwhile
async function engineWaitForLoads()
{
    let waiting = true;
    const start = performance.now();
    const drawFrame = ()=>
    {
        if (!waiting) return;
        engineLoadingScreenDraw((performance.now() - start) / 1e3);
        setTimeout(drawFrame, 16);
    };
    headlessMode || drawFrame();
    try
    {
        for (let count; count !== engineLoads.length;)
        {
            count = engineLoads.length;
            await Promise.allSettled(engineLoads);
        }
    }
    finally { waiting = false; }
}

// one frame of the loading screen, once loading has taken half a second, so a fast load never shows it; input
// while it shows is dropped, as it is under the splash
function engineLoadingScreenDraw(elapsed)
{
    if (headlessMode || !loadingScreen || elapsed < .5) return;
    inputClear();
    engineUpdateCanvas();
    loadingScreen(engineLoadsDone / engineLoads.length);
}

/**
 * @callback GameInitCallback - Called after the engine starts, can be async
 * @return {void|Promise<void>}
 * @memberof Engine
 */
/**
 * @callback LoadingScreenCallback - Draws the loading screen on mainContext, each frame while the game loads
 * @param {number} progress - The part of the loads done, 0 to 1
 * @memberof Engine
 */
/**
 * @callback GameCallback - Update or render function for the game
 * @memberof Engine
 */

/** Startup LittleJS engine with your callback functions
 *  @param {GameInitCallback} [gameInit] - Called once after the engine starts up, can be async for loading
 *  @param {GameCallback} [gameUpdate] - Called every frame before objects are updated (60fps), use for game logic
 *  @param {GameCallback} [gameUpdatePost] - Called after physics and objects are updated, even when paused, use for UI updates
 *  @param {GameCallback} [gameRender] - Called before objects are rendered, use for drawing backgrounds/world elements
 *  @param {GameCallback} [gameRenderPost] - Called after objects are rendered, use for drawing UI/overlays
 *  @param {Array<string>} [imageSources=[]] - List of image file paths to preload (e.g., ['player.png', 'tiles.png'])
 *  @param {HTMLElement} [rootElement] - Root DOM element to attach canvas to, defaults to document.body
 *    It keeps its own inline styles and the canvas centers inside it, but the canvas is still sized from the window,
 *    so set canvasFixedSize or canvasMaxSize to fit a smaller element
 *  @example
 *  // Basic engine startup
 *  engineInit(
 *    ()=> { LOG('Game initialized!'); },  // gameInit
 *    ()=> { updateGameLogic(); },         // gameUpdate
 *    ()=> { updateUI(); },                // gameUpdatePost
 *    ()=> { drawBackground(); },          // gameRender
 *    ()=> { drawHUD(); },                 // gameRenderPost
 *    ['tiles.png', 'tilesLevel.png']       // images to load
 *  );
 *  @memberof Engine
 *  @return {Promise<void>} - Done when the images have loaded and gameInit has run */
async function engineInit(gameInit, gameUpdate, gameUpdatePost, gameRender, gameRenderPost, imageSources=[], rootElement)
{
    showEngineVersion && console.log(`${engineName} Engine v${engineVersion}`);
    ASSERT(!engineInitialized, 'engine already initialized');
    // runtime guard so release builds (where the assert is stripped) don't
    // double-register listeners / double-add canvases on a second call
    if (engineInitialized) return;
    engineInitialized = true;
    engineLoads = [], engineLoadsDone = 0;
    ASSERT(isArray(imageSources), 'pass in images as array');

    // allow passing in empty functions
    gameInit       ||= ()=>{};
    gameUpdate     ||= ()=>{};
    gameUpdatePost ||= ()=>{};
    gameRender     ||= ()=>{};
    gameRenderPost ||= ()=>{};

    // Called automatically by engine to setup render system
    function enginePreRender()
    {
        // the level editor's own view while it is open, in debug builds, before the camera goes to WebGL
        editorPreRender();

        // disable smoothing for pixel art
        mainContext.imageSmoothingEnabled = !tilesPixelated;

        // setup gl rendering if enabled
        glPreRender();
        setShader(); // a shader left set last frame does not carry into this one

        // plugins that draw underneath the 2D layer
        pluginList.forEach(plugin=>plugin.preRender?.());
    }

    // internal update loop for engine
    function engineUpdate(frameTimeMS=0)
    {
        const manualStepAtStart = engineManualStep;

        // update time keeping
        let frameTimeDeltaMS = frameTimeMS - frameTimeLastMS;
        // skip delta on the very first frame so timeReal doesn't jump
        // by ~page-load-time when RAF starts handing real timestamps
        if (!frameTimeLastMS) frameTimeDeltaMS = 0;
        frameTimeLastMS = frameTimeMS;
        if (debug || debugWatermark)
            averageFPS = lerp(averageFPS, 1e3/(frameTimeDeltaMS||1), .05);
        // the time the frame will be on screen, in whole display frames; engineStep's steps are exact already
        if (!manualStepAtStart)
            frameTimeDeltaMS = engineSmoothDelta(frameTimeDeltaMS);
        audioUpdateVolume();
        // the time keys work while the debug overlay is open, or always when debugKeysAlways is set
        const debugKeys = debug && (debugOverlay || debugKeysAlways);
        const debugSpeedUp   = debugKeys && keyIsDown('Equal'); // +
        const debugSpeedDown = debugKeys && keyIsDown('Minus'); // -
        const debugScale = debugSpeedUp ? 10 : debugSpeedDown ? .1 : 1;

        // apply time deltas
        const frameTimeDeltaUnscaledMS = frameTimeDeltaMS;
        timeReal += frameTimeDeltaMS * debugScale / 1e3;
        const combinedScale = timeScale * debugScale;
        frameTimeDeltaMS *= combinedScale;
        let wasUpdated = false;
        if (engineVariableStep)
        {
            // one update for the frame with timeDelta the time it covers, per-frame values are the game's to scale;
            // engineStep's frames are exactly 1/60, its first too, which has no frame before it to take a delta from
            if (frameTimeDeltaUnscaledMS > 0 || manualStepAtStart)
            {
                // frozen stands still as in the fixed step, and timeDelta keeps the last update's
                const frozenTick = paused || !combinedScale;
                if (!frozenTick)
                {
                    timeDelta = manualStepAtStart ? combinedScale / frameRate :
                        min(frameTimeDeltaUnscaledMS, 50) * combinedScale / 1e3; // clamp min framerate
                    time += timeDelta;
                    ++frame;
                }
                engineTick(frozenTick);
            }
        }
        else
        {
            // paused or a time scale of 0 is frozen: it ticks on unscaled time, so the update rate stays fixed instead
            // of following however fast the display refreshes, and gameUpdatePost and input still run to leave it
            const frozen = paused || !combinedScale;
            frameTimeBufferMS += frozen ? frameTimeDeltaUnscaledMS : frameTimeDeltaMS;
            frameTimeBufferMS = min(frameTimeBufferMS, 50 * (frozen ? 1 : max(1, combinedScale))); // clamp min framerate

            // apply time delta smoothing, improves smoothness of framerate in some browsers
            let deltaSmooth = 0;
            if (frameTimeBufferMS < 0 && frameTimeBufferMS > -9)
            {
                // force at least one update each frame since it is waiting for refresh
                deltaSmooth = frameTimeBufferMS;
                frameTimeBufferMS = 0;
            }

            // update multiple frames if necessary in case of slow framerate; a tick that throws still spends its time
            // and the smoothing still comes back, so a release build going on past an error each tick keeps its rate
            try
            {
                while (frameTimeBufferMS >= 0)
                {
                    try
                    {
                        // read again each tick, so a pause set by the game stops the rest of this frame's catch-up ticks
                        const frozenTick = paused || !(timeScale * debugScale);

                        // increment frame and update time, frozen does not advance time
                        if (!frozenTick)
                            time = timeFixedStart + (frame++ - frameFixedStart) / frameRate;
                        engineTick(frozenTick);
                    }
                    finally { frameTimeBufferMS -= 1e3 / frameRate; }
                }
            }
            finally
            {
                // add the time smoothing back in
                frameTimeBufferMS += deltaSmooth;
            }
        }

        // one tick of the loop: update game and objects, when frozen update everything except them
        function engineTick(frozenTick)
        {
            wasUpdated = true;
            engineUpdateCanvas();
            inputUpdate();
            if (!frozenTick)
                gameUpdate();
            pluginList.forEach(plugin=>plugin.update?.());
            if (frozenTick)
            {
                // update object transforms even when paused
                for (const o of engineObjects)
                    o.parent || o.updateTransforms();

                // objects made and destroyed while paused, like a menu's effects, still leave the list
                engineObjects.some(o=>o.destroyed) && (engineObjects = engineObjects.filter(o=>!o.destroyed));
            }
            else
                engineObjectsUpdate();

            // do post update
            debugUpdate();
            gameUpdatePost();
            inputUpdatePost();
            if (debugVideoCaptureIsActive())
                renderFrame();
        }

        // manual step turned on by this frame's updates, set the buffer the loop and smoothing just moved again
        if (engineManualStep && !manualStepAtStart)
            frameTimeBufferMS = -.5e3 / frameRate;

        // check if the window changed so a resize is picked up even when
        // the game is not updating, for example when timeScale is 0
        let windowChanged = false;
        if (!headlessMode)
        {
            const dpr = devicePixelRatio;
            windowChanged = windowWidthLast !== innerWidth ||
                windowHeightLast !== innerHeight || windowPixelRatioLast !== dpr;
            windowWidthLast = innerWidth;
            windowHeightLast = innerHeight;
            windowPixelRatioLast = dpr;
        }

        // render only when something changed, displays that refresh faster
        // than the fixed update rate would otherwise redraw identical frames
        if (!debugVideoCaptureIsActive() && (wasUpdated || windowChanged))
            renderFrame();
        engineManualStep || engineScheduleFrame();

        function renderFrame()
        {
            if (headlessMode) return;

            // canvas must be updated before rendering
            if (!wasUpdated)
                engineUpdateCanvas();

            // render the game and objects
            enginePreRender();
            gameRender();
            engineObjectsSort();
            for (const o of engineObjects)
            {
                if (o.destroyed) continue;
                setShader(o.shader); // each object draws with its own shader, or none
                o.render();
            }
            setShader(); // back to the engine's for gameRenderPost

            // post rendering
            gameRenderPost();
            setShader(); // plugin, input and debug draws start from the engine's state
            setAdditiveBlendMode(false);
            pluginList.forEach(plugin=>plugin.render?.());
            inputRender();
            debugRender();
            glFlush();
            debugRenderPost();
            drawCount = 0;
            primitiveCount = 0;
        }
    }

    // skip setup if headless
    if (headlessMode) return startEngine([]);

    // ensure body exists for minimal HTML where the script runs before <body> is parsed
    if (!document.body)
        document.documentElement.appendChild(document.createElement('body'));
    rootElement ||= document.body;

    // setup webgl
    glInit(rootElement);

    // setup html
    let styleRoot =
        'margin:0;' +                 // fill the window
        'overflow:hidden;' +          // no scroll bars
        'background:#000;' +          // set background color
        'user-select:none;' +         // prevent hold to select
        '-webkit-user-select:none;' + // compatibility for ios
        'touch-action:none;' +        // prevent mobile pinch to resize
        '-webkit-touch-callout:none;'; // compatibility for ios
    // the canvases center on a root element with a height of its own, not the page; one sized only by its
    // children has none, since the canvases are placed apart from it, and would clip them all away
    if (rootElement !== document.body && rootElement.clientHeight && getComputedStyle(rootElement).position === 'static')
        styleRoot += 'position:relative;';
    rootElement.style.cssText = styleRoot + rootElement.style.cssText; // its own inline styles come after and win
    mainCanvas = rootElement.appendChild(document.createElement('canvas'));
    drawContext = mainContext = mainCanvas.getContext('2d');

    // init stuff and start engine
    inputInit();
    audioInit();
    debugInit();

    // setup canvases
    // transform way is still more reliable than flexbox or grid
    const styleCanvas = 'position:absolute;'+ // allow canvases to overlap
        'top:50%;left:50%;transform:translate(-50%,-50%)'; // center on screen
    mainCanvas.style.cssText = styleCanvas;
    if (glCanvas)
        glCanvas.style.cssText = styleCanvas;
    setCanvasPixelated(canvasPixelated);
    engineUpdateCanvas();
    glPreRender();

    // create offscreen canvases for image processing
    workContext = createCanvasContext(64);
    workCanvas = workContext.canvas;
    workReadContext = createCanvasContext(64, 64, true);
    workReadCanvas = workReadContext.canvas;

    // create promises for loading images
    /** @type {Array<Promise<any>>} */
    const promises = imageSources.map((src, i)=> loadTexture(i, src));

    // no images to load
    if (!imageSources.length)
        promises.push(loadTexture(0));

    // load engine font image
    promises.push(imageFontInit());

    if (showSplashScreen)
    {
        // draw splash screen
        /** @type {Promise<void>} */
        const splash = new Promise(resolve =>
        {
            let t = 0;
            updateSplash();
            function updateSplash()
            {
                inputClear();
                drawEngineLogo(t+=.01);
                t>1 ? resolve() : setTimeout(updateSplash, 16);
            }
        });
        promises.push(splash);
    }

    // the splash first, the images load under it, then the loading screen for the rest
    showSplashScreen && await promises[promises.length - 1];
    return startEngine(promises);

    // gameInit runs once the images are in, and the game loop starts once it and everything loaded while it ran are
    // done, the loading screen showing in the meantime; an error in gameInit reaches the caller
    async function startEngine(images)
    {
        const init = (async ()=> { await Promise.all(images); await gameInit(); })();
        engineAddLoad(init);
        await engineWaitForLoads();
        engineLoads = undefined;
        await init;
        engineUpdateInternal = engineUpdate; // engineStep only runs once the game is set up
        engineManualStep || engineUpdate();
    }
}

// Resize the canvas to fit the window and prepare it for a new frame
// Called automatically each frame and by the splash screen before the loop starts
// mainCanvasSize is css pixels and the backing store is that scaled by the
// pixel ratio, so the ratio only changes sharpness, never how big things look
function engineUpdateCanvas()
{
    if (headlessMode) return;

    // the backing store is scaled by this, every size below is css pixels
    const dpr = getCanvasPixelRatio();

    if (canvasFixedSize.x)
    {
        // set canvas fixed size
        mainCanvasSize = canvasFixedSize.copy();

        // fit to window using css width and height
        const innerAspect = innerWidth / innerHeight;
        const fixedAspect = canvasFixedSize.x / canvasFixedSize.y;
        const w = innerAspect < fixedAspect ? '100%' : '';
        const h = innerAspect < fixedAspect ? '' : '100%';
        mainCanvas.style.width  = w;
        mainCanvas.style.height = h;
        if (glCanvas)
        {
            glCanvas.style.width  = w;
            glCanvas.style.height = h;
        }
    }
    else
    {
        // get main canvas size based on window size, in css pixels so
        // canvasMaxSize caps how big the canvas looks, not its resolution
        mainCanvasSize.x = min(innerWidth,  canvasMaxSize.x) | 0;
        mainCanvasSize.y = min(innerHeight, canvasMaxSize.y) | 0;

        // responsive aspect ratio, of the size after canvasMaxSize, which can change its shape
        const innerAspect = mainCanvasSize.x / mainCanvasSize.y;
        ASSERT(!canvasMaxAspect || canvasMinAspect <= canvasMaxAspect);
        if (canvasMaxAspect && innerAspect > canvasMaxAspect)
        {
            // full height
            const w = mainCanvasSize.y * canvasMaxAspect | 0;
            mainCanvasSize.x = min(w, canvasMaxSize.x);
        }
        else if (innerAspect < canvasMinAspect)
        {
            // full width
            const h = mainCanvasSize.x / canvasMinAspect | 0;
            mainCanvasSize.y = min(h, canvasMaxSize.y);
        }

        // css size is the canvas size, the backing store is scaled up below
        mainCanvas.style.width  = mainCanvasSize.x + 'px';
        mainCanvas.style.height = mainCanvasSize.y + 'px';
        if (glCanvas)
        {
            glCanvas.style.width  = mainCanvasSize.x + 'px';
            glCanvas.style.height = mainCanvasSize.y + 'px';
        }
    }

    // clear main canvas and set size
    // only set the size when it changes, setting it invalidates the canvas
    // frame which makes the browser rebuild the display list for the page
    const bufferSizeX = mainCanvasSize.x * dpr | 0;
    const bufferSizeY = mainCanvasSize.y * dpr | 0;
    if (mainCanvas.width !== bufferSizeX || mainCanvas.height !== bufferSizeY)
    {
        mainCanvas.width  = bufferSizeX;
        mainCanvas.height = bufferSizeY;
    }
    else
    {
        // setting the size also resets the context state, match that
        mainContext.setTransform(1, 0, 0, 1, 0, 0);
        mainContext.globalCompositeOperation = 'source-over';
        mainContext.clearRect(0, 0, bufferSizeX, bufferSizeY);
    }

    // scale the context so 2d drawing is in css pixels
    mainContext.setTransform(dpr, 0, 0, dpr, 0, 0);

    // apply the clear color to main canvas
    if (canvasClearColor.a > 0 && !glEnable)
    {
        mainContext.fillStyle = canvasClearColor.toString();
        mainContext.fillRect(0, 0, mainCanvasSize.x, mainCanvasSize.y);
        mainContext.fillStyle = BLACK.toString();
    }

    // set default line join and cap, round on purpose: it looks better, suits text and keeps sharp corners from
    // spiking far out; WebGL outlines are square and mitered for speed, the two are not meant to match
    mainContext.lineJoin = 'round';
    mainContext.lineCap  = 'round';
}

// ask for the next frame of the loop, once however often it is called before that frame, and skip it if manual
// step was turned on since, so turning it off and on again within a frame can not start a second loop
function engineScheduleFrame()
{
    if (engineFrameScheduled) return;
    engineFrameScheduled = true;
    const next = (frameTimeMS)=>
    {
        engineFrameScheduled = false;
        if (engineManualStep) return;
        if (debug) return engineUpdateInternal(frameTimeMS); // a debug build stops at an error, where it shows it
        try { engineUpdateInternal(frameTimeMS); }
        catch (error)
        {
            // a release build goes on past an error in a frame, a frozen game is the worst a player can get; an error
            // is logged when it is not the last one again, one every frame would flood the console
            const text = String(error);
            text === engineFrameErrorLast || console.error(error);
            engineFrameErrorLast = text;
            // the frame's input is cleared as its tick would have, or a key press that threw would be pressed again
            inputUpdatePost();
            engineScheduleFrame();
        }
    };
    if (typeof requestAnimationFrame === 'function')
        requestAnimationFrame(next);
    else // a headless server in Node has no display to wait for, a timer keeps the pace
        setTimeout(()=> next(performance.now()), 1e3 / frameRate);
}

// max frames engineStep can advance in one call, 10 minutes at 60fps
// large counts block until they finish, so this catches runaway values
const engineStepMaxFrames = 36000;

/** Advance the engine by a number of frames
 *  Requires setEngineManualStep(true), before engineInit or while running; it stops early if an update turns it off
 *  Respects paused exactly as the normal update loop does
 *  @param {number} [frames] - frames of 1/60 of a second to advance, max 36000; timeScale sets how many fixed
 *  updates they run, as in the normal loop, one each at timeScale 1
 *  @example
 *  setHeadlessMode(true);
 *  setEngineManualStep(true);
 *  await engineInit(gameInit, gameUpdate, gameUpdatePost, gameRender, gameRenderPost);
 *  engineStep(600); // advance 10 seconds of game time
 *  @memberof Engine */
function engineStep(frames=1)
{
    ASSERT(engineManualStep,
        'engineStep requires setEngineManualStep(true)');
    ASSERT(engineUpdateInternal, 'engineStep requires engineInit to complete');
    // runtime guard so release builds (where the asserts are stripped) can't
    // start a second requestAnimationFrame chain or call an undefined update
    if (!engineManualStep || !engineUpdateInternal) return;
    ASSERT(Number.isInteger(frames) && frames >= 0 && frames <= engineStepMaxFrames,
        'engineStep requires a whole frame count from 0 to ' + engineStepMaxFrames);
    frames = min(frames, engineStepMaxFrames); // release has no asserts, don't freeze
    for (let i = frames; i > 0 && engineManualStep; --i) // an update that turns manual step off hands back the loop
        engineUpdateInternal(frameTimeLastMS + 1e3 / frameRate);
}

/** Update each engine object and remove destroyed objects; time and frame are advanced by the engine loop, not here
 *  - Can be called manually if objects need to be updated outside of main loop
 *  @memberof Engine */
function engineObjectsUpdate()
{
    ++engineObjectsUpdateCount;
    engineObjectsCollidePairs.clear();
    // objects update in render order, which rendering keeps them in, so a headless run or a frame that rendered
    // nothing updates them the same way
    engineObjectsSort();
    // get list of solid objects for physics optimization, in update order, which 3D collision pairs by;
    // 2D checks the static ones last, so a contact with a moving object can not leave something back inside a static
    // solid it was already pushed out of
    const fixed = [];
    engineObjectsCollide = [];
    engineObjectsCollideStaticLast = [];
    for (const o of engineObjects)
        o.collideSolidObjects && (engineObjectsCollide.push(o), (o.mass ? engineObjectsCollideStaticLast : fixed).push(o));
    for (const o of fixed)
        engineObjectsCollideStaticLast.push(o);

    // update physics before object update
    for (const o of engineObjects)
        if (!o.parent && !o.destroyed)
            o.updatePhysics();

    // recursive object update: the children are walked from a copy on a shared stack, since a child that
    // destroys itself leaves its parent's list on the spot and the next child would slide past the loop
    function updateChildObjects(children)
    {
        if (!children.length) return; // most objects have none, and this runs for every one
        const start = engineChildStack.length;
        for (const child of children)
            engineChildStack.push(child);
        try
        {
            for (let i = start; i < engineChildStack.length; ++i)
                updateChildObject(engineChildStack[i]);
        }
        finally { engineChildStack.length = start; } // put back when an update throws too, or it keeps them
    }
    const pass = engineObjectsUpdateCount;
    function updateChildObject(o)
    {
        if (o.destroyed || o.updatePass === pass) return;

        // its parent is up to date, so it updates from where it is now, and its children from where it is after
        o.updatePass = pass;
        o.updateTransforms(false);
        o.update();
        o.children.length && o.updateTransforms(false);
        updateChildObjects(o.children);
    }
    function updateTopObject(o)
    {
        if (o.parent || o.destroyed || o.updatePass === pass) return; // a child that let go is not updated twice

        // update top level objects, each child places itself before it updates so it sees this frame's position,
        // then the whole tree is placed again so what the children changed in their localPos lands before render
        o.updatePass = pass;
        o.update();
        updateChildObjects(o.children);
        o.updateTransforms();
    }
    for (const o of engineObjects)
        updateTopObject(o);

    // a child let go during the update from a place in the list already walked is on its own now, updated here
    for (const o of engineObjects)
        updateTopObject(o);

    // remove destroyed objects
    engineObjects.some(o=>o.destroyed) && (engineObjects = engineObjects.filter(o=>!o.destroyed));
}

// sort the objects by render order, keeping the order of equals, only when one is out of order, as they are kept
// sorted and most frames change none
function engineObjectsSort()
{
    for (let i = engineObjects.length; --i > 0;)
        if (engineObjects[i].renderOrder < engineObjects[i-1].renderOrder)
            return void engineObjects.sort((a,b)=> a.renderOrder - b.renderOrder);
}

/** Destroy and remove all objects
 *  - This can be used to clear out all objects when restarting a level
 *  - Objects with the persistent flag set are left alone, for things that outlive a level
 *  - Objects can override their destroy function to do cleanup or stick around
 *  @param {boolean} [immediate] - true removes attached effects like particle emitters at once, false lets them finish first
 *  @memberof Engine */
function engineObjectsDestroy(immediate=true)
{
    for (const o of engineObjects)
        o.parent || o.persistent || o.destroy(immediate);
    engineObjects = engineObjects.filter(o=>!o.destroyed);
}

/** Collects all object within a given area
 *  - An object is collected when its box overlaps the area, or with testCenters when its center is inside it
 *  - Objects destroyed this frame are left out, they are only in the list until the frame ends
 *  @param {Vector2} [pos] - Center of test area, or undefined for all objects
 *  @param {Vector2|number} [size] - Diameter of a circle if a number, full size of a rectangle if a Vector2,
 *                                   left out or 0 the objects that overlap the point at pos
 *  @param {Array<EngineObject>} [objects=engineObjects] - List of objects to check
 *  @param {boolean} [testCenters] - Test only each object's center, a little faster, and ignores object sizes
 *  @return {Array<EngineObject>} - List of collected objects
 *  @memberof Engine */
function engineObjectsCollect(pos, size, objects=engineObjects, testCenters=false)
{
    const collectedObjects = [];
    if (!pos)
    {
        // all objects
        for (const o of objects)
            o.destroyed || collectedObjects.push(o);
    }
    else if (!size || size instanceof Vector2)
    {
        // bounding box test, a point when there is no size or a size of 0
        const boxSize = size instanceof Vector2 ? size : vec2();
        for (const o of objects)
            o.destroyed || (testCenters ? isOverlapping(pos, boxSize, o.pos) : o.isOverlapping(pos, boxSize))
                && collectedObjects.push(o);
    }
    else
    {
        // circle test, a diameter like every other size, against the nearest point of each box
        const radiusSquared = (size/2)**2;
        for (const o of objects)
        {
            if (o.destroyed) continue;
            const dx = testCenters ? pos.x - o.pos.x : max(abs(pos.x - o.pos.x) - o.size.x/2, 0);
            const dy = testCenters ? pos.y - o.pos.y : max(abs(pos.y - o.pos.y) - o.size.y/2, 0);
            dx*dx + dy*dy < radiusSquared && collectedObjects.push(o);
        }
    }
    return collectedObjects;
}

/**
 * @callback ObjectCallbackFunction - Function that processes an object
 * @param {EngineObject} object
 *  @memberof Engine
 */

/** Triggers a callback for each object within a given area, objects destroyed this frame left out
 *  @param {Vector2} [pos] - Center of test area, or undefined for all objects
 *  @param {Vector2|number} [size] - Diameter of a circle if a number, full size of a rectangle if a Vector2
 *  @param {ObjectCallbackFunction} [callbackFunction] - Calls this function on every object that passes the test, needed
 *                                                     (marked optional only because the area before it is)
 *  @param {Array<EngineObject>} [objects=engineObjects] - List of objects to check
 *  @param {boolean} [testCenters] - Test only each object's center, see engineObjectsCollect
 *  @memberof Engine */
function engineObjectsCallback(pos, size, callbackFunction, objects=engineObjects, testCenters=false)
{
    // an object an earlier callback destroyed is skipped
    for (const o of engineObjectsCollect(pos, size, objects, testCenters))
        o.destroyed || callbackFunction(o);
}

/** Return a list of objects intersecting a ray, objects destroyed this frame left out
 *  - Only objects with collideRaycast set are hit, which setCollision turns on
 *  @param {Vector2} start
 *  @param {Vector2} end
 *  @param {Array<EngineObject>} [objects=engineObjects] - List of objects to check
 *  @return {Array<EngineObject>} - List of objects hit
 *  @memberof Engine */
function engineObjectsRaycast(start, end, objects=engineObjects)
{
    const hitObjects = [];
    for (const o of objects)
    {
        if (o.collideRaycast && !o.destroyed && isIntersecting(start, end, o.pos, o.size))
        {
            debugRaycast && debugRect(o.pos, o.size, '#f00', 0, 0, false, false);
            hitObjects.push(o);
        }
    }

    debugRaycast && debugLine(start, end, hitObjects.length ? '#f00' : '#00f', .02, 0, false);
    return hitObjects;
}
/**
 * LittleJS Debug System
 * - Press Esc to toggle debug overlay with object picking
 * - Number keys toggle debug visualizations (physics, particles, etc.) while the overlay is open
 * - +/- keys control time scale for slow motion/fast forward while the overlay is open
 * - setDebugKeysAlways lets those keys work with the overlay closed too
 * - ASSERT and LOG macros for development (removed in release builds)
 * - Debug primitive rendering (rectangles, circles, lines, points, text)
 * - Screenshot and video capture support
 * - FPS counter and performance watermark
 * - Debug overlay shows mouse position and picked objects
 * @namespace Debug
 */

/** True if debug is enabled
 *  @type {boolean}
 *  @default
 *  @memberof Debug */
const debug = true;

/** Size to render debug points by default
 *  @type {number}
 *  @default
 *  @memberof Debug */
const debugPointSize = .5;

/** True if watermark with FPS should be shown, false in release builds
 *  @type {boolean}
 *  @default
 *  @memberof Debug */
let debugWatermark = true;

/** Key code used to toggle debug mode, Esc by default
 *  @type {string}
 *  @default
 *  @memberof Debug */
let debugKey = 'Escape';

/** Let the debug keys work while the overlay is closed, the number keys and the +/- time keys, for a game that does
 *  not use them; off by default, so they only work while the overlay is open
 *  @type {boolean}
 *  @default
 *  @memberof Debug */
let debugKeysAlways = false;

/** True if the debug overlay is active, always false in release builds
 *  @type {boolean}
 *  @default
 *  @memberof Debug */
let debugOverlay = false;

/** Open or close the debug overlay from code, as the debug key does; does nothing in release builds
 *  @param {boolean} [show]
 *  @memberof Debug */
function setDebugOverlay(show=true) { debug && (debugOverlay = !!show); }

/** True if the tweakables panel is shown, 9 toggles it while the overlay is open; set it to show the panel
 *  from the start, the panel is never shown in release builds
 *  @type {boolean}
 *  @default
 *  @memberof Debug */
let debugTweakables = false;

// the shadow behind debug text, so it reads over anything: the overlay menu and the mouse text both use it;
// a smaller blur is tighter and darker, a larger one softer and fainter
const debugTextShadowColor = '#000', debugTextShadowBlur = 9;
function debugTextShadow(context) { context.shadowColor = debugTextShadowColor; context.shadowBlur = debugTextShadowBlur; }

// Engine internal variables not exposed to documentation
let debugPrimitives = [], debugClearCount = 0, debugPhysics = false, debugRaycast = false, debugParticles = false, debugGamepads = false, debugSound = false, debugTiles = 0, debugTakeScreenshot;
// debugTiles is 0 for off, 1 for every layer, and 2 on for one layer at a time, see debugTileLayersSelected

///////////////////////////////////////////////////////////////////////////////
// Debug helper functions

/** Asserts if the expression is false, does nothing in release builds
 *  Halts execution if the assert fails and throws an error
 *  @param {*} assert - any value, the assert fails when it is falsy
 *  @param {...Object} output - error message output
 *  @memberof Debug */
function ASSERT(assert, ...output)
{
    if (assert) return;
    console.assert(assert, ...output)
    throw new Error('Assert failed!'); // halt execution
}

/** Log to console if debug is enabled, does nothing in release builds
 *  @param {...Object} output - message output
 *  @memberof Debug */
function LOG(...output) { console.log(...output); }

/** Draw a debug rectangle in world space, or on the screen with screenSpace
 *  @param {Vector2} pos
 *  @param {Vector2} [size=vec2()]
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {number} [angle]
 *  @param {boolean} [fill]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugRect(pos, size=vec2(), color=WHITE, time=0, angle=0, fill=false, screenSpace=drawScreenSpace)
{
    ASSERT(isVector2(pos), 'pos must be a vec2');
    ASSERT(isVector2(size), 'size must be a vec2');
    ASSERT(isStringLike(color) || isColor(color), 'color is invalid');
    ASSERT(isNumber(time), 'time must be a number');
    ASSERT(isNumber(angle), 'angle must be a number');

    if (headlessMode) return; // nothing draws them, they would pile up
    if (isColor(color))
        color = color.toString();
    const timer = new Timer(time, true); // real time, so they still expire while the game is paused
    debugPrimitives.push({pos:pos.copy(), size:size.copy(), color, timer, angle, fill, screenSpace});
}

/** Draw a debug poly in world space, or on the screen with screenSpace
 *  @param {Vector2} pos
 *  @param {Array<Vector2>} points
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {number} [angle]
 *  @param {boolean} [fill]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugPoly(pos, points, color=WHITE, time=0, angle=0, fill=false, screenSpace=drawScreenSpace)
{
    ASSERT(isVector2(pos), 'pos must be a vec2');
    ASSERT(isArray(points), 'points must be an array');
    ASSERT(isStringLike(color) || isColor(color), 'color is invalid');
    ASSERT(isNumber(time), 'time must be a number');
    ASSERT(isNumber(angle), 'angle must be a number');

    if (headlessMode) return;
    if (isColor(color))
        color = color.toString();
    pos = pos.copy();
    points = points.map(p=>p.copy());
    const timer = new Timer(time, true); // real time, so they still expire while the game is paused
    debugPrimitives.push({pos, points, color, timer, angle, fill, screenSpace});
}

/** Draw a debug circle in world space, or on the screen with screenSpace
 *  @param {Vector2} pos
 *  @param {number} [size] - diameter
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {boolean} [fill]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugCircle(pos, size=0, color=WHITE, time=0, fill=false, screenSpace=drawScreenSpace)
{
    ASSERT(isVector2(pos), 'pos must be a vec2');
    ASSERT(isNumber(size), 'size must be a number');
    ASSERT(isStringLike(color) || isColor(color), 'color is invalid');
    ASSERT(isNumber(time), 'time must be a number');

    if (headlessMode) return;
    if (isColor(color))
        color = color.toString();
    pos = pos.copy();
    const timer = new Timer(time, true); // real time, so they still expire while the game is paused
    debugPrimitives.push({pos, size, color, timer, angle:0, fill, screenSpace});
}

/** Draw a debug point in world space, or on the screen with screenSpace
 *  @param {Vector2} pos
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {number} [angle]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugPoint(pos, color, time, angle, screenSpace=drawScreenSpace)
{ debugRect(pos, undefined, color, time, angle, false, screenSpace); }

/** Draw a debug line in world space, or on the screen with screenSpace
 *  @param {Vector2} posA
 *  @param {Vector2} posB
 *  @param {Color|string} [color]
 *  @param {number} [width]
 *  @param {number} [time]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugLine(posA, posB, color, width=.1, time=0, screenSpace=drawScreenSpace)
{
    ASSERT(isVector2(posA), 'posA must be a vec2');
    ASSERT(isVector2(posB), 'posB must be a vec2');
    ASSERT(isNumber(width), 'width must be a number');

    const halfDelta = vec2((posB.x - posA.x)/2, (posB.y - posA.y)/2);
    const size = vec2(width, halfDelta.length()*2);
    // screen space y points down, so its angle is measured the other way, as drawLine does
    const angle = vec2(halfDelta.x, screenSpace ? -halfDelta.y : halfDelta.y).angle();
    debugRect(posA.add(halfDelta), size, color, time, angle, true, screenSpace);
}

/** Draw a debug combined axis aligned bounding box in world space, or on the screen with screenSpace
 *  @param {Vector2} posA
 *  @param {Vector2} sizeA
 *  @param {Vector2} posB
 *  @param {Vector2} sizeB
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugOverlap(posA, sizeA, posB, sizeB, color, time, screenSpace=drawScreenSpace)
{
    ASSERT(isVector2(posA), 'posA must be a vec2');
    ASSERT(isVector2(posB), 'posB must be a vec2');
    ASSERT(isVector2(sizeA), 'sizeA must be a vec2');
    ASSERT(isVector2(sizeB), 'sizeB must be a vec2');

    const minPos = vec2(
        min(posA.x - sizeA.x/2, posB.x - sizeB.x/2),
        min(posA.y - sizeA.y/2, posB.y - sizeB.y/2)
    );
    const maxPos = vec2(
        max(posA.x + sizeA.x/2, posB.x + sizeB.x/2),
        max(posA.y + sizeA.y/2, posB.y + sizeB.y/2)
    );
    debugRect(minPos.lerp(maxPos,.5), maxPos.subtract(minPos), color, time, 0, false, screenSpace);
}

/** Draw debug text in world space, or on the screen with screenSpace
 *  @param {string|number} text
 *  @param {Vector2} pos
 *  @param {number} [size]
 *  @param {Color|string} [color]
 *  @param {number} [time]
 *  @param {number} [angle]
 *  @param {string} [font]
 *  @param {boolean} [screenSpace=drawScreenSpace]
 *  @memberof Debug */
function debugText(text, pos, size=1, color=WHITE, time=0, angle=0, font='monospace', screenSpace=drawScreenSpace)
{
    ASSERT(isStringLike(text), 'text must be a string');
    ASSERT(isVector2(pos), 'pos must be a vec2');
    ASSERT(isNumber(size), 'size must be a number');
    ASSERT(isStringLike(color) || isColor(color), 'color is invalid');
    ASSERT(isNumber(time), 'time must be a number');
    ASSERT(isNumber(angle), 'angle must be a number');
    ASSERT(isStringLike(font), 'font must be a string');

    if (headlessMode) return;
    if (isColor(color))
        color = color.toString();
    pos = pos.copy();
    const timer = new Timer(time, true); // real time, so they still expire while the game is paused
    debugPrimitives.push({text, pos, size, color, timer, angle, font, screenSpace});
}

/** Clear all debug primitives in the list
 *  @memberof Debug */
function debugClear() { debugPrimitives = []; ++debugClearCount; } // the count lets plugins clear their own

/** Trigger debug system to take a screenshot
 *  @memberof Debug */
function debugScreenshot() { debugTakeScreenshot = 1; }

/** Breaks on all asserts/errors, hides the canvas, and shows message in plain text
 *  This is a good function to call at the start of your game to catch all errors
 *  In release builds this function has no effect
 *  @memberof Debug */
function debugShowErrors()
{
    const showError = (message)=>
    {
        // replace entire page with error message
        document.body.style.cssText = 'background-color:#111;margin:8px';
        const pre = document.createElement('pre'); // the message as text, a file name in it never markup
        pre.style.cssText = 'color:#f00;font-size:28px;white-space:pre-wrap';
        pre.textContent = String(message);
        document.body.replaceChildren(pre);
    }
    
    const originalAssert = console.assert;
    console.assert = (assertion, ...output)=>
    {
        originalAssert(assertion, ...output);
        if (!assertion)
        {
            const message = output.join(' ');
            const stack = new Error().stack;
            throw 'Assertion failed!\n' + message + '\n' + stack;
        }
    };
    onunhandledrejection = (event)=>
        showError(event.reason?.stack || event.reason);
    onerror = (message, source, lineno, colno)=>
        showError(`${message}\n${source}\nLn ${lineno}, Col ${colno}`);
}

///////////////////////////////////////////////////////////////////////////////
// Engine debug functions (called automatically)

function debugInit()
{
    if (showEngineVersion)
        console.warn("LittleJS DEBUG build loaded. Use the release build for production.");
}

function debugUpdate()
{
    if (!debug) return;

    if (keyWasPressed(debugKey)) // Esc
        debugOverlay = !debugOverlay;
    const debugKeys = debugOverlay || debugKeysAlways; // the keys work while the overlay is open, or always if set
    if (debugKeys)
    {
        if (keyWasPressed('Digit1'))
            debugPhysics = !debugPhysics, debugParticles = false;
        if (keyWasPressed('Digit2'))
            debugTiles = (debugTiles + 1) % (debugTileLayersShown().length + 2); // off, all, then each layer
        if (keyWasPressed('Digit3'))
            debugParticles = !debugParticles, debugPhysics = false;
        if (keyWasPressed('Digit4'))
            debugRaycast = !debugRaycast;
        if (keyWasPressed('Digit5'))
            debugGamepads = !debugGamepads;
        if (keyWasPressed('Digit6'))
            debugSound = !debugSound;
        if (keyWasPressed('Digit7'))
            debugScreenshot();
        if (keyWasPressed('Digit9'))
            debugTweakables = !debugTweakables;
        if (keyWasPressed('Digit0'))
            levelEditor.isOpen ? levelEditor.close() : levelEditor.open();
    }
    if (debugVideoCaptureIsActive())
    {
        // control to stop video capture, a capture the overlay started also stops when the overlay closes,
        // one the game started from code runs until it calls debugVideoCaptureStop
        if (debugKeys ? keyWasPressed('Digit8') : debugVideoCapture.fromOverlay)
            debugVideoCaptureStop();
    }
    else if (debugKeys && keyWasPressed('Digit8'))
    {
        debugVideoCaptureStart();
        if (debugVideoCapture)
            debugVideoCapture.fromOverlay = true;
    }
}

// the text beside the mouse, with the same shadow as the overlay
function debugMouseText(text)
{
    mainContext.save();
    debugTextShadow(mainContext);
    drawTextScreen(text, mousePosScreen, 24, WHITE, 0, BLACK, 'center', 'monospace', undefined, undefined, 0, mainContext);
    mainContext.restore();
}

// the center of the tile under a world position, on the grid of the collision layer that has a tile there
function debugTileCellCenter(pos)
{
    for (const layer of tileCollisionLayers)
    {
        const local = pos.subtract(layer.pos);
        if (local.arrayCheck(layer.size) && layer.getCollisionData(local))
            return local.floor().add(layer.pos).add(vec2(.5));
    }
    return pos.floor().add(vec2(.5));
}

// the tile layers Debug Tiles can show, the ones not switched off with debugShow, in render order
function debugTileLayersShown()
{
    return engineObjects.filter(o=> o instanceof TileLayer && !o.destroyed && o.debugShow)
        .sort((a, b)=> a.renderOrder - b.renderOrder); // a stable sort, so equal orders keep the order they were made in
}

// the layers Debug Tiles shows right now, from the ones shown: every one, or the one the 2 key has stepped to,
// every one again if layers went away since
function debugTileLayersSelected(layers)
{
    const layer = layers[debugTiles - 2];
    return layer ? [layer] : layers;
}

// what the overlay menu says Debug Tiles is showing
function debugTilesLabel(layers)
{
    if (!debugTiles) return '';
    const layer = layers[debugTiles - 2];
    return layer ? ` (layer ${debugTiles - 1} of ${layers.length}, renderOrder ${layer.renderOrder}${layer instanceof TileCollisionLayer ? ', collision' : ''})` : ' (all)';
}

// Debug Tiles: each layer's bounds, then the collision value of every cell on screen, tinted by value, with the
// number when a tile is big enough on screen to read it
function debugTileLayers(layers)
{
    // everything the camera can see, turned or not
    const reach = getCameraSize().length() / 2;
    const showValues = cameraScale >= 24;
    for (const layer of debugTileLayersSelected(layers))
    {
        const isCollision = layer instanceof TileCollisionLayer, size = layer.size, pos = layer.pos;
        const color = isCollision ? '#f80' : '#0cf';
        debugRect(pos.add(size.scale(.5)), size, color, 0, 0, false, false);
        const label = 'layer ' + (layers.indexOf(layer) + 1) + ', ' + size.x + 'x' + size.y + ', renderOrder ' + layer.renderOrder + (isCollision ? ', collision' : '');
        debugText(label, pos.add(vec2(size.x / 2, size.y + .4)), .6, color, 0, 0, 'monospace', false);
        if (!isCollision) continue;

        const x0 = max(0, floor(cameraPos.x - reach - pos.x)), x1 = min(size.x, ceil(cameraPos.x + reach - pos.x));
        const y0 = max(0, floor(cameraPos.y - reach - pos.y)), y1 = min(size.y, ceil(cameraPos.y + reach - pos.y));
        for (let y = y0; y < y1; ++y)
        for (let x = x0; x < x1; ++x)
        {
            const data = layer.collisionData[y * size.x + x];
            if (!data) continue;
            const center = vec2(pos.x + x + .5, pos.y + y + .5), tint = hsl(data * .17 % 1, 1, .6, .8);
            debugRect(center, vec2(.9), tint, 0, 0, false, false);
            showValues && debugText(data, center, .5, tint, 0, 0, 'monospace', false);
        }
    }
}

// the tile and collision value under the mouse of each layer shown by Debug Tiles, as lines of the mouse text
function debugTileText(layers)
{
    if (!debugTiles) return '';
    // each layer by its number in the 2 key's cycle, the one the menu shows
    let text = '';
    for (const layer of debugTileLayersSelected(layers))
    {
        const local = mousePos.subtract(layer.pos);
        if (!local.arrayCheck(layer.size)) continue;
        // only a collision layer has collision data, the others are just drawn
        const data = layer.getData(local);
        const collision = layer instanceof TileCollisionLayer && layer.getCollisionData(local);
        text += '\nlayer ' + (layers.indexOf(layer) + 1) + ': tile ' + (data?.tile ?? 'empty') + (collision ? ', collision ' + collision : '');
    }
    return text;
}

function debugRender()
{
    if (debugTakeScreenshot)
    {
        // combine canvases, remove alpha and save, before the capture check so it is taken during video capture too
        glFlush();
        combineCanvases();
        saveCanvas(mainCanvas);
        debugTakeScreenshot = 0;
    }

    if (debugVideoCaptureIsActive())
    {
        // don't show debug info when capturing video, but still drop the expired primitives so they don't pile up
        debugPrimitives = debugPrimitives.filter(r=>r.timer<0);
        return;
    }

    // flush any gl sprites before drawing debug info
    glFlush();

    // the tile layers Debug Tiles can show, found once for everything below
    const tileLayers = debugTiles ? debugTileLayersShown() : [];

    const savedDrawCount = drawCount;
    const savedPrimitiveCount = primitiveCount;

    const debugContext = mainContext;
    if (debugGamepads && gamepadsEnable)
    {
        // draw gamepads
        const maxGamepads = 8;
        let gamepadConnectedCount = 0;
        for (let i = 0; i < maxGamepads; i++)
            gamepadConnected(i) && gamepadConnectedCount++;

        for (let i = 0; i < maxGamepads; i++)
        {
            if (!gamepadConnected(i))
                continue;

            const stickScale = 1;
            const buttonScale = .2;
            const cornerPos = cameraPos.add(vec2(-stickScale*2, ((gamepadConnectedCount-1)/2-i)*stickScale*3));
            debugText(i, cornerPos.add(vec2(-stickScale, stickScale)), 1, WHITE, 0, 0, 'monospace', false);
            if (i === gamepadPrimary)
                debugText('Main', cornerPos.add(vec2(-stickScale*2, 0)),1, '#0f0', 0, 0, 'monospace', false);

            // read analog sticks
            const stickCount = gamepadStickCount(i); // none after an inputClear this frame
            for (let j = 0; j < stickCount; j++)
            {
                if (!(j in gamepadStickData[i]))
                    continue; // skip sticks that are not present (eg a disabled touch left stick)
                const stick = gamepadStick(j, i);
                const drawPos = cornerPos.add(vec2(j*stickScale*2, 0));
                const stickPos = drawPos.add(stick.scale(stickScale));
                debugCircle(drawPos, stickScale*2, '#fff7',0,true, false);
                debugLine(drawPos, stickPos, '#f00', .1, 0, false);
                debugText(j, drawPos, .3, WHITE, 0, 0, 'monospace', false);
                debugPoint(stickPos, '#f00', undefined, undefined, false);
            }

            const buttonCount = inputData[i+1].length;
            for (let j = 0; j < buttonCount; j++)
            {
                const drawPos = cornerPos.add(vec2(j*buttonScale*2, -stickScale-buttonScale*2));
                const pressed = gamepadIsDown(j, i);
                debugCircle(drawPos, buttonScale*2, pressed ? '#f00' : '#fff7', 0, true, false);
                debugText(j, drawPos, .3, WHITE, 0, 0, 'monospace', false);
            }
        }
    }

    let debugObject;
    if (debugOverlay)
    {
        // draw red rectangle around screen
        const cameraSize = getCameraSize();
        debugRect(cameraPos, cameraSize.subtract(vec2(.1)), '#f008', 0, 0, false, false);

        // mouse pick
        let bestDistance = Infinity;
        for (const o of engineObjects)
        {
            if (o.destroyed)
                continue;

            if (o instanceof TileLayer)
                continue; // prevent tile layers from being picked

            o.renderDebugInfo();
            if (!o.size.x || !o.size.y)
                continue;

            const distance = mousePos.distanceSquared(o.pos);
            if (distance < bestDistance)
            {
                bestDistance = distance;
                debugObject = o;
            }
        }

        if (tileCollisionTest(mousePos))
        {
            // show the collision tile under the mouse, on its layer's own grid
            drawRect(debugTileCellCenter(mousePos), vec2(1), rgb(1,1,0,.5), 0, false, false);
        }
    }

    // Debug Tiles draws with the overlay closed too, like the other modes listed in the corner
    debugTiles && debugTileLayers(tileLayers);

    {
        // draw debug primitives, the line width put back after so the game's next frame starts as it would in release
        debugContext.save();
        debugContext.lineWidth = 2;
        debugPrimitives.forEach(p=>
        {
            debugContext.save();

            // create canvas transform from world space to screen space
            // without scaling because we want consistent pixel sizes
            let pos = p.pos, scale = 1, angle = p.angle;
            if (!p.screenSpace)
            {
                pos = worldToScreen(p.pos);
                scale = cameraScale;
                angle -= cameraAngle;
            }
            debugContext.translate(pos.x|0, pos.y|0);
            debugContext.rotate(angle);
            debugContext.scale(1, p.text !== undefined ? 1 : -1);
            debugContext.fillStyle = p.color;
            debugContext.strokeStyle = p.color;
            if (p.text !== undefined)
            {
                debugContext.font = p.size*scale + 'px '+ p.font;
                debugContext.textAlign = 'center';
                debugContext.textBaseline = 'middle';
                debugContext.fillText(p.text, 0, 0);
            }
            else if (p.points !== undefined)
            {
                // poly
                debugContext.beginPath();
                for (const point of p.points)
                {
                    const p2 = point.scale(scale).floor();
                    debugContext.lineTo(p2.x, p2.y);
                }
                debugContext.closePath();
                p.fill && debugContext.fill();
                debugContext.stroke();
            }
            else if (p.size === 0 || (p.size.x === 0 && p.size.y === 0))
            {
                // point
                const pointSize = debugPointSize * scale;
                debugContext.fillRect(-pointSize/2, -1, pointSize, 3);
                debugContext.fillRect(-1, -pointSize/2, 3, pointSize);
            }
            else if (p.size.x !== undefined)
            {
                // rect
                const s = p.size.scale(scale).floor();
                const w = s.x, h = s.y;
                p.fill && debugContext.fillRect(-w/2|0, -h/2|0, w, h);
                debugContext.strokeRect(-w/2|0, -h/2|0, w, h);
            }
            else
            {
                // circle
                debugContext.beginPath();
                debugContext.arc(0, 0, abs(p.size)*scale/2, 0, 9); // a negative radius would throw
                p.fill && debugContext.fill();
                debugContext.stroke();
            }

            debugContext.restore();
        });
        debugContext.restore();

        // remove expired primitives
        debugPrimitives = debugPrimitives.filter(r=>r.timer<0);
    }

    if (debugObject)
    {
        const raycastHitPos = tileCollisionRaycast(debugObject.pos, mousePos);
        raycastHitPos && drawRect(debugTileCellCenter(raycastHitPos), vec2(1), rgb(0,1,1,.3), 0, false, false);
        drawLine(mousePos, debugObject.pos, .1, raycastHitPos ? rgb(1,0,0,.5) : rgb(0,1,0,.5), undefined, undefined, false, false);

        let debugText = 'mouse pos = ' + mousePos;
        if (tileCollisionLayers.length)
            debugText += '\nmouse collision = ' + tileCollisionGetData(mousePos);
        debugText += debugTileText(tileLayers);
        debugText += '\n\n--- object info ---\n';
        debugText += debugObject.toString();
        debugMouseText(debugText);
    }
    else if (debugOverlay && debugTiles)
    {
        // no object to pick, the tiles under the mouse on their own
        const text = debugTileText(tileLayers);
        text && debugMouseText('mouse pos = ' + mousePos + text);
    }

    {
        // draw debug overlay
        const fontSize = 20;
        const lineHeight = fontSize * 1.2 | 0;
        debugContext.save();
        debugContext.fillStyle = '#fff';
        debugContext.textAlign = 'left';
        debugContext.textBaseline = 'top';
        debugContext.font = fontSize + 'px monospace';
        debugTextShadow(debugContext);

        let x = 9, y = 0, h = lineHeight;
        if (debugOverlay)
        {
            debugContext.fillText(`${engineName} v${engineVersion}`, x, y += h/2 );
            debugContext.fillText('Time: ' + formatTime(time), x, y += h);
            debugContext.fillText('FPS: ' + averageFPS.toFixed(1) + (glEnable?' WebGL':' Canvas2D'), 
                x, y += h);
            debugContext.fillText('Objects: ' + engineObjects.length, x, y += h);
            debugContext.fillText('Draw Calls: ' + drawCount, x, y += h);
            debugContext.fillText('Primitives: ' + primitiveCount, x, y += h);
            debugContext.fillText('---------', x, y += h);
            debugContext.fillStyle = '#f00';
            debugContext.fillText('ESC: Debug Overlay', x, y += h);
            debugContext.fillStyle = debugPhysics ? '#f00' : '#fff';
            debugContext.fillText('1: Debug Physics', x, y += h);
            debugContext.fillStyle = debugTiles ? '#f00' : '#fff';
            debugContext.fillText('2: Debug Tiles' + debugTilesLabel(tileLayers), x, y += h);
            debugContext.fillStyle = debugParticles ? '#f00' : '#fff';
            debugContext.fillText('3: Debug Particles', x, y += h);
            debugContext.fillStyle = debugRaycast ? '#f00' : '#fff';
            debugContext.fillText('4: Debug Raycasts', x, y += h);
            debugContext.fillStyle = debugGamepads ? '#f00' : '#fff';
            debugContext.fillText('5: Debug Gamepads', x, y += h);
            debugContext.fillStyle = debugSound ? '#f00' : '#fff';
            debugContext.fillText('6: Debug Sound', x, y += h);
            debugContext.fillStyle = '#fff';
            debugContext.fillText('7: Save Screenshot', x, y += h);
            debugContext.fillText('8: Toggle Video Capture', x, y += h);
            debugContext.fillStyle = debugTweakables ? '#f00' : '#fff';
            debugContext.fillText('9: Tweakables', x, y += h);
            debugContext.fillStyle = levelEditor.isOpen ? '#f00' : '#fff';
            debugContext.fillText('0: Edit Level', x, y += h);
            for (const line of debugOverlayKeys)
            {
                // a key a debug plugin added, when it has something to say
                const key = line();
                if (!key) continue;
                debugContext.fillStyle = key.on ? '#f00' : '#fff';
                debugContext.fillText(key.text, x, y += h);
            }
            debugContext.fillStyle = '#fff';

            let keysPressed = '';
            let mousePressed = '';
            for (const i in inputData[0])
            {
                // read the input state itself, keyIsDown asserts on the numbered keys for..in gives as strings
                if (!(inputData[0][i] & 1))
                    continue;
                if (!isNaN(+i)) // mouse buttons are numbered, keys are named
                    mousePressed += i + ' ' ;
                else
                    keysPressed += i + ' ' ;
            }
            mousePressed && debugContext.fillText('Mouse: ' + mousePressed, x, y += h);
            keysPressed && debugContext.fillText('Keys: ' + keysPressed, x, y += h);

            // show gamepad buttons
            for (let i = 1; i < inputData.length; i++)
            {
                let buttonsPressed = '';
                if (inputData[i])
                for (const j in inputData[i])
                {
                    if (inputData[i][j] & 1)
                        buttonsPressed += j + ' ' ;
                }
                buttonsPressed && debugContext.fillText(`Gamepad ${i-1}: ` + buttonsPressed, x, y += h);
            }
        }
        else
        {
            debugContext.fillText(debugPhysics ? 'Debug Physics' : '', x, y += h);
            debugContext.fillText(debugTiles ? 'Debug Tiles' + debugTilesLabel(tileLayers) : '', x, y += h);
            debugContext.fillText(debugParticles ? 'Debug Particles' : '', x, y += h);
            debugContext.fillText(debugRaycast ? 'Debug Raycasts' : '', x, y += h);
            debugContext.fillText(debugGamepads ? 'Debug Gamepads' : '', x, y += h);
            debugContext.fillText(debugSound ? 'Debug Sound' : '', x, y += h);
        }

        debugContext.restore();
    }
    
    if (debugWatermark || debugOverlay)
    {
        // show fps stats display, the text state put back after for the game's next frame
        mainContext.save();
        mainContext.textAlign = 'right';
        mainContext.textBaseline = 'top';
        mainContext.font = '1em monospace';
        mainContext.fillStyle = '#000';
        const text = engineName + ' v' + engineVersion + ' / '
            + savedDrawCount + ' / ' + savedPrimitiveCount + ' / '
            + engineObjects.length + ' / ' + averageFPS.toFixed(1)
            + (glEnable ? ' GL' : ' 2D') ;
        mainContext.fillText(text, mainCanvasSize.x-3, 3);
        mainContext.fillStyle = '#fff';
        mainContext.fillText(text, mainCanvasSize.x-2, 2);
        mainContext.restore();
    }
}

function debugRenderPost() { debugVideoCaptureIsActive() && debugVideoCaptureUpdate(); }

///////////////////////////////////////////////////////////////////////////////
// video capture - records video and audio at 60 fps using MediaRecorder API

// internal variables used to capture video
let debugVideoCapture, debugVideoCaptureIcon;

/** Check if video capture is active
 *  @memberof Debug
 *  @return {boolean} */
function debugVideoCaptureIsActive() { return !!debugVideoCapture; }

/** Start capturing video
 *  @memberof Debug */
function debugVideoCaptureStart()
{
    ASSERT(!debugVideoCaptureIsActive(), 'Already capturing video!');

    // everything that can fail where recording is unsupported is in the try, a missing captureStream
    // or a MediaRecorder that refuses webm throws here and is cleaned up rather than stopping the game
    const captureTimer = new Timer(0, true);
    const chunks = [];
    let videoTrack, mediaRecorder, audioStreamDestination, silentAudioSource, audioTapNode;
    try
    {
        // setup captureStream to capture manually by passing 0
        const stream = mainCanvas.captureStream(0);
        videoTrack = stream.getVideoTracks()[0];
        videoTrack.applyConstraints({frameRate:frameRate}).catch(()=>{});

        // set up the media recorder
        mediaRecorder = new MediaRecorder(stream,
            {mimeType:'video/webm;codecs=vp8'});
        mediaRecorder.ondataavailable = (e)=> chunks.push(e.data);
        mediaRecorder.onstop = ()=>
        {
            const blob = new Blob(chunks, {type: 'video/webm'});
            const url = URL.createObjectURL(blob);
            saveDataURL(url, 'capture.webm', 1e3);
        };

        if (soundEnable)
        {
            // create silent audio source
            // fixes issue where video can not start recording without audio
            silentAudioSource = new ConstantSourceNode(audioContext, { offset: 0 });
            silentAudioSource.connect(audioMasterGain);
            silentAudioSource.start();

            // tap the end of the master chain so a master effect is in the recording
            // (a master effect swapped mid-capture drops the tap, the rest records silent)
            audioTapNode = audioMasterEffectOutput || audioMasterGain;
            audioStreamDestination = audioContext.createMediaStreamDestination();
            audioTapNode.connect(audioStreamDestination);
            for (const track of audioStreamDestination.stream.getAudioTracks())
                stream.addTrack(track); // add audio tracks to capture stream
        }

        // start recording
        mediaRecorder.start();
    }
    catch(e)
    {
        LOG('Video capture not supported in this browser!');
        videoTrack?.stop();
        silentAudioSource?.stop();
        if (audioStreamDestination)
        {
            // the tap may not have been made before the failure
            try { audioTapNode.disconnect(audioStreamDestination); }
            catch { }
        }
        return;
    }

    if (!debugVideoCaptureIcon)
    {
        // create recording icon to show it is capturing video
        debugVideoCaptureIcon = document.createElement('div');
        debugVideoCaptureIcon.style.position = 'absolute';
        debugVideoCaptureIcon.style.padding = '9px';
        debugVideoCaptureIcon.style.color = '#f00';
        debugVideoCaptureIcon.style.font = '50px monospace';
        document.body.appendChild(debugVideoCaptureIcon);
    }
    // show recording icon, only once recording has started
    debugVideoCaptureIcon.textContent = '';
    debugVideoCaptureIcon.style.display = '';

    LOG('Video capture started.');

    // save debug video info
    debugVideoCapture =
    {
        mediaRecorder,
        captureTimer,
        videoTrack,
        silentAudioSource,
        audioStreamDestination,
        audioTapNode
    };
}

/** Stop capturing video and save to disk
 *  @memberof Debug */
function debugVideoCaptureStop()
{
    ASSERT(debugVideoCaptureIsActive(), 'Not capturing video!');

    // stop recording
    LOG(`Video capture ended. ${debugVideoCapture.captureTimer.get().toFixed(2)} seconds recorded.`);
    debugVideoCaptureIcon.style.display = 'none';
    debugVideoCapture.silentAudioSource?.stop();
    debugVideoCapture.mediaRecorder?.stop();
    debugVideoCapture.videoTrack?.stop();
    if (debugVideoCapture.audioStreamDestination)
    {
        // the tap is already gone if the master effect changed during the capture
        try { debugVideoCapture.audioTapNode.disconnect(debugVideoCapture.audioStreamDestination); }
        catch { }
    }
    debugVideoCapture = undefined;
}

// update video capture, called automatically by engine
function debugVideoCaptureUpdate()
{
    ASSERT(debugVideoCaptureIsActive(), 'Not capturing video!');

    // save the video frame
    combineCanvases();
    debugVideoCapture.videoTrack.requestFrame();
    debugVideoCaptureIcon.textContent = '● REC '
        + formatTime(debugVideoCapture.captureTimer.get());
}

///////////////////////////////////////////////////////////////////////////////
// debug utility functions

// make color constants immutable with debug assertions
function debugProtectConstant(obj)
{
    if (debug)
    {
        // get properties and store original values
        const props = Object.keys(obj), values = {};
        props.forEach(prop => values[prop] = obj[prop]);
        
        // replace with getters/setters that assert
        props.forEach(prop =>
        {
            Object.defineProperty(obj, prop, {
                get: ()=> values[prop],
                set: (value)=> 
                {
                    ASSERT(false, `Cannot modify engine constant. Attempted to set constant (${obj}) property '${prop}' to '${value}'.`);
                },
                enumerable: true
            });
        });
    }
    
    // freeze the object to prevent adding new properties
    return Object.freeze(obj);
}

///////////////////////////////////////////////////////////////////////////////
// Input capture: the free camera and the 3D level editor take the keyboard and mouse, so the game under them reads
// every key and mouse button as up, and no mouse movement or wheel; gamepads are left to the game

let inputCaptureOn = false;      // something has taken the keyboard and mouse
let inputCaptureReading = false; // it is reading them now
let inputCaptureDeltaScreen, inputCaptureWheel = 0; // this update's mouse movement and wheel, for it alone

// the game let go of a captured mouse itself, with pointerLockExit, since the debug tools last looked: a capture
// that is lost without it is the browser's doing, which is how Chrome takes Escape
let inputLockLetGo = false;
function inputLockExit() { inputLockLetGo = true; }

// the keys debug plugins add to the overlay's list, each a function that gives {text, on} or nothing to show
const debugOverlayKeys = [];

// take the keyboard and mouse from the game, or hand them back
function inputCapture(on=true)
{
    inputCaptureOn = !!on;
    inputCaptureDeltaScreen = vec2();
    inputCaptureWheel = 0;
}

// read the input as the one that took it, keyIsDown and the rest work as always inside read
function inputCaptureRead(read)
{
    const was = inputCaptureReading;
    inputCaptureReading = true;
    try { return read(); }
    finally { inputCaptureReading = was; }
}

// if a read of the keyboard and mouse, device 0, is the game's while they are taken
function inputCaptureHides(device) { return inputCaptureOn && !inputCaptureReading && !device; }

// called first in inputUpdate: the mouse movement and wheel go to the one that took the input
function inputCaptureMouse()
{
    if (!inputCaptureOn) return;
    inputCaptureDeltaScreen = mouseDeltaScreen;
    inputCaptureWheel = mouseWheel;
    mouseDeltaScreen = vec2();
    mouseWheel = 0;
}

/**
 * LittleJS Math Classes and Functions
 * - Comprehensive math utilities for game development
 * - Vector2 class for 2D positions, directions, and math operations
 * - Color class for RGBA colors with interpolation and manipulation
 * - RandomGenerator for seeded pseudo-random number generation
 * - Math shortcuts (PI, abs, floor, ceil, min, max, sin, cos, etc.)
 * - Interpolation functions (lerp, smoothStep, percent)
 * - Clamping, wrapping, and modulo operations
 * - Angle utilities with wrap-around support
 * - Collision detection (overlapping, intersection, line tests)
 * - Random number generation and seeding
 * - Type checking utilities
 * @namespace Math
 */

/** The value of PI
 *  @type {number}
 *  @default Math.PI
 *  @memberof Math */
const PI = Math.PI;

/** Returns absolute value of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const abs = Math.abs;

/** Returns floored value of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const floor = Math.floor;

/** Returns ceiled value of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const ceil = Math.ceil;

/** Returns rounded value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const round = Math.round;

/** Returns lowest value passed in
 *  @param {...number} values
 *  @return {number}
 *  @memberof Math */
const min = Math.min;

/** Returns highest value passed in
 *  @param {...number} values
 *  @return {number}
 *  @memberof Math */
const max = Math.max;

/** Returns the sign of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const sign = (x) => Math.sign(x);

/** Returns hypotenuse of values passed in
 *  @param {...number} values
 *  @return {number}
 *  @memberof Math */
const hypot = (...values) => Math.hypot(...values);

/** Returns log2 of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const log2 = (x) => Math.log2(x);

/** Returns sin of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const sin = Math.sin;

/** Returns cos of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const cos = Math.cos;

/** Returns tan of value passed in
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const tan = Math.tan;

/** Returns atan2 of values passed in
 *  @param {number} y
 *  @param {number} x
 *  @return {number}
 *  @memberof Math */
const atan2 = Math.atan2;

/** Returns first param modulo the second param, but adjusted so negative numbers work as expected
 *  @param {number} dividend
 *  @param {number} [divisor]
 *  @return {number}
 *  @memberof Math */
function mod(dividend, divisor=1) { return ((dividend % divisor) + divisor) % divisor; }

/** Clamps the value between max and min
 *  @param {number} value
 *  @param {number} [min]
 *  @param {number} [max]
 *  @return {number}
 *  @memberof Math */
function clamp(value, min=0, max=1) { return value < min ? min : value > max ? max : value; }

/** Returns what percentage the value is between valueA and valueB, clamped to 0-1
 *  @param {number} value
 *  @param {number} valueA
 *  @param {number} valueB
 *  @return {number}
 *  @memberof Math */
function percent(value, valueA, valueB)
{ return (valueB-=valueA) ? clamp((value-valueA)/valueB) : 0; }

/** Linearly interpolates between values passed in using percent, percent is clamped to 0-1
 *  @param {number} valueA
 *  @param {number} valueB
 *  @param {number} percent
 *  @return {number}
 *  @memberof Math */
function lerp(valueA, valueB, percent)
{ return valueA + clamp(percent) * (valueB-valueA); }

/** Gets percent between percentA and percentB and linearly interpolates between lerpA and lerpB
 *  A shortcut for lerp(lerpA, lerpB, percent(value, percentA, percentB))
 *  @param {number} value
 *  @param {number} percentA
 *  @param {number} percentB
 *  @param {number} lerpA
 *  @param {number} lerpB
 *  @return {number}
 *  @memberof Math */
function percentLerp(value, percentA, percentB, lerpA, lerpB)
{ return lerp(lerpA, lerpB, percent(value, percentA, percentB)); }

/** Returns signed wrapped distance between the two values passed in
 *  @param {number} valueA
 *  @param {number} valueB
 *  @param {number} [wrapSize]
 *  @return {number}
 *  @memberof Math */
function distanceWrap(valueA, valueB, wrapSize=1)
{
    ASSERT(wrapSize > 0, 'distanceWrap wrapSize must be > 0');
    const d = (valueA - valueB) % wrapSize;
    return d*2 % wrapSize - d;
}

/** Linearly interpolates between values passed in with wrapping, percent is clamped to 0-1
 *  @param {number} valueA
 *  @param {number} valueB
 *  @param {number} percent
 *  @param {number} [wrapSize]
 *  @return {number}
 *  @memberof Math */
function lerpWrap(valueA, valueB, percent, wrapSize=1)
{ return valueA + clamp(percent) * distanceWrap(valueB, valueA, wrapSize); }

/** Returns signed wrapped distance between the two angles passed in
 *  @param {number} angleA
 *  @param {number} angleB
 *  @return {number}
 *  @memberof Math */
function distanceAngle(angleA, angleB) { return distanceWrap(angleA, angleB, 2*PI); }

/** Linearly interpolates between the angles passed in with wrapping, percent is clamped to 0-1
 *  @param {number} angleA
 *  @param {number} angleB
 *  @param {number} percent
 *  @return {number}
 *  @memberof Math */
function lerpAngle(angleA, angleB, percent) { return lerpWrap(angleA, angleB, percent, 2*PI); }

/** Applies smoothstep function to the percentage value, clamped between 0 and 1
 *  @param {number} percent
 *  @return {number}
 *  @memberof Math */
function smoothStep(percent)
{
    percent = clamp(percent);
    return percent * percent * (3 - 2 * percent);
}

/** Checks if the value passed in is a power of two
 *  @param {number} value
 *  @return {boolean}
 *  @memberof Math */
function isPowerOfTwo(value) { return value > 0 && value % 1 === 0 && 2**round(log2(value)) === value; } // any size, not only 32 bits

/** Returns the nearest whole power of two not less than the value, 1 for a value of 1 or less
 *  @param {number} value
 *  @return {number}
 *  @memberof Math */
function nearestPowerOfTwo(value)
{
    const power = 2**ceil(log2(max(value, 1)));
    return power < value ? power * 2 : power; // log2 of a value just above a power can round down to it
}

/** Returns true if two axis aligned bounding boxes are overlapping
 *  this can be used for simple collision detection between objects
 *  @param {Vector2} posA - Center of box A
 *  @param {Vector2} sizeA - Size of box A
 *  @param {Vector2} posB - Center of box B
 *  @param {Vector2} [sizeB=vec2()] - Size of box B, uses a point if undefined
 *  @return {boolean} - True if overlapping
 *  @memberof Math */
function isOverlapping(posA, sizeA, posB, sizeB=vec2())
{
    const dx = (posA.x - posB.x)*2;
    const dy = (posA.y - posB.y)*2;
    const sx = sizeA.x + sizeB.x;
    const sy = sizeA.y + sizeB.y;
    // symmetric so isOverlapping(A,B) === isOverlapping(B,A) at touching edges
    return abs(dx) < sx && abs(dy) < sy;
}

/** Returns true if a line segment is intersecting an axis aligned box
 *  @param {Vector2} start - Start of raycast
 *  @param {Vector2} end   - End of raycast
 *  @param {Vector2} pos   - Center of box
 *  @param {Vector2} size  - Size of box
 *  @return {boolean}      - True if intersecting
 *  @memberof Math */
function isIntersecting(start, end, pos, size)
{
    // Liang-Barsky algorithm
    const boxMin = pos.subtract(size.scale(.5));
    const boxMax = boxMin.add(size);
    const delta = end.subtract(start);
    const a = start.subtract(boxMin);
    const b = start.subtract(boxMax);
    const p = [-delta.x, delta.x, -delta.y, delta.y];
    const q = [a.x, -b.x, a.y, -b.y];
    let tMin = 0, tMax = 1;
    for (let i = 4; i--;)
    {
        if (p[i])
        {
            const t = q[i] / p[i];
            if (p[i] < 0)
            {
                if (t > tMax) return false;
                tMin = max(t, tMin);
            }
            else
            {
                if (t < tMin) return false;
                tMax = min(t, tMax);
            }
        }
        else if (q[i] < 0)
            return false;
    }

    return true;
}

///////////////////////////////////////////////////////////////////////////////
// Collision helpers, none of them change anything that is passed in
// Boxes are axis aligned and centered on pos with a full size, like drawRect
// Each returns how far to move the first shape to get it clear, or undefined when they are not touching
// isOverlapping answers whether two boxes touch, these answer how far out

/** Returns the vector to move circle A by so it no longer overlaps circle B, or undefined
 *  @param {Vector2} posA - Center of circle A
 *  @param {number} radiusA
 *  @param {Vector2} posB - Center of circle B
 *  @param {number} radiusB
 *  @return {Vector2|undefined}
 *  @memberof Math */
function collideCircleCircle(posA, radiusA, posB, radiusB)
{
    const d = posA.subtract(posB);
    const r = radiusA + radiusB;
    const dist = d.length();
    if (dist >= r)
        return undefined;
    return d.normalize(r - dist); // coincident centers normalize to straight up
}

/** Returns the vector to move a circle out of an axis aligned box, or undefined
 *  @param {Vector2} pos - Center of the circle
 *  @param {number} radius
 *  @param {Vector2} boxPos - Center of the box
 *  @param {Vector2} boxSize - Full size of the box
 *  @return {Vector2|undefined}
 *  @memberof Math */
function collideCircleBox(pos, radius, boxPos, boxSize)
{
    const h = boxSize.scale(.5);
    const closest = vec2(clamp(pos.x, boxPos.x - h.x, boxPos.x + h.x), clamp(pos.y, boxPos.y - h.y, boxPos.y + h.y));
    const d = pos.subtract(closest), distSq = d.lengthSquared();
    if (distSq)
        return distSq >= radius*radius ? undefined : d.normalize(radius - distSq**.5);

    // center is inside the box, push out along the axis of least penetration
    const offset = pos.subtract(boxPos);
    return pushOutAxis(offset, h.x - abs(offset.x), h.y - abs(offset.y), radius);
}

/** Returns the vector to move box A by so it no longer overlaps box B, the shortest way out, or undefined
 *  - isOverlapping is the yes or no version of this
 *  @param {Vector2} posA - Center of box A
 *  @param {Vector2} sizeA - Full size of box A
 *  @param {Vector2} posB - Center of box B
 *  @param {Vector2} sizeB - Full size of box B
 *  @return {Vector2|undefined}
 *  @memberof Math */
function collideBoxBox(posA, sizeA, posB, sizeB)
{
    const d = posA.subtract(posB);
    const overlapX = (sizeA.x + sizeB.x)/2 - abs(d.x);
    const overlapY = (sizeA.y + sizeB.y)/2 - abs(d.y);
    if (overlapX <= 0 || overlapY <= 0)
        return undefined;
    return pushOutAxis(d, overlapX, overlapY);
}

// the axis with the smallest penetration, pointing the way d does, with extra distance added
function pushOutAxis(d, penX, penY, extra=0)
{
    const s = (v)=> v >= 0 ? 1 : -1; // sign() gives 0 on a tie, which would be no push
    return penX <= penY ? vec2(s(d.x)*(penX + extra), 0) : vec2(0, s(d.y)*(penY + extra));
}

/** Returns an oscillating wave between 0 and amplitude with frequency of 1 Hz by default
 *  @param {number} [frequency] - Frequency of the wave in Hz
 *  @param {number} [amplitude] - Amplitude (max height) of the wave
 *  @param {number} [t=time]    - Value to use for time of the wave
 *  @param {number} [offset]    - Value to use for time offset of the wave
 *  @param {number} [type]      - Wave type: 0=sine, 1=triangle, 2=square, 3=sawtooth
 *  @return {number}            - Value waving between 0 and amplitude
 *  @memberof Math */
function oscillate(frequency=1, amplitude=1, t=time, offset=0, type=0)
{
    const phase = mod(offset + t*frequency, 1);
    let value;
    
    if (type === 1) // triangle, from 0 up and back like the others
        value = 1 - 2 * abs(2 * phase - 1);
    else if (type === 2) // square
        value = phase < .5 ? -1 : 1;
    else if (type === 3) // sawtooth
        value = 2 * phase - 1;
    else // sine
        value = -cos(phase * 2*PI);
    return amplitude/2 * (value + 1);
}

/**
 * Check if object is a valid number, not NaN or undefined, but it may be infinite
 * @param {any} n
 * @return {boolean}
 * @memberof Math */
function isNumber(n) { return typeof n === 'number' && !isNaN(n); }

/**
 * Check if a value is stringifiable — i.e. it has a toString that returns
 * a string. Use this for ASSERTs and inputs that will be coerced to text;
 * use `typeof x === 'string'` inline if you need strict-string semantics.
 * - Returns true for strings, numbers, and most objects
 * - Returns false for null and undefined
 * @param {any} s
 * @return {boolean}
 * @memberof Math */
function isStringLike(s) { return s != null && typeof s.toString === 'function' && typeof s.toString() === 'string'; }

/**
 * Check if object is an array
 * @param {any} a
 * @return {a is Array<any>}
 * @memberof Math */
function isArray(a) { return Array.isArray(a); }

/**
 * @callback LineTestFunction - Checks if a position is colliding
 * @param {Vector2} pos
 * @memberof Math
 */

/**
 * Casts a ray and returns position of the first collision found, or undefined if none are found
 * @param {Vector2} posStart
 * @param {Vector2} posEnd
 * @param {LineTestFunction} testFunction - Check if colliding
 * @param {Vector2} [normal] - Optional vector to store the normal
 * @return {Vector2|undefined} - Position of the collision or undefined if none found
 * @memberof Math */
function lineTest(posStart, posEnd, testFunction, normal)
{
    ASSERT(isVector2(posStart), 'posStart must be a vec2');
    ASSERT(isVector2(posEnd), 'posEnd must be a vec2');
    ASSERT(typeof testFunction === 'function', 'testFunction must be a function');
    ASSERT(!normal || isVector2(normal), 'normal must be a vec2');

    // get ray direction and length
    const dx = posEnd.x - posStart.x;
    const dy = posEnd.y - posStart.y;
    const totalLength = (dx*dx + dy*dy)**.5;
    if (!totalLength) return;

    // current integer cell we are in, the one below a whole start heading down the grid, which it goes into
    const pos = posStart.floor();
    if (dx < 0 && pos.x === posStart.x) --pos.x;
    if (dy < 0 && pos.y === posStart.y) --pos.y;

    // normalize ray direction
    const dirX = dx / totalLength;
    const dirY = dy / totalLength;

    // step direction in grid
    const stepX = sign(dirX);
    const stepY = sign(dirY);

    // distance along the ray to cross one full cell in X or Y
    const tDeltaX = dirX ? abs(1 / dirX) : Infinity;
    const tDeltaY = dirY ? abs(1 / dirY) : Infinity;

    // distance along the ray from start to the first grid boundary
    const nextGridX = stepX > 0 ? pos.x + 1 : pos.x;
    const nextGridY = stepY > 0 ? pos.y + 1 : pos.y;
    const tMaxX = dirX ? (nextGridX - posStart.x) / dirX : Infinity;
    const tMaxY = dirY ? (nextGridY - posStart.y) / dirY : Infinity;

    // use line drawing algorithm to test for collisions
    let t = 0, tX = tMaxX, tY = tMaxY, wasX = tDeltaX < tDeltaY;
    while (t < totalLength)
    {
        if (testFunction(pos))
        {
            // set hit point
            const hitPos = vec2(posStart.x + dirX*t, posStart.y + dirY*t);

            // ensure result is inside the tile
            const e = 1e-9;
            const hitPosFloor = hitPos.floor();
            if (hitPosFloor.x < pos.x)
                hitPos.x = pos.x;
            else if (hitPosFloor.x > pos.x)
                hitPos.x = pos.x + 1 - e;
            if (hitPosFloor.y < pos.y)
                hitPos.y = pos.y;
            else if (hitPosFloor.y > pos.y) 
                hitPos.y = pos.y + 1 - e;

            // set normal
            if (normal)
                wasX ? normal.set(-stepX,0) : normal.set(0,-stepY);
            return hitPos;
        }

        // advance to the next grid boundary
        if (wasX = tX < tY)
        {
            pos.x += stepX;
            t = tX;
            tX += tDeltaX;
        }
        else
        {
            pos.y += stepY;
            t = tY;
            tY += tDeltaY;
        }
    }
}

