/**
 * Seeded random number generator
 * - Can be used to create a deterministic random number sequence
 * - The seed works as a 32 bit integer, and one that is 0 as an integer
 *   (0, a fraction between -1 and 1, or a multiple of 2**32) uses the default seed
 * @memberof Engine
 * @example
 * let r = new RandomGenerator(123); // random number generator with seed 123
 * let a = r.float();                // random value between 0 and 1
 * let b = r.int(10);                // random integer between 0 and 9
 * r.seed = 123;                     // reset the seed
 * let c = r.float();                // the same value as a
 */
class RandomGenerator
{
    /** Create a random number generator with the seed passed in
     *  @param {number} [seed] - Starting seed, 0 as an integer uses the default seed */
    constructor(seed = 123456789)
    {
        /** @property {number} - random seed, set it to reseed */
        this.seed = seed;
    }

    /** Returns a seeded random value between the two values passed in
    *  @param {number} [valueA]
    *  @param {number} [valueB]
    *  @return {number} */
    float(valueA=1, valueB=0)
    {
        // xorshift stays at 0 once there, so a seed that is 0 as an integer uses the default seed
        this.seed = this.seed|0 || 123456789;

        // xorshift algorithm steps the seed
        this.seed ^= this.seed << 13;
        this.seed ^= this.seed >>> 17;
        this.seed ^= this.seed << 5;

        // the value is the seed scrambled by a hash, since xorshift barely mixes a small seed in its first steps,
        // so nearby seeds would start with nearly the same values; the seed itself steps as before
        return valueB + (valueA - valueB) * noiseHash(this.seed);
    }

    /** Returns a floored seeded random value between the two values passed in
    *  @param {number} valueA
    *  @param {number} [valueB]
    *  @return {number} */
    int(valueA, valueB=0) { return floor(this.float(valueA, valueB)); }

    /** Randomly returns true or false given the chance of true passed in
    *  @param {number} [chance]
    *  @return {boolean} */
    bool(chance=.5) { return this.float() < chance; }

    /** Randomly returns either -1 or 1 deterministically
    *  @return {number} */
    sign() { return this.float() > .5 ? 1 : -1; }

    /** Returns a seeded random value between the two values passed in with a random sign
    *  @param {number} [valueA]
    *  @param {number} [valueB]
    *  @return {number} */
    floatSign(valueA=1, valueB=0)
    {
        const lo = min(valueA, valueB);
        const hi = max(valueA, valueB);
        const d = hi - lo;
        const e = this.float(d*2);
        return e < d ? lo + e : d - lo - e;
    }

    /** Returns a random angle between -PI and PI
    *  @return {number} */
    angle() { return this.float(-PI, PI); }

    /** Returns a seeded vec2 with each component between the two values passed in
    *  - A point in a square, not a random direction like randVec2, see direction for that
    *  @param {number} [valueA]
    *  @param {number} [valueB]
    *  @return {Vector2} */
    vec2(valueA=1, valueB=0)
    { return vec2(this.float(valueA, valueB), this.float(valueA, valueB)); }

    /** Returns a seeded Vector2 pointing a random way with the length passed in, the twin of randVec2
    *  @param {number} [length]
    *  @return {Vector2} */
    direction(length=1) { return new Vector2().setAngle(this.float(2*PI), length); }

    /** Returns a random color between the two passed in colors, combine components if linear
    *  @param {Color}   [colorA=WHITE]
    *  @param {Color}   [colorB=BLACK]
    *  @param {boolean} [linear]
    *  @return {Color} */
    randColor(colorA=new Color, colorB=new Color(0,0,0,1), linear=false)
    {
        return linear ? colorA.lerp(colorB, this.float()) :
            new Color(
                this.float(colorA.r,colorB.r), 
                this.float(colorA.g,colorB.g), 
                this.float(colorA.b,colorB.b), 
                this.float(colorA.a,colorB.a));
    }

    /** Returns a new color that has each component randomly adjusted
     * @param {Color} color
     * @param {number} [amount]
     * @param {number} [alphaAmount]
     * @return {Color} */
    mutateColor(color, amount=.05, alphaAmount=0)
    {
        ASSERT_NUMBER_VALID(amount);
        ASSERT_NUMBER_VALID(alphaAmount);
        return new Color
        (
            color.r + this.float(amount, -amount),
            color.g + this.float(amount, -amount),
            color.b + this.float(amount, -amount),
            color.a + this.float(alphaAmount, -alphaAmount)
        ).clamp();
    }
}

