// the default loading screen: Loading over a bar across the middle, filled by the part of the loads done
function drawLoadingScreen(progress)
{
    const x = mainContext, w = mainCanvasSize.x, h = mainCanvasSize.y;
    const barWidth = min(w * .6, 400), barHeight = 12, left = (w - barWidth) / 2, top = h / 2;
    x.save();
    x.fillStyle = '#000';
    x.fillRect(0, 0, w, h);
    x.fillStyle = x.strokeStyle = '#fff';
    x.font = '28px ' + fontDefault;
    x.textAlign = 'center';
    x.textBaseline = 'bottom';
    x.fillText('Loading', w / 2, top - 16);
    x.lineWidth = 2;
    x.strokeRect(left, top, barWidth, barHeight);
    x.fillRect(left, top, barWidth * clamp(progress), barHeight);
    x.restore();
}

function drawEngineLogo(t)
{
    const blackAndWhite = 0;
    const showName = 1;

    // LittleJS Logo and Splash Screen
    // the splash runs before the engine loop so size the canvas here too
    engineUpdateCanvas();
    const x = mainContext;
    const w = mainCanvasSize.x;
    const h = mainCanvasSize.y;
    {
        // background
        const p3 = percent(t, 1, .8);
        const p4 = percent(t, 0, .5);
        const g = x.createRadialGradient(w/2,h/2,0,w/2,h/2,hypot(w,h)*.6);
        g.addColorStop(0,hsl(0,0,lerp(0,p3/2,p4),p3).toString());
        g.addColorStop(1,hsl(0,0,0,p3).toString());
        x.save();
        x.fillStyle = g;
        x.fillRect(0,0,w,h);
    }
    const gradient = (X1,Y1,X2,Y2,C,S=1)=>
    {
        if (C >= 0)
        {
            if (blackAndWhite)
                x.fillStyle = '#fff';
            else
            {
                const g = x.fillStyle = x.createLinearGradient(X1,Y1,X2,Y2);
                g.addColorStop(0,color(C,2));
                g.addColorStop(1,color(C,1));
            }
        }
        else
            x.fillStyle = '#000';
        C >= -1 ? (x.fill(), S && x.stroke()) : x.stroke();
    }
    const circle = (X,Y,R,A=0,B=2*PI,C,S)=>
    {
        x.beginPath();
        x.arc(X,Y,R,p*A,p*B);
        gradient(X,Y-R,X,Y+R,C,S);
    }
    const rect = (X,Y,W,H,C)=>
    {
        x.beginPath();
        x.rect(X,Y,W,H*p);
        gradient(X,Y+H,X+W,Y,C);
    }
    const poly = (points,C,Y,H)=>
    {
        x.beginPath();
        for (const p of points)
            x.lineTo(p.x, p.y);
        x.closePath();
        gradient(0, Y, 0, Y+H,C);
    }
    const color = (c,l)=> l?`hsl(${[.95,.56,.13][c%3]*360} 99%${[0,50,75][l]}%)`:'#000';

    // center and fit to screen
    const alpha = oscillate(1,1,t);
    const p = percent(alpha, .1, .5);
    const size = min(6, min(w,h)/99);
    x.translate(w/2,h/2);
    x.scale(size,size);
    x.translate(-40,-35);
    p < 1 && x.setLineDash([99*p,99]);
    x.lineJoin = x.lineCap = 'round';
    x.lineWidth = .1 + p*1.9;
    //x.strokeStyle='#fff7';

    if (showName)
    {
        // engine name text
        const Y = 54;
        const s = 'LittleJS';
        x.font = '900 15.5px arial';
        x.lineWidth = .1+p*3.9;
        x.textAlign = 'center';
        x.textBaseline = 'top';
        rect(11,Y+1,59,8*p,-1);
        x.beginPath();

        let w2 = 0;
        for (let i=0;i<s.length;++i)
            w2 += x.measureText(s[i]).width;
        for (let j=2;j--;)
        for (let i=0,X=40-w2/2;i<s.length;++i)
        {
            const w = x.measureText(s[i]).width, X2 = X+w/2;
            gradient(X2,Y,X2+2,Y+13,i>5?1:0);
            x[j?'strokeText':'fillText'](s[i],X2,Y+.5,17*p);
            X += w;
        }

        x.lineWidth = .1 + p*1.9;
        rect(3,Y,73,0); // bottom
    }

    rect(7,15,26,-7,0);   // cab top
    rect(25,15,8,25,-1);  // cab front
    rect(10,40,15,-25,1); // cab back
    rect(14,21,7,9,2);    // cab window
    rect(38,20,6,-6,2);   // little stack

    // big stack
    rect(49,20,10,-6,0);
    const stackPoints = [vec2(44,8),vec2(64,8),vec2(59,8+6*p),vec2(49,8+6*p)];
    poly(stackPoints,2,8,6*p);
    rect(44,8,20,-7,0);

    // engine
    for (let i=5;i--;) circle(59-i*6*p,30,10,0,2*PI,1,0);
    circle(59,30,4,0,7,2); // light

    // engine outline
    rect(35,20,24,0);  // top
    circle(59,30,10);  // front
    circle(47,30,10,PI/2,PI*3/2); // middle
    circle(35,30,10,PI/2,PI*3/2); // back
    rect(7,40,13,7,-1);   // bottom back
    rect(17,40,43,14,-1); // bottom center

    // wheels
    for (let i=3;i--;) for (let j=2;j--;) circle(17+15*i,47,j?7:1,0,2*PI,2);

    // cowcatcher
    for (let i=2;i--;)
    {
        let w=6, s=7, o=53+w*p*i
        const points = [vec2(o+s,54),vec2(o,40),vec2(o+w*p,40),vec2(o+s+w*p,54)];
        poly(points,0,40,14);
    }

    x.restore();
}

/**
 * LittleJS Medal System
 * - Achievement/trophy system for games
 * - Medal class with name, description, icon, and unlock tracking
 * - Automatic saving to local storage, unless a service like Newgrounds holds the medal (see Medal.isLocal)
 * - Visual display queue with slide-in notifications
 * - The Newgrounds plugin extends it with NewgroundsMedal, held on the server while logged in
 * - Setting debugMedals = true in the game code before medalsInit skips the load and the save, and in the debug build logs the Newgrounds traffic; it is not exported, so only a script tag build can set it
 * @namespace Medals
 */

let debugMedals = false; // see the header

///////////////////////////////////////////////////////////////////////////////
// Medals settings

/** How long to show medals for in seconds
 *  @type {number}
 *  @default
 *  @memberof Settings */
let medalDisplayTime = 5;

/** How quickly to slide on/off medals in seconds
 *  @type {number}
 *  @default
 *  @memberof Settings */
let medalDisplaySlideTime = .5;

/** Size of medal display
 *  @type {Vector2}
 *  @default Vector2(640,80)
 *  @memberof Settings */
let medalDisplaySize = vec2(640, 80);

/** Set to stop medals from being unlockable (like if cheats are enabled)
 *  @type {boolean}
 *  @default
 *  @memberof Settings */
let medalsPreventUnlock = false;

/** List of all medals
 *  @type {Object<number, Medal>}
 *  @memberof Medals */
const medals = {};

// Engine internal variables not exposed to documentation
let medalsDisplayQueue = [], medalsSaveName, medalsDisplayTimeLast, medalsRenderAdded;

///////////////////////////////////////////////////////////////////////////////

/** Initialize medals with a save name used for storage
 *  - Call this after creating all medals
 *  - Loads which medals are unlocked from the save, and writes the catalog back
 *  - A medal a service like Newgrounds holds is left as it is, see Medal.isLocal
 *  @param {string} saveName - The localStorage key the medals are kept under, a different one from the game's own
 *  readSaveData and writeSaveData, or each would overwrite the other
 *  @memberof Medals */
function medalsInit(saveName)
{
    medalsSaveName = saveName;
    medalsLoad();

    // add the medal display once, however often this is called
    if (!medalsRenderAdded)
        engineAddPlugin(undefined, medalsRender);
    medalsRenderAdded = true;
}

// check which local medals are unlocked in the save, and write the catalog back
function medalsLoad()
{
    // the saved unlocks of medals not made yet stay for them, a medal made late or behind a flag keeps its unlock
    if (debugMedals || !medalsSaveName) return;
    const saved = readSaveData(medalsSaveName);
    ASSERT(Object.keys(saved).every(key=> isNumber(+key)),
        'the medals save name holds other data, give medalsInit a name of its own');
    medalsForEach(medal=> {
        if (medal.isLocal())
            medal.unlocked = !!saved[medal.id]?.unlocked;
    });
    medalsSave();
}

// show the first medal in the queue, sliding it on and off
function medalsRender()
{
    if (!medalsDisplayQueue.length) return;

    // update first medal in queue
    const medal = medalsDisplayQueue[0];
    const elapsed = timeReal - medalsDisplayTimeLast;
    if (!medalsDisplayTimeLast)
        medalsDisplayTimeLast = timeReal;
    else if (elapsed > medalDisplayTime)
    {
        medalsDisplayTimeLast = 0;
        medalsDisplayQueue.shift();
    }
    else
    {
        // slide on/off medals, the slides share the display time when it is short
        const slideTime = min(medalDisplaySlideTime, medalDisplayTime/2);
        const slideOffTime = medalDisplayTime - slideTime;
        const hidePercent =
            elapsed < slideTime ? 1 - elapsed / slideTime :
            elapsed > slideOffTime ? (elapsed - slideOffTime) / slideTime : 0;
        medal.render(hidePercent);
    }
}

/**
 *  @callback MedalCallbackFunction - Function that processes a medal
 *  @param {Medal} medal
 *  @memberof Medals
 */

/** Calls a function for each medal
 *  @param {MedalCallbackFunction} callback
 *  @memberof Medals */
function medalsForEach(callback)
{ Object.values(medals).forEach(medal=> callback(medal)); }

/** Reset all medals to locked and persist the cleared catalog
 *  - A medal a service like Newgrounds holds is left alone, the service has it
 *  @memberof Medals */
function medalsReset()
{
    medalsForEach(medal=> medal.isLocal() && (medal.unlocked = false));
    if (medalsSaveName && !debugMedals)
    {
        // the saved unlocks of medals not made yet are cleared too, they are read when those medals are made
        const saved = readSaveData(medalsSaveName);
        for (const id in saved)
            if (!medals[id] && saved[id] && typeof saved[id] === 'object')
                saved[id].unlocked = false;
        writeSaveData(medalsSaveName, saved);
    }
    medalsSave();
}

// write the local medals to the save, keeping the entries of medals a service holds
function medalsSave()
{
    if (debugMedals || !medalsSaveName) return;
    // every saved entry stays: a medal not made this time keeps its unlock for when it is, since a player given a
    // medal back is better than one who lost it, and what is not a medal is the game's own, under the same name
    const saved = readSaveData(medalsSaveName);
    const data = {...saved};
    medalsForEach(medal=> {
        if (!medal.isLocal())
        {
            // a service holds this medal, its entry stays as it was for when it is local again
            if (saved[medal.id]) data[medal.id] = saved[medal.id];
            return;
        }
        const entry = {
            name: medal.name,
            description: medal.description,
            icon: medal.icon,
            unlocked: medal.unlocked,
        };
        if (medal.image) entry.src = medal.image.src;
        data[medal.id] = entry;
    });
    writeSaveData(medalsSaveName, data);
}

///////////////////////////////////////////////////////////////////////////////

/**
 * Medal - Tracks an unlockable medal
 * @memberof Medals
 * @example
 * // create a medal
 * const medal_example = new Medal(0, 'Example Medal', 'More info about the medal goes here.', '🎖️');
 *
 * // initialize medals
 * medalsInit('Example Game');
 *
 * // unlock the medal
 * medal_example.unlock();
 */
class Medal
{
    /** Create a medal and add it to the list of medals
     *  @param {number} id            - The unique identifier of the medal
     *  @param {string} name          - Name of the medal
     *  @param {string} [description] - Description of the medal
     *  @param {string} [icon]        - Icon for the medal
     *  @param {string} [src]         - Image location for the medal
     */
    constructor(id, name, description='', icon='🏆', src)
    {
        ASSERT(isNumber(id) && id >= 0 && !medals[id], 'medal id must be a unique number of 0 or more');

        /** @property {number} - The unique identifier of the medal */
        this.id = id;

        /** @property {string} - Name of the medal */
        this.name = name;

        /** @property {string} - Description of the medal */
        this.description = description;

        /** @property {string} - Icon for the medal */
        this.icon = icon;

        /** @property {boolean} - Is the medal unlocked? */
        this.unlocked = false;

        /** @property {HTMLImageElement|undefined} - Source image for the medal icon, if any
         *  @type {HTMLImageElement|undefined} */
        this.image = undefined;
        if (src)
            (this.image = new Image).src = src;

        // add this to list of medals, unlocked if the save says so when medalsInit came first
        medals[id] = this;
        if (medalsSaveName && !debugMedals && this.isLocal())
            this.unlocked = !!readSaveData(medalsSaveName)[id]?.unlocked;
    }

    /** Unlocks a medal if not already unlocked
     *  - The promise is optional, for when a game wants to know the outcome
     *  @return {Promise<boolean>} - Whether the medal is unlocked, right away unless a service like Newgrounds has to confirm */
    unlock()
    {
        if (!medalsPreventUnlock && !this.unlocked)
        {
            ASSERT(medalsSaveName, 'save name must be set');
            this.unlocked = true;
            medalsSave();
            medalsDisplayQueue.push(this);
        }
        return Promise.resolve(this.unlocked);
    }

    /** Whether the local save holds this medal, it is neither loaded nor written while a service like Newgrounds holds it
     *  @return {boolean} */
    isLocal() { return true; }

    /** Render a medal
     *  @param {number} [hidePercent] - How much to slide the medal off screen
     */
    render(hidePercent=0)
    {
        const context = mainContext;
        const width = min(medalDisplaySize.x, mainCanvasSize.x);
        const height = medalDisplaySize.y;
        const x = mainCanvasSize.x - width;
        const y = -height*hidePercent;
        const backgroundColor = hsl(0,0,.9);

        // draw containing rect and clip to that region
        context.save();
        context.beginPath();
        context.fillStyle = backgroundColor.toString();
        context.strokeStyle = BLACK.toString();
        const lineWidth = context.lineWidth = 3;
        context.rect(x + lineWidth/2, y + lineWidth/2, width - lineWidth, height - lineWidth); // the whole border shows
        context.fill();
        context.stroke();
        context.clip();

        // draw the icon
        const gap = vec2(.1, .05).scale(height);
        const iconSize = height - 2*gap.x;
        this.renderIcon(vec2(x + gap.x + iconSize/2, y + height/2), iconSize);

        // draw the name
        const nameSize = height*.5;
        const descriptionSize = height*.3;
        const pos = vec2(x + iconSize + 2*gap.x, y + gap.y*2 + nameSize/2);
        const textWidth = width - iconSize - 3*gap.x;
        drawTextScreen(this.name, pos, nameSize, BLACK, 0, undefined, 'left', undefined, undefined, textWidth);

        // draw the description
        pos.y = y + height - gap.y*2 - descriptionSize/2;
        drawTextScreen(this.description, pos, descriptionSize, BLACK, 0, undefined, 'left', undefined, undefined, textWidth);
        context.restore();
    }

    /** Render the icon for a medal
     *  @param {Vector2} pos - Screen space position
     *  @param {number} size - Screen space size
     */
    renderIcon(pos, size)
    {
        // draw the image once it has loaded, or the icon; a broken image would throw
        const image = this.image;
        if (image && image.complete && image.naturalWidth)
            mainContext.drawImage(image, pos.x-size/2, pos.y-size/2, size, size);
        else
            drawTextScreen(this.icon, pos, size*.7, BLACK);
    }

}

///////////////////////////////////////////////////////////////////////////////
// Medals setting setters

/** Set how long to show medals for in seconds
 *  @param {number} time
 *  @memberof Settings */
function setMedalDisplayTime(time) { medalDisplayTime = time; }

/** Set how quickly to slide on/off medals in seconds
 *  @param {number} time
 *  @memberof Settings */
function setMedalDisplaySlideTime(time) { medalDisplaySlideTime = time; }

/** Set size of medal display
 *  @param {Vector2} size
 *  @memberof Settings */
function setMedalDisplaySize(size) { medalDisplaySize = size.copy(); }

/** Set to stop medals from being unlockable
 *  @param {boolean} preventUnlock
 *  @memberof Settings */
function setMedalsPreventUnlock(preventUnlock) { medalsPreventUnlock = preventUnlock; }

/**
 * LittleJS Newgrounds Plugin
 * - NewgroundsMedal extends Medal with Newgrounds API functionality
 * - When logged in, Newgrounds holds the player's NewgroundsMedals: they unlock once the server confirms and the local save leaves them alone
 * - A plain Medal is never touched, so a game can use the plugin for scoreboards alone
 * - Without a session the medal and scoreboard lists still come in, so the medals get their names and icons; unlocking on the server and posting scores need a logged in player
 * - Create the medals as NewgroundsMedals with their ids on Newgrounds, then new NewgroundsPlugin(app_id, cipher); medalsInit is still needed, before or after
 * - Encrypts medal unlocks and posted scores, the calls Newgrounds secures, with the browser's own WebCrypto when the app has a cipher, no library needed
 * - Logs a view when it starts, and provides functions to unlock medals and to post and read scoreboards
 * - Tells the Newgrounds page around the game when a medal unlocks or a score posts, as the official client does
 * - Checks the session every minute when logged in, which keeps it alive, and plays as not logged in once it is lost
 * - Where the browser has AbortSignal.timeout, a request that takes longer than 15 seconds fails like one that could not reach the server
 * - Every call is a fetch, so the functions return promises; await newgrounds.ready for the medals and scoreboards
 * @namespace Newgrounds
 */

/** Global Newgrounds object
 *  @type {NewgroundsPlugin}
 *  @memberof Newgrounds */
let newgrounds;

// Engine internal variables not exposed to documentation
const newgroundsUnlocksToResend = new Set; // pending medals whose request did not reach the server
const newgroundsUnlocksRefused = new Set; // medals the server refused this visit, asked again they answer no unsent
const newgroundsSecureComponents = ['Medal.unlock', 'ScoreBoard.postScore']; // the calls encrypted with a cipher
const newgroundsSessionErrors = [104, 110, 111]; // expired session, login required, session canceled
const newgroundsTimeoutMS = 15e3; // how long a request may take before it fails

// whether the server answered that the session is gone, as opposed to a request that failed on the way
function newgroundsSessionLost(response)
{ return newgroundsSessionErrors.includes(response?.result?.data?.error?.code ?? response?.error?.code); }

// tell the Newgrounds page around the game, with the message the official client sends
function newgroundsNotifyPage(component, id)
{ globalThis.top?.postMessage(JSON.stringify({'ngioComponent':component, 'id':id}), '*'); }

///////////////////////////////////////////////////////////////////////////////
/**
 * NewgroundsMedal: its id is the medal's id on the Newgrounds API Tools page; when logged in it only unlocks once the server confirms
 * @extends Medal
 * @memberof Newgrounds
 */
class NewgroundsMedal extends Medal
{
    /** Create a NewgroundsMedal and add it to the list of medals
     *  @param {number} id            - The unique identifier of the medal
     *  @param {string} name          - Name of the medal
     *  @param {string} [description] - Description of the medal
     *  @param {string} [icon]        - Icon for the medal
     *  @param {string} [src]         - Image location for the medal
     */
    constructor(id, name, description, icon, src)
    {
        super(id, name, description, icon, src);

        /** @property {number|undefined} - Difficulty from the server once ready, 1 easy to 5 brutal
         *  @type {number|undefined} */
        this.difficulty = undefined;

        /** @property {number|undefined} - Point value from the server once ready
         *  @type {number|undefined} */
        this.value = undefined;
    }

    /** Whether the local save holds this medal, false while logged in when Newgrounds holds it
     *  @return {boolean} */
    isLocal() { return !newgrounds?.session_id; }

    /** Unlocks a medal if not already unlocked, once Newgrounds confirms it when logged in
     *  - The promise is optional, for when a game wants to know the outcome
     *  - A request that did not reach the server is sent again after the session check every minute, and calling
     *    unlock again while the medal is pending returns the same promise
     *  - One the server refused is not sent again this visit, calling unlock again resolves false without a request
     *  - An answer that the session is gone makes the game play as not logged in, and the pending medals, this one too,
     *    unlock locally unless unlocks are prevented; a refused one only unlocks if it is earned again
     *  @return {Promise<boolean>} - Whether the medal is unlocked, once the server has answered when logged in */
    unlock()
    {
        if (medalsPreventUnlock || this.unlocked || this.isLocal())
            return super.unlock(); // nothing to send, or not logged in and the local save holds the medal

        // logged in, Newgrounds holds the medal: it unlocks once the server confirms, one request at a time
        ASSERT(medalsSaveName, 'save name must be set');
        if (newgroundsUnlocksRefused.has(this))
            return Promise.resolve(false); // refused this visit, asking again will not change that
        const pending = newgrounds.pendingUnlocks;
        if (pending.has(this))
            return pending.get(this);
        const request = newgrounds.unlockMedal(this.id).then(response=>
        {
            if (newgroundsSessionLost(response))
                newgrounds.dropSession(); // the pending unlocks, this one too, are local now
            const serverMedal = response?.result?.data?.medal;
            if (!serverMedal?.unlocked || medalsPreventUnlock)
            {
                debugMedals && LOG('Newgrounds did not unlock medal', this.id, response?.result?.data?.error || response?.error);
                if (this.isLocal())
                    return this.unlocked; // the session dropped, the medal is local now
                if (!response || serverMedal?.unlocked)
                    newgroundsUnlocksToResend.add(this); // did not reach the server, or confirmed while prevented: pending
                else
                {
                    // refused, which will not change: no longer pending, so a session drop does not unlock it
                    pending.delete(this);
                    newgroundsUnlocksRefused.add(this);
                }
                return false;
            }
            const listed = newgrounds.medals.find(m=> m['id'] == this.id);
            listed && Object.assign(listed, serverMedal); // keep the fetched list in step
            if (serverMedal['icon'] && serverMedal['icon'] != this.image?.src)
                (this.image = new Image).src = serverMedal['icon']; // a secret medal shows its real icon once unlocked
            pending.delete(this);
            newgroundsNotifyPage('Medal.unlock', this.id);
            return super.unlock();
        });
        pending.set(this, request);
        return request;
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Newgrounds API object
 * @memberof Newgrounds
 */
class NewgroundsPlugin
{
    /** Create the global newgrounds object
     *  - Logs a view right away, for a guest and a logged in player alike, so a game does not have to
     *  - Create the medals first: they take their name and icon from the server once it answers, and when logged in they are locked here until it does
     *  - Call medalsInit too, before or after: an unlock asserts without it, and it keeps the medals while not logged in
     *  @param {string} app_id   - The Newgrounds App ID
     *  @param {string} [cipher] - The encryption key from the app's settings, AES-128 as Base64; medal unlocks and posted
     *    scores are encrypted with the browser's WebCrypto, which needs a secure page, https or localhost
     *  @example
     *  // create the newgrounds object, replace the app id with your own
     *  const app_id = 'your_app_id_here';
     *  new NewgroundsPlugin(app_id);
     */
    constructor(app_id, cipher)
    {
        ASSERT(!newgrounds, 'there can only be one newgrounds object');
        ASSERT(!cipher || typeof crypto != 'undefined' && crypto.subtle, 'a cipher needs WebCrypto, which the browser only has on a secure page');
        ASSERT(!cipher || /^[A-Za-z0-9+/]{22}==$/.test(cipher), 'the cipher must be the Base64 AES-128 key from the app settings');

        newgrounds = this; // set global newgrounds object
        /** @property {string} - The Newgrounds App ID */
        this.app_id = app_id;
        /** @property {string|undefined} - AES-128/Base64 encryption key, if any
         *  @type {string|undefined} */
        this.cipher = cipher;
        /** @type {CryptoKey|undefined} */
        this.cryptoKey = undefined; // the cipher imported for WebCrypto, on the first encrypted call
        const hasLocation = typeof location != 'undefined';
        /** @property {string} - Hostname sent with the view the plugin logs when it starts */
        this.host = hasLocation ? location.hostname : '';
        /** @property {Array} - Medals fetched from Newgrounds, empty until ready, with the unlocks only when logged in */
        this.medals = [];
        /** @property {Array} - Scoreboards fetched from Newgrounds, empty until ready */
        this.scoreboards = [];
        /** @property {{id: number, name: string, url: string, supporter: boolean}|null} - The logged in player once ready, null when not logged in
         *  @type {{id: number, name: string, url: string, supporter: boolean}|null} */
        this.user = null;

        /** @property {Map<NewgroundsMedal, Promise<boolean>>} - Medals whose unlock is in flight or waiting to be resent, with their request's promise; one the server refused leaves it
         *  @type {Map<NewgroundsMedal, Promise<boolean>>} */
        this.pendingUnlocks = new Map;

        // get session id from url search params
        /** @property {string|null} - Newgrounds session id from the URL, null when not logged in or once the session is lost
         *  @type {string|null} */
        this.session_id = hasLocation ? new URL(location.href).searchParams.get('ngio_session_id') : null;
        // Newgrounds holds this player's NewgroundsMedals: locked until the server says otherwise, the local save leaves them alone
        if (this.session_id)
            medalsForEach(medal=> medal instanceof NewgroundsMedal && (medal.unlocked = false));

        /** @property {Promise<NewgroundsPlugin>} - Resolves once the session is checked and the lists are in, empty if the server could not be reached */
        this.ready = this.init();
    }

    /** Log the view, check the session, fetch the medals and scoreboards, then keep the session alive; the constructor runs it once
     *  @private */
    async init()
    {
        this.call('App.logView', {'host':this.host}); // every view counts, guest or logged in

        let medalList;
        if (this.session_id)
        {
            // the player is logged in when the server knows the session, it has a user and the medals come in
            const sessionResult = await this.call('App.checkSession');
            const session = sessionResult?.result?.data?.['session'];
            const user = session && !session['expired'] && session['user'];
            medalList = user && (await this.call('Medal.getList'))?.result?.data?.['medals'];
            if (medalList && this.session_id)
                this.user = user;
            else
            {
                this.dropSession(); // without the server (offline / bad session / server error), or lost meanwhile
                medalList = undefined; // its unlocks belong to the lost session
            }
        }

        // not logged in, the list comes too, without the unlocks
        medalList = medalList || (await this.call('Medal.getList'))?.result?.data?.['medals'];
        this.medals = medalList || [];
        debugMedals && LOG(this.medals);
        for (const newgroundsMedal of this.medals)
        {
            const medal = medals[newgroundsMedal['id']];
            if (medal instanceof NewgroundsMedal) // a plain medal with the same id is left alone
            {
                // copy the server's medal data
                medal.image =       new Image;
                medal.image.src =   newgroundsMedal['icon'];
                medal.name =        newgroundsMedal['name'];
                medal.description = newgroundsMedal['description'];
                medal.unlocked =    medal.unlocked || !!newgroundsMedal['unlocked']; // keeps a local unlock, or one that landed first
                medal.difficulty =  newgroundsMedal['difficulty'];
                medal.value =       newgroundsMedal['value'];
                if (medal.value) // add value to description
                    medal.description += ` (${ medal.value })`;

                if (this.session_id && medal.unlocked)
                {
                    newgroundsMedal['unlocked'] = true; // the list says so too
                    this.pendingUnlocks.delete(medal); // and a request waiting to be resent, or refused, is done
                    newgroundsUnlocksToResend.delete(medal);
                    newgroundsUnlocksRefused.delete(medal);
                }
            }
        }

        const scoreboardResult = await this.call('ScoreBoard.getBoards');
        this.scoreboards = scoreboardResult?.result?.data?.scoreboards || [];
        debugMedals && LOG(this.scoreboards);
        if (!this.session_id)
            return this;

        // logged in, check the session every minute, which keeps it alive, and resend the unlocks that did not reach the server
        const keepAlive = setInterval(async ()=>
        {
            if (!this.session_id)
                return clearInterval(keepAlive);
            const response = await this.call('App.checkSession');
            const session = response?.result?.data?.['session'];
            if (newgroundsSessionLost(response) || session && (session['expired'] || !session['user']))
                return this.dropSession();
            this.resendUnlocks();
        }, 60e3);
        return this;
    }

    /** Play as not logged in from now on: the NewgroundsMedals come back from the local save, keeping the unlocks the
     *  server confirmed meanwhile, and the unlocks still pending unlock locally; a refused one only if it is earned again
     *  - internal, the medals call it too when the server says the session is gone
     *  @ignore */
    dropSession()
    {
        if (!this.session_id) return;
        debugMedals && LOG('Newgrounds session unavailable; medals are local');
        const confirmed = Object.values(medals).filter(medal=> medal.unlocked);
        this.session_id = null;
        this.user = null;
        medalsLoad(); // the NewgroundsMedals are local again, back from the save
        confirmed.forEach(medal=> medal.unlocked = true);
        medalsSave();

        // the unlocks still out are local too, they unlock now, or are dropped like any local unlock while prevented
        const pending = [...this.pendingUnlocks.keys()];
        this.pendingUnlocks.clear();
        newgroundsUnlocksToResend.clear();
        newgroundsUnlocksRefused.clear();
        for (const medal of pending)
            medal.unlock();
    }

    /** Send the unlocks whose request did not reach the server again, which the session check does every minute
     *  - A request still out is left to answer, and while unlocks are prevented they wait */
    resendUnlocks()
    {
        if (medalsPreventUnlock) return;
        for (const medal of newgroundsUnlocksToResend)
        {
            this.pendingUnlocks.delete(medal);
            medal.unlock(); // a failure is only added back once the new request answers
        }
        newgroundsUnlocksToResend.clear();
    }

    /** Send a request to unlock a medal by id, the local medal is not changed; NewgroundsMedal.unlock sends this and waits for the answer
     *  @param {number} id - The medal id
     *  @return {Promise<Object>} - The response JSON object, undefined when the call failed */
    unlockMedal(id) { return this.call('Medal.unlock', {'id':id}); }

    /** Send message to post score
     *  @param {number} id    - The scoreboard id
     *  @param {number} value - The score value, a whole number
     *  @return {Promise<Object>} - The response JSON object, undefined when the call failed; result.data.success says whether
     *    it posted, which needs a logged in player; an answer that the session is gone makes the game play as not logged
     *    in, and one that timed out may still have posted */
    postScore(id, value)
    {
        return this.call('ScoreBoard.postScore', {'id':id, 'value':value}).then(response=>
        {
            response?.result?.data?.success && newgroundsNotifyPage('ScoreBoard.postScore', id);
            newgroundsSessionLost(response) && this.dropSession();
            return response;
        });
    }

    /** Get scores from a scoreboard
     *  @param {number} id        - The scoreboard id
     *  @param {string|number} [user] - A user's id or name, to load only their scores
     *  @param {boolean} [social] - If true, only the scores of the user and their friends, the logged in player when user is left out
     *  @param {number} [skip]    - Number of scores to skip over
     *  @param {number} [limit]   - Number of scores to include in the list
     *  @param {string} [period]  - 'D' today, which the server assumes when left out, 'W' this week, 'M' this month, 'Y' this year or 'A' all time
     *  @return {Promise<Object>} - The response JSON object, undefined when the call failed; the scores are in
     *    result.data.scores, each with user.name, value and formatted_value; without a user or social it is the whole board
     */
    getScores(id, user, social=false, skip=0, limit=10, period)
    {
        // the whole board goes without the session, which the server would narrow down to the logged in player
        const session_id = user || social ? this.session_id : null;
        const parameters = {'id':id, 'user':user, 'social':social, 'skip':skip, 'limit':limit, 'period':period};
        return this.call('ScoreBoard.getScores', parameters, session_id);
    }

    /** Encrypt text the way the Newgrounds gateway expects, AES-128 CBC with a random iv in front, as Base64
     *  @param {string} text
     *  @return {Promise<string>} */
    async encrypt(text)
    {
        if (!this.cryptoKey)
        {
            const keyBytes = Uint8Array.from(atob(this.cipher), c=> c.charCodeAt(0));
            this.cryptoKey = await crypto.subtle.importKey('raw', keyBytes, 'AES-CBC', false, ['encrypt']);
        }
        const iv = crypto.getRandomValues(new Uint8Array(16));
        const encrypted = new Uint8Array(await crypto.subtle.encrypt({'name':'AES-CBC', iv}, this.cryptoKey, new TextEncoder().encode(text)));
        const bytes = new Uint8Array(iv.length + encrypted.length);
        bytes.set(iv);
        bytes.set(encrypted, iv.length);
        let binary = '';
        for (const b of bytes)
            binary += String.fromCharCode(b);
        return btoa(binary);
    }

    /** Send a message to call a component of the Newgrounds API
     *  @param {string}  component    - Name of the component
     *  @param {Object}  [parameters] - Parameters to use for call
     *  @param {string|null} [session_id] - The session to send, the player's by default
     *  @return {Promise<Object>}     - The response JSON object, undefined when the call failed or took over 15 seconds;
     *    a component's own success and error are in result.data, and a cipher that is not a key gives error 201
     */
    async call(component, parameters, session_id=this.session_id)
    {
        const url = 'https://www.newgrounds.io/gateway_v3.php';
        try
        {
            /** @type {Object} */
            let execute = {'component':component, 'parameters':parameters};
            if (this.cipher && newgroundsSecureComponents.includes(component))
            {
                // only the encrypted call goes; a key that will not even import is refused here the way the server
                // refuses a wrong one, since sending again cannot fix it
                const secure = await this.encrypt(JSON.stringify(execute)).catch(e=> debugMedals && LOG('Newgrounds cipher failed', e));
                if (!secure)
                    return {'success':false, 'error':{'code':201, 'message':'Invalid Encryption: the cipher is not a Base64 AES-128 key'}};
                execute = {'secure': secure};
            }

            // build the request object, in the form the Newgrounds.io docs give
            const request =
            {
                'app_id':     this.app_id,
                'session_id': session_id,
                'execute':    execute
            };

            // send it as post data
            const formData = new FormData();
            formData.append('request', JSON.stringify(request));
            const signal = globalThis.AbortSignal?.timeout?.(newgroundsTimeoutMS); // a stalled request fails
            const response = await fetch(url, {'method':'POST', 'body':formData, 'signal':signal});
            const text = await response.text();
            debugMedals && LOG(text);
            return text ? JSON.parse(text) : undefined;
        }
        catch(e) { debugMedals && LOG('newgrounds call failed', e); }
    }
}

/**
 * LittleJS Post Processing Plugin
 * - Supports shadertoy style post processing shaders
 * - call new PostProcessPlugin() to setup post processing
 * - can be enabled to pass other canvases through a final shader
 * - iResolution is the canvas backing store, so it grows with canvasPixelRatio
 *   like shadertoy does. Effects that use it only for uv (p/iResolution.xy) are
 *   unaffected, but ones that set a feature size from it, like scan lines, get
 *   finer as the ratio rises. Divide by getCanvasPixelRatio() to pin them.
 * @namespace PostProcess
 */

///////////////////////////////////////////////////////////////////////////////

/** Global Post Process plugin object
 *  @type {PostProcessPlugin}
 *  @memberof PostProcess */
let postProcess;

/////////////////////////////////////////////////////////////////////////
/**
 * Post Process Plugin - Applies a full screen shader to the rendered output
 * - Create it after any plugin that draws, since plugins render in the order they are made
 *   and this one shades what is on the canvas when its turn comes
 * - It runs after gameRenderPost, so a HUD drawn there with WebGL is shaded (and bloomed) too;
 *   draw the HUD with useWebGL=false (the main canvas) or from a plugin created after this one
 * @memberof PostProcess
 */
class PostProcessPlugin
{
    /** Create global post processing shader
    *  @param {string} [shaderCode] - Shadertoy style mainImage code, a pass-through when left out
    *  @param {boolean} [includeMainCanvas] - combine mainCanvas onto glCanvas
    *  @param {boolean} [feedbackTexture] - also pass the shader's own output from the previous frame as iChannel1,
    *                                       for trails and echoes; iChannel0 is still the frame just drawn
    *  @example
    *  // create the post process plugin object
    *  new PostProcessPlugin(shaderCode);
    */
    constructor(shaderCode, includeMainCanvas=false, feedbackTexture=false)
    {
        ASSERT(engineInitialized || headlessMode, 'create the plugin after engineInit, e.g. in gameInit');
        ASSERT(!postProcess, 'Post process already initialized');
        ASSERT(!(includeMainCanvas && feedbackTexture), 'Post process cannot both include main canvas and use feedback texture');
        postProcess = this;

        /** @property {string} - The shadertoy style mainImage code it shades with, see setShaderCode */
        this.shaderCode = shaderCode || postProcessEffects(); // no code passes the frame through

        /** @property {Object<string, number|Array<number>>} - The game's own values for the shader, a uniform each
         *  by its name, a number a float and a list of 2 to 4 numbers a vector, set every frame as they are; an
         *  effect setting can be one of these names, so it changes every frame without making the shader again, all
         *  but glow's size, which sets how many samples it takes; adding or removing a name makes the shader again,
         *  and the shader is first made at the first render, so values set right after the plugin are in it; a name
         *  is a GLSL name not starting with an underscore, which the effects keep for their own, nor i and a capital
         *  or gl_, and not c, uv or p, the names mainImage works on
         *  @type {Object<string, number|Array<number>>} */
        this.values = {};
        // the names of the values the shader was made with
        this.valueNames = '';

        /** @property {WebGLProgram|undefined} - Shader for post processing
         *  @type {WebGLProgram|undefined} */
        this.shader = undefined;
        /** @property {WebGLTexture|undefined} - Texture for post processing
         *  @type {WebGLTexture|undefined} */
        this.texture = undefined;
        /** @property {WebGLTexture|undefined} - The previous frame's output, iChannel1, when feedbackTexture is set
         *  @type {WebGLTexture|undefined} */
        this.feedbackTexture = undefined;
        /** @property {WebGLVertexArrayObject|undefined} - Vertex array object
         *  @type {WebGLVertexArrayObject|undefined} */
        this.vao = undefined;

        // the shader is made at the first render, so values the game sets after this, which its code may name, are
        // declared in it
        !headlessMode && !glEnable && console.warn('PostProcessPlugin: WebGL not enabled!');
        engineAddPlugin(undefined, postProcessRender, postProcessContextLost, postProcessContextRestored);

        function initPostProcess()
        {
            if (headlessMode || !glEnable) return;

            // create resources, the feedback starting black, as if the frame before the first were empty
            if (feedbackTexture)
            {
                postProcess.feedbackTexture = glCreateTexture();
                glContext.bindTexture(glContext.TEXTURE_2D, postProcess.feedbackTexture);
                glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA, 1, 1, 0, glContext.RGBA,
                    glContext.UNSIGNED_BYTE, new Uint8Array([0, 0, 0, 255]));
                glContext.bindTexture(glContext.TEXTURE_2D, glActiveTexture);
            }
            postProcess.texture = glCreateTexture();
            postProcess.shader = glCreateProgram(
                '#version 300 es\n' +            // specify GLSL ES version
                'precision highp float;'+        // use highp for accuracy
                'in vec2 p;'+                    // position
                'void main(){'+                  // shader entry point
                'gl_Position=vec4(p+p-1.,1,1);'+ // set position
                '}'                              // end of shader
                ,
                postProcessFragmentSource(postProcess.shaderCode, postProcess.values)
            );
            postProcess.valueNames = postProcessValueKey(postProcess.values);

            // setup VAO for post processing
            postProcess.vao = glContext.createVertexArray();
            glContext.bindVertexArray(postProcess.vao);
            glContext.bindBuffer(glContext.ARRAY_BUFFER, glGeometryBuffer);

            // configure vertex attributes
            const vertexByteStride = 8;
            const pLocation = glContext.getAttribLocation(postProcess.shader, 'p');
            glContext.enableVertexAttribArray(pLocation);
            glContext.vertexAttribPointer(pLocation, 2, glContext.FLOAT, false, vertexByteStride, 0);

            // the engine's own vertex array and buffer back, its next batch is written into the buffer bound
            glContext.bindVertexArray(glPolyMode ? glPolyVAO : glInstancedVAO);
            glContext.bindBuffer(glContext.ARRAY_BUFFER, glArrayBuffer);
        }
        function postProcessContextLost()
        {
            postProcess.shader = undefined;
            postProcess.texture = undefined;
            postProcess.feedbackTexture = undefined;
            LOG('PostProcessPlugin: WebGL context lost');
        }
        function postProcessContextRestored()
        {
            initPostProcess();
            LOG('PostProcessPlugin: WebGL context restored');
        }
        function postProcessRender()
        {
            if (headlessMode || !glEnable) return;

            // clear out the buffer, before anything here binds its own
            glFlush();

            // made now if WebGL was off when the plugin was made, when a lost context came back, when setShaderCode
            // gave it new code, or when the game added or took away a value, which the shader declares
            if (postProcess.shader && postProcessValueKey(postProcess.values) !== postProcess.valueNames)
                postProcess.setShaderCode(postProcess.shaderCode);
            if (!postProcess.shader)
            {
                if (glContext.isContextLost()) return;
                initPostProcess();
            }
            if (glFailedPrograms.has(postProcess.shader))
                return; // a shader that did not build in a release build, the frame shows as it is

            // ensure we render to the default framebuffer (in case any earlier
            // caller this frame left a render target bound)
            glContext.bindFramebuffer(glContext.FRAMEBUFFER, null);

            // setup shader program to draw a quad
            glContext.useProgram(postProcess.shader);
            glContext.bindVertexArray(postProcess.vao);
            glContext.pixelStorei(glContext.UNPACK_FLIP_Y_WEBGL, true);
            // upload the canvas the way it shows, premultiplied, since the shader writes full alpha; unpremultiplied
            // a see-through pixel would come out at its full brightness instead of faded over the background
            glContext.pixelStorei(glContext.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
            glContext.disable(glContext.BLEND);

            // setup texture
            glContext.activeTexture(glContext.TEXTURE0);
            glContext.bindTexture(glContext.TEXTURE_2D, postProcess.texture);
            if (includeMainCanvas)
            {
                // copy main canvas to work canvas at the backing store size,
                // mainCanvasSize is css pixels so it would lose resolution
                // sized again only when the canvas changed, setting a size remakes the canvas even to the same one
                if (workCanvas.width !== mainCanvas.width || workCanvas.height !== mainCanvas.height)
                    workCanvas.width = mainCanvas.width, workCanvas.height = mainCanvas.height;
                else
                    workContext.clearRect(0, 0, workCanvas.width, workCanvas.height);
                glCopyToContext(workContext);
                workContext.drawImage(mainCanvas, 0, 0);
                // clear the main canvas with clearRect, resizing it would also
                // reset the context state (smoothing, line caps) for anything
                // drawn after this and reallocate the canvas every frame
                mainContext.save();
                mainContext.setTransform(1, 0, 0, 1, 0, 0);
                mainContext.clearRect(0, 0, mainCanvas.width, mainCanvas.height);
                mainContext.restore();

                // copy work canvas to texture
                glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA, glContext.RGBA, glContext.UNSIGNED_BYTE, workCanvas);
            }
            else
            {
                // copy glCanvas to texture
                glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA, glContext.RGBA, glContext.UNSIGNED_BYTE, glCanvas);
            }

            // the previous frame's output, on the second texture unit
            if (feedbackTexture)
            {
                glContext.activeTexture(glContext.TEXTURE1);
                glContext.bindTexture(glContext.TEXTURE_2D, postProcess.feedbackTexture);
            }

            // the 3D depth, when render3D draws it, on the third texture unit, with what sceneDepth needs to read it
            const depth = typeof render3D != 'undefined' && render3D?.depthTexture ? render3D : undefined;
            glContext.activeTexture(glContext.TEXTURE2);
            glContext.bindTexture(glContext.TEXTURE_2D, depth?.cameraDepthTexture || null);
            glContext.activeTexture(glContext.TEXTURE0);
            // all 0 without one, which an effect reads as no depth
            const camera = depth?.camera;
            glContext.uniform3f(glUniformLocation(postProcess.shader, 'iDepthRange'), camera?.near || 0,
                !camera || camera.far == Infinity ? 0 : camera.far, camera?.orthographic ? 1 : 0);

            // set uniforms and draw
            const uniformLocation = (name)=>glUniformLocation(postProcess.shader, name);
            glContext.uniform1i(uniformLocation('iChannel0'), 0);
            glContext.uniform1i(uniformLocation('iChannel1'), 1);
            glContext.uniform1i(uniformLocation('iChannel2'), 2);
            glContext.uniform1f(uniformLocation('iTime'), time);
            glContext.uniform3f(uniformLocation('iResolution'), mainCanvas.width, mainCanvas.height, 1);
            for (const name in postProcess.values)
            {
                const value = postProcess.values[name], location = uniformLocation(name);
                if (isArray(value))
                    [, , glContext.uniform2fv, glContext.uniform3fv, glContext.uniform4fv][value.length]?.call(glContext, location, value);
                else
                    glContext.uniform1f(location, value);
            }
            glContext.drawArrays(glContext.TRIANGLE_STRIP, 0, 4);

            if (feedbackTexture)
            {
                // keep this frame's output for the next one, in the feedback texture still bound to the second
                // unit, then hand the first texture unit back to the engine
                glContext.activeTexture(glContext.TEXTURE1);
                glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA, glContext.RGBA, glContext.UNSIGNED_BYTE, glCanvas);
                glContext.activeTexture(glContext.TEXTURE0);
            }

            // the depth leaves the third unit for whatever draws next
            glContext.activeTexture(glContext.TEXTURE2);
            glContext.bindTexture(glContext.TEXTURE_2D, null);
            glContext.activeTexture(glContext.TEXTURE0);

            // restore defaults so subsequent dynamic texture uploads aren't flipped or premultiplied
            glContext.pixelStorei(glContext.UNPACK_FLIP_Y_WEBGL, false);
            glContext.pixelStorei(glContext.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);

            // bind back the texture the 2D batch thinks is bound, a plugin drawing after this one uses it
            if (glActiveTexture)
                glContext.bindTexture(glContext.TEXTURE_2D, glActiveTexture);

            // force it to set instanced mode
            glSetInstancedMode(true);
        }
    }

    /** Shade with new code from the next frame on, to switch effects while the game runs; the shader is made again
     *  @param {string} [shaderCode] - Shadertoy style mainImage code, postProcessEffects builds it; none passes the
     *  frame through */
    setShaderCode(shaderCode)
    {
        ASSERT(!shaderCode || typeof shaderCode === 'string', 'shader code must be a string');
        this.shaderCode = shaderCode || postProcessEffects();
        if (!this.shader || headlessMode || !glContext) return;

        // what the new shader replaces, made again by the next render
        glContext.deleteProgram(this.shader);
        glContext.deleteTexture(this.texture);
        this.feedbackTexture && glContext.deleteTexture(this.feedbackTexture);
        glContext.deleteVertexArray(this.vao);
        this.shader = this.texture = this.feedbackTexture = this.vao = undefined;
    }
}

///////////////////////////////////////////////////////////////////////////////

// what the shader declares of the game's values, each name and its length, so a value that changes either makes the
// shader again
const postProcessValueKey = (values)=> Object.entries(values).map(([name, v])=> name + ':' + (isArray(v) ? v.length : 1)).join();

// the fragment shader of the post process pass around its mainImage snippet: the frame on iChannel0, the last output
// on iChannel1 with a feedback texture, and the 3D depth on iChannel2 when render3D.depthTexture is on, read with
// sceneDepth(uv), the distance from the camera along its view in world units, uv 0 to 1 across the screen; and a
// uniform for each of the game's values, a float or a vector of the list's length
function postProcessFragmentSource(shaderCode, values={})
{
    let declared = '';
    for (const name in values)
    {
        const value = values[name], length = isArray(value) ? value.length : 1;
        ASSERT(postProcessNameCheck(name), 'a postProcess value needs a name GLSL takes that the shader does not use', name);
        ASSERT(!isArray(value) || length >= 2 && length <= 4, 'a postProcess value is a number or 2 to 4 of them', name);
        declared += `uniform ${length > 1 ? 'vec' + length : 'float'} ${name};`;
    }
    return '#version 300 es\n' +        // specify GLSL ES version
        'precision highp float;'+        // use highp for accuracy
        'uniform sampler2D iChannel0;'+  // input texture
        'uniform sampler2D iChannel1;'+  // the previous frame's output, when feedbackTexture is set
        'uniform highp sampler2D iChannel2;'+ // the 3D depth, when render3D.depthTexture is on, highp or it is 11 bits
        'uniform vec3 iResolution;'+     // size of output texture
        'uniform float iTime;'+          // time
        'uniform vec3 iDepthRange;'+     // the camera's near, its far or 0 for none, and 1 when orthographic
        declared +                       // the game's own values
        'out vec4 c;'+                   // out color
        // the depth texture's value back to a distance, as the camera's projection put it there
        'float sceneDepth(vec2 uv){'+
        'float d=texture(iChannel2,uv).r*2.-1.,n=iDepthRange.x,f=iDepthRange.y;'+
        'return iDepthRange.z>0.?(d*(f-n)+f+n)/2.:f>0.?2.*n*f/(f+n-d*(f-n)):2.*n/max(1.-d,1e-7);}'+
        // whether there is depth to read: a range of all 0 is none, an orthographic near plane may be behind
        '\n#define LJS_HAS_DEPTH (iDepthRange != vec3(0))\n'+ // a define needs a line of its own
        '\n' + shaderCode + '\n'+        // insert custom shader code
        'void main(){'+                  // shader entry point
        'mainImage(c,gl_FragCoord.xy);'+ // call post process function
        'c.a=1.;'+                       // always use full alpha
        '}';                             // end of shader
}

/**
 * Shader code for a bloom effect, the bright parts of the image blurred back over it
 * - Pass it to PostProcessPlugin, or edit the string to build an effect on top of it
 * @param {number|string} [threshold] - Brightness where the glow starts, 0 is everything and 1 is only pure white
 * @param {number|string} [strength] - How much glow to add
 * @param {number} [size] - How far the glow spreads in pixels, which also sets how many samples it takes, so a
 *   number and not a value's name
 * @return {string}
 * @memberof PostProcess
 */
function postProcessBloomShader(threshold=.6, strength=1, size=6)
{
    return postProcessEffects(postProcessGlow(threshold, strength, size));
}

/**
 * Set up post processing with a bloom effect, so bright colors and lights glow
 * @param {number|string} [threshold] - Brightness where the glow starts, 0 is everything and 1 is only pure white
 * @param {number|string} [strength] - How much glow to add
 * @param {number} [size] - How far the glow spreads in pixels
 * @param {boolean} [includeMainCanvas] - Glow the 2D canvas too, off by default so HUD text stays crisp
 *   (a HUD drawn with WebGL in gameRenderPost glows either way, draw it with useWebGL=false)
 * @return {PostProcessPlugin}
 * @memberof PostProcess
 * @example
 * postProcessBloom(); // in gameInit, after any Render3DPlugin
 */
function postProcessBloom(threshold=.6, strength=1, size=6, includeMainCanvas=false)
{ return new PostProcessPlugin(postProcessBloomShader(threshold, strength, size), includeMainCanvas); }

///////////////////////////////////////////////////////////////////////////////
// Effects: pieces of shader code, each with its settings written in as numbers, that postProcessEffects joins in
// order into one shader; a piece works on c, the pixel's color, and uv, where it is on the screen from 0 to 1, with p
// its pixel; one that bends uv or samples the frame, the curve, chromatic and glow, goes before the ones that shade

// a number as GLSL writes it, a float with a point
// an effect setting: a number written into the code, or the name of a postProcess value, read from it each frame
const postProcessNumber = (n)=> typeof n === 'string' ?
    (ASSERT(postProcessNameCheck(n), 'an effect setting is a number or the name of a postProcess value', n), n) :
    (ASSERT(isNumber(n) && isFinite(n), 'an effect setting is a finite number or the name of a postProcess value', n),
        n && abs(n) < .01 ? String(n) : n.toFixed(4)); // a small one keeps its digits, as 1.5e-7 or 0.00015

// a GLSL name for a value or a setting, which no part of the shader uses already: not the engine's own, i and a
// capital, nor those of mainImage or an effect's own locals, which start with an underscore, nor a GLSL word
const postProcessGLSLWords = new Set(('c uv p sceneDepth mainImage main ' +
    // keywords and reserved words
    'attribute const uniform varying layout centroid flat smooth noperspective patch sample break continue do for ' +
    'while switch case default if else subroutine in out inout float double int void bool true false invariant ' +
    'precise discard return lowp mediump highp precision struct common partition active asm class union enum ' +
    'typedef template this resource goto inline noinline public static extern external interface long short half ' +
    'fixed unsigned superp input output filter sizeof cast namespace using coherent volatile restrict readonly ' +
    'writeonly atomic_uint uint mat2 mat3 mat4 vec2 vec3 vec4 ivec2 ivec3 ivec4 bvec2 bvec3 bvec4 uvec2 uvec3 uvec4 ' +
    // built in functions
    'radians degrees sin cos tan asin acos atan sinh cosh tanh asinh acosh atanh pow exp log exp2 log2 sqrt ' +
    'inversesqrt abs sign floor trunc round roundEven ceil fract mod modf min max clamp mix step smoothstep isnan ' +
    'isinf length distance dot cross normalize faceforward reflect refract matrixCompMult outerProduct transpose ' +
    'determinant inverse lessThan lessThanEqual greaterThan greaterThanEqual equal notEqual any all not textureSize ' +
    'texture textureProj textureLod textureOffset texelFetch texelFetchOffset textureProjOffset textureLodOffset ' +
    'textureProjLod textureProjLodOffset textureGrad textureGradOffset textureProjGrad textureProjGradOffset dFdx ' +
    'dFdy fwidth').split(' '));
const postProcessNameCheck = (name)=> /^[A-Za-z][A-Za-z0-9_]*$/.test(name) && !name.includes('__') &&
    !/^(i[A-Z]|gl_|webgl_|GL_|mat[2-4]|[dfh]vec[2-4]|[iu]?(sampler|image)([123]D|Cube|Buffer|External))/.test(name) && !postProcessGLSLWords.has(name);

/**
 * Join effects into one post process shader, in the order given, for PostProcessPlugin or setShaderCode
 * - Each effect is a piece of shader code on c, the pixel's color, and uv, where it is on the screen from 0 to 1;
 *   your own code is a piece too, a line of GLSL or many, dropped in where you put it
 * - Put the ones that bend the picture or sample it first: postProcessCurve, postProcessChromatic, postProcessGlow
 * @param {...string} effects - The pieces, from the effect functions or your own code
 * @return {string} - Shadertoy style mainImage code
 * @example
 * new PostProcessPlugin(postProcessEffects(
 *     postProcessScanlines(.5), postProcessVignette(), 'c.rgb *= vec3(1, .9, .8);'));
 * @memberof PostProcess
 */
function postProcessEffects(...effects)
{
    ASSERT(effects.every((e)=> typeof e === 'string'), 'each effect is a piece of shader code, a string');
    return 'void mainImage(out vec4 c, vec2 p)\n{\n' +
        '    vec2 uv = p / iResolution.xy;\n' +
        '    c = texture(iChannel0, uv);\n' +
        effects.map((e)=> '    {\n' + e + '\n    }\n').join('') + '}\n';
}

/**
 * Bright parts glow, the bloom as an effect to join with others; postProcessBloom sets up bloom on its own
 * @param {number|string} [threshold] - Brightness where the glow starts, 0 is everything and 1 is only pure white
 * @param {number|string} [strength] - How much glow to add
 * @param {number} [size] - How far the glow spreads in pixels, which also sets how many samples it takes, so a
 *   number and not a value's name
 * @return {string}
 * @memberof PostProcess
 */
function postProcessGlow(threshold=.6, strength=1, size=6)
{
    ASSERT(isNumber(size), 'glow size is a number, it sets how many samples the glow takes');
    ASSERT(size > 0, 'glow size must be above zero');
    ASSERT(size <= 32, 'a glow this wide takes a sample every few pixels of every ring, which is hundreds of samples a pixel', size);

    // Taps on three rings over a disc of the given size, one every three pixels or so of each ring
    // so there is no gap wide enough to show. The count follows the ring all the way out: hold it
    // still and a wider glow only spreads the same taps further apart, until they show up as the
    // ring of evenly spaced copies a single ring of eight leaves around anything bright.
    // Each ring has its own count, odd and unequal, and its own turn off the last, so the little
    // the taps do miss comes out as fine ripple instead of a shape of its own.
    const rings = 3;
    let code = '', taps = 0;
    for (let j = 0; j < rings; ++j)
    {
        const radius = ((j + .5) / rings) ** .5 * size;   // equal area per ring
        const count = max(5 + 2 * j, round(2 * radius)) | 1;
        taps += count;
        code += `
        for (int _k = 0; _k < ${count}; ++_k)
        {
            float _a = float(_k) * ${(2 * PI / count).toFixed(7)}${j ? ' + ' + (j * 2.3999632).toFixed(7) : ''};
            _glow += max(vec3(0), texture(iChannel0, uv + vec2(cos(_a), sin(_a)) * ${radius.toFixed(4)} / iResolution.xy).rgb - ${postProcessNumber(threshold)});
        }`;
    }
    return `        // glow
        vec3 _glow = vec3(0);${code}
        c.rgb += _glow * ${typeof strength === 'string' ? postProcessNumber(strength) + ' / ' + taps + '.' :
            (strength / taps).toFixed(6)};`; // a number as before, a value's name divided in the shader
}

/**
 * Scan lines across the screen, like an old TV
 * @param {number|string} [strength] - How dark the lines are, and how bright between them
 * @param {number|string} [spacing] - Pixels from one line to the next
 * @return {string}
 * @memberof PostProcess
 */
function postProcessScanlines(strength=.5, spacing=6)
{
    return `        // scanlines
        c.rgb *= 1. - ${postProcessNumber(strength)} * cos(p.y * 6.2832 / ${postProcessNumber(spacing)});`;
}

/**
 * Static noise over the picture, changing every frame
 * @param {number|string} [strength] - How bright the static is
 * @param {number|string} [size] - Size of a speck in pixels
 * @return {string}
 * @memberof PostProcess
 */
function postProcessNoise(strength=.1, size=2)
{
    return `        // noise
        vec2 _q = fract((floor(p / ${postProcessNumber(size)}) + mod(iTime * 500., 1e3)) * .3197);
        c.rgb += ${postProcessNumber(strength)} * fract(1. + sin(51. * _q.x + 73. * _q.y) * 13753.3);`;
}

/**
 * Darken toward the edges and corners
 * @param {number|string} [strength] - How dark the corners get, 1 is black
 * @param {number|string} [falloff] - How far in it reaches, low darkens most of the screen, high only the corners
 * @return {string}
 * @memberof PostProcess
 */
function postProcessVignette(strength=1, falloff=3)
{
    return `        // vignette
        vec2 _d = uv * 2. - 1.;
        c.rgb *= 1. - ${postProcessNumber(strength)} * min(1., pow(dot(_d, _d) / 2., ${postProcessNumber(falloff)}));`;
}

/**
 * Bend the picture like the bulged glass of an old TV, black past the corners; put it first
 * @param {number|string} [strength] - How much it bends
 * @return {string}
 * @memberof PostProcess
 */
function postProcessCurve(strength=.1)
{
    return `        // curve
        vec2 _d = uv * 2. - 1.;
        _d *= 1. + ${postProcessNumber(strength)} * dot(_d, _d);
        uv = _d * .5 + .5;
        c = all(lessThan(abs(_d), vec2(1))) ? texture(iChannel0, uv) : vec4(0, 0, 0, 1);`;
}

/**
 * Split red and blue apart toward the edges, like a cheap lens; put it before what shades the picture
 * @param {number|string} [strength] - How far apart at the edge, as a part of the screen
 * @return {string}
 * @memberof PostProcess
 */
function postProcessChromatic(strength=.005)
{
    return `        // chromatic
        vec2 _d = (uv - .5) * ${postProcessNumber(strength)} * 2.;
        c.r = texture(iChannel0, uv + _d).r;
        c.b = texture(iChannel0, uv - _d).b;`;
}

// a blur's widest is 32 pixels, past which its 24 taps sit far enough apart to show; a value's is the game's to keep
const postProcessBlurCheck = (blur)=>
    ASSERT(typeof blur === 'string' || blur <= 32, 'a blur of more than 32 pixels shows its taps as copies', blur);

// a blur over a disc of radius _r pixels around uv, of 24 taps spread evenly by the golden angle; weight, when given,
// is GLSL for how much a tap at _puv, _s of the radius out, counts, from 0 to 1
function postProcessDiscBlur(weight)
{
    return `
        vec3 _sum = vec3(0);
        float _total = 0.;
        for (int _k = 0; _k < 24; ++_k)
        {
            float _s = sqrt((float(_k) + .5) / 24.), _a = float(_k) * 2.39996;
            vec2 _puv = uv + vec2(cos(_a), sin(_a)) * _s * _r / iResolution.xy;
            float _w = ${weight || '1.'};
            _sum += texture(iChannel0, _puv).rgb * _w;
            _total += _w;
        }
        c.rgb = _total > 0. ? _sum / _total : c.rgb;`;
}

/**
 * Keep a band across the screen sharp and blur the picture above and below it, as a tilt shift lens does, which
 * makes a scene look like a small model; it reads only the screen, so it works in 2D and 3D; put it first
 * @param {number|string} [focus] - Height of the middle of the sharp band, 0 the bottom of the screen and 1 the top
 * @param {number|string} [size] - Height of the sharp band, as a part of the screen
 * @param {number|string} [blur] - Widest blur in pixels, reached half the screen past the band, at most 32
 * @return {string}
 * @memberof PostProcess
 * @example
 * new PostProcessPlugin(postProcessEffects(postProcessTiltShift(.4, .2, 10), postProcessVignette(.5)));
 */
function postProcessTiltShift(focus=.5, size=.25, blur=8)
{
    postProcessBlurCheck(blur);
    const n = postProcessNumber;
    return `        // tilt shift
        float _r = ${n(blur)} * smoothstep(0., .5, abs(uv.y - ${n(focus)}) - ${n(size)} * .5);${postProcessDiscBlur()}`;
}

/**
 * Keep what is a distance from the camera sharp and blur what is nearer or farther, as a camera lens does; needs
 * render3D.depthTexture on, and blurs 3D only, 2D draws having no depth; put it first
 * - What is in focus stays sharp at its edges: a blur in front of or behind it leaves out what is in focus
 * @param {number|string} [focus] - Distance from the camera, along its view, that is sharpest, in world units
 * @param {number|string} [range] - How deep the sharp part is; the blur grows over as far again past it
 * @param {number|string} [blur] - Widest blur in pixels, at most 32
 * @return {string}
 * @memberof PostProcess
 * @example
 * render3D.depthTexture = true;
 * new PostProcessPlugin(postProcessEffects(postProcessDepthOfField(10, 4, 8)));
 */
function postProcessDepthOfField(focus=10, range=4, blur=8)
{
    postProcessBlurCheck(blur);
    const n = postProcessNumber;
    const amount = (depth)=> `${n(blur)} * smoothstep(0., ${n(range)}, abs(${depth} - ${n(focus)}) - ${n(range)} * .5)`;
    // a tap counts as far as its own blur reaches back to here, so a sharp thing in front is not smeared over
    return `        // depth of field, none where there is no depth, as with render3D.depthTexture off
        float _r = LJS_HAS_DEPTH ? ${amount('sceneDepth(uv)')} : 0.;${postProcessDiscBlur(`clamp(${amount('sceneDepth(_puv)')} - _s * _r + 1., 0., 1.)`)}`;
}

/**
 * Draw lines where the 3D depth jumps, around objects and along their creases; needs render3D.depthTexture on
 * @param {Color} [color] - The lines' color, its alpha how strong they are
 * @param {number|string} [thickness] - How wide the lines are in pixels
 * @param {number|string} [threshold] - How big a jump makes a line, as a part of the distance, lower draws more
 * @return {string}
 * @memberof PostProcess
 */
function postProcessOutline(color=BLACK, thickness=1, threshold=.02)
{
    ASSERT(isColor(color), 'outline color must be a Color');
    const n = postProcessNumber;
    return `        // outline
        vec2 _o = ${n(thickness)} / iResolution.xy;
        float _d = sceneDepth(uv);
        float _dx = abs(sceneDepth(uv + vec2(_o.x, 0)) + sceneDepth(uv - vec2(_o.x, 0)) - 2. * _d);
        float _dy = abs(sceneDepth(uv + vec2(0, _o.y)) + sceneDepth(uv - vec2(0, _o.y)) - 2. * _d);
        vec4 _line = vec4(${n(color.r)}, ${n(color.g)}, ${n(color.b)}, ${n(color.a)});
        if (LJS_HAS_DEPTH)
            c.rgb = mix(c.rgb, _line.rgb, _line.a * step(${n(threshold)}, max(_dx, _dy) / max(abs(_d), 1e-6)));`;
}

/**
 * The look of an old TV, as one effect to use alone or join with others: static noise, scan lines, a soft glow and
 * a vignette, and a bulged screen when curve is set; any setting at 0 leaves that part out
 * @param {Object} [settings]
 * @param {number|string} [settings.noise] - Static noise strength
 * @param {number|string} [settings.scanlines] - Scan line strength
 * @param {number|string} [settings.scanlineSpacing] - Pixels from one scan line to the next
 * @param {number|string} [settings.glow] - Soft glow strength
 * @param {number|string} [settings.vignette] - Vignette strength
 * @param {number|string} [settings.curve] - How much the screen bulges, 0 by default for flat
 * @return {string}
 * @example
 * new PostProcessPlugin(postProcessEffects(postProcessTV({scanlines: .4, curve: .1})));
 * @memberof PostProcess
 */
function postProcessTV({noise=.1, scanlines=.5, scanlineSpacing=6, glow=.4, vignette=1, curve=0}={})
{
    const parts = [];
    curve && parts.push(postProcessCurve(curve));
    glow && parts.push(postProcessGlow(0, glow, 2));
    scanlines && parts.push(postProcessScanlines(scanlines, scanlineSpacing));
    noise && parts.push(postProcessNoise(noise, 1));
    vignette && parts.push(postProcessVignette(vignette, 6));
    return parts.map((part)=> '    {\n' + part + '\n    }').join('\n');
}

/**
 * LittleJS Light System Plugin
 * - Adds 2D dynamic lighting to the scene
 * - Lights are first-class EngineObjects (the Light class)
 * - Each Light draws a soft falloff blob of its color into a shared lightmap
 * - Lights accumulate ADDITIVELY in the lightmap (red + blue = magenta)
 * - The lightmap is then MULTIPLIED with the scene during composite, so unlit
 *   areas go to the ambient color and lit areas show the scene tinted by the
 *   accumulated light color
 * - Draw the world at full brightness — the lightmap does the darkening
 * - The pass runs after gameRenderPost, so a HUD drawn there with WebGL is
 *   darkened too; draw the HUD with useWebGL=false (the main canvas) or from
 *   a plugin created after this one
 * - Any EngineObject may override renderLight() to additively contribute to the
 *   lightmap (e.g. lava that lights the floor around it, weapon flashes, glowing crystals)
 * - Set obj.emissive to 1 to show an object at full brightness in its own colors, lit or not, or between 0 and 1 for
 *   partly: it draws its shape into the lightmap through renderEmissive(), which calls render() by default; exact for
 *   solid pixels, a partly transparent one is self lit by its alpha too, so it shows darker
 * - Set lightSystem.shadows for objects to block light: each frame every object draws black into a
 *   shadow map through renderShadow(), which calls render() by default; obj.castShadow = false keeps it
 *   out (a floor TileLayer, a background), a draw's alpha sets how much light it blocks, and
 *   setShadowTransparent lets its color tint the light
 * - Set light.glow for a soft hazy glow over a light, like a lamp at night; it is added over the lit scene after the
 *   lightmap, so it shows in the dark and sits in front of everything there
 * - Must be constructed BEFORE PostProcessPlugin so post-process sees lit pixels
 * @namespace LightSystem
 */

///////////////////////////////////////////////////////////////////////////////

/** Global Light System plugin object
 *  @type {LightSystemPlugin}
 *  @memberof LightSystem */
let lightSystem;

///////////////////////////////////////////////////////////////////////////////

/**
 * LightSystemPlugin
 * - Owns the offscreen lightmap texture, falloff/composite shaders, and the
 *   per-frame render pass that multiplies the lightmap onto the WebGL scene
 * - The composite is MULTIPLICATIVE: unlit areas get the ambient color, lit
 *   areas show the scene tinted by the accumulated light color. So you should
 *   draw your world at full brightness — the lightmap handles the darkening.
 * @memberof LightSystem
 */
class LightSystemPlugin
{
    /** Create the global light system plugin.
     *  @param {Vector2} [textureSize]  - Size of the lightmap texture (defaults to following mainCanvasSize, which is css pixels, so the lightmap is not scaled by canvasPixelRatio; pass mainCanvasSize.scale(getCanvasPixelRatio()) for a full resolution lightmap)
     *  @param {Color}   [ambientColor] - Color applied to unlit areas of the scene (defaults to BLACK = pitch dark). Set a small RGB like rgb(0.1,0.1,0.15) for a faint "moonlight" baseline so unlit areas aren't fully black.
     *  @example
     *  // simplest usage
     *  new LightSystemPlugin();
     */
    constructor(textureSize, ambientColor)
    {
        ASSERT(engineInitialized || headlessMode, 'create the plugin after engineInit, e.g. in gameInit');
        ASSERT(!lightSystem, 'LightSystemPlugin already initialized');
        ASSERT(!postProcess, 'LightSystemPlugin must be created before PostProcessPlugin');
        lightSystem = this;

        /** @property {boolean} - When false, the render pass is skipped entirely */
        this.enabled = true;
        /** @property {Color} - Baseline color applied to unlit areas of the scene. Defaults to BLACK (pitch dark). Set to a small RGB for a faint ambient. The lightmap is cleared to this color each frame, then lights add on top, then the result multiplies the scene. */
        this.ambientColor = (ambientColor || BLACK).copy();
        /** @property {Vector2} - Size of the lightmap texture, follows mainCanvasSize (css pixels, so it is not scaled by canvasPixelRatio) unless a size was passed */
        this.textureSize = textureSize ? textureSize.copy() : undefined;
        /** @property {boolean} - True when no size was passed, so the lightmap follows mainCanvasSize */
        this.textureSizeAuto = !textureSize;

        /** @property {WebGLTexture|undefined} - The lightmap texture
         *  @type {WebGLTexture|undefined} */
        this.texture = undefined;
        /** @property {WebGLProgram|undefined} - Shader for drawing per-Light falloff blobs into the lightmap
         *  @type {WebGLProgram|undefined} */
        this.lightShader = undefined;
        /** @property {WebGLProgram|undefined} - Shader for compositing the lightmap over the main scene
         *  @type {WebGLProgram|undefined} */
        this.compositeShader = undefined;
        /** @property {WebGLVertexArrayObject|undefined} - Vertex array object for the light shader
         *  @type {WebGLVertexArrayObject|undefined} */
        this.lightVAO = undefined;
        /** @property {WebGLVertexArrayObject|undefined} - Vertex array object for the composite shader
         *  @type {WebGLVertexArrayObject|undefined} */
        this.compositeVAO = undefined;

        /** @property {boolean} - Cast shadows: every object draws black into a shadow map once a frame and each light's rays stop at them; off by default and free when off */
        this.shadows = false;
        /** @property {number} - Pixels across the square shadow map, made again when changed */
        this.shadowMapSize = 1024;
        /** @property {number} - How many times the larger side of the view the shadow map covers, so casters just off screen still cast in; raise it when lights reach further than a view past the screen */
        this.shadowMapScale = 2;
        /** @property {number} - Pixels across each light's own shadow texture, made again when changed; larger is sharper,
         *  and a gap between casters narrower than about 4*radius/shadowTextureSize world units closes */
        this.shadowTextureSize = 256;
        /** @property {number} - Stretch passes per shadow casting light, fewer is cheaper and shorter shadows */
        this.shadowPassCount = 16;
        /** @property {number} - How much light bleeds into a caster's near side, 0 for hard edged casters, 1 for most;
         *  the bleed reaches further in under a bigger light, so a thin wall under a big one lets some through, lower it
         *  for those */
        this.shadowSoftness = .5;
        /** @property {boolean} - True while the shadow pass runs, read only, so a render() can skip parts that should not cast */
        this.shadowPass = false;
        /** @property {boolean} - True while emissive objects draw into the lightmap, read only, see EngineObject.emissive */
        this.emissivePass = false;
        /** @property {WebGLTexture|undefined} - The shadow map, casters drawn black on white around the camera, read only
         *  @type {WebGLTexture|undefined} */
        this.shadowMap = undefined;
        /** @property {WebGLTexture|undefined} - One of the two textures each light's shadow is built in
         *  @type {WebGLTexture|undefined} */
        this.shadowTextureA = undefined;
        /** @property {WebGLTexture|undefined} - The other
         *  @type {WebGLTexture|undefined} */
        this.shadowTextureB = undefined;
        /** @property {WebGLProgram|undefined} - Copies the shadow map around a light into its texture
         *  @type {WebGLProgram|undefined} */
        this.shadowCopyShader = undefined;
        /** @property {WebGLProgram|undefined} - One stretch pass of a light's shadow texture
         *  @type {WebGLProgram|undefined} */
        this.shadowStretchShader = undefined;
        /** @property {WebGLVertexArrayObject|undefined} - Vertex array object for the copy shader
         *  @type {WebGLVertexArrayObject|undefined} */
        this.shadowCopyVAO = undefined;
        /** @property {WebGLVertexArrayObject|undefined} - Vertex array object for the stretch shader
         *  @type {WebGLVertexArrayObject|undefined} */
        this.shadowStretchVAO = undefined;
        /** @property {OffscreenCanvasRenderingContext2D|undefined} - Where Canvas2D draws go during the shadow and emissive passes, a 1x1 canvas, so text in a render() is not drawn twice
         *  @type {OffscreenCanvasRenderingContext2D|undefined} */
        this.shadowContext = undefined;
        /** @property {Vector2} - World position of the shadow map's bottom left corner, set each shadow pass */
        this.shadowMapOrigin = vec2();
        /** @property {number} - World size the shadow map covers, set each shadow pass */
        this.shadowMapWorldSize = 0;
        this.shadowMapSizeAllocated = 0;     // sizes the textures were made at, to remake them on a change
        this.shadowTextureSizeAllocated = 0;

        initLightSystem();
        engineAddPlugin(undefined, lightSystemRender,
            lightSystemContextLost, lightSystemContextRestored);

        function initLightSystem()
        {
            if (headlessMode) return;
            if (!glEnable)
            {
                console.warn('LightSystemPlugin: WebGL not enabled!');
                return;
            }

            // where Canvas2D draws go during the shadow and emissive passes
            lightSystem.shadowContext ||= createCanvasContext(1);

            // resolve texture size default at init time (mainCanvasSize may
            // not be set yet at the moment the constructor first ran), and
            // again on a context restore, the canvas may have changed since
            if (lightSystem.textureSizeAuto)
                lightSystem.textureSize = mainCanvasSize.copy();
            lightSystem.clampTextureSizes();

            // allocate the lightmap texture with null data at textureSize
            lightSystem.texture = glContext.createTexture();
            glContext.bindTexture(glContext.TEXTURE_2D, lightSystem.texture);
            glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA,
                lightSystem.textureSize.x, lightSystem.textureSize.y, 0,
                glContext.RGBA, glContext.UNSIGNED_BYTE, null);
            glContext.texParameteri(glContext.TEXTURE_2D, glContext.TEXTURE_MAG_FILTER, glContext.LINEAR);
            glContext.texParameteri(glContext.TEXTURE_2D, glContext.TEXTURE_MIN_FILTER, glContext.LINEAR);
            glContext.texParameteri(glContext.TEXTURE_2D, glContext.TEXTURE_WRAP_S, glContext.CLAMP_TO_EDGE);
            glContext.texParameteri(glContext.TEXTURE_2D, glContext.TEXTURE_WRAP_T, glContext.CLAMP_TO_EDGE);

            // light falloff shader: one quad per Light, fragment computes radial falloff
            lightSystem.lightShader = glCreateProgram(
                '#version 300 es\n' +
                'precision highp float;'+
                'uniform mat4 m;'+
                'uniform vec2 lightPos;'+
                'uniform float radius;'+
                'in vec2 g;'+              // unit quad geometry [0..1]
                'out vec2 vWorldPos;'+
                'out vec2 vUV;'+           // across the light's quad, the shadow texture's uv
                'void main(){'+
                'vec2 worldP=lightPos+(g-.5)*2.*radius;'+
                'gl_Position=m*vec4(worldP,1,1);'+
                'vWorldPos=worldP;'+
                'vUV=g;'+
                '}'
                ,
                '#version 300 es\n' +
                'precision highp float;'+
                'uniform vec2 lightPos;'+
                'uniform float radius;'+
                'uniform float fadeRange;'+
                'uniform vec4 color;'+
                'uniform sampler2D shadowTexture;'+ // this light's shadow, white where its rays reach
                'uniform bool useShadow;'+
                'in vec2 vWorldPos;'+
                'in vec2 vUV;'+
                'out vec4 c;'+
                'void main(){'+
                'float dist=distance(vWorldPos,lightPos);'+
                'float t=clamp((radius-dist)/max(fadeRange,1e-6),0.,1.);'+
                'c=vec4(color.rgb*t*color.a,1.);'+
                'if(useShadow)c.rgb*=texture(shadowTexture,vUV).rgb;'+
                '}'
            );
            // the shadow texture is on unit 1, the engine's tracked texture stays on unit 0
            glContext.useProgram(lightSystem.lightShader);
            glContext.uniform1i(glUniformLocation(lightSystem.lightShader, 'shadowTexture'), 1);

            // composite shader: fullscreen quad, samples the lightmap
            lightSystem.compositeShader = glCreateProgram(
                '#version 300 es\n' +
                'precision highp float;'+
                'in vec2 p;'+
                'void main(){'+
                'gl_Position=vec4(p+p-1.,1,1);'+
                '}'
                ,
                '#version 300 es\n' +
                'precision highp float;'+
                'uniform sampler2D s;'+
                'uniform vec3 iResolution;'+
                'out vec4 c;'+
                'void main(){'+
                'vec2 uv=gl_FragCoord.xy/iResolution.xy;'+
                'c=vec4(texture(s,uv).rgb,1.);'+
                '}'
            );

            // one quad VAO per program, the engine's unit triangle strip through the named attribute
            lightSystem.lightVAO = createQuadVAO(lightSystem.lightShader, 'g');
            lightSystem.compositeVAO = createQuadVAO(lightSystem.compositeShader, 'p');
        }
        function createQuadVAO(program, attribute)
        {
            const gl = glContext, vao = gl.createVertexArray();
            gl.bindVertexArray(vao);
            gl.bindBuffer(gl.ARRAY_BUFFER, glGeometryBuffer);
            const location = gl.getAttribLocation(program, attribute);
            gl.enableVertexAttribArray(location);
            gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 8, 0);
            return vao;
        }
        function createTexture(size)
        {
            const gl = glContext, texture = gl.createTexture();
            gl.bindTexture(gl.TEXTURE_2D, texture);
            gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, size, size, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
            gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
            return texture;
        }
        function initShadows()
        {
            const gl = glContext, ls = lightSystem;
            ls.shadowMap = createTexture(ls.shadowMapSize);
            ls.shadowTextureA = createTexture(ls.shadowTextureSize);
            ls.shadowTextureB = createTexture(ls.shadowTextureSize);
            ls.shadowMapSizeAllocated = ls.shadowMapSize;
            ls.shadowTextureSizeAllocated = ls.shadowTextureSize;
            // put back the texture the engine tracks
            if (glActiveTexture)
                gl.bindTexture(gl.TEXTURE_2D, glActiveTexture);

            const quadVertex =
                '#version 300 es\n' +
                'precision highp float;'+
                'in vec2 p;'+                   // unit quad [0..1]
                'out vec2 uv;'+
                'void main(){gl_Position=vec4(p+p-1.,1,1);uv=p;}';

            // copy: the shadow map around the light into the light's texture, light at the center
            ls.shadowCopyShader = glCreateProgram(quadVertex,
                '#version 300 es\n' +
                'precision highp float;'+
                'uniform sampler2D s;'+         // the shadow map
                'uniform vec2 lightPos;'+
                'uniform float radius;'+
                'uniform vec2 mapOrigin;'+      // world bottom left of the map
                'uniform float mapInvSize;'+    // 1 over the world size it covers
                'uniform float tap;'+           // half a texel of the light's texture, in world units
                'uniform float core;'+          // radius around the light where casters are left out
                'in vec2 uv;'+
                'out vec4 c;'+
                'void main(){'+
                'vec2 w=lightPos+(uv-.5)*2.*radius;'+  // world position of this texel
                'vec3 o=vec3(1);'+
                // the darkest of four taps a half texel out, so a caster a texel thin still covers two whole
                // texels, the stretch's filtering between two would leak through one
                'for(int i=0;i<4;i++){'+
                'vec2 m=(w+tap*(vec2(i%2,i/2)*2.-1.)-mapOrigin)*mapInvSize;'+ // in the map, world up at v=0
                // past the map's edge is open, clamping would stretch its edge texels across the light
                'o=min(o,m==clamp(m,0.,1.)?texture(s,vec2(m.x,1.-m.y)).rgb:vec3(1));'+
                '}'+
                'c=vec4(length(w-lightPos)<core?vec3(1):o,1);'+
                '}');

            // stretch: each texel keeps the darkest of itself and the texel toward the light, so a caster's
            // alpha and color carry through as they are; the bleed lights a caster's near side only where
            // the ray from the light still reaches, so it never lifts a texel already in shadow
            ls.shadowStretchShader = glCreateProgram(quadVertex,
                '#version 300 es\n' +
                'precision highp float;'+
                'uniform sampler2D s;'+         // the previous pass
                'uniform float scale;'+         // how much further out this pass pushes the casters
                'uniform float brightness;'+    // light bled into the near side of casters this pass
                'in vec2 uv;'+
                'out vec4 c;'+
                'void main(){'+
                'float mask=1.-smoothstep(.35,.525,length(uv-.5));'+ // full out to 70% of the radius, FrankEngine's light mask
                'vec3 b=texture(s,(uv-.5)/scale+.5).rgb;'+
                'c=vec4(min(texture(s,uv).rgb+brightness*mask*b,b),1);'+
                '}');

            ls.shadowCopyVAO = createQuadVAO(ls.shadowCopyShader, 'p');
            ls.shadowStretchVAO = createQuadVAO(ls.shadowStretchShader, 'p');

            // the plugin samples on unit 1 so the engine's tracked texture on unit 0 is untouched
            gl.useProgram(ls.shadowCopyShader);
            gl.uniform1i(glUniformLocation(ls.shadowCopyShader, 's'), 1);
            gl.useProgram(ls.shadowStretchShader);
            gl.uniform1i(glUniformLocation(ls.shadowStretchShader, 's'), 1);
        }
        function freeShadows()
        {
            const gl = glContext, ls = lightSystem;
            gl.deleteTexture(ls.shadowMap);
            gl.deleteTexture(ls.shadowTextureA);
            gl.deleteTexture(ls.shadowTextureB);
            gl.deleteProgram(ls.shadowCopyShader);
            gl.deleteProgram(ls.shadowStretchShader);
            gl.deleteVertexArray(ls.shadowCopyVAO);
            gl.deleteVertexArray(ls.shadowStretchVAO);
            clearShadows();
        }
        function clearShadows()
        {
            const ls = lightSystem;
            ls.shadowMap = ls.shadowTextureA = ls.shadowTextureB = undefined;
            ls.shadowCopyShader = ls.shadowStretchShader = undefined;
            ls.shadowCopyVAO = ls.shadowStretchVAO = undefined;
        }
        function lightSystemShadowPass()
        {
            const ls = lightSystem;

            // make the resources the first time, and again when a size changed
            ls.clampTextureSizes();
            if (!ls.shadowMap || ls.shadowMapSize !== ls.shadowMapSizeAllocated
                || ls.shadowTextureSize !== ls.shadowTextureSizeAllocated)
            {
                ls.shadowMap && freeShadows();
                initShadows();
            }

            // a square of world space around the camera, rounded to its own texels so the
            // grid stays put in the world as the camera moves, or the shadows would shimmer
            const size = ls.shadowMapSize;
            const view = mainCanvasSize.scale(1/cameraScale);
            const worldSize = ls.shadowMapScale * max(view.x, view.y);
            const texel = worldSize / size;
            const center = vec2(floor(cameraPos.x/texel)*texel, floor(cameraPos.y/texel)*texel);
            ls.shadowMapOrigin = center.subtract(vec2(worldSize/2));
            ls.shadowMapWorldSize = worldSize;

            // draw with the map's camera, the way a tile layer redraw does; Canvas2D draws
            // go to a 1x1 canvas so text in a render() does not reach the screen twice
            const saved = [drawContext, mainCanvasSize, cameraPos, cameraScale, cameraAngle, canvasClearColor, glCustomShader];
            drawContext = ls.shadowContext;
            mainCanvasSize = vec2(size);
            cameraPos = center;
            cameraScale = size / worldSize;
            cameraAngle = 0;
            canvasClearColor = WHITE;
            glSetRenderTarget(ls.shadowMap, true);
            glSkipScreenSpace = true; // the map's camera would put them anywhere
            ls.shadowPass = true;
            try
            {
                for (const o of engineObjects)
                {
                    if (o.destroyed || !o.castShadow) continue;
                    // every color black, its alpha kept, set for each object since a render that left
                    // setShadowTransparent on ends with it
                    glColorMask = 0xff000000;
                    setShader(o.shader); // its own Shader as in the main pass, so a snippet that cuts holes casts the same shape
                    o.renderShadow();
                }
            }
            finally
            {
                // hand everything back even when a render threw, or every frame after it draws black with no text
                ls.shadowPass = false;
                glColorMask = -1;
                glSkipScreenSpace = false;
                glSetRenderTarget();
                [drawContext, mainCanvasSize, cameraPos, cameraScale, cameraAngle, canvasClearColor, glCustomShader] = saved;
            }
        }
        function lightSystemRender()
        {
            if (headlessMode || !glEnable) return;
            if (!lightSystem.enabled) return;
            if (!lightSystem.texture)
            {
                // made now if WebGL was off when the plugin was made, or when a lost context came back
                if (glContext.isContextLost()) return;
                initLightSystem();
                if (!lightSystem.texture) return;
            }

            // 1. flush any in-flight sprite batch from earlier render passes
            glFlush();
            const prevAdditive = glAdditive;

            // 1b. the shadow pass draws every caster black into the shadow map
            if (lightSystem.shadows)
                lightSystemShadowPass();

            // an automatic size follows the canvas, so reallocate the lightmap when
            // the canvas changed size, after the flush so the batch keeps its texture
            const size = lightSystem.textureSize;
            const wantX = glClampTextureSize(mainCanvasSize.x), wantY = glClampTextureSize(mainCanvasSize.y);
            if (lightSystem.textureSizeAuto && (size.x !== wantX || size.y !== wantY))
            {
                lightSystem.textureSize = vec2(wantX, wantY);
                glContext.bindTexture(glContext.TEXTURE_2D, lightSystem.texture);
                glContext.texImage2D(glContext.TEXTURE_2D, 0, glContext.RGBA,
                    wantX, wantY, 0,
                    glContext.RGBA, glContext.UNSIGNED_BYTE, null);
                // put back the texture the engine tracks, a draw in renderLight must not sample the lightmap
                if (glActiveTexture)
                    glContext.bindTexture(glContext.TEXTURE_2D, glActiveTexture);
            }

            // 2. bind lightmap as render target, clear to ambientColor
            const ac = lightSystem.ambientColor;
            glContext.bindFramebuffer(glContext.FRAMEBUFFER, glFramebuffer);
            glContext.framebufferTexture2D(glContext.FRAMEBUFFER,
                glContext.COLOR_ATTACHMENT0, glContext.TEXTURE_2D, lightSystem.texture, 0);
            glContext.viewport(0, 0, lightSystem.textureSize.x, lightSystem.textureSize.y);
            glContext.clearColor(ac.r, ac.g, ac.b, ac.a);
            glContext.clear(glContext.COLOR_BUFFER_BIT);

            // 3. walk engineObjects calling renderLight() — additive blend
            //    (lightmap accumulates raw additive color contributions)
            setAdditiveBlendMode();
            glContext.enable(glContext.BLEND);
            glContext.blendFunc(glContext.ONE, glContext.ONE);

            // the camera transform is the same for every light, and a uniform
            // keeps its value per program, so set it once for the whole pass.
            // It is the canvas transform glPreRender built: world→NDC over
            // mainCanvasSize (not textureSize), the viewport handles the
            // lightmap's actual resolution. No y-flip: the composite samples
            // this FBO with gl_FragCoord/iResolution (origin bottom-left), so
            // storing world +Y at the top of the texture lines up with the canvas.
            const ls = lightSystem.lightShader;
            glContext.useProgram(ls);
            glContext.uniformMatrix4fv(glUniformLocation(ls, 'm'), false, glTransform);
            glSetInstancedMode(true);

            // a target set and ended while the lights draw, a tile layer redrawn in a renderLight, comes back here
            glRenderTargetBase = [lightSystem.texture, lightSystem.textureSize];
            try
            {
                for (const o of engineObjects)
                {
                    if (o.destroyed) continue;
                    glAdditive || setAdditiveBlendMode(); // added again, an emitter ends its render with it off
                    o.renderLight();
                }

                // 3b. emissive objects draw their shape in gray at their emissive level, white at 1, adding that much
                //     light where they are so they show their own colors; text goes to the 1x1 canvas as in the
                //     shadow pass, so it is not drawn twice
                const saved = [drawContext, glCustomShader];
                drawContext = lightSystem.shadowContext;
                lightSystem.emissivePass = true;
                try
                {
                    for (const o of engineObjects)
                    {
                        if (o.destroyed || !(o.emissive > 0)) continue;
                        const level = clamp(o.emissive)*255+.5|0; // packed like rgbaInt, red in the low byte
                        glColorMask = 0xff000000; // its own alpha, and the gray from the additive color
                        glColorAdditive = level | level<<8 | level<<16;
                        glAdditive || setAdditiveBlendMode(); // added, an emitter ends its render with it off
                        setShader(o.shader);
                        o.renderEmissive();
                    }
                    glFlush();
                }
                finally
                {
                    lightSystem.emissivePass = false;
                    glColorMask = -1;
                    glColorAdditive = 0;
                    [drawContext, glCustomShader] = saved;
                }
            }
            finally
            {
                glRenderTargetBase = undefined;
            }

            // 4. drain any sprite-batched draws (e.g. drawTile inside a
            //    custom renderLight override) so they hit the FBO, not the
            //    canvas after we unbind
            glFlush();
            glContext.bindFramebuffer(glContext.FRAMEBUFFER, null);

            // backing store size, mainCanvasSize is css pixels
            glContext.viewport(0, 0, glCanvas.width, glCanvas.height);

            // 5. composite: fullscreen quad, multiplicative blend onto glCanvas
            //    (scene * lightmap — unlit areas go to black, lit areas are
            //    the scene tinted by the accumulated light color)
            glContext.useProgram(lightSystem.compositeShader);
            glContext.bindVertexArray(lightSystem.compositeVAO);
            glContext.activeTexture(glContext.TEXTURE0);
            glContext.bindTexture(glContext.TEXTURE_2D, lightSystem.texture);
            const cs = lightSystem.compositeShader;
            glContext.uniform1i(glUniformLocation(cs, 's'), 0);
            glContext.uniform3f(glUniformLocation(cs, 'iResolution'),
                mainCanvas.width, mainCanvas.height, 1);
            glContext.blendFunc(glContext.DST_COLOR, glContext.ZERO);
            glContext.drawArrays(glContext.TRIANGLE_STRIP, 0, 4);

            // 6. restore engine state so subsequent draws use the engine's
            //    tracked texture binding (otherwise glSetTexture would think
            //    the prior texture was still bound when actually the lightmap
            //    is, and any debug text / future draw could sample the lightmap)
            if (glActiveTexture)
                glContext.bindTexture(glContext.TEXTURE_2D, glActiveTexture);
            glSetInstancedMode(true);

            // 7. the lights' glows, added over the lit scene so the darkness does not dim them
            setAdditiveBlendMode();
            for (const o of engineObjects)
                o instanceof Light && !o.destroyed && o.renderGlow();
            glFlush();
            setAdditiveBlendMode(prevAdditive);
        }
        function lightSystemContextLost()
        {
            lightSystem.texture = undefined;
            lightSystem.lightShader = undefined;
            lightSystem.compositeShader = undefined;
            lightSystem.lightVAO = undefined;
            lightSystem.compositeVAO = undefined;
            clearShadows();
            LOG('LightSystemPlugin: WebGL context lost');
        }
        function lightSystemContextRestored()
        {
            initLightSystem();
            LOG('LightSystemPlugin: WebGL context restored');
        }
    }

    /** Bring the sizes of the textures it makes down to what the device can make: shadowMapSize, shadowTextureSize
     *  and a textureSize given by hand; called before they are made, so a size too big falls back instead of failing */
    clampTextureSizes()
    {
        this.shadowMapSize = glClampTextureSize(this.shadowMapSize);
        this.shadowTextureSize = glClampTextureSize(this.shadowTextureSize);
        const size = this.textureSize;
        if (!size) return;
        const x = glClampTextureSize(size.x), y = glClampTextureSize(size.y);
        if (x !== size.x || y !== size.y)
            this.textureSize = vec2(x, y); // only when it is too large, this runs every frame
    }

    /** Draw a single Light's falloff blob into the currently bound lightmap.
     *  Called by Light.renderLight() during the plugin's render pass.
     *  @param {Light} light */
    drawLight(light)
    {
        if (headlessMode || !glEnable || !this.lightShader) return;

        // skip a light that can not touch the screen, its quad is the full
        // radius out from its center on every side
        if (!isOnScreen(light.pos, light.radius*2)) return;

        // drain any sprite-batched draws queued by a previous custom
        // renderLight() override (e.g. drawRect inside a LavaTile). They were
        // queued in the engine's instanced-vertex format and must flush with
        // the engine's shader+VAO bound — NOT this plugin's light shader.
        glFlush();

        // a shadow casting light builds its shadow texture first, leaving it on unit 1 and the lightmap bound
        const useShadow = this.shadows && light.castShadow && !!this.shadowMap;
        useShadow && this.renderLightShadow(light);

        glContext.useProgram(this.lightShader);
        glContext.bindVertexArray(this.lightVAO);
        glContext.enable(glContext.BLEND);
        glContext.blendFunc(glContext.ONE, glContext.ONE); // added, whatever a tile layer redrawn before it left set

        // the camera transform 'm' was set once for the pass by the plugin
        const ls = this.lightShader;
        glContext.uniform2f(glUniformLocation(ls, 'lightPos'), light.pos.x, light.pos.y);
        glContext.uniform1f(glUniformLocation(ls, 'radius'), light.radius);
        glContext.uniform1f(glUniformLocation(ls, 'fadeRange'), light.fadeRange);
        glContext.uniform1i(glUniformLocation(ls, 'useShadow'), useShadow ? 1 : 0);
        const c = light.color;
        glContext.uniform4f(glUniformLocation(ls, 'color'), c.r, c.g, c.b, c.a);

        glContext.drawArrays(glContext.TRIANGLE_STRIP, 0, 4);

        // restore engine's instanced shader+VAO so subsequent renderLight()
        // overrides that batch through drawRect/drawTile work correctly
        glSetInstancedMode(true);
    }

    /** Build a light's shadow texture from the shadow map: the map around the light, its casters stretched
     *  away from the light a little further each pass with light bled into their near sides. Leaves the
     *  result on texture unit 1 and the lightmap bound again. Called by drawLight.
     *  @param {Light} light */
    renderLightShadow(light)
    {
        const gl = glContext, size = this.shadowTextureSize;
        gl.disable(gl.BLEND);
        gl.viewport(0, 0, size, size);
        gl.activeTexture(gl.TEXTURE1);

        // the shadow map around the light, light at the center of the texture
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.shadowTextureA, 0);
        const cs = this.shadowCopyShader;
        gl.useProgram(cs);
        gl.bindVertexArray(this.shadowCopyVAO);
        gl.bindTexture(gl.TEXTURE_2D, this.shadowMap);
        gl.uniform2f(glUniformLocation(cs, 'lightPos'), light.pos.x, light.pos.y);
        gl.uniform1f(glUniformLocation(cs, 'radius'), light.radius);
        gl.uniform2f(glUniformLocation(cs, 'mapOrigin'), this.shadowMapOrigin.x, this.shadowMapOrigin.y);
        gl.uniform1f(glUniformLocation(cs, 'mapInvSize'), 1/this.shadowMapWorldSize);
        gl.uniform1f(glUniformLocation(cs, 'tap'), light.radius/size);
        gl.uniform1f(glUniformLocation(cs, 'core'), light.shadowCore);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

        // stretch the casters out from the light, starting a 128th of the texture and growing 1.5x a pass, which
        // reaches the edge in about 16 passes with no gaps since each pass scales by less than the shadow already
        // extends; small steps, so the bleed does not show as stairs along the shadow edges; a fraction of the
        // texture rather than a count of texels, so a larger texture only makes the shadows sharper, not shorter;
        // the bleed fades out over the first 10 passes, the distances FrankEngine's soften covered at 1.8x
        const ss = this.shadowStretchShader;
        gl.useProgram(ss);
        gl.bindVertexArray(this.shadowStretchVAO);
        let src = this.shadowTextureA, dst = this.shadowTextureB;
        for (let k = 0; k < this.shadowPassCount; ++k)
        {
            gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, dst, 0);
            gl.bindTexture(gl.TEXTURE_2D, src);
            gl.uniform1f(glUniformLocation(ss, 'scale'), 1 + 2*1.5**k/256);
            gl.uniform1f(glUniformLocation(ss, 'brightness'), clamp((10.1-k)/7.2)**2 * this.shadowSoftness);
            gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
            [src, dst] = [dst, src];
        }

        // leave the result on unit 1 for the light shader and go back to the lightmap
        gl.bindTexture(gl.TEXTURE_2D, src);
        gl.activeTexture(gl.TEXTURE0);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, this.texture, 0);
        gl.viewport(0, 0, this.textureSize.x, this.textureSize.y);
        gl.enable(gl.BLEND);
        gl.blendFunc(gl.ONE, gl.ONE);
    }

    /** In the shadow pass, let the draws that follow keep their color in the shadow map, so light passing
     *  through them is tinted instead of blocked: a stained glass window, colored smoke. Any draw blocks light
     *  by its alpha, so a fading sprite casts a fading shadow; this keeps the color as well. It covers what was drawn
     *  under it in the map as any draw does, so glass drawn after a wall cuts a tinted window in the wall's shadow, and
     *  a wall drawn after the glass covers it. Does nothing outside
     *  the pass, so a render() can call it around those draws unconditionally; set it back to false after them.
     *  @param {boolean} [transparent] */
    setShadowTransparent(transparent=true)
    {
        // the mask applies as each draw is queued, so nothing needs flushing
        if (this.shadowPass)
            glColorMask = transparent ? -1 : 0xff000000;
    }
}

///////////////////////////////////////////////////////////////////////////////

/**
 * A Light is an EngineObject that contributes a soft additive blob of color
 * to the LightSystem plugin's lightmap.
 * - castShadow on a Light means its rays stop at casters when lightSystem.shadows is on, three.js's meaning
 *   for a light; a Light's own render() draws nothing so the object meaning never applies to it
 * - A light inside a caster is blocked entirely, so the object that holds it, its lamp, a torch, the player
 *   carrying it, needs a shadowCore that reaches past it, castShadow = false, or a renderShadow that leaves
 *   the light's spot out
 * @extends EngineObject
 * @memberof LightSystem
 * @example
 * new Light(vec2(5, 5), 4, rgb(1, 0.5, 0));        // orange light, full soft blob
 * new Light(vec2(0, 0), 8, rgb(1, 1, 1), 2);       // white core with 2-unit soft halo
 */
class Light extends EngineObject
{
    /** Create a light object and add it to the engine object list
     *  @param {Vector2} pos - World space position
     *  @param {number} radius - Total extent of the light in world units
     *  @param {Color} [color] - Color of the light; alpha modulates intensity
     *  @param {number} [fadeRange] - Width of the soft edge in world units (defaults to radius) */
    constructor(pos, radius, color, fadeRange)
    {
        super(pos, vec2(1), undefined, 0, color);
        this.mass = 0; // static, a light stays where it is put in a game with gravity
        ASSERT(isNumber(radius) && radius >= 0, 'Light radius must be a non-negative number');
        ASSERT(fadeRange === undefined || (isNumber(fadeRange) && fadeRange >= 0),
            'Light fadeRange must be a non-negative number when provided');

        /** @property {number} - Total extent of the light in world units */
        this.radius = radius;
        /** @property {number} - Width of the soft edge in world units */
        this.fadeRange = fadeRange === undefined ? radius : fadeRange;
        /** @property {number} - Radius around the light where casters are left out of its shadow, so the lamp
         *  or torch that holds it, or the player carrying it, does not block it; it has to reach past that object's
         *  corners, about half its diagonal and a little more, or dark rays run out from them */
        this.shadowCore = 0;
        /** @property {number} - Size across of a soft hazy glow drawn over the light, like a lamp at night, 0 for
         *  none; it is added over the lit scene, in front of everything there */
        this.glow = 0;
        /** @property {number} - How fast the glow fades from its middle: 1 by default, .5 a wide haze, 2 a tight
         *  bright core */
        this.glowFalloff = 1;
        /** @type {TileInfo|undefined} */
        this.glowTileInfo = undefined; // the whole glow texture, kept for the falloff it was made for
    }

    /** Lights are invisible in the main render pass — they only contribute
     *  to the lightmap via renderLight(). */
    render() {}

    /** Draw this light's falloff blob into the lightmap.
     *  Called by LightSystemPlugin during its render pass. No-op when the
     *  plugin or WebGL is unavailable. */
    renderLight()
    {
        lightSystem && lightSystem.drawLight(this);
    }

    /** Draw this light's glow, soft and round, its glow size across and in its color, added over the lit scene;
     *  called by LightSystemPlugin after the lightmap is applied */
    renderGlow()
    {
        if (!(this.glow > 0)) return;
        const size = vec2(this.glow);
        if (!isOnScreen(this.pos, size)) return;
        const texture = engineGlowTexture(this.glowFalloff);
        if (!texture) return;
        if (this.glowTileInfo?.textureInfo !== texture)
            this.glowTileInfo = new TileInfo(vec2(), texture.size, texture);
        drawTile(this.pos, size, this.glowTileInfo, this.color, 0, false, undefined, true, false);
    }
}

/**
 * LittleJS Audio Effects Plugin
 * - Web Audio effects with a wet/dry mix: filter, reverb, delay, distortion, compressor
 * - Route a sound through one with sound.output = effect
 * - Route everything with setAudioMasterEffect(effect)
 * - Chain effects with effect.connect(nextEffect)
 * @namespace AudioEffects
 */

///////////////////////////////////////////////////////////////////////////////
// audioParamRamp lives in engineAudio.js, core loads before plugins in the bundle
/**
 * Base class for audio effects, an input and output with a wet/dry mix between them
 * - Sounds connect to input, output goes to the master gain until connect() moves it
 * - Subclasses put their nodes between input and the wet gain with connectEffect
 * @memberof AudioEffects
 * @example
 * const cave = new AudioReverb(3, 2);
 * footstep.output = cave; // every play of this sound is in the cave
 */
class AudioEffect
{
    /** Create an audio effect
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(mix=1)
    {
        ASSERT(isNumber(mix), 'mix must be a number');

        /** @property {number} - Wet/dry balance, 0 is fully dry and 1 is fully wet */
        this.mix = clamp(mix);
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {GainNode} - Connect sounds to this node */
        this.input = audioContext.createGain();
        /** @property {GainNode} - This node carries the mixed result, send it somewhere with connect(), never by assigning here
         *  - Unlike sound.output, which is where a sound's audio goes and can be set to an effect */
        this.output = audioContext.createGain();
        /** @property {GainNode} - Level of the unprocessed signal */
        this.dryGain = audioContext.createGain();
        /** @property {GainNode} - Level of the processed signal */
        this.wetGain = audioContext.createGain();

        this.input.connect(this.dryGain).connect(this.output);
        this.wetGain.connect(this.output);
        this.setMix(mix);

        // send the result to the speakers, connect() moves it into a chain instead
        this.output.connect(audioMasterGain);
    }

    /** Set the wet/dry balance
     *  @param {number} mix - 0 is fully dry and 1 is fully wet
     *  @param {number} [fadeTime] - Seconds to ramp over so the change doesn't click */
    setMix(mix, fadeTime=0)
    {
        ASSERT(isNumber(mix), 'mix must be a number');
        this.mix = mix = clamp(mix);
        if (!audioContext) return;
        this.rampParam(this.dryGain.gain, 1-mix, fadeTime);
        this.rampParam(this.wetGain.gain, mix, fadeTime);
    }

    /** Ramp one of this effect's params, keeping the effect running until the ramp is done
     *  - The browser drops an effect from rendering while nothing plays through it, which
     *    would freeze a ramp partway, so a silent source feeds the input for the ramp's length
     *  @param {AudioParam} param - The param to ramp
     *  @param {number} value - Where to ramp to
     *  @param {number} [fadeTime] - Seconds to ramp over, 0 sets the value at once
     *  @protected */
    rampParam(param, value, fadeTime=0)
    {
        audioParamRamp(param, value, fadeTime);
        if (!fadeTime) return;
        const keepAlive = new ConstantSourceNode(audioContext, { offset: 0 });
        keepAlive.connect(this.input);
        keepAlive.onended = ()=> keepAlive.disconnect();
        keepAlive.start();
        keepAlive.stop(audioContext.currentTime + fadeTime);
    }

    /** Send this effect's output into another effect or audio node instead of the speakers
     *  @template {AudioEffect|AudioNode} T
     *  @param {T} target - The next effect in the chain, or any audio node
     *  @return {T} - The target, so chains read left to right */
    connect(target)
    {
        if (!audioContext) return target; // no audio outside a browser, where the engine runs headless

        // an effect stands in for its input node, the same rule as sound.output
        const node = /** @type {AudioNode} */ (target && 'input' in target ? target.input : target);
        ASSERT(node && typeof node.connect === 'function', 'target must be an AudioEffect or AudioNode');
        this.output.disconnect();
        this.output.connect(node);
        return target;
    }

    /** Stop sending this effect's output anywhere */
    disconnect() { this.output?.disconnect(); }

    /** Wire nodes between the input and the wet gain, for subclasses
     *  @param {AudioNode} first - Node the input connects to
     *  @param {AudioNode} [last=first] - Node that connects to the wet gain
     *  @protected */
    connectEffect(first, last=first)
    {
        this.input.connect(first);
        last.connect(this.wetGain);
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Filter effect, muffle sounds underwater or behind a wall
 * @extends AudioEffect
 * @memberof AudioEffects
 * @example
 * const muffle = new AudioFilter('lowpass', 400);
 * setAudioMasterEffect(muffle);
 * muffle.setFrequency(20000, .5); // sweep back to clear
 */
class AudioFilter extends AudioEffect
{
    /** Create a filter effect
     *  @param {BiquadFilterType} [type] - lowpass, highpass, bandpass, notch, etc.
     *  @param {number} [frequency] - Cutoff or center frequency in Hz
     *  @param {number} [q] - Resonance at the cutoff, higher is sharper
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(type='lowpass', frequency=1000, q=1, mix=1)
    {
        super(mix);
        ASSERT(isNumber(frequency) && frequency >= 0, 'frequency must be positive or zero');
        ASSERT(isNumber(q), 'q must be a number');
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {BiquadFilterNode} - The filter node */
        this.node = audioContext.createBiquadFilter();
        this.node.type = type;
        this.node.frequency.value = frequency;
        this.node.Q.value = q;
        this.connectEffect(this.node);
    }

    /** Set the cutoff or center frequency
     *  @param {number} frequency - Frequency in Hz
     *  @param {number} [fadeTime] - Seconds to sweep over */
    setFrequency(frequency, fadeTime=0)
    {
        ASSERT(isNumber(frequency) && frequency >= 0, 'frequency must be positive or zero');
        if (!audioContext) return;
        this.rampParam(this.node.frequency, frequency, fadeTime);
    }

    /** Set the resonance at the cutoff
     *  @param {number} q - Higher is sharper
     *  @param {number} [fadeTime] - Seconds to ramp over */
    setQ(q, fadeTime=0)
    {
        ASSERT(isNumber(q), 'q must be a number');
        if (!audioContext) return;
        this.rampParam(this.node.Q, q, fadeTime);
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Reverb effect, puts sounds in a room, cave, or hall
 * - The impulse response is generated, no audio file needed
 * @extends AudioEffect
 * @memberof AudioEffects
 * @example
 * const hall = new AudioReverb(4, 1.5, .4);
 * footstep.output = hall;
 */
class AudioReverb extends AudioEffect
{
    /** Create a reverb effect
     *  @param {number} [duration] - Seconds until the reverb tail is silent
     *  @param {number} [decay] - How quickly the tail fades, higher is faster
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(duration=2, decay=2, mix=.5)
    {
        super(mix);
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {ConvolverNode} - The convolver node */
        this.node = audioContext.createConvolver();
        this.setRoom(duration, decay);
        this.connectEffect(this.node);
    }

    /** Change the room by rebuilding the impulse response
     *  @param {number} duration - Seconds until the reverb tail is silent
     *  @param {number} [decay] - How quickly the tail fades, higher is faster */
    setRoom(duration, decay=2)
    {
        ASSERT(isNumber(duration) && duration > 0, 'duration must be positive');
        ASSERT(isNumber(decay) && decay > 0, 'decay must be positive');
        if (!audioContext) return;
        this.node.buffer = this.createImpulse(duration, decay);
    }

    /** Build a stereo impulse response of decaying noise
     *  @param {number} duration - Seconds until silence
     *  @param {number} decay - How quickly it fades, higher is faster
     *  @return {AudioBuffer} */
    createImpulse(duration, decay)
    {
        const sampleRate = audioContext.sampleRate;
        const length = max(1, sampleRate * duration | 0);
        const buffer = audioContext.createBuffer(2, length, sampleRate);
        for (let channel = 2; channel--;)
        {
            const samples = buffer.getChannelData(channel);
            for (let i = length; i--;)
                samples[i] = rand(-1, 1) * (1 - i/length) ** decay;
        }
        return buffer;
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Delay effect, echoes that repeat and fade
 * @extends AudioEffect
 * @memberof AudioEffects
 * @example
 * const canyon = new AudioDelay(.4, .5);
 * shout.output = canyon;
 */
class AudioDelay extends AudioEffect
{
    /** Create a delay effect
     *  @param {number} [time] - Seconds between echoes, up to 5
     *  @param {number} [feedback] - How much of each echo repeats, 0 to .95
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(time=.3, feedback=.4, mix=.5)
    {
        super(mix);
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {DelayNode} - The delay node */
        this.node = audioContext.createDelay(5);
        /** @property {GainNode} - How much of the delayed signal feeds back in */
        this.feedbackGain = audioContext.createGain();
        this.node.connect(this.feedbackGain).connect(this.node);
        this.connectEffect(this.node);
        this.setTime(time);
        this.setFeedback(feedback);
    }

    /** Set the time between echoes
     *  - Browsers hold a delay in a feedback loop to at least one render quantum, so 0 is not a bypass
     *  @param {number} time - Seconds, up to 5
     *  @param {number} [fadeTime] - Seconds to ramp over, pitch bends while it moves */
    setTime(time, fadeTime=0)
    {
        ASSERT(isNumber(time) && time >= 0 && time <= 5, 'time must be between 0 and 5');
        if (!audioContext) return;
        this.rampParam(this.node.delayTime, time, fadeTime);
    }

    /** Set how much of each echo repeats, clamped below 1 so it always dies out
     *  @param {number} feedback - 0 to .95
     *  @param {number} [fadeTime] - Seconds to ramp over */
    setFeedback(feedback, fadeTime=0)
    {
        ASSERT(isNumber(feedback), 'feedback must be a number');
        if (!audioContext) return;
        this.rampParam(this.feedbackGain.gain, clamp(feedback, 0, .95), fadeTime);
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Distortion effect, overdrive for radios, damaged robots, and engines
 * @extends AudioEffect
 * @memberof AudioEffects
 * @example
 * const radio = new AudioDistortion(.8);
 * voice.output = radio;
 */
class AudioDistortion extends AudioEffect
{
    /** Create a distortion effect
     *  @param {number} [amount] - How hard to drive the signal, 0 is clean and 1 is crushed
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(amount=.5, mix=1)
    {
        super(mix);

        /** @property {number} - How hard the signal is driven, 0 is clean and 1 is crushed */
        this.amount = clamp(amount);
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {WaveShaperNode} - The wave shaper node */
        this.node = audioContext.createWaveShaper();
        this.node.oversample = '2x';
        this.setAmount(amount);
        this.connectEffect(this.node);
    }

    /** Set how hard to drive the signal, rebuilds the shaping curve
     *  @param {number} amount - 0 is clean and 1 is crushed */
    setAmount(amount)
    {
        ASSERT(isNumber(amount), 'amount must be a number');
        this.amount = amount = clamp(amount);
        if (!audioContext) return;

        // soft clip curve, drive grows with the square of amount so low values stay subtle
        // enough points that quiet signals are still shaped at high drive, where the curve is steep near 0
        const drive = 100 * amount * amount;
        const samples = 1024;
        const curve = new Float32Array(samples);
        for (let i = samples; i--;)
        {
            const x = i * 2 / (samples - 1) - 1;
            curve[i] = (1 + drive) * x / (1 + drive * abs(x));
        }
        this.node.curve = curve;
    }
}

///////////////////////////////////////////////////////////////////////////////
/**
 * Compressor effect, evens out loud and quiet so many sounds at once don't clip
 * - Meant for the master bus, it is not on by default
 * @extends AudioEffect
 * @memberof AudioEffects
 * @example
 * const compressor = new AudioCompressor;
 * setAudioMasterEffect(compressor);
 */
class AudioCompressor extends AudioEffect
{
    /** Create a compressor effect
     *  @param {number} [threshold] - Level in dB above which the signal is reduced
     *  @param {number} [ratio] - How much to reduce it, 12 means 12 dB in becomes 1 dB out
     *  @param {number} [mix] - Wet/dry balance, 0 is fully dry and 1 is fully wet */
    constructor(threshold=-24, ratio=12, mix=1)
    {
        super(mix);
        ASSERT(isNumber(threshold), 'threshold must be a number');
        ASSERT(isNumber(ratio) && ratio >= 1, 'ratio must be 1 or more');
        if (!audioContext) return; // no audio outside a browser, where the engine runs headless

        /** @property {DynamicsCompressorNode} - The compressor node */
        this.node = audioContext.createDynamicsCompressor();
        this.node.threshold.value = threshold;
        this.node.ratio.value = ratio;
        this.connectEffect(this.node);
    }

    /** Set the level above which the signal is reduced
     *  @param {number} threshold - Level in dB
     *  @param {number} [fadeTime] - Seconds to ramp over */
    setThreshold(threshold, fadeTime=0)
    {
        ASSERT(isNumber(threshold), 'threshold must be a number');
        if (!audioContext) return;
        this.rampParam(this.node.threshold, threshold, fadeTime);
    }

    /** Set how much the signal is reduced above the threshold
     *  @param {number} ratio - 1 is no reduction, 20 is a hard limit
     *  @param {number} [fadeTime] - Seconds to ramp over */
    setRatio(ratio, fadeTime=0)
    {
        ASSERT(isNumber(ratio) && ratio >= 1, 'ratio must be 1 or more');
        if (!audioContext) return;
        this.rampParam(this.node.ratio, ratio, fadeTime);
    }
}

/**
 * LittleJS User Interface Plugin
 * - call new UISystemPlugin() to setup the UI system
 * - Gamepad and keyboard navigation support
 * - Nested Menus
 * - Text
 * - Buttons
 * - Checkboxes
 * - Images
 * - Sliders
 * - Video
 * @namespace UISystem
 */

///////////////////////////////////////////////////////////////////////////////

/** Global UI system plugin object
 *  @type {UISystemPlugin}
 *  @memberof UISystem */
let uiSystem;

/** Enable UI system debug drawing
 *  0=off, 1=normal, 2=show invisible
 *  @type {number}
 *  @default
 *  @memberof UISystem */
let uiDebug = 0;

/** Enable UI system debug drawing
 *  0=off, 1=normal, 2=show invisible
 *  @param {number|boolean} debugMode
 *  @memberof UISystem */
function uiSetDebug(debugMode)
{ uiDebug = typeof debugMode === 'boolean' ? (debugMode ? 1 : 0) : debugMode; }

/**
 * @callback DragAndDropCallback - Callback for drag and drop events
 * @param {DragEvent} event - The drag event
 * @memberof UISystem
 */

///////////////////////////////////////////////////////////////////////////////
/**
 * UI System Global Object
 * @memberof UISystem
 */
class UISystemPlugin
{
    /** Create the global UI system object
     *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context]
     *  @example
     *  // create the ui plugin object
     *  new UISystemPlugin;
     */
    constructor(context=mainContext)
    {
        ASSERT(!uiSystem, 'UI system already initialized');
        ASSERT(context || headlessMode, 'create the UISystemPlugin after engineInit, in gameInit');
        uiSystem = this;

        // default settings
        /** @property {boolean} - Activate when mouse is pressed down instead of clicked */
        this.activateOnPress = false;
        /** @property {Color} - Default fill color for UI elements */
        this.defaultColor = WHITE;
        /** @property {Color} - Default outline color for UI elements */
        this.defaultLineColor = BLACK;
        /** @property {Color} - Default text color for UI elements */
        this.defaultTextColor = BLACK;
        /** @property {Color} - Default button color for UI elements */
        this.defaultButtonColor = hsl(0,0,.7);
        /** @property {Color} - Default hover color for UI elements */
        this.defaultHoverColor = hsl(0,0,.9);
        /** @property {Color} - Default color for disabled UI elements */
        this.defaultDisabledColor = hsl(0,0,.3);
        /** @property {Color|undefined} - Uses a gradient fill combined with color
         *  @type {Color|undefined} */
        this.defaultGradientColor = undefined;
        /** @property {number} - Default line width for UI elements */
        this.defaultLineWidth = 4;
        /** @property {number} - Default rounded rect corner radius for UI elements */
        this.defaultCornerRadius = 0;
        /** @property {number} - Default scale to use for fitting text to object */
        this.defaultTextFitScale = .8;
        /** @property {string} - Default font for UI elements */
        this.defaultFont = fontDefault;
        /** @property {Sound|undefined} - Default sound when interactive UI element is pressed
         *  @type {Sound|undefined} */
        this.defaultSoundPress = undefined;
        /** @property {Sound|undefined} - Default sound when interactive UI element is released
         *  @type {Sound|undefined} */
        this.defaultSoundRelease = undefined;
        /** @property {Sound|undefined} - Default sound when interactive UI element is clicked
         *  @type {Sound|undefined} */
        this.defaultSoundClick = undefined;
        /** @property {Color} - Color for shadow */
        this.defaultShadowColor = CLEAR_BLACK;
        /** @property {number} - Size of shadow blur */
        this.defaultShadowBlur = 5;
        /** @property {Vector2} - Offset of shadow blur */
        this.defaultShadowOffset = vec2(5);
        /** @property {TileSlice|undefined} - Style to draw UI elements with in place of their rectangle, tinted by
         *  their color, undefined for rectangles; needs the drawUtilities plugin
         *  @type {TileSlice|undefined} */
        this.defaultSlice = undefined;
        /** @property {TileSlice|undefined} - Style to draw slider handles with, undefined for the slider's own slice
         *  @type {TileSlice|undefined} */
        this.defaultHandleSlice = undefined;
        /** @property {number} - If set ui coords will be renormalized to this canvas height */
        this.nativeHeight = 0;

        // navigation properties
        /** @property {UIObject|undefined} - Object currently selected by navigation (gamepad or keyboard)
         *  @type {UIObject|undefined} */
        this.navigationObject = undefined;
        /** @property {Timer} - Cool down timer for navigation inputs */
        this.navigationTimer = new Timer(undefined, true);
        /** @property {number} - Time between navigation inputs in seconds */
        this.navigationDelay = .2;
        /** @property {number} - Which way keys and gamepads move the selection: 0 horizontal, 1 vertical, 2 both */
        this.navigationDirection = 1;
        /** @property {boolean} - True if user last used navigation instead of mouse */
        this.navigationMode = false;

        // system state
        /** @property {Array<UIObject>} - List of all UI elements
         *  @type {Array<UIObject>} */
        this.uiObjects = [];
        /** @property {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} - Context to render UI elements to */
        this.uiContext = context;
        /** @property {UIObject|undefined} - Object user is currently interacting with
         *  @type {UIObject|undefined} */
        this.activeObject = undefined;
        /** @property {UIObject|undefined} - Top most object user is over
         *  @type {UIObject|undefined} */
        this.hoverObject = undefined;
        /** @property {UIObject|undefined} - Hover object at start of update
         *  @type {UIObject|undefined} */
        this.lastHoverObject = undefined;
        /** @property {UIObject|undefined} - Current confirm menu being shown
         *  @type {UIObject|undefined} */
        this.confirmDialog = undefined;
        /** @private
         *  @type {UIObject|undefined} */
        this._keyInputObject = undefined;
        /** @private
         *  @type {Array<Array<any>>|undefined} */
        this._dragListeners = undefined;
        /** @private */
        this._onKeyDown = (e) =>
        {
            // a field that was hidden, disabled or destroyed since it took focus, or is behind a confirm dialog opened
            // since, does not take the key, the game gets it, and the next UI update ends the edit, so it ends one
            // way whichever comes first
            const o = this._keyInputObject;
            if (!o || !uiObjectIsUsable(o) || uiObjectIsBehindDialog(o)) return;

            // the field has the key, the game's input never sees it; browser shortcuts still work,
            // and only the keys a field uses lose their default, so F5, F11, F12 and the like still work
            e.stopPropagation();
            const key = e.key || '';
            if (!e.ctrlKey && !e.metaKey && !e.altKey)
            if (key.length === 1 ||
                /^(Backspace|Delete|Tab|Arrow(Up|Down|Left|Right)|Home|End|Enter|Escape)$/.test(key))
                e.preventDefault(); // no scrolling, find as you type or going back
            e.type === 'keydown' && o.onKeyDown(e);
        };

        engineAddPlugin(uiUpdate, uiRender);

        // set object position based on anchor target (parent box, or canvas for roots),
        // self-pivot, and localPos offset
        function updateTransforms(o)
        {
            let targetPos, targetSize;
            if (o.parent)
            {
                targetPos = o.parent.nativePos;
                targetSize = o.parent.size;
            }
            else
            {
                // anchor to canvas in native coords (handles nativeHeight if set)
                targetPos = uiSystem.screenToNative(mainCanvasSize.scale(.5));
                targetSize = uiSystem.nativeHeight
                    ? vec2(mainCanvasSize.x * uiSystem.nativeHeight / mainCanvasSize.y,
                           uiSystem.nativeHeight)
                    : mainCanvasSize;
            }

            const a = o.anchor;
            o.nativePos = targetPos
                .add(targetSize.multiply(a).scale(.5))   // anchor point on target
                .subtract(o.size.multiply(a).scale(.5))  // pivot shift on self
                .add(o.localPos);                        // user offset
        }

        // setup recursive update and render
        // update in reverse order to detect mouse enter/leave
        function uiUpdate()
        {
            // a held or focused object that can no longer be used, itself or through a parent, lets go,
            // and one that was hidden or disabled is still released, a destroyed one stays silent
            const activeObject = uiSystem.activeObject;
            if (activeObject && !uiObjectIsUsable(activeObject))
            {
                // a text field being edited is active without being held, it was released when the press ended
                uiSystem.activeObject = undefined;
                activeObject.destroyed || activeObject === uiSystem.keyInputObject || activeObject.onRelease();
            }
            // an edit whose field can no longer be used, or is behind a confirm dialog, ends as if it were finished,
            // so onChange keeps the text
            const keyInputObject = uiSystem.keyInputObject;
            if (keyInputObject && (!uiObjectIsUsable(keyInputObject) || uiObjectIsBehindDialog(keyInputObject)))
            {
                if (keyInputObject instanceof UITextInput && !keyInputObject.destroyed)
                    keyInputObject.stopEditing();
                else
                    uiSystem.keyInputObject = undefined;
            }

            // a click off the field being edited ends the edit before anything updates, so the click goes on to
            // what it lands on, another field or a button, as in a web form
            const editing = uiSystem.keyInputObject;
            const clickedOff = editing instanceof UITextInput && mouseWasPressed(0) && !editing.isMouseOverlapping();
            clickedOff && editing.stopEditing();

            // reset hover object at start of update
            uiSystem.lastHoverObject = uiSystem.hoverObject;
            uiSystem.hoverObject = undefined;

            // a hidden object is not updated, so the one whose hover ends by hiding it, itself or through a parent,
            // is left here; a disabled one still updates and handles its own leave
            const lastHoverObject = uiSystem.lastHoverObject;
            if (lastHoverObject && !lastHoverObject.destroyed && uiObjectIsHidden(lastHoverObject))
            {
                uiSystem.lastHoverObject = undefined;
                lastHoverObject.onLeave();
            }

            if (mouseWasPressed(0))
            {
                // exit navigation mode on mouse press
                uiSystem.navigationMode = false;
                uiSystem.navigationObject = undefined;
            }
            if (uiSystem.keyInputObject)
            {
                // handle text input, navigation keeps its place for when the edit ends, and the hover stays where it
                // was, so an edit started by navigation does not end with an onLeave that had no onEnter
                uiSystem.activeObject = uiSystem.keyInputObject;
                uiSystem.hoverObject = uiSystem.lastHoverObject;
            }

            // navigation with gamepad/keyboard
            const navigableObjects = uiSystem.getNavigableObjects();
            if (!navigableObjects.length)
                uiSystem.navigationObject = undefined;
            else if (!uiSystem.keyInputObject)
            {
                // unselect object if it is no longer navigable
                if (!navigableObjects.includes(uiSystem.navigationObject))
                    uiSystem.navigationObject = undefined;

                if (!isTouchDevice)
                if (uiSystem.navigationMode && !uiSystem.navigationObject)
                {
                    // select first auto focus object
                    uiSystem.navigationObject = navigableObjects.find(o=>o.navigationAutoSelect);
                }
                
                // navigate with dpad or left stick
                if (!uiSystem.navigationTimer.active())
                {
                    // navigate through list with gamepad or keyboard
                    const direction = sign(uiSystem.getNavigationDirection());
                    if (direction)
                    {
                        let newNavigationObject;
                        if (!uiSystem.navigationObject)
                        {
                            // use auto select object
                            newNavigationObject = navigableObjects.find(o=>o.navigationAutoSelect);

                            if (!newNavigationObject)
                            {
                                // try first or last object
                                const newIndex = direction > 0 ? 0 : navigableObjects.length-1;
                                newNavigationObject = navigableObjects[newIndex];
                            }
                        }
                        else
                        {
                            const currentIndex = navigableObjects.indexOf(uiSystem.navigationObject);
                            const newIndex = mod(currentIndex + direction, navigableObjects.length);
                            newNavigationObject = navigableObjects[newIndex];
                        }
                        
                        if (uiSystem.navigationObject !== newNavigationObject)
                        {
                            uiSystem.navigationMode = true;
                            uiSystem.hoverObject = undefined;
                            uiSystem.navigationObject = newNavigationObject;
                            uiSystem.navigationTimer.set(uiSystem.navigationDelay);
                            newNavigationObject.soundPress &&
                                newNavigationObject.soundPress.play();
                        }
                    }
                }

                // activate the navigation object when pressed, the press is used up as a mouse click is
                if (uiSystem.navigationObject)
                if (uiSystem.getNavigationWasPressed())
                {
                    uiSystem.navigationObject.navigatePressed();
                    if (isUsingGamepad)
                        inputClearKey(0, gamepadPrimary+1, false, true, false);
                    else
                    {
                        inputClearKey('Space', 0, false, true, false);
                        inputClearKey('Enter', 0, false, true, false);
                    }
                }
            }

            // update in reverse order so topmost objects get priority, from the list as it was
            // since a callback may call destroyObjects, which swaps in a shorter one
            // a confirm dialog is modal, so it goes first however late it was made, and UI made after it opened
            // can not take the mouse through it
            const uiObjects = uiSystem.uiObjects, dialog = uiSystem.confirmDialog;
            dialog && updateObject(dialog);
            for (let i = uiObjects.length; i--;)
            {
                const o = uiObjects[i];
                o.parent || o === dialog || updateObject(o);
            }

            // a click off the field that no UI object took is used up, the game does not see the click that ended it
            clickedOff && mouseWasPressed(0) && inputClearKey(0, 0);

            // remove destroyed objects
            uiSystem.uiObjects = uiSystem.uiObjects.filter(o=>!o.destroyed);

            function updateObject(o)
            {
                if (o.destroyed || !o.visible) return;

                // update in reverse order to detect mouse enter/leave, from a copy since a child may destroy
                // siblings mid-update (e.g. dialog close) and the ones after it would shift under the loop
                updateTransforms(o);
                const children = o.children.slice();
                for (let i=children.length; i--;)
                    updateObject(children[i]);
                if (!o.destroyed)
                    o.update();
            }
        }
        function uiRender()
        {
            const context = uiSystem.uiContext;
            context.save();
            if (uiSystem.nativeHeight)
            {
                // convert to native height
                const s = mainCanvasSize.y / uiSystem.nativeHeight;
                context.translate(-s*mainCanvasSize.x/2,0);
                context.scale(s,s);
                context.translate(mainCanvasSize.x/2/s,0);
            }

            function renderObject(o)
            {
                // a destroyed object stays in the list until the next update, but is gone now
                if (o.destroyed || !o.visible) return;

                // render object and children
                updateTransforms(o);
                o.render();
                for (const c of o.children)
                    renderObject(c);
            }
            // a confirm dialog is drawn over everything, UI made after it opened too
            const dialog = uiSystem.confirmDialog;
            uiSystem.uiObjects.forEach(o=> o.parent || o === dialog || renderObject(o));
            dialog && renderObject(dialog);

            if (uiDebug > 0)
            {
                // debug render all objects
                function renderDebug(o, visible=true)
                {
                    visible &&= !!o.visible;
                    if (o.destroyed || !visible && uiDebug < 2)
                        return; // only mode 2 shows the invisible ones
                    updateTransforms(o);
                    o.renderDebug(visible);
                    for (const c of o.children)
                        renderDebug(c, visible);
                }
                uiSystem.uiObjects.forEach(o=> o.parent || o === dialog || renderDebug(o));
                dialog && renderDebug(dialog);
            }
            context.restore();
        }
    }

    /** Draw a rectangle to the UI context
    *  @param {Vector2} pos
    *  @param {Vector2} size
    *  @param {Color}   [color]
    *  @param {number}  [lineWidth]
    *  @param {Color}   [lineColor]
    *  @param {number}  [cornerRadius]
    *  @param {Color}   [gradientColor]
    *  @param {Color}   [shadowColor]
    *  @param {number}  [shadowBlur]
    *  @param {Vector2} [shadowOffset] */
    drawRect(pos, size, color=WHITE, lineWidth=0, lineColor=BLACK, cornerRadius=0, gradientColor, shadowColor=BLACK, shadowBlur=0, shadowOffset=vec2())
    {
        ASSERT(isVector2(pos), 'pos must be a vec2');
        ASSERT(isVector2(size), 'size must be a vec2');
        ASSERT(isColor(color), 'color must be a color');
        ASSERT(isNumber(lineWidth), 'lineWidth must be a number');
        ASSERT(isColor(lineColor), 'lineColor must be a color');
        ASSERT(isNumber(cornerRadius), 'cornerRadius must be a number');
        
        const context = uiSystem.uiContext;
        if (gradientColor)
        {
            const g = context.createLinearGradient(
                pos.x, pos.y-size.y/2, pos.x, pos.y+size.y/2);
            const c = color.toString();
            g.addColorStop(0, c);
            g.addColorStop(.5, gradientColor.toString());
            g.addColorStop(1, c);
            context.fillStyle = g;
        }
        else
            context.fillStyle = color.toString();
        uiSetShadow(context, shadowColor, shadowBlur, shadowOffset);
        context.beginPath();
        if (cornerRadius && context['roundRect'])
            context['roundRect'](pos.x-size.x/2, pos.y-size.y/2, size.x, size.y, cornerRadius);
        else
            context.rect(pos.x-size.x/2, pos.y-size.y/2, size.x, size.y);
        context.fill();
        context.shadowColor = '#0000';
        if (lineWidth && lineColor.a > 0)
        {
            context.strokeStyle = lineColor.toString();
            context.lineWidth = lineWidth;
            context.stroke();
        }
    }

    /** Draw a TileSlice to the UI context, in place of a rectangle
    *  @param {TileSlice} slice
    *  @param {Vector2}   pos
    *  @param {Vector2}   size
    *  @param {Color}     [color] */
    drawSlice(slice, pos, size, color=WHITE)
    {
        ASSERT(typeof TileSlice === 'function' && slice instanceof TileSlice, 'slice must be a TileSlice, from the drawUtilities plugin');
        ASSERT(isVector2(pos), 'pos must be a vec2');
        ASSERT(isVector2(size), 'size must be a vec2');
        ASSERT(isColor(color), 'color must be a color');
        if (color.a > 0) // a clear one, like a UIText's, costs a tint of each piece for nothing
            slice.drawScreen(pos, size, color, undefined, 0, false, uiSystem.uiContext);
    }

    /** Draw a line to the UI context
    *  @param {Vector2} posA
    *  @param {Vector2} posB
    *  @param {number}  [lineWidth=uiSystem.defaultLineWidth]
    *  @param {Color}   [lineColor=uiSystem.defaultLineColor] */
    drawLine(posA, posB, lineWidth=uiSystem.defaultLineWidth, lineColor=uiSystem.defaultLineColor)
    {
        ASSERT(isVector2(posA), 'posA must be a vec2');
        ASSERT(isVector2(posB), 'posB must be a vec2');
        ASSERT(isNumber(lineWidth), 'lineWidth must be a number');
        ASSERT(isColor(lineColor), 'lineColor must be a color');

        const context = uiSystem.uiContext;
        context.strokeStyle = lineColor.toString();
        context.lineWidth = lineWidth;
        context.beginPath();
        context.lineTo(posA.x, posA.y);
        context.lineTo(posB.x, posB.y);
        context.stroke();
    }

    /** Draw a tile to the UI context
    *  @param {Vector2}  pos
    *  @param {Vector2}  size
    *  @param {TileInfo} tileInfo
    *  @param {Color}    [color=uiSystem.defaultColor]
    *  @param {number}   [angle]
    *  @param {boolean}  [mirror]
    *  @param {Color}    [shadowColor]
    *  @param {number}   [shadowBlur]
    *  @param {Vector2}  [shadowOffset] */
    drawTile(pos, size, tileInfo, color=uiSystem.defaultColor, angle=0, mirror=false, shadowColor=BLACK, shadowBlur=0, shadowOffset=vec2())
    {
        const context = uiSystem.uiContext;
        uiSetShadow(context, shadowColor, shadowBlur, shadowOffset);
        drawTile(pos, size, tileInfo, color, angle, mirror, CLEAR_BLACK, false, true, context);
        context.shadowColor = '#0000';
    }

    /** Draw text to the UI context
    *  @param {string}  text
    *  @param {Vector2} pos
    *  @param {Vector2} size
    *  @param {Color}   [color=uiSystem.defaultColor]
    *  @param {number}  [lineWidth=uiSystem.defaultLineWidth]
    *  @param {Color}   [lineColor=uiSystem.defaultLineColor]
    *  @param {'left'|'center'|'right'} [align]
    *  @param {string}  [font=uiSystem.defaultFont]
    *  @param {string}  [fontStyle]
    *  @param {boolean} [applyMaxWidth]
    *  @param {Vector2} [textShadow]
    *  @param {Color}   [shadowColor]
    *  @param {number}  [shadowBlur]
    *  @param {Vector2} [shadowOffset] */
    drawText(text, pos, size, color=uiSystem.defaultColor, lineWidth=uiSystem.defaultLineWidth, lineColor=uiSystem.defaultLineColor, align='center', font=uiSystem.defaultFont, fontStyle='', applyMaxWidth=true, textShadow=undefined, shadowColor=BLACK, shadowBlur=0, shadowOffset=vec2())
    {
        const context = uiSystem.uiContext;
        if (textShadow && shadowColor.a > 0)
            drawTextScreen(text, pos.add(textShadow), size.y, shadowColor, lineWidth, lineColor, align, font, fontStyle, applyMaxWidth ? size.x : undefined, 0, context);
        uiSetShadow(context, shadowColor, shadowBlur, shadowOffset);
        drawTextScreen(text, pos, size.y, color, lineWidth, lineColor, align, font, fontStyle, applyMaxWidth ? size.x : undefined, 0, context);
        context.shadowColor = '#0000';
    }

    /** Setup drag and drop event handlers
    *  Automatically prevents defaults and calls the given functions
    *  @param {DragAndDropCallback} [onDrop] - when a file is dropped
    *  @param {DragAndDropCallback} [onDragEnter] - when a file is dragged onto the window
    *  @param {DragAndDropCallback} [onDragLeave] - when a file is dragged off the window
    *  @param {DragAndDropCallback} [onDragOver] - continuously when dragging over */
    setupDragAndDrop(onDrop, onDragEnter, onDragLeave, onDragOver)
    {
        // remove any prior listeners so repeated setup calls don't stack
        if (this._dragListeners)
            for (const [type, listener] of this._dragListeners)
                document.removeEventListener(type, listener);
        this._dragListeners = [];
        const setCallback = (callback, listenerType, when=()=> true)=>
        {
            const listener = (e)=> { e.preventDefault(); when() && callback && callback(e); };
            document.addEventListener(listenerType, listener);
            this._dragListeners.push([listenerType, listener]);
        };

        // every element the drag crosses sends its own enter and leave, and a move between two ends with a leave,
        // so they are counted, and only the first enter and the last leave are the window's
        let depth = 0;
        setCallback(onDrop,      'drop',      ()=> { depth = 0; return true; });
        setCallback(onDragEnter, 'dragenter', ()=> !depth++);
        setCallback(onDragLeave, 'dragleave', ()=> !!depth && !--depth);
        setCallback(onDragOver,  'dragover');
    }

    /** Convert a screen space position to native UI position
     *  @param {Vector2} pos
     *  @return {Vector2} */
    screenToNative(pos)
    {
        if (!uiSystem.nativeHeight)
            return pos;
    
        const s = mainCanvasSize.y / uiSystem.nativeHeight;
        const sInv = 1/s;
        const p = pos.copy();
        p.x += s*mainCanvasSize.x/2;
        p.x *= sInv;
        p.y *= sInv;
        p.x -= sInv*mainCanvasSize.x/2;
        return p;
    }

    /** Object to send keyboard input to (typically a UITextInput), which keeps the keys from the game while set.
     *  The keyboard listeners are only attached while this is set,
     *  so games that never use text input pay no event-handling cost.
     *  To end typing in a field, call its stopEditing(), which also fires its onChange and release sound
     *  @type {UIObject|undefined} */
    get keyInputObject() { return this._keyInputObject; }
    set keyInputObject(obj)
    {
        const had = !!this._keyInputObject;
        this._keyInputObject = obj;
        // listen on the window as the event comes down, before the engine's input on the document can see it
        if (!had && obj)
        {
            addEventListener('keydown', this._onKeyDown, true);
            addEventListener('keyup', this._onKeyDown, true);
            inputClearKeyboard(); // keys held when editing starts let go, or they would stay down

            // a press that starts the edit, as with activateOnPress, is let go now, the updates skip its release
            // while the edit goes on; a click on release already had its release
            const held = this.activeObject;
            if (held && mouseIsDown(0))
            {
                this.activeObject = undefined;
                held.onRelease();
                held.soundRelease && held.soundRelease.play();
            }
        }
        else if (had && !obj)
        {
            removeEventListener('keydown', this._onKeyDown, true);
            removeEventListener('keyup', this._onKeyDown, true);
        }
    }

    /** Destroy and remove all objects */
    destroyObjects()
    {
        for (const o of this.uiObjects)
            o.parent || o.destroy();
        this.uiObjects = this.uiObjects.filter(o=>!o.destroyed);
        this.activeObject = undefined;
        this.hoverObject = undefined;
        this.lastHoverObject = undefined;
        this.keyInputObject = undefined;
        this.confirmDialog = undefined;
    }

    /** Get all navigable UI objects sorted by navigationIndex
     *  @return {Array<UIObject>} */
    getNavigableObjects()
    {
        function getNavigableRecursive(o)
        {
            if (o.destroyed || !o.visible || o.disabled)
                return; // skip children if parent is destroyed, invisible or disabled

            if (o.isInteractive() && o.navigationIndex !== undefined)
                objects.push(o);
            for (const child of o.children)
                getNavigableRecursive(child);
        }

        // get all the valid navigable objects recursively
        // while the confirm dialog is open only its buttons can be navigated
        const objects = [];
        if (uiSystem.confirmDialog)
            getNavigableRecursive(uiSystem.confirmDialog);
        else for (const o of uiSystem.uiObjects)
            o.parent || getNavigableRecursive(o);

        // sort by navigationIndex (lower numbers first), ties keep creation and child order
        objects.sort((a, b)=> a.navigationIndex - b.navigationIndex);
        return objects;
    }

    /** Check if the mouse is over a visible UI object that can be hovered, or anywhere while the
     *  confirm dialog is open, so a game can leave world clicks on the UI alone, on touch too.
     *  The UI uses up a click before objects update and gameUpdatePost, so read world clicks there,
     *  or check this in gameUpdate, which runs first. Positions are from the last UI update.
     *  @return {boolean} */
    isMouseOverUI()
    {
        function isOverRecursive(o)
        {
            if (o.destroyed || !o.visible)
                return false; // a hidden parent hides its children
            if (o.canBeHover && o.isMouseOverlapping())
                return true;
            return o.children.some(isOverRecursive);
        }

        // a click while a text field is being edited ends the edit, the UI takes it
        if (uiSystem.keyInputObject)
            return true;

        // while the confirm dialog is open it blocks everything else
        if (uiSystem.confirmDialog)
            return isOverRecursive(uiSystem.confirmDialog);
        return uiSystem.uiObjects.some(o=> !o.parent && isOverRecursive(o));
    }

    /** Get navigation direction from gamepad or keyboard
     *  @return {number} */
    getNavigationDirection()
    {
        const vertical = uiSystem.navigationDirection === 1;
        const both = uiSystem.navigationDirection === 2;
        if (isUsingGamepad)
        {
            const stick = gamepadStick(0, gamepadPrimary);
            const dpad = gamepadDpad(gamepadPrimary);
            if (both)
                return -(stick.y || dpad.y) || (stick.x || dpad.x);
            return vertical ? -(stick.y || dpad.y) : (stick.x || dpad.x);
        }
        const up = 'ArrowUp', down = 'ArrowDown', left = 'ArrowLeft', right = 'ArrowRight';
        if (both)
        {
            return keyIsDown(up) || keyIsDown(left) ? -1 :
                keyIsDown(down) || keyIsDown(right) ? 1 : 0;
        }
        const back = vertical ? up : left;
        const forward = vertical ? down : right;
        return keyIsDown(back) ? -1 : keyIsDown(forward) ? 1 : 0;
    }

    /** Get other axis navigation direction from gamepad or keyboard
     *  @return {number} */
    getNavigationOtherDirection()
    {
        if (uiSystem.navigationDirection === 2)
            return 0; // other direction disabled

        const vertical = uiSystem.navigationDirection === 1;
        if (isUsingGamepad)
        {
            const stick = gamepadStick(0, gamepadPrimary);
            const dpad = gamepadDpad(gamepadPrimary);
            return !vertical ? (stick.y || dpad.y) : (stick.x || dpad.x);
        }
        // up is positive, as it is on the gamepad
        if (!vertical)
            return keyIsDown('ArrowUp') ? 1 : keyIsDown('ArrowDown') ? -1 : 0;
        return keyIsDown('ArrowLeft') ? -1 : keyIsDown('ArrowRight') ? 1 : 0;
    }

    /** Get if navigation button was pressed from gamepad or keyboard
     *  @return {boolean} */
    getNavigationWasPressed()
    {
        return isUsingGamepad ? gamepadWasPressed(0, gamepadPrimary) :
            keyWasPressed('Space') || keyWasPressed('Enter');
    }
        
    /** Show a confirmation dialog with Yes/No buttons
     *  Centers the dialog on the screen with darkened background
     *  @param {string} [text] - The message to display
     *  @param {Function} [yesCallback] - Called when Yes is clicked
     *  @param {Function} [noCallback] - Called when No is clicked, or the exit key or gamepad B closes it
     *  @param {Vector2} [size] - Size of the confirmation dialog, the title and buttons are placed by it
     *  @param {string} [exitKey] - Key that closes the menu as No, gamepad B (button 1) does too
     *  @return {UIObject} The confirmation menu object
     */
    showConfirmDialog(text='Are you sure?', yesCallback, noCallback, size=vec2(500,250), exitKey='Escape')
    {
        ASSERT(!uiSystem.confirmDialog, 'a confirm dialog is already open, check uiSystem.confirmDialog');
        if (uiSystem.confirmDialog)
            return uiSystem.confirmDialog; // in a release build, the one open, as a second would break navigation

        const savedNavigationDirection = uiSystem.navigationDirection;
        const savedNavigationObject = uiSystem.navigationObject;

        // allow both axes for navigation
        uiSystem.navigationDirection = 2;

        // confirm menu
        const confirmMenu = new UIObject(vec2(), size);
        uiSystem.confirmDialog = confirmMenu;
        confirmMenu.onRender = ()=>
        {
            const backgroundColor = hsl(0,0,0,.7);
            uiSystem.drawRect(vec2(), vec2(1e9), backgroundColor);
        }
        let opened = false;
        confirmMenu.onUpdate = ()=>
        {
            // not the press that opened it, a game may open it on the same back button, so its first update is skipped
            // (not by frame number, which does not advance while paused, where a confirm is usually shown)
            if (opened && (keyWasPressed(exitKey) || gamepadWasPressed(1)))
            {
                closeMenu(); // the exit key or gamepad B answers no
                noCallback && noCallback();
            }
            opened = true;
        }
        confirmMenu.isMouseOverlapping = ()=> true; // always hover
        
        // the title and buttons are laid out for the default 500 by 250 and scaled to the dialog's size, so a
        // small or narrow one still fits them
        const scaleX = size.x/500, scaleY = size.y/250;
        const gap = 50, y = size.y/5;
        const textTitle = new UIText(vec2(0,-y), vec2(size.x-gap, 70*scaleY), text);
        confirmMenu.addChild(textTitle);

        // yes button
        const buttonSize = vec2(120*scaleX, 70*scaleY);
        const buttonYes = new UIButton(vec2(-80*scaleX,y), buttonSize, 'Yes');
        buttonYes.textHeight = 40*scaleY;
        buttonYes.navigationIndex = 1;
        buttonYes.hoverColor = hsl(0,1,.5);
        buttonYes.onClick = ()=> { closeMenu(); yesCallback && yesCallback(); };
        confirmMenu.addChild(buttonYes);
        
        // no button
        const buttonNo = new UIButton(vec2(80*scaleX,y), buttonSize, 'No');
        buttonNo.textHeight = 40*scaleY;
        buttonNo.navigationIndex = 2;
        buttonNo.navigationAutoSelect = true;
        buttonNo.onClick = ()=> { closeMenu(); noCallback && noCallback(); };
        confirmMenu.addChild(buttonNo);

        // return to normal navigation however the menu goes, by its buttons,
        // destroyObjects or a call to its destroy, with the item that opened it selected again
        const destroy = confirmMenu.destroy.bind(confirmMenu);
        confirmMenu.destroy = ()=>
        {
            const closing = uiSystem.confirmDialog === confirmMenu;
            if (closing)
            {
                uiSystem.confirmDialog = undefined;
                uiSystem.navigationDirection = savedNavigationDirection;
            }
            destroy(); // its buttons go, and the one selected clears the selection
            if (closing && savedNavigationObject && !savedNavigationObject.destroyed)
                uiSystem.navigationObject = savedNavigationObject;
        };

        // close menu and clear the input that closed it
        function closeMenu()
        {
            ASSERT(uiSystem.confirmDialog === confirmMenu);
            confirmMenu.destroy();
            inputClear();
        }
        return confirmMenu;
    }
}

// whether a UI object can still be used: it and every parent visible, enabled and not destroyed
function uiObjectIsUsable(o)
{
    for (; o; o = o.parent)
        if (o.destroyed || !o.visible || o.disabled)
            return false;
    return true;
}

// set the canvas shadow for the next draw, when it has a color and a blur or an offset; the caller clears it
function uiSetShadow(context, shadowColor, shadowBlur, shadowOffset)
{
    if (shadowColor.a > 0 && (shadowBlur || shadowOffset.x || shadowOffset.y))
    {
        context.shadowColor = shadowColor.toString();
        context.shadowBlur = shadowBlur;
        context.shadowOffsetX = shadowOffset.x;
        context.shadowOffsetY = shadowOffset.y;
    }
}

// whether an open confirm dialog shuts a UI object out, it is modal: all but the dialog and what is in it
function uiObjectIsBehindDialog(o)
{
    const dialog = uiSystem.confirmDialog;
    if (!dialog)
        return false;
    for (; o; o = o.parent)
        if (o === dialog)
            return false;
    return true;
}

// whether a UI object is disabled, itself or through a parent
function uiObjectIsDisabled(o)
{
    for (; o; o = o.parent)
        if (o.disabled)
            return true;
    return false;
}

// whether a UI object is hidden, itself or through a parent
function uiObjectIsHidden(o)
{
    for (; o; o = o.parent)
        if (!o.visible)
            return true;
    return false;
}

///////////////////////////////////////////////////////////////////////////////
/**
 * UI Object - Base level object for all UI elements
 * @memberof UISystem */
class UIObject
{
    /** Create a UIObject
     *  @param {Vector2}  [pos=vec2()]
     *  @param {Vector2}  [size=vec2()]
     */
    constructor(pos=vec2(), size=vec2())
    {
        ASSERT(uiSystem, 'create the UISystemPlugin before UI objects');
        ASSERT(isVector2(pos), 'ui object pos must be a vec2');
        ASSERT(isVector2(size), 'ui object size must be a vec2');

        /** @property {Vector2} - Position you set: an offset from this object's
         *  anchor point (the parent box, or the canvas for roots). This is the
         *  input that controls placement — set this, not nativePos. */
        this.localPos = pos.copy();
        /** @property {Vector2} - Resolved position in native UI space, recomputed
         *  every frame from localPos + anchor (and nativeHeight, if set). This is a
         *  derived output used for drawing and hit-testing; assigning to it has no
         *  effect since it is overwritten each frame. Set localPos instead. */
        this.nativePos = pos.copy();
        /** @property {Vector2} - Screen space size of the object */
        this.size = size.copy();
        /** @property {Color} - Color of the object */
        this.color = uiSystem.defaultColor.copy();
        /** @property {Color|undefined} - Color of the object when active, uses hoverColor if undefined
         *  @type {Color|undefined} */
        this.activeColor = undefined;
        /** @property {string|undefined} - Text for this ui object
         *  @type {string|undefined} */
        this.text = undefined;
        /** @property {Color} - Color when disabled */
        this.disabledColor = uiSystem.defaultDisabledColor.copy();
        /** @property {boolean} - Is this object disabled? */
        this.disabled = false;
        /** @property {Color} - Color for text */
        this.textColor = uiSystem.defaultTextColor.copy();
        /** @property {Color} - Color used when hovering over the object */
        this.hoverColor = uiSystem.defaultHoverColor.copy();
        /** @property {Color} - Color for line drawing */
        this.lineColor = uiSystem.defaultLineColor.copy();
        /** @property {Color|undefined} - Uses a gradient fill combined with color
         *  @type {Color|undefined} */
        this.gradientColor = uiSystem.defaultGradientColor ? uiSystem.defaultGradientColor.copy() : undefined;
        /** @property {number} - Width for line drawing */
        this.lineWidth = uiSystem.defaultLineWidth;
        /** @property {number} - Corner radius for rounded rects */
        this.cornerRadius = uiSystem.defaultCornerRadius;
        /** @property {TileSlice|undefined} - Style to draw with in place of the rectangle, tinted by the color for its
         *  state; its art has the frame, so the outline, corner radius and shadow are not drawn
         *  @type {TileSlice|undefined} */
        this.slice = uiSystem.defaultSlice;
        /** @property {string} - Font for this object */
        this.font = uiSystem.defaultFont;
        /** @property {string|undefined} - Font style for this object or undefined
         *  @type {string|undefined} */
        this.fontStyle = undefined;
        /** @property {number|undefined} - Override for text width
         *  @type {number|undefined} */
        this.textWidth = undefined;
        /** @property {number|undefined} - Override for text height
         *  @type {number|undefined} */
        this.textHeight = undefined;
        /** @property {number} - Scale text to fit in the object */
        this.textFitScale = uiSystem.defaultTextFitScale;
        /** @property {Vector2|undefined} - How much to offset the text shadow or undefined.
         *  UIText draws it in its shadowColor, which is clear by default, so set that too;
         *  the blurred shadow then shows as well unless shadowBlur and shadowOffset are zero.
         *  The other widgets draw it in black
         *  @type {Vector2|undefined} */
        this.textShadow = undefined;
        /** @property {Color} - Color for text line drawing  */
        this.textLineColor = uiSystem.defaultLineColor.copy();
        /** @property {number} - Width for text line drawing */
        this.textLineWidth = 0;
        /** @property {boolean} - Should this object be drawn */
        this.visible  = true;
        /** @property {Array<UIObject>} - A list of this object's children
         *  @type {Array<UIObject>} */
        this.children = [];
        /** @property {UIObject|undefined} - This object's parent, position is in parent space
         *  @type {UIObject|undefined} */
        this.parent = undefined;
        /** @property {number} - Added size to make small buttons easier to touch on mobile devices */
        this.extraTouchSize = 0;
        /** @property {Sound|undefined} - Sound when interactive element is pressed
         *  @type {Sound|undefined} */
        this.soundPress = uiSystem.defaultSoundPress;
        /** @property {Sound|undefined} - Sound when interactive element is released
         *  @type {Sound|undefined} */
        this.soundRelease = uiSystem.defaultSoundRelease;
        /** @property {Sound|undefined} - Sound when interactive element is clicked
         *  @type {Sound|undefined} */
        this.soundClick = uiSystem.defaultSoundClick;
        /** @property {boolean} - Is this element interactive */
        this.interactive = false;
        /** @property {boolean} - Activate when dragged over with mouse held down */
        this.dragActivate = false;
        /** @property {boolean} - True if this can be a hover object */
        this.canBeHover = true;
        /** @property {Color} - Color for shadow */
        this.shadowColor = uiSystem.defaultShadowColor?.copy();
        /** @property {number} - Size of shadow blur */
        this.shadowBlur = uiSystem.defaultShadowBlur;
        /** @property {Vector2} - Offset of shadow blur */
        this.shadowOffset = uiSystem.defaultShadowOffset?.copy();
        /** @property {number|undefined} - Optional navigation order index, lower values are selected first
         *  @type {number|undefined} */
        this.navigationIndex = undefined;
        /** @property {boolean} - Should this be auto selected by navigation? Must also have valid navigation index. */
        this.navigationAutoSelect = false;
        /** @property {Vector2} - Where on parent (or canvas if no parent) this object is anchored.
         *  Components in [-1, 1]: (0,0)=center, (-1,-1)=top-left, (1,1)=bottom-right.
         *  Also acts as self-pivot — e.g. (1,-1) puts your top-right corner at the anchor point. */
        this.anchor = vec2();
        /** @property {'left'|'center'|'right'} - Horizontal text alignment: left, center, or right
         *  @type {'left'|'center'|'right'} */
        this.align = 'center';
        /** @property {boolean} - Has this object been destroyed? */
        this.destroyed = false;

        uiSystem.uiObjects.push(this);
    }

    /** Add a child UIObject to this object, returns child for chaining
     *  @param {UIObject} child
     *  @return {UIObject} The child object added */
    addChild(child)
    {
        ASSERT(!child.parent && !this.children.includes(child), 'child already has a parent, removeChild it first');
        this.children.push(child);
        child.parent = this;
        return child;
    }

    /** Remove a child UIObject from this object
     *  @param {UIObject} child */
    removeChild(child)
    {
        ASSERT(child.parent === this && this.children.includes(child));
        this.children.splice(this.children.indexOf(child), 1);
        child.parent = undefined;
    }

    /** Destroy this object, destroy its children, detach its parent, and mark it for removal */
    destroy()
    {
        if (this.destroyed)
            return;

        // clear ui-system references that point at this object so events
        // don't keep firing against a destroyed target (especially the
        // keydown listener attached for keyInputObject)
        if (uiSystem.activeObject     === this) uiSystem.activeObject     = undefined;
        if (uiSystem.hoverObject      === this) uiSystem.hoverObject      = undefined;
        if (uiSystem.lastHoverObject  === this) uiSystem.lastHoverObject  = undefined;
        if (uiSystem.navigationObject === this) uiSystem.navigationObject = undefined;
        if (uiSystem.keyInputObject   === this) uiSystem.keyInputObject   = undefined;

        // disconnect from parent and destroy children
        this.destroyed = true;
        this.parent?.removeChild(this);
        for (const child of this.children)
        {
            child.parent = undefined;
            child.destroy();
        }
        // clear references so destroyed children can be GC'd
        this.children.length = 0;
    }

    /** Check if the mouse is overlapping this ui object
     *  @return {boolean} - True if overlapping */
    isMouseOverlapping()
    {
        if (!mouseInWindow) return false;

        const size = !isTouchDevice ? this.size :
                this.size.add(vec2(this.extraTouchSize || 0));
        const pos = uiSystem.screenToNative(mousePosScreen);
        return isOverlapping(this.nativePos, size, pos);
    }

    /** Update the object, called automatically by plugin once each frame
     *  @return {void} */
    update()
    {
        // call the custom update callback, which may destroy this object
        this.onUpdate();
        if (this.destroyed) return;

        // unset active if disabled, itself or through a parent, and let go of it
        const disabled = uiObjectIsDisabled(this);
        if (disabled)
        {
            if (this === uiSystem.activeObject)
            {
                uiSystem.activeObject = undefined;
                if (this !== uiSystem.keyInputObject) // a field being edited was released when its press ended
                {
                    this.onRelease();
                    if (this.destroyed) return;
                }
            }
            // a field being edited is ended by the next UI update, through stopEditing, so onChange keeps its text
        }

        if (uiSystem.keyInputObject)
            return;

        const wasHover = uiSystem.lastHoverObject === this;
        const isActive = this.isActiveObject();
        const mouseDown = mouseIsDown(0);
        // a press and release in one frame is a press too, as it is for a button that is not drag activated
        const mousePress = mouseWasPressed(0) || this.dragActivate && mouseDown;
        if (this.canBeHover)
        if (!uiSystem.navigationMode) // no mouse hover in navigation mode
        if (mousePress || isActive || (!mouseDown && !isTouchDevice))
        if (!uiSystem.hoverObject && this.isMouseOverlapping())
            uiSystem.hoverObject = this;
        if (this.isHoverObject())
        {
            if (!disabled)
            {
                if (mousePress)
                {
                    if (this.interactive)
                    {
                        // drag activate sees the held mouse as a press every frame, only a new one counts
                        const newPress = !this.dragActivate || !wasHover || mouseWasPressed(0);
                        if (newPress)
                        {
                            this.onPress();
                            if (this.destroyed) // the press took it away, and the press is used up
                                return void inputClearKey(0, 0, false, true, false);
                            this.soundPress && this.soundPress.play();
                            if (uiSystem.activeObject && !isActive)
                                uiSystem.activeObject.onRelease();
                        }
                        if (uiSystem.keyInputObject && uiSystem.keyInputObject !== this)
                        {
                            // its onPress started an edit elsewhere, the updates skip its release while it goes on
                            this.onRelease();
                            this.soundRelease && this.soundRelease.play();
                        }
                        else
                            uiSystem.activeObject = this;

                        if (newPress && uiSystem.activateOnPress)
                            this.click(!this.soundPress);
                        if (this.destroyed)
                            return void inputClearKey(0, 0, false, true, false);
                    }
                }
                // the object that was the active one going into this update: one pressed and let go inside a
                // frame is clicked on the next, with its release, not on both
                if (!uiSystem.activateOnPress)
                if (!mouseDown && isActive && this.isActiveObject() && this.interactive)
                    this.click();
                if (this.destroyed) return;
            }

            // clear mouse was pressed state even when disabled
            mousePress && inputClearKey(0, 0, false, true, false);
        }
        if (isActive)
        if (!mouseDown || (this.dragActivate && !this.isHoverObject()))
        {
            this.onRelease();
            this.soundRelease && this.soundRelease.play();
            uiSystem.activeObject = undefined;
        }

        // call enter/leave events
        if (this.isHoverObject() !== wasHover)
            this.isHoverObject() ? this.onEnter() : this.onLeave();
    }

    /** Render the object, called automatically by plugin once each frame */
    render()
    {
        // call the custom render callback
        this.onRender();

        if (!this.size.x || !this.size.y) return;

        const isNavigationObject = this.isNavigationObject();
        const disabled = this.interactive ? uiObjectIsDisabled(this) : this.disabled;
        const lineColor = isNavigationObject ? this.color :
            this.interactive && this.isActiveObject() && !disabled ?
            this.color : this.lineColor;
        const color = isNavigationObject ? this.hoverColor :
            disabled ? this.disabledColor :
            this.interactive ?
                this.isActiveObject() ? this.activeColor || this.hoverColor :
                this.isHoverObject() ? this.hoverColor :
                this.color : this.color;
        const lineWidth = this.lineWidth * (isNavigationObject ? 1.5 : 1);
        
        if (this.slice)
            uiSystem.drawSlice(this.slice, this.nativePos, this.size, color);
        else
            uiSystem.drawRect(this.nativePos, this.size, color, lineWidth, lineColor, this.cornerRadius, this.gradientColor, this.shadowColor || CLEAR_BLACK, this.shadowBlur, this.shadowOffset);
    }

    /** Get the size for text with overrides and scale
     *  @return {Vector2} */
    getTextSize()
    {
        // text fitted to the size shares its height between its lines, a set textHeight is the height of each line
        const lines = this.textHeight ? 1 : (this.text + '').split('\n').length;
        return vec2(
            this.textWidth  || this.textFitScale * this.size.x,
            this.textHeight || this.textFitScale * this.size.y / lines);
    }

    /** Get where the text is drawn, the center, or the edge of the text area its align puts it against
     *  @param {Vector2} textSize - From getTextSize
     *  @return {Vector2} */
    getTextPos(textSize)
    {
        const side = this.align === 'left' ? -1 : this.align === 'right' ? 1 : 0;
        return this.nativePos.add(vec2(side * textSize.x / 2, 0));
    }

    /** Called when the navigation button is pressed on this object */
    navigatePressed() { this.click(); }

    /** Is the mouse hovering over this element
     *  @return {boolean} */
    isHoverObject() { return uiSystem.hoverObject === this; }

    /** Is the mouse held onto this element
     *  @return {boolean} */
    isActiveObject() { return uiSystem.activeObject === this; }

    /** Is the gamepad or keyboard navigation object
     *  @return {boolean} */
    isNavigationObject() { return uiSystem.navigationObject === this; }

    /** Is this object in keyboard input mode
     *  @return {boolean} */
    isKeyInputObject() { return uiSystem.keyInputObject === this; }

    /** Can it be interacted with, it and every parent visible and enabled
     *  @return {boolean} */
    isInteractive() { return this.interactive && uiObjectIsUsable(this); }

    /** Returns string containing info about this object for debugging
     *  @return {string} */
    toString()
    {
        let text = 'type = ' + this.constructor.name;
        if (this.text)
            text += '\ntext = ' + this.text;
        if (this.nativePos.x || this.nativePos.y)
            text += '\nnativePos = ' + this.nativePos;
        if (this.localPos.x || this.localPos.y)
            text += '\nlocalPos = ' + this.localPos;
        if (this.size.x || this.size.y)
            text += '\nsize = ' + this.size;
        if (this.color)
            text += '\ncolor = ' + this.color;
        return text;
    }

    /** Called if uiDebug is enabled
     *  @param {boolean} [visible] */
    renderDebug(visible=true)
    {
        // apply color based on state
        const color =
            !visible ? GREEN :
            this.isHoverObject() ? YELLOW :
            uiObjectIsDisabled(this) ? PURPLE :
            this.interactive ? RED : BLUE;
        uiSystem.drawRect(this.nativePos, this.size, CLEAR_BLACK, 4, color);
    }

    /** Internal function called when object is clicked
     *  @param {boolean} [playSound] */
    click(playSound=true)
    {
        this.onClick(); 
        if (playSound && this.soundClick)
            this.soundClick.play();
    }

    /** Called each frame before object updates */
    onUpdate() {}

    /** Called each frame before object renders */
    onRender() {}

    /** Called when the mouse enters the object */
    onEnter() {}

    /** Called when the mouse leaves the object */
    onLeave() {}

    /** Called when the mouse is pressed while over the object */
    onPress() {}

    /** Called when a press on it ends, wherever the mouse is let go, or when it is disabled or hidden while held, or
     *  an edit takes the press; onClick is the one for a press let go over it */
    onRelease() {}

    /** Called when user clicks on this object */
    onClick() {}

    /** Called when the state of this object changes */
    onChange() {}

    /** Called with each key while this is the keyInputObject
     *  @param {KeyboardEvent} e */
    onKeyDown(e) {}
};

///////////////////////////////////////////////////////////////////////////////
/** 
 * UIText - A UI object that displays text
 * @extends UIObject
 * @memberof UISystem
 */
class UIText extends UIObject
{
    /** Create a UIText object
     *  @param {Vector2} [pos]
     *  @param {Vector2} [size]
     *  @param {string}  [text]
     *  @param {'left'|'center'|'right'} [align]
     *  @param {string}  [font=uiSystem.defaultFont]
     */
    constructor(pos, size, text='', align='center', font=uiSystem.defaultFont)
    {
        super(pos, size);

        ASSERT(isStringLike(text), 'ui text must be a string');
        ASSERT(['left','center','right'].includes(align), 'ui text align must be left, center, or right');
        ASSERT(isStringLike(font), 'ui text font must be a string');

        // set properties
        this.text = text;
        this.align = align;
        this.font = font;

        // text can not be a hover object by default
        this.canBeHover = false;
        
        // no background by default
        this.color = CLEAR_BLACK.copy();
        this.shadowColor = CLEAR_BLACK.copy();
        /** @type {Color|undefined} */
        this.gradientColor = undefined;
        this.lineWidth = 0;

        // use max fit scale by default
        this.textFitScale = 1;
    }
    render()
    {
        super.render();

        // render the text
        const textSize = this.getTextSize();
        uiSystem.drawText(this.text, this.getTextPos(textSize), textSize, this.textColor, this.textLineWidth, this.textLineColor, this.align, this.font, this.fontStyle, true, this.textShadow, this.shadowColor || CLEAR_BLACK, this.shadowBlur, this.shadowOffset);
    }
}

///////////////////////////////////////////////////////////////////////////////
/** 
 * UITextInput - An editable text input field
 * - A simple text entry field that supports basic editing
 * - Suitable for short text input like names or numbers
 * - Reads a physical keyboard: no on-screen keyboard opens on touch devices, and IME composition and paste do not type,
 *   use an HTML input element for those
 * @extends UIObject
 * @memberof UISystem
 */
class UITextInput extends UIObject
{
    /** Create a UITextInput object
     *  @param {Vector2} [pos]
     *  @param {Vector2} [size]
     *  @param {string}  [text]
     */
    constructor(pos, size, text='')
    {
        super(pos, size);

        ASSERT(isStringLike(text), 'ui text must be a string');

        /** @property {number} - Max length of input (0 = no limit) */
        this.maxLength = 0;

        // set properties, as a string, which typing adds to
        this.text = text + '';
        this.interactive = true;
        this.canBeHover = true;
    }

    /** Start editing the text, called when it is clicked
     *  @param {boolean} [playSound] */
    click(playSound=true)
    {
        // an edit in another field ends first, with its onChange, like a Tab to the next field
        const editing = uiSystem.keyInputObject;
        if (editing !== this && editing instanceof UITextInput)
            editing.stopEditing();

        // start editing the text, the gamepad press that started it is used up so it does not stop it too
        uiSystem.keyInputObject = this;
        inputClearKey(0, gamepadPrimary+1, false, true, false);
        this.onClick();
        playSound && this.soundClick && this.soundClick.play();
    }

    /** Stop editing the text */
    stopEditing()
    {
        if (!this.isKeyInputObject())
            return;

        if (this.soundRelease)
            this.soundRelease.play();
        uiSystem.activeObject = undefined;
        uiSystem.keyInputObject = undefined;
        this.onChange();
    }

    /** Key down event handler if this object is being edited
     *  @param {KeyboardEvent} e */
    onKeyDown(e)
    {
        // named keys by key, so numpad Enter works as Enter
        const code = e.code, key = e.key || ''; // autofill sends a keydown with no key
        if (e.repeat && (key === 'Enter' || code === 'Space'))
            return; // a key held when editing began repeats, it should not type or stop editing
        this.text += ''; // a game may have set a number
        if (key === 'Backspace')
            this.text = [...this.text].slice(0, -1).join(''); // a whole character, an emoji is two code units
        else if (key === 'Enter' || key === 'Escape')
            this.stopEditing();
        else if (key.length === 1) // printable characters
        {
            // ctrl and cmd shortcuts do not type, but AltGr reports ctrl and alt and types characters like @
            if ((e.ctrlKey || e.metaKey) && !e.getModifierState?.('AltGraph'))
                return;
            if (!this.maxLength || this.text.length < this.maxLength)
                this.text += key;
        }
    }

    update()
    {
        super.update();

        if (!this.isKeyInputObject())
            return;

        // the gamepad's press stops editing and is used up, a click off the field is handled by the UI update
        if (gamepadWasPressed(0, gamepadPrimary))
        {
            this.stopEditing();
            inputClearKey(0, gamepadPrimary+1, false, true, false);
        }
        else if (mouseWasPressed(0))
            inputClearKey(0, 0, false, true, false); // a click inside is used up like any click on the UI
    }

    render()
    {
        super.render();

        // draw the text scaled to fit
        const textSize = this.getTextSize();
        let text = this.text;
        if (this.isKeyInputObject()) // add a cursor to end of text
            text += timeReal%1 < .5 ?  '█' : '░';
        uiSystem.drawText(text, this.getTextPos(textSize), textSize, 
            this.textColor, this.textLineWidth, this.textLineColor, this.align, this.font, this.fontStyle, true, this.textShadow);
    }
}

