/** 
 * Box2D Global Object
 * - Wraps Box2d world and provides global functions
 * @memberof Box2D
 */
class Box2dPlugin
{
    /** Create the global Box2D plugin object, box2dInit does this
     *  @param {Object} instance */
    constructor(instance)
    {
        ASSERT(!box2d, 'Box2D already initialized');
        box2d = this;

        /** @property {Object} - The Box2d instance */
        this.instance = instance;
        /** @property {Object} - The Box2d world */
        this.world = new box2d.instance.b2World();
        /** @property {Array<Box2dObject>} - List of all Box2d objects, a destroyed one stays until the next step
         *  with its body undefined
         *  @type {Array<Box2dObject>} */
        this.objects = [];
        /** @property {number} - Velocity iterations per update*/
        this.velocityIterations = 8;
        /** @property {number} - Position iterations per update*/
        this.positionIterations = 3;
        /** @property {number} - Static, zero mass, zero velocity, may be manually moved
         *  @type {number} */
        this.bodyTypeStatic = instance.b2_staticBody;
        /** @property {number} - Kinematic, zero mass, non-zero velocity set by user, moved by solver
         *  @type {number} */
        this.bodyTypeKinematic = instance.b2_kinematicBody;
        /** @property {number} - Dynamic, positive mass, non-zero velocity determined by forces, moved by solver
         *  @type {number} */
        this.bodyTypeDynamic = instance.b2_dynamicBody;

        // a body that goes takes its joints with it, their wrappers let go of them, and a gear joint on one of them
        // goes too, since it would keep pointers to what was freed; that destroy waits in the queue, which DestroyBody
        // runs from, and is skipped if the gear hung off this same body and went with it
        const destructionListener = new box2d.instance.JSDestructionListener();
        destructionListener.SayGoodbyeJoint = function(jointPointer)
        {
            const joint = box2dJoints.get(jointPointer);
            if (joint)
            {
                box2dDestroyGears(joint);
                joint.box2dJoint = 0;
            }
            box2dJoints.delete(jointPointer);
        };
        destructionListener.SayGoodbyeFixture = function() {};
        box2d.world.SetDestructionListener(destructionListener);

        // setup contact listener
        const listener = new box2d.instance.JSContactListener();
        listener.BeginContact = function(contactPtr)
        {
            const contact  = box2d.instance.wrapPointer(contactPtr, box2d.instance.b2Contact);
            const fixtureA = contact.GetFixtureA();
            const fixtureB = contact.GetFixtureB();
            const objectA  = fixtureA.GetBody().object;
            const objectB  = fixtureB.GetBody().object;
            // raw user-created b2Bodies may have no .object — skip those
            if (!objectA || !objectB) return;
            objectA.beginContact(objectB, fixtureA, fixtureB);
            objectB.beginContact(objectA, fixtureB, fixtureA);
        }
        listener.EndContact = function(contactPtr)
        {
            const contact  = box2d.instance.wrapPointer(contactPtr, box2d.instance.b2Contact);
            const fixtureA = contact.GetFixtureA();
            const fixtureB = contact.GetFixtureB();
            const objectA  = fixtureA.GetBody().object;
            const objectB  = fixtureB.GetBody().object;
            if (!objectA || !objectB) return;
            objectA.endContact(objectB, fixtureA, fixtureB);
            objectB.endContact(objectA, fixtureB, fixtureA);
        };
        listener.PreSolve  = function() {};
        listener.PostSolve = function() {};
        box2d.world.SetContactListener(listener);
    }

    /** Step the physics world simulation
     *  @param {number} [frames] */
    step(frames=1)
    {
        // the engine's gravity, Box2D does not wake a sleeping body for a new one, so a change wakes them all
        if (gravity.x !== box2dGravity.x || gravity.y !== box2dGravity.y)
        {
            box2dGravity.x = gravity.x, box2dGravity.y = gravity.y;
            box2d.world.SetGravity(box2dTemp(gravity));
            for (let b = box2d.world.GetBodyList(); !box2d.isNull(b); b = b.GetNext())
                b.SetAwake(true);
        }
        for (let i=frames; i--;)
        {
            box2d.world.Step(timeDelta, this.velocityIterations, this.positionIterations);

            // what a contact callback destroyed or changed, now the world can take it
            box2dRunPending();
        }

        // remove destroyed objects, once for all of them
        this.objects = this.objects.filter(o=>!o.destroyed);
    }

    ///////////////////////////////////////////////////////////////////////////////
    // raycasting and querying

    /** raycast and return a list of all the results, nearest first
     *  @param {Vector2} start
     *  @param {Vector2} end
     *  @param {boolean} [includeSensors] - Also hit sensors, trigger zones are passed through by default
     *  @return {Array<Box2dRaycastResult>} */
    raycastAll(start, end, includeSensors=false)
    {
        // a ray with no length fails an assert that stops Box2D for good, measured as Box2D does in 32 bit floats,
        // where two ends a float apart are one point; one that is not a number has no length either
        const f = Math.fround, dx = f(f(end.x) - f(start.x)), dy = f(f(end.y) - f(start.y));
        const lengthSquared = f(f(dx*dx) + f(dy*dy));
        if (!(lengthSquared > 0 && lengthSquared < Infinity))
            return [];

        const raycastCallback = box2dQueryObject('rayCast', 'JSRayCastCallback');
        raycastCallback.ReportFixture = function(fixturePointer, point, normal, fraction)
        {
            const fixture = box2d.instance.wrapPointer(fixturePointer, box2d.instance.b2Fixture);
            const o = fixture.GetBody().object;
            if (!o || o.destroyed)
                return 1; // a raw body with no Box2dObject or one destroyed this step, continue getting results
            if (!includeSensors && fixture.IsSensor())
                return -1; // skip it, Box2D goes on as if it were not there
            point  = box2d.vec2FromPointer(point);
            normal = box2d.vec2FromPointer(normal);
            raycastResults.push(new Box2dRaycastResult(fixture, point, normal, fraction));
            return 1; // continue getting results
        };

        const raycastResults = [];
        box2d.world.RayCast(raycastCallback, box2dTemp(start), box2dTemp(end, 1));
        raycastResults.sort((a,b)=> a.fraction - b.fraction); // Box2D reports them in its tree's order
        debugRaycast && debugLine(start, end, raycastResults.length ? '#f00' : '#00f', .02, 0, false);
        return raycastResults;
    }

    /** raycast and return the first result
     *  @param {Vector2} start
     *  @param {Vector2} end
     *  @param {boolean} [includeSensors] - Also hit sensors, trigger zones are passed through by default
     *  @return {Box2dRaycastResult|undefined} */
    raycast(start, end, includeSensors=false)
    {
        return box2d.raycastAll(start, end, includeSensors)[0];
    }

    /** Every object whose shapes' bounding boxes overlap a box, not the shapes themselves, so near the corner of a
     *  turned box or a circle it finds one the box does not touch; use pointCast or a raycast for exact
     *  @param {Vector2} pos
     *  @param {Vector2} size
     *  @param {boolean} [includeSensors] - Also find sensors, trigger zones are passed through by default
     *  @return {Array<Box2dObject>} */
    boxCastAll(pos, size, includeSensors=false)
    {
        const queryCallback = box2dQueryObject('query', 'JSQueryCallback');
        queryCallback.ReportFixture = function(fixturePointer)
        {
            const fixture = box2d.instance.wrapPointer(fixturePointer, box2d.instance.b2Fixture);
            if (!includeSensors && fixture.IsSensor())
                return true; // a trigger zone, continue getting results
            const o = fixture.GetBody().object;
            if (o && !o.destroyed && !queryObjects.includes(o) // skip raw bodies and ones destroyed this step
                && box2dFixtureOverlaps(fixture, aabb))
                queryObjects.push(o); // add if not already in list
            return true; // continue getting results
        };

        const aabb = box2dQueryObject('aabb', 'b2AABB');
        aabb.set_lowerBound(box2dTemp(pos.subtract(size.scale(.5))));
        aabb.set_upperBound(box2dTemp(pos.add(size.scale(.5))));

        let queryObjects = [];
        box2d.world.QueryAABB(queryCallback, aabb);
        debugRaycast && debugRect(pos, size, queryObjects.length ? '#f00' : '#00f', 0, 0, false, false);
        return queryObjects;
    }

    /** The first object whose shapes' bounding boxes overlap a box, not the shapes themselves, so near the corner of
     *  a turned box or a circle it finds one the box does not touch; use pointCast or a raycast for exact
     *  @param {Vector2} pos
     *  @param {Vector2} size
     *  @param {boolean} [includeSensors] - Also find sensors, trigger zones are passed through by default
     *  @return {Box2dObject|undefined} */
    boxCast(pos, size, includeSensors=false)
    {
        const queryCallback = box2dQueryObject('query', 'JSQueryCallback');
        queryCallback.ReportFixture = function(fixturePointer)
        {
            const fixture = box2d.instance.wrapPointer(fixturePointer, box2d.instance.b2Fixture);
            if (!includeSensors && fixture.IsSensor())
                return true; // a trigger zone, continue getting results
            const o = fixture.GetBody().object;
            if (!o || o.destroyed)
                return true; // a raw body with no Box2dObject or one destroyed this step, continue getting results
            if (!box2dFixtureOverlaps(fixture, aabb))
                return true; // only near the box, continue getting results
            queryObject = o;
            return false; // stop getting results
        };

        const aabb = box2dQueryObject('aabb', 'b2AABB');
        aabb.set_lowerBound(box2dTemp(pos.subtract(size.scale(.5))));
        aabb.set_upperBound(box2dTemp(pos.add(size.scale(.5))));

        let queryObject;
        box2d.world.QueryAABB(queryCallback, aabb);
        debugRaycast && debugRect(pos, size, queryObject ? '#f00' : '#00f', 0, 0, false, false);
        return queryObject;
    }

    /** circle cast and return all the objects whose position is within the circle, wherever their shapes are
     *  @param {Vector2} pos
     *  @param {number} diameter
     *  @param {boolean} [includeSensors] - Also find objects whose shapes are all sensors, like trigger zones
     *  @return {Array<Box2dObject>} */
    circleCastAll(pos, diameter, includeSensors=false)
    {
        // by each object's position, so an object whose shapes are offset from it is still found
        const radius2 = (diameter/2)**2;
        const results = box2d.objects.filter(o=> !o.destroyed && o.body && o.pos.distanceSquared(pos) < radius2 &&
            (includeSensors || o.getFixtureList().some(fixture=> !fixture.IsSensor())));
        debugRaycast && debugCircle(pos, diameter, results.length ? '#f00' : '#00f', 0, false, false);
        return results;
    }

    /** circle cast and return the object whose position is nearest, of those within the circle
     *  @param {Vector2} pos
     *  @param {number} diameter
     *  @param {boolean} [includeSensors] - Also find objects whose shapes are all sensors, like trigger zones
     *  @return {Box2dObject|undefined} */
    circleCast(pos, diameter, includeSensors=false)
    {
        let bestResult, bestDistance2;
        for (const result of box2d.circleCastAll(pos, diameter, includeSensors))
        {
            const distance2 = result.pos.distanceSquared(pos);
            if (!bestResult || distance2 < bestDistance2)
            {
                bestResult = result;
                bestDistance2 = distance2;
            }
        }
        return bestResult;
    }

    /** point cast and return the first object
     *  @param {Vector2} pos
     *  @param {boolean} [dynamicOnly]
     *  @param {boolean} [includeSensors] - Also find sensors, so a pickup radius does not grab its object from afar
     *  @return {Box2dObject|undefined} */
    pointCast(pos, dynamicOnly=true, includeSensors=false)
    {
        const queryCallback = box2dQueryObject('query', 'JSQueryCallback');
        queryCallback.ReportFixture = function(fixturePointer)
        {
            const fixture = box2d.instance.wrapPointer(fixturePointer, box2d.instance.b2Fixture);
            if (!includeSensors && fixture.IsSensor())
                return true; // a trigger zone, continue getting results
            if (dynamicOnly && fixture.GetBody().GetType() !== box2d.bodyTypeDynamic)
                return true; // continue getting results
            if (!fixture.TestPoint(box2dTemp(pos)))
                return true; // continue getting results
            const o = fixture.GetBody().object;
            if (!o || o.destroyed)
                return true; // a raw body with no Box2dObject or one destroyed this step, continue getting results
            queryObject = o;
            return false; // stop getting results
        };

        const aabb = box2dQueryObject('aabb', 'b2AABB');
        aabb.set_lowerBound(box2dTemp(pos));
        aabb.set_upperBound(box2dTemp(pos));

        let queryObject;
        box2d.world.QueryAABB(queryCallback, aabb);
        debugRaycast && debugRect(pos, vec2(), queryObject ? '#f00' : '#00f', 0, 0, false, false);
        return queryObject;
    }

    ///////////////////////////////////////////////////////////////////////////////
    // drawing

    /** draws a fixture
     *  @param {Object} fixture
     *  @param {Vector2} pos
     *  @param {number} angle
     *  @param {Color} [color]
     *  @param {Color} [lineColor]
     *  @param {number} [lineWidth]
     *  @param {boolean} [useWebGL=glEnable]
     *  @param {CanvasRenderingContext2D} [context] */
    drawFixture(fixture, pos, angle, color=WHITE, lineColor=BLACK, lineWidth=.1, useWebGL, context)
    {
        const shape = box2d.castShapeObject(fixture.GetShape());
        switch (shape.GetType())
        {
            case box2d.instance.b2Shape.e_polygon:
            {
                let points = [];
                for (let i=shape.GetVertexCount(); i--;)
                    points.push(box2d.vec2From(shape.GetVertex(i)));
                drawPoly(points, color, lineWidth, lineColor, pos, angle, useWebGL, false, context);
                break;
            }
            case box2d.instance.b2Shape.e_circle:
            {
                const radius = shape.get_m_radius(), offset = box2d.vec2From(shape.get_m_p());
                drawCircle(pos.add(offset.rotate(angle)), radius*2, color, lineWidth, lineColor, useWebGL, false, context);
                break;
            }
            case box2d.instance.b2Shape.e_edge:
            {
                const v1 = box2d.vec2From(shape.get_m_vertex1());
                const v2 = box2d.vec2From(shape.get_m_vertex2());
                drawLine(v1, v2, lineWidth, lineColor, pos, angle, useWebGL, false, context);
                break;
            }
        }
    }

    ///////////////////////////////////////////////////////////////////////////////
    // helper functions

    /** converts a box2d vec2 to a Vector2
     *  @param {Object} v
     *  @return {Vector2} */
    vec2From(v)
    {
        ASSERT(v instanceof box2d.instance.b2Vec2);
        return new Vector2(v.get_x(), v.get_y()); 
    }

    /** converts a box2d vec2 pointer to a Vector2
     *  @param {Object} vp
     *  @return {Vector2} */
    vec2FromPointer(vp)
    {
        const v = box2d.instance.wrapPointer(vp, box2d.instance.b2Vec2);
        return box2d.vec2From(v);
    }

    /** converts a Vector2 to a new box2d vec2, which stays until destroyed with box2d.instance.destroy;
     *  the plugin itself passes Box2D reused ones, since Box2D copies every vector it is given
     *  @param {Vector2} v
     *  @return {Object} - A Box2D vector, its b2Vec2 */
    vec2dTo(v)
    {
        ASSERT(isVector2(v));
        return new box2d.instance.b2Vec2(v.x, v.y);
    }

    /** checks if a box2d object is null
     *  @param {Object} o
     *  @return {boolean} */
    isNull(o) { return !box2d.instance.getPointer(o); }

    /** casts a box2d object to a shape type
     *  @param {Object} o
     *  @return {Object} - The shape as its own Box2D type */
    castShapeObject(o)
    {
        switch (o.GetType())
        {
            case box2d.instance.b2Shape.e_circle:
                return box2d.instance.castObject(o, box2d.instance.b2CircleShape);
            case box2d.instance.b2Shape.e_edge:
                return box2d.instance.castObject(o, box2d.instance.b2EdgeShape);
            case box2d.instance.b2Shape.e_polygon:
                return box2d.instance.castObject(o, box2d.instance.b2PolygonShape);
            case box2d.instance.b2Shape.e_chain:
                return box2d.instance.castObject(o, box2d.instance.b2ChainShape);
        }
        
        ASSERT(false, 'Unknown box2d object type');
    }

    /** casts a box2d object to a joint type
     *  @param {Object} o
     *  @return {Object} - The joint as its own Box2D type */
    castJointObject(o)
    {
        switch (o.GetType())
        {
            case box2d.instance.e_revoluteJoint:
                return box2d.instance.castObject(o, box2d.instance.b2RevoluteJoint);
            case box2d.instance.e_prismaticJoint:
                return box2d.instance.castObject(o, box2d.instance.b2PrismaticJoint);
            case box2d.instance.e_distanceJoint:
                return box2d.instance.castObject(o, box2d.instance.b2DistanceJoint);
            case box2d.instance.e_pulleyJoint:
                return box2d.instance.castObject(o, box2d.instance.b2PulleyJoint);
            case box2d.instance.e_mouseJoint:
                return box2d.instance.castObject(o, box2d.instance.b2MouseJoint);
            case box2d.instance.e_gearJoint:
                return box2d.instance.castObject(o, box2d.instance.b2GearJoint);
            case box2d.instance.e_wheelJoint:
                return box2d.instance.castObject(o, box2d.instance.b2WheelJoint);
            case box2d.instance.e_weldJoint:
                return box2d.instance.castObject(o, box2d.instance.b2WeldJoint);
            case box2d.instance.e_frictionJoint:
                return box2d.instance.castObject(o, box2d.instance.b2FrictionJoint);
            case box2d.instance.e_ropeJoint:
                return box2d.instance.castObject(o, box2d.instance.b2RopeJoint);
            case box2d.instance.e_motorJoint:
                return box2d.instance.castObject(o, box2d.instance.b2MotorJoint);
        }
        
        ASSERT(false, 'Unknown box2d object type');
    }
}

///////////////////////////////////////////////////////////////////////////////
/** Box2d Init - Call with await to init box2d
 *  @example
 *  await box2dInit();
 *  @return {Promise<Box2dPlugin>}
 *  @memberof Box2D */
async function box2dInit()
{
    // load box2d
    // @ts-ignore - Box2D is the global that box2d.wasm.js defines
    new Box2dPlugin(await Box2D());
    setupDebugDraw();
    engineAddPlugin(box2dUpdate, box2dRender);
    return box2d;

    // add the box2d plugin to the engine
    function box2dUpdate()
    {
        // frozen like the engine objects while paused or time is stopped
        if (paused || !timeScale)
        {
            // what was destroyed while frozen leaves the list, the step does it otherwise
            box2d.objects = box2d.objects.filter(o=>!o.destroyed);
            return;
        }

        box2d.step();

        // copy box2d physics results to engine objects
        for (const o of box2d.objects)
        {
            if (o.body)
            {
                // moved in place, as the engine moves an EngineObject's pos, so what holds it follows the body;
                // box2d uses reverse angle
                const p = o.body.GetPosition();
                o.pos.set(p.get_x(), p.get_y());
                o.angle = -o.body.GetAngle();
            }
        }
    }
    function box2dRender()
    {
        if (box2dDebug || debugPhysics)
            box2d.world.DrawDebugData();
    }
    
    // box2d debug drawing
    function setupDebugDraw()
    {
        // setup debug draw
        const debugLineWidth = .1;
        const debugDraw = new box2d.instance.JSDraw();
        const box2dColor = (c)=> new Color(c.get_r(), c.get_g(), c.get_b());
        const box2dColorPointer = (c)=>
            box2dColor(box2d.instance.wrapPointer(c, box2d.instance.b2Color));
        const getDebugColor = (color)=>box2dColorPointer(color).scale(1,.8);
        const getPointsList = (vertices, vertexCount)=>
        {
            const points = [];
            for (let i=vertexCount; i--;)
                points.push(box2d.vec2FromPointer(vertices+i*8));
            return points;
        }
        debugDraw.DrawSegment = function(point1, point2, color)
        {
            color = getDebugColor(color);
            point1 = box2d.vec2FromPointer(point1);
            point2 = box2d.vec2FromPointer(point2);
            drawLine(point1, point2, debugLineWidth, color, vec2(), 0, false, false);
        };
        debugDraw.DrawPolygon = function(vertices, vertexCount, color)
        {
            color = getDebugColor(color);
            const points = getPointsList(vertices, vertexCount);
            drawPoly(points, CLEAR_WHITE, debugLineWidth, color, vec2(), 0, false, false);
        };
        debugDraw.DrawSolidPolygon = function(vertices, vertexCount, color)
        {
            color = getDebugColor(color);
            const points = getPointsList(vertices, vertexCount);
            drawPoly(points, color, 0, color, vec2(), 0, false, false);
        };
        debugDraw.DrawCircle = function(center, radius, color)
        {
            color = getDebugColor(color);
            center = box2d.vec2FromPointer(center);
            drawCircle(center, radius*2, CLEAR_WHITE, debugLineWidth, color, false, false);
        };
        debugDraw.DrawSolidCircle = function(center, radius, axis, color)
        {
            color = getDebugColor(color);
            center = box2d.vec2FromPointer(center);
            axis = box2d.vec2FromPointer(axis).scale(radius);
            drawCircle(center, radius*2, color, debugLineWidth, color, false, false);
            drawLine(vec2(), axis, debugLineWidth, color, center, 0, false, false);
        };
        debugDraw.DrawTransform = function(transform)
        {
            transform = box2d.instance.wrapPointer(transform, box2d.instance.b2Transform);
            const pos = box2d.vec2From(transform.get_p());
            const angle = -transform.get_q().GetAngle();
            const p1 = vec2(1,0), c1 = rgb(.75,0,0,.8);
            const p2 = vec2(0,1), c2 = rgb(0,.75,0,.8);
            drawLine(vec2(), p1, debugLineWidth, c1, pos, angle, false, false);
            drawLine(vec2(), p2, debugLineWidth, c2, pos, angle, false, false);
        }
            
        debugDraw.AppendFlags(box2d.instance.b2Draw.e_shapeBit);
        debugDraw.AppendFlags(box2d.instance.b2Draw.e_jointBit);
        //debugDraw.AppendFlags(box2d.instance.b2Draw.e_aabbBit);
        //debugDraw.AppendFlags(box2d.instance.b2Draw.e_pairBit);
        //debugDraw.AppendFlags(box2d.instance.b2Draw.e_centerOfMassBit);
        box2d.world.SetDebugDraw(debugDraw);
    }
}
/**
 * LittleJS Drawing Utilities Plugin
 * - Extra drawing functions for LittleJS
 * - Nine slice and three slice drawing, and TileSlice to keep one as a style, like a UI skin
 * @namespace DrawUtilities
 */

///////////////////////////////////////////////////////////////////////////////

/** Draw a scalable nine-slice UI element in screen space, drawNineSlice with screenSpace set
 *  - Draws with the 2D context by default, on top of what WebGL drew, like drawTextScreen
 *  - With no angle its pieces land on whole pixels and meet exactly, so pixel art lines up and extraSpace is not used
 *  @param {Vector2} pos - Screen space position
 *  @param {Vector2} size - Screen space size
 *  @param {TileInfo} startTile - Top-left tile of the 3x3 block to sample (see drawNineSlice)
 *  @param {Color} [color=WHITE] - Color to modulate with
 *  @param {number} [borderSize] - Rendered thickness of the border sections
 *  @param {Color} [additiveColor] - Additive color
 *  @param {number} [extraSpace] - Extra spacing adjustment
 *  @param {number} [angle] - Angle to rotate by
 *  @param {boolean} [useWebGL] - Use WebGL for rendering
 *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use
 *  @memberof DrawUtilities */
function drawNineSliceScreen(pos, size, startTile, color=WHITE, borderSize=32, additiveColor, extraSpace=2, angle=0, useWebGL=false, context)
{
    // the order before 1.20 had borderSize, extraSpace and angle after startTile
    ASSERT(isColor(color), 'drawNineSliceScreen takes a color after startTile, then borderSize', color);
    drawNineSlice(pos, size, startTile, color, borderSize, additiveColor, extraSpace, angle, useWebGL, true, context);
}

/** Draw a scalable nine-slice UI element in world space
 *  Color and additive color apply in WebGL and Canvas2D (with canvasColorTiles)
 *  The nine-slice samples a 3x3 block of tiles from the tilesheet, it does not
 *  subdivide a single tile. Pass the top-left tile of that block as startTile;
 *  the other 8 tiles (edges, corners, and center) are taken automatically from
 *  the 3x3 grid of tiles extending right and down from it. borderSize only sets
 *  the rendered thickness of the edges and corners, not how the texture is cut.
 *  @param {Vector2} pos - World space position
 *  @param {Vector2} size - World space size
 *  @param {TileInfo} startTile - Top-left tile of the 3x3 block to sample the nine-slice from
 *  @param {Color} [color] - Color to modulate with
 *  @param {number} [borderSize] - Rendered thickness of the border sections, 1 in world space and 32 pixels in
 *    screen space by default
 *  @param {Color} [additiveColor] - Additive color
 *  @param {number} [extraSpace] - Extra spacing adjustment, .05 in world space and 2 pixels in screen space by
 *    default
 *  @param {number} [angle] - Angle to rotate by
 *  @param {boolean} [useWebGL=glEnable] - Use WebGL for rendering
 *  @param {boolean} [screenSpace=drawScreenSpace] - Use screen space coordinates
 *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use
 *  @memberof DrawUtilities */
function drawNineSlice(pos, size, startTile, color, borderSize, additiveColor, extraSpace, angle=0, useWebGL=glEnable, screenSpace=drawScreenSpace, context)
{
    // the border and spacing defaults are in the units of the space it draws in
    borderSize ??= screenSpace ? 32 : 1;
    extraSpace ??= screenSpace ? 2 : .05;
    if (!size.x || !size.y) return; // nothing to draw, the spacing must not make a sliver of it
    if (color && color.a < 1)
        extraSpace = 0; // see through, the overlap that hides a seam would draw twice and show brighter
    // setup nine slice tiles - startTile is the top-left of a 3x3 tile block,
    // so the center tile is one tile down and right from it, stepping over
    // the padding around each tile the way tile() lays out the grid
    const step = startTile.size.add(vec2(startTile.padding*2));
    if (screenSpace && !angle)
    {
        // on whole pixels, the pieces in the screen's rows and columns of the block
        drawSliceSnapped(pos, size, borderSize, (col, row)=>
            [startTile.offset(step.multiply(vec2(col, row))), 0], color, additiveColor, useWebGL, context);
        return;
    }
    borderSize = min(borderSize, abs(size.x)/2, abs(size.y)/2); // a box too small for two borders splits between them
    const centerTile = startTile.offset(step);
    const centerSize = size.add(vec2(extraSpace-borderSize*2));
    const cornerSize = vec2(borderSize);
    const cornerOffset = size.scale(.5).subtract(cornerSize.scale(.5));
    const flip = screenSpace ? -1 : 1;
    const rotateAngle = screenSpace ? -angle : angle;

    // center
    drawTile(pos, centerSize, centerTile, color, angle, false, additiveColor, useWebGL, screenSpace, context);
    for (let i=4; i--;)
    {
        // sides
        const horizontal = i%2;
        const sidePos = cornerOffset.multiply(vec2(horizontal?i===1?1:-1:0, horizontal?0:i?-1:1));
        const sideSize = vec2(horizontal ? borderSize : centerSize.x, horizontal ? centerSize.y : borderSize);
        const sideTile = centerTile.offset(step.multiply(vec2(i===1?1:i===3?-1:0,i===0?-flip:i===2?flip:0)))
        drawTile(pos.add(sidePos.rotate(rotateAngle)), sideSize, sideTile, color, angle, false, additiveColor, useWebGL, screenSpace, context);
    }
    for (let i=4; i--;)
    {
        // corners
        const flipX = i>1;
        const flipY = i && i<3;
        const cornerPos = cornerOffset.multiply(vec2(flipX?-1:1, flipY?-1:1));
        const cornerTile = centerTile.offset(step.multiply(vec2(flipX?-1:1,flipY?flip:-flip)));
        drawTile(pos.add(cornerPos.rotate(rotateAngle)), cornerSize, cornerTile, color, angle, false, additiveColor, useWebGL, screenSpace, context);
    }
}

/** Draw a scalable three-slice UI element in screen space, drawThreeSlice with screenSpace set
 *  - Draws with the 2D context by default, on top of what WebGL drew, like drawTextScreen
 *  - With no angle its pieces land on whole pixels and meet exactly, so pixel art lines up and extraSpace is not used
 *  @param {Vector2} pos - Screen space position
 *  @param {Vector2} size - Screen space size
 *  @param {TileInfo} startTile - First of 3 consecutive tiles: corner, side, center (see drawThreeSlice)
 *  @param {Color} [color=WHITE] - Color to modulate with
 *  @param {number} [borderSize] - Rendered thickness of the border sections
 *  @param {Color} [additiveColor] - Additive color
 *  @param {number} [extraSpace] - Extra spacing adjustment
 *  @param {number} [angle] - Angle to rotate by
 *  @param {boolean} [useWebGL] - Use WebGL for rendering
 *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use
 *  @memberof DrawUtilities */
function drawThreeSliceScreen(pos, size, startTile, color=WHITE, borderSize=32, additiveColor, extraSpace=2, angle=0, useWebGL=false, context)
{
    // the order before 1.20 had borderSize, extraSpace and angle after startTile
    ASSERT(isColor(color), 'drawThreeSliceScreen takes a color after startTile, then borderSize', color);
    drawThreeSlice(pos, size, startTile, color, borderSize, additiveColor, extraSpace, angle, useWebGL, true, context);
}

/** Draw a scalable three-slice UI element in world space
 *  Color and additive color apply in WebGL and Canvas2D (with canvasColorTiles)
 *  The three-slice samples 3 consecutive tiles from the tilesheet, it does not
 *  subdivide a single tile. Pass the first tile as startTile; the three tiles
 *  are used in order as corner, side, and center, then rotated and mirrored to
 *  build all four edges and corners. borderSize only sets the rendered thickness.
 *  @param {Vector2} pos - World space position
 *  @param {Vector2} size - World space size
 *  @param {TileInfo} startTile - First of 3 consecutive tiles (corner, side, center) for the three-slice
 *  @param {Color} [color] - Color to modulate with
 *  @param {number} [borderSize] - Rendered thickness of the border sections, 1 in world space and 32 pixels in
 *    screen space by default
 *  @param {Color} [additiveColor] - Additive color
 *  @param {number} [extraSpace] - Extra spacing adjustment, .05 in world space and 2 pixels in screen space by
 *    default
 *  @param {number} [angle] - Angle to rotate by
 *  @param {boolean} [useWebGL=glEnable] - Use WebGL for rendering
 *  @param {boolean} [screenSpace=drawScreenSpace] - Use screen space coordinates
 *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use
 *  @memberof DrawUtilities */
function drawThreeSlice(pos, size, startTile, color, borderSize, additiveColor, extraSpace, angle=0, useWebGL=glEnable, screenSpace=drawScreenSpace, context)
{
    // the border and spacing defaults are in the units of the space it draws in
    borderSize ??= screenSpace ? 32 : 1;
    extraSpace ??= screenSpace ? 2 : .05;
    if (!size.x || !size.y) return; // nothing to draw, the spacing must not make a sliver of it
    if (color && color.a < 1)
        extraSpace = 0; // see through, the overlap that hides a seam would draw twice and show brighter
    // setup three slice tiles - 3 tiles in a row starting at startTile
    const cornerTile = startTile.frame(0);
    const sideTile   = startTile.frame(1);
    const centerTile = startTile.frame(2);
    if (screenSpace && !angle)
    {
        // on whole pixels, each corner and side the top left one's tile turned a quarter more going clockwise
        const turns = [[0,0,1],[3,-1,1],[3,2,2]]; // by column in each row, -1 for the center
        drawSliceSnapped(pos, size, borderSize, (col, row)=>
        {
            const turn = turns[row][col], corner = col !== 1 && row !== 1;
            return turn < 0 ? [centerTile, 0] : [corner ? cornerTile : sideTile, turn*PI/2];
        }, color, additiveColor, useWebGL, context);
        return;
    }
    borderSize = min(borderSize, abs(size.x)/2, abs(size.y)/2); // a box too small for two borders splits between them
    const centerSize = size.add(vec2(extraSpace-borderSize*2));
    const cornerSize = vec2(borderSize);
    const cornerOffset = size.scale(.5).subtract(cornerSize.scale(.5));
    const flip = screenSpace ? -1 : 1;
    const rotateAngle = screenSpace ? -angle : angle;

    // center
    drawTile(pos, centerSize, centerTile, color, angle, false, additiveColor, useWebGL, screenSpace, context);
    for (let i=4; i--;)
    {
        // sides
        const a = angle + i*PI/2;
        const horizontal = i%2;
        const sidePos = cornerOffset.multiply(vec2(horizontal?i===1?1:-1:0, horizontal?0:i?-flip:flip));
        const sideSize = vec2(horizontal ? centerSize.y : centerSize.x, borderSize);
        drawTile(pos.add(sidePos.rotate(rotateAngle)), sideSize, sideTile, color, a, false, additiveColor, useWebGL, screenSpace, context);
    }
    for (let i=4; i--;)
    {
        // corners
        const a = angle + i*PI/2;
        const flipX = !i || i>2;
        const flipY = i>1;
        const cornerPos = cornerOffset.multiply(vec2(flipX?-1:1, flipY?-flip:flip));
        drawTile(pos.add(cornerPos.rotate(rotateAngle)), cornerSize, cornerTile, color, a, false, additiveColor, useWebGL, screenSpace, context);
    }
}

///////////////////////////////////////////////////////////////////////////////

/**
 * A tile drawn as a box of any size, kept as a style to draw with, like a UI skin
 * - 9 slices is a nine-slice from the 3x3 block of tiles at tileInfo, see drawNineSlice
 * - 3 slices is a three-slice from the 3 tiles in a row at tileInfo, see drawThreeSlice
 * - 1 slice is the whole tile stretched over the box, a plain image
 * - The UI system draws a widget's background with one, see uiSystem.defaultSlice
 * @memberof DrawUtilities
 * @example
 * const panel = new TileSlice(tile(0, 16), 9, .5); // a border of half a world unit
 * panel.draw(vec2(0, 5), vec2(10, 4));
 * uiSystem.defaultSlice = new TileSlice(tile(0, 16), 9, 16); // UI sizes are pixels, every widget made after this
 */
class TileSlice
{
    /** Create a tile slice style
     *  @param {TileInfo} tileInfo - The tile, or the first of the tiles, to draw with
     *  @param {number} [slices] - 9 for a nine-slice, 3 for a three-slice, 1 for the whole tile
     *  @param {number} [borderSize] - Drawn thickness of the edges and corners, undefined for the draw's own default
     *  @param {number} [extraSpace] - Extra spacing adjustment of the slices, undefined for the draw's own default */
    constructor(tileInfo, slices=9, borderSize, extraSpace)
    {
        ASSERT(tileInfo instanceof TileInfo, 'tileInfo must be a TileInfo');
        ASSERT(slices === 9 || slices === 3 || slices === 1, 'slices must be 9, 3 or 1');
        ASSERT(borderSize === undefined || isNumber(borderSize), 'borderSize must be a number');

        /** @property {TileInfo} - The tile, or the first of the tiles, to draw with */
        this.tileInfo = tileInfo;
        /** @property {number} - 9 for a nine-slice, 3 for a three-slice, 1 for the whole tile */
        this.slices = slices;
        /** @property {number|undefined} - Drawn thickness of the edges and corners, undefined for the draw's default
         *  @type {number|undefined} */
        this.borderSize = borderSize;
        /** @property {number|undefined} - Extra spacing adjustment of the slices, undefined for the draw's default
         *  @type {number|undefined} */
        this.extraSpace = extraSpace;
    }

    /** Draw it as a box in world space, or in screen space
     *  @param {Vector2} pos - Center position
     *  @param {Vector2} size - Size of the box
     *  @param {Color} [color] - Color to modulate with
     *  @param {Color} [additiveColor] - Additive color
     *  @param {number} [angle] - Angle to rotate by
     *  @param {boolean} [useWebGL=glEnable] - Use WebGL for rendering
     *  @param {boolean} [screenSpace=drawScreenSpace] - Are pos and size in screen space?
     *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use */
    draw(pos, size, color=WHITE, additiveColor, angle=0, useWebGL=glEnable, screenSpace=drawScreenSpace, context)
    {
        if (screenSpace) // with the screen space defaults for the border and spacing
            return this.drawScreen(pos, size, color, additiveColor, angle, useWebGL, context);
        if (this.slices === 9)
            drawNineSlice(pos, size, this.tileInfo, color, this.borderSize, additiveColor, this.extraSpace, angle, useWebGL, screenSpace, context);
        else if (this.slices === 3)
            drawThreeSlice(pos, size, this.tileInfo, color, this.borderSize, additiveColor, this.extraSpace, angle, useWebGL, screenSpace, context);
        else
            drawTile(pos, size, this.tileInfo, color, angle, false, additiveColor, useWebGL, screenSpace, context);
    }

    /** Draw it as a box in screen space, with the 2D context by default, on top of what WebGL drew, like drawTextScreen
     *  @param {Vector2} pos - Screen space center position
     *  @param {Vector2} size - Screen space size
     *  @param {Color} [color] - Color to modulate with
     *  @param {Color} [additiveColor] - Additive color
     *  @param {number} [angle] - Angle to rotate by
     *  @param {boolean} [useWebGL] - Use WebGL for rendering
     *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use */
    drawScreen(pos, size, color=WHITE, additiveColor, angle=0, useWebGL=false, context)
    {
        if (this.slices === 9)
            drawNineSliceScreen(pos, size, this.tileInfo, color, this.borderSize, additiveColor, this.extraSpace, angle, useWebGL, context);
        else if (this.slices === 3)
            drawThreeSliceScreen(pos, size, this.tileInfo, color, this.borderSize, additiveColor, this.extraSpace, angle, useWebGL, context);
        else
            drawTile(pos, size, this.tileInfo, color, angle, false, additiveColor, useWebGL, true, context);
    }
}

// draw a slice box in screen space with no angle on whole pixels: the edges and the border are rounded, and every
// piece is cut from them, so the pieces meet exactly and their texels line up where they do, with no overlap to hide
// a seam; pieceTile(col, row) gives the tile and angle for the piece in that column and row of the box, top left 0
function drawSliceSnapped(pos, size, borderSize, pieceTile, color, additiveColor, useWebGL, context)
{
    // the pixels it lands on are the device's: a 2D context's own scale and offset, like the UI under nativeHeight
    // centered on an odd sized canvas, or the pixel ratio; the draws land half a pixel past, see shift below
    const canvas2D = !useWebGL || !glEnable || !!context;
    const transform = canvas2D && (context || drawContext)?.getTransform?.();
    const ratio = getCanvasPixelRatio();
    const [scaleX, scaleY, offsetX, offsetY] = transform ?
        [transform.a || 1, transform.d || 1, transform.e || 0, transform.f || 0] : [ratio, ratio, 0, 0];
    const edges = (center, length, scale, offset)=>
    {
        // snapped in device order, which a mirrored context reverses, then put back in the box's own order
        const border = max(1, round(borderSize * abs(scale)));
        const a = round((center - length/2) * scale + offset), b = a + round(length * scale);
        const start = min(a, b), end = max(a, b);
        const inner = min(start + border, floor((start + end)/2)); // a box too small for two borders splits
        const device = [start, inner, max(end - border, inner), end];
        return (scale < 0 ? device.reverse() : device).map(edge=> (edge - offset) / scale);
    };
    const xs = edges(pos.x, size.x, scaleX, offsetX), ys = edges(pos.y, size.y, scaleY, offsetY);
    const shift = .5; // a screen space draw lands half a pixel past its position, in Canvas2D and WebGL alike
    for (let row = 3; row--;)
    for (let col = 3; col--;)
    {
        const w = xs[col+1] - xs[col], h = ys[row+1] - ys[row];
        if (w <= 0 || h <= 0) continue;
        const [tileInfo, angle] = pieceTile(col, row);
        const turned = round(angle / (PI/2)) % 2; // a quarter turn swaps the sides it is drawn with
        const piecePos = vec2(xs[col] + w/2 - shift, ys[row] + h/2 - shift);
        drawTile(piecePos, turned ? vec2(h, w) : vec2(w, h), tileInfo, color, angle, false, additiveColor, useWebGL, true, context);
    }
}

/** Draw a crescent / moon-phase shape built from a polygon
 *  Routes through drawPoly, so it supports WebGL, screen space, color, and outlines
 *  - At angle 0 the lit side faces up while waxing (percent below .5) and down while waning, and the lit width
 *    grows evenly with the phase, not as the real moon's does
 *  @param {Vector2} pos - Center position
 *  @param {number}  [size] - Diameter
 *  @param {number}  [percent] - Moon phase over a full cycle (0=new, .25=first quarter, .5=full, .75=last quarter), wraps
 *  @param {Color}   [color] - Fill color
 *  @param {number}  [angle] - Angle to rotate by
 *  @param {boolean} [invert] - Draw the unlit part of the disk instead of the lit part
 *  @param {number}  [lineWidth] - Outline width, 0 for no outline
 *  @param {Color}   [lineColor] - Outline color
 *  @param {boolean} [useWebGL=glEnable] - Use WebGL for rendering
 *  @param {boolean} [screenSpace=drawScreenSpace] - Use screen space coordinates
 *  @param {CanvasRenderingContext2D|OffscreenCanvasRenderingContext2D} [context] - Canvas context to use
 *  @memberof DrawUtilities */
function drawCrescent(pos, size=1, percent=0, color=WHITE, angle=0, invert=false, lineWidth=0, lineColor=BLACK, useWebGL=glEnable, screenSpace=drawScreenSpace, context)
{
    // build local-space points and let drawPoly apply pos/angle so screen space works
    const points = getCrescentPoints(vec2(), size, percent, 0, invert);
    drawPoly(points, color, lineWidth, lineColor, pos, angle, useWebGL, screenSpace, context);
}

/** Get the list of points that make up a crescent / moon-phase shape
 *  Returns world-space points with pos and angle baked in, ready for drawPoly or other use
 *  @param {Vector2} pos - Center position
 *  @param {number}  [size] - Diameter
 *  @param {number}  [percent] - Moon phase over a full cycle (0=new, .25=first quarter, .5=full, .75=last quarter), wraps
 *  @param {number}  [angle] - Angle to rotate by
 *  @param {boolean} [invert] - The unlit part of the disk instead of the lit part
 *  @param {number}  [sides=glCircleSides] - Number of sides for a full circle (halved per arc)
 *  @return {Array<Vector2>} - List of points making up the crescent
 *  @memberof DrawUtilities */
function getCrescentPoints(pos, size=1, percent=0, angle=0, invert=false, sides=glCircleSides)
{
    ASSERT(isVector2(pos), 'pos must be a vec2');
    ASSERT(isNumber(size) && isNumber(percent), 'size and percent must be numbers');

    // map phase to a signed terminator curve: -1 new, 0 half, 1 full
    let p = mod(percent*4, 4); // quarter phase 0..4
    if (p >= 2)                // second half of cycle flips orientation
        angle += PI;
    p = p <= 2 ? p-1 : 3-p;
    if (invert)                // the unlit part: the other side of the same curve
    {
        p = -p;
        angle += PI;
    }

    // build the crescent: outer semicircle, then inner half-ellipse traced back
    const points = [];
    const segs = max(3, sides>>1);
    const radius = size/2;
    for (let i=0; i<=segs; i++)
    {
        const t = i/segs*PI;
        points.push(vec2(radius*cos(t), radius*sin(t)).rotate(angle).add(pos));
    }
    for (let i=segs; i>=0; i--)
    {
        const t = i/segs*PI;
        points.push(vec2(radius*cos(t), -radius*p*sin(t)).rotate(angle).add(pos));
    }
    return points;
}
/**
 * LittleJS Texture Sheet Plugin
 * - Packs images into texture sheets as they are loaded
 * - Sprites are placed automatically, callers get a TileInfo
 * - Sheets are created and filled as needed
 * - Sheets fill in call order, images decode in parallel
 * - Animation frames keep layout and wrap across rows as needed
 * - WebGL textures upload once per batch of loads
 * - loadAtlas imports pre-packed atlases (TexturePacker and Aseprite json)
 * - loadTiles packs separate tile images, or several tile sheets, into one tile set for tile layers and maps
 * @namespace TextureSheets
 */

/** Width and height in pixels of texture sheets created by loadSprite
 *  @type {number}
 *  @default
 *  @memberof Settings */
let textureSheetSize = 2048;

/** Default padding pixels around each frame packed by loadSprite
 *  @type {number}
 *  @default
 *  @memberof Settings */
let textureSheetPadding = 1;

/** Array of texture sheets created by loadSprite
 *  @type {Array<TextureSheet>}
 *  @memberof TextureSheets */
let textureSheets = [];

// pending loads pack through a queue so sheets fill in call order
let textureSheetQueue = Promise.resolve();
let textureSheetPendingCount = 0;
// what each load handed back by what it was given, so the same image loaded again is packed once
const textureSheetLoaded = new Map;
// a load's key: what it was given, a vector by its numbers
const textureSheetLoadKey = (...parts)=> parts.map((p)=> isVector2(p) ? p.x + ',' + p.y : String(p)).join('|');
// a load whose file failed is forgotten, so loading it again tries again, as when the server comes back
const textureSheetLoadFailed = (key, loaded)=> textureSheetLoaded.get(key) === loaded && textureSheetLoaded.delete(key);

/**
 * Texture Sheet - A texture that images are packed into as they load
 * Uses shelf packing, images are placed left to right then wrap to a new row
 * @memberof TextureSheets
 */
class TextureSheet
{
    /** Create a texture sheet, called automatically by loadSprite
     *  @param {number} [size] - Width and height of the sheet in pixels */
    constructor(size=textureSheetSize)
    {
        ASSERT(size > 0, 'texture sheet size must be positive');

        /** @property {number} - Width and height of the sheet in pixels */
        this.size = size;
        /** @property {OffscreenCanvasRenderingContext2D} - 2d context for the canvas */
        this.context = headlessMode ? undefined : createCanvasContext(size);
        /** @property {OffscreenCanvas} - Canvas holding the packed images */
        this.canvas = this.context?.canvas;
        /** @property {TextureInfo} - The texture info for this sheet */
        this.textureInfo = new TextureInfo(this.canvas);
        /** @property {Vector2} - Where the next image will be packed */
        this.cursor = vec2();
        /** @property {number} - Height of the row being packed */
        this.rowHeight = 0;
        /** @property {boolean} - Has the canvas changed since the last webgl upload? */
        this.glDirty = false;

        if (headlessMode)
        {
            // tiles still need bounds when there is no canvas to measure
            this.textureInfo.size = vec2(size);
            this.textureInfo.sizeInverse = vec2(1/size);
        }
    }

    /** Find a spot for an image on this sheet without drawing it
     *  @param {Vector2} imageSize - Size of the source image in pixels
     *  @param {Vector2} [frameSize] - Size of each frame, or the whole image less its source padding if not passed
     *  @param {number} [padding] - How many pixels padding around each frame
     *  @param {number|Vector2} [sourcePadding] - How many pixels padding around each frame in the source image
     *  @return {TileInfo|undefined} Tile for the packed image, or undefined if the sheet is full */
    tryAdd(imageSize, frameSize, padding=textureSheetPadding, sourcePadding=0)
    {
        // a number pads both axes the same
        const sourcePad = isNumber(sourcePadding) ?
            vec2(/** @type {number} */ (sourcePadding)) : /** @type {Vector2} */ (sourcePadding);
        ASSERT(isVector2(sourcePad) && sourcePad.x >= 0 && sourcePad.y >= 0,
            'sourcePadding must be a number or vec2 >= 0');
        ASSERT(isVector2(imageSize), 'sizes must be vec2');
        frameSize ||= imageSize.subtract(sourcePad.scale(2)); // the whole image, less the padding baked into it
        ASSERT(isVector2(frameSize), 'sizes must be vec2');
        ASSERT(frameSize.x > 0 && frameSize.y > 0, 'frame size must be positive');

        // the source may have its own padding baked in around each frame
        const sourceCellWidth = frameSize.x + sourcePad.x*2;
        const sourceCellHeight = frameSize.y + sourcePad.y*2;
        ASSERT(imageSize.x % sourceCellWidth === 0 && imageSize.y % sourceCellHeight === 0,
            'image size must be a multiple of the padded frame size');

        const cellWidth = frameSize.x + padding*2;
        const cellHeight = frameSize.y + padding*2;
        const maxColumns = this.size / cellWidth | 0;
        ASSERT(maxColumns > 0, 'frame is too wide to fit on a texture sheet');

        // keep the layout of the source image, but narrow it if a row is too wide
        // frames wrap down to the next row, which TileInfo.frame handles via columns
        // whole frames only, a partial one left over at an edge is ignored
        const sourceColumns = imageSize.x / sourceCellWidth | 0;
        const frameCount = sourceColumns * (imageSize.y / sourceCellHeight | 0);
        if (!frameCount)
            return undefined; // smaller than a frame, there is nothing to pack
        const columns = min(sourceColumns, maxColumns);
        const blockWidth = columns * cellWidth;
        const blockHeight = ceil(frameCount / columns) * cellHeight;

        // probe the placement using locals so a failed try leaves the sheet unchanged
        let x = this.cursor.x, y = this.cursor.y, rowHeight = this.rowHeight;
        if (x + blockWidth > this.size)
        {
            // start a new row if this one does not have enough space left
            x = 0;
            y += rowHeight;
            rowHeight = 0;
        }

        // out of space, the caller needs to use a different sheet
        if (y + blockHeight > this.size)
            return undefined;

        // commit the placement, tile pos points inside the padding to match how tile() works
        this.cursor.x = x + blockWidth;
        this.cursor.y = y;
        this.rowHeight = max(rowHeight, blockHeight);
        return new TileInfo(vec2(x + padding, y + padding), frameSize, this.textureInfo, padding, 0, columns);
    }

    /** Draw an image into this sheet at a tile returned by tryAdd
     *  @param {HTMLImageElement|HTMLCanvasElement|OffscreenCanvas|ImageBitmap} image - Source image to copy from
     *  @param {TileInfo} tileInfo - Where to put it, from tryAdd
     *  @param {boolean} [update] - Upload to webgl now, pass false when batching
     *  @param {number|Vector2} [sourcePadding] - How many pixels padding around each frame in the source image */
    drawImage(image, tileInfo, update=true, sourcePadding=0)
    {
        ASSERT(!!this.context, 'texture sheet has no canvas');

        // a number pads both axes the same
        const sourcePad = isNumber(sourcePadding) ?
            vec2(/** @type {number} */ (sourcePadding)) : /** @type {Vector2} */ (sourcePadding);

        // copy frames in order, reading the source left to right, top to bottom
        // the destination wraps at tileInfo.columns which may be narrower than the source
        const frameSize = tileInfo.size;
        const sourceCellWidth = frameSize.x + sourcePad.x*2;
        const sourceCellHeight = frameSize.y + sourcePad.y*2;
        // whole frames only as tryAdd packed them, a fractional count would never end the loop
        const sourceColumns = image.width / sourceCellWidth | 0;
        const frameCount = sourceColumns * (image.height / sourceCellHeight | 0);
        const columns = tileInfo.columns || frameCount;
        const cellWidth = frameSize.x + tileInfo.padding*2;
        const cellHeight = frameSize.y + tileInfo.padding*2;
        for (let i = frameCount; i--;)
        {
            const sourceX = (i % sourceColumns) * sourceCellWidth + sourcePad.x;
            const sourceY = (i / sourceColumns | 0) * sourceCellHeight + sourcePad.y;
            this.context.drawImage(image,
                sourceX, sourceY, frameSize.x, frameSize.y,
                tileInfo.pos.x + (i % columns) * cellWidth,
                tileInfo.pos.y + (i / columns | 0) * cellHeight,
                frameSize.x, frameSize.y);
        }

        // upload now unless the caller is batching more images
        this.glDirty = true;
        update && this.updateTexture();
    }

    /** Upload the canvas to webgl if it has changed since the last upload
     *  Only needed after batching, drawImage uploads automatically by default */
    updateTexture()
    {
        if (!this.glDirty) return;
        this.glDirty = false;
        this.textureInfo.createWebGLTexture();
    }
}

///////////////////////////////////////////////////////////////////////////////

/** Load an image and pack it into a texture sheet
 *  - Returns a TileInfo immediately which is filled in when the image loads
 *  - Nothing is visible until it loads, use spritesReady to wait for it
 *  - Pass frameSize for animations, then step through them with TileInfo.frame
 *  - Grid images keep their layout and frames wrap down to the next row
 *  - Pass sourcePadding if the source image has padding baked in around frames
 *  - The same image loaded again with the same settings gives back what the first load did, packed once, unless
 *    that load failed
 *  @param {string} src - Image source path
 *  @param {Vector2|number} [frameSize] - Size of each animation frame in pixels, or the whole image less its
 *  source padding if not passed
 *  @param {number} [padding] - How many pixels padding around each frame
 *  @param {number|Vector2} [sourcePadding] - How many pixels padding around each frame in the source image
 *  @return {TileInfo}
 *  @example
 *  const playerTile = loadSprite('player.png');     // a single sprite
 *  const runTile = loadSprite('run.png', vec2(16)); // a 16x16 frame animation
 *  @memberof TextureSheets */
function loadSprite(src, frameSize, padding=textureSheetPadding, sourcePadding=0)
{
    ASSERT(isStringLike(src), 'image src must be a string');
    ASSERT(!frameSize || isVector2(frameSize) || isNumber(frameSize), 'frameSize must be a vec2 or number');
    ASSERT(isNumber(padding), 'padding must be a number');
    ASSERT(isNumber(sourcePadding) || isVector2(sourcePadding), 'sourcePadding must be a number or vec2');
    ASSERT(engineInitialized || headlessMode, 'call loadSprite after engineInit, e.g. in gameInit');

    if (isNumber(frameSize))
        frameSize = vec2(/** @type {number} */ (frameSize));
    const key = textureSheetLoadKey('sprite', src, frameSize, padding, sourcePadding);
    if (!headlessMode && textureSheetLoaded.has(key))
        return textureSheetLoaded.get(key);

    // start with an empty tile that gets filled in when the image loads
    const tileInfo = new TileInfo(vec2(), vec2(), undefined, padding, 0);
    if (headlessMode) return tileInfo;
    textureSheetLoaded.set(key, tileInfo);

    // point at a sheet right away so drawing before it loads picks up empty pixels
    tileInfo.textureInfo = (textureSheets[0] || textureSheetCreate()).textureInfo;

    // start decoding right away, images decode in parallel
    const image = new Image;
    const imagePromise = new Promise(resolve =>
    {
        image.onerror = image.onload = resolve;
        image.crossOrigin = 'anonymous';
        image.src = src;
    });

    // pack through a queue so sheets fill in call order, not decode order
    textureSheetQueueJob('loadSprite ' + src, async ()=>
    {
        await imagePromise;
        if (image.width)
        {
            // pack onto a sheet, then fill in the tile that was already handed out,
            // copying every field so nothing is missed if TileInfo gains more of them
            const imageSize = vec2(image.width, image.height);
            const added = textureSheetAdd(imageSize, frameSize, padding, sourcePadding);
            if (!added)
            {
                // leave the tile empty, no sheet can hold it
                console.warn('loadSprite image is too large to fit on a texture sheet:', src);
                return;
            }
            Object.assign(tileInfo, added.tile);
            added.sheet.drawImage(image, tileInfo, false, sourcePadding); // upload once per batch below
        }
        else
        {
            // leave the tile empty if the image failed to load
            console.warn('loadSprite failed to load image:', src);
            textureSheetLoadFailed(key, tileInfo);
        }
    });

    return tileInfo;
}

/** Load tile images and pack them into texture sheets as one tile set, for tile layers and maps
 *  - Each image is cut into tiles of tileSize, left to right then down, so an image of one tile is one tile and a
 *    sheet is all of its tiles; the tiles are numbered from 0 in the order the images are given
 *  - Returns a tile set at once, a TileInfo whose tiles fill in as the images load; wait for them with spritesReady
 *  - Give it to tileLayersLoad, a TileLayer or a TileCollisionLayer as its tile info: tile n draws tiles[n],
 *    wherever it was packed, and the level editor's palette offers each of them; frame and index do not read the
 *    list, use set.tiles[n] for one tile; make the layers after spritesReady, a layer made before draws nothing
 *  - An image that is not a whole number of tiles gives the whole tiles in it; a sheet with gaps between its tiles
 *    is not read, cut it into its tiles first
 *  - An image that fails to load, or that no sheet can hold, adds no tiles and says so in the console, so the tiles
 *    of the images after it move up
 *  - The same images loaded again with the same settings give back what the first load did, packed once, unless
 *    an image of it failed
 *  @param {Array<string>} sources - Image source paths
 *  @param {Vector2|number} [tileSize] - Size of a tile in pixels
 *  @param {number} [padding] - How many pixels padding around each tile on the sheet
 *  @return {TileInfo}
 *  @example
 *  const tiles = loadTiles(['grass.png', 'dirt.png', 'water.png', 'props.png'], 16);
 *  await spritesReady();
 *  tileLayersLoad(map, tiles); // tile 0 is grass, 1 dirt, 2 water, then the tiles of props.png
 *  @memberof TextureSheets */
function loadTiles(sources, tileSize=tileDefaultSize, padding=textureSheetPadding)
{
    ASSERT(isArray(sources) && sources.every((src)=> isStringLike(src)), 'sources must be a list of image paths');
    ASSERT(isVector2(tileSize) || isNumber(tileSize), 'tileSize must be a vec2 or number');
    ASSERT(isNumber(padding), 'padding must be a number');
    ASSERT(engineInitialized || headlessMode, 'call loadTiles after engineInit, e.g. in gameInit');
    const size = isNumber(tileSize) ? vec2(/** @type {number} */ (tileSize)) : /** @type {Vector2} */ (tileSize).copy();
    const key = textureSheetLoadKey('tiles', sources.join('\n'), size, padding);
    if (!headlessMode && textureSheetLoaded.has(key))
        return textureSheetLoaded.get(key);
    const set = new TileInfo(vec2(), size, undefined, 0, 0);
    set.tiles = [];
    if (headlessMode) return set;
    textureSheetLoaded.set(key, set);
    set.textureInfo = (textureSheets[0] || textureSheetCreate()).textureInfo;

    // every image decodes at once, and packs through the queue in the order given, so the tiles keep that order
    for (const src of sources)
    {
        const image = new Image;
        const imagePromise = new Promise((resolve)=>
        {
            image.onerror = image.onload = resolve;
            image.crossOrigin = 'anonymous';
            image.src = src;
        });
        textureSheetQueueJob('loadTiles ' + src, async ()=>
        {
            await imagePromise;
            // the whole tiles of it, an edge past the last one left out
            const columns = image.width / size.x | 0, rows = image.height / size.y | 0, count = columns * rows;
            const added = count && textureSheetAdd(vec2(columns * size.x, rows * size.y), size, padding, 0);
            image.width || textureSheetLoadFailed(key, set);
            if (!added)
                return console.warn('loadTiles: ' + src + (count ? ' does not fit on a texture sheet' :
                    ' failed to load, or is smaller than a tile') + ', its tiles are left out');
            added.sheet.drawImage(image, added.tile, false); // upload once per batch
            for (let k = 0; k < count; ++k)
                set.tiles.push(added.tile.frame(k));
        });
    }
    return set;
}

/** Load a pre-packed texture atlas and repack it onto texture sheets
 *  - Supports TexturePacker json (hash and array) and Aseprite json
 *  - Returns an empty object which is filled with TileInfos when loaded
 *  - Frames are named by the json, animations are grouped automatically
 *  - Aseprite frame tags become animations, so do names like run_0, run_1
 *  - Trimmed frames are restored to their full source size when packed
 *  - Rotated frames are rotated back upright when packed
 *  - The same atlas loaded again by its paths, with the same padding, gives back what the first load did, packed
 *    once, unless that load failed
 *  @param {string} imageSrc - Atlas image path
 *  @param {string|Object} jsonSrc - Atlas json path, or already parsed json data
 *  @param {number} [padding] - How many pixels padding around each frame
 *  @return {Object<string, TileInfo>} Object mapping frame and animation names to TileInfos
 *  @example
 *  const atlas = loadAtlas('sprites.png', 'sprites.json');
 *  await spritesReady();
 *  drawTile(pos, size, atlas.player);          // a single frame
 *  drawTile(pos, size, atlas.run.frame(2));    // frame 2 of the run animation
 *  @memberof TextureSheets */
function loadAtlas(imageSrc, jsonSrc, padding=textureSheetPadding)
{
    ASSERT(isStringLike(imageSrc), 'atlas image src must be a string');
    ASSERT(isStringLike(jsonSrc) || typeof jsonSrc === 'object', 'atlas json must be a path or object');
    ASSERT(isNumber(padding), 'padding must be a number');
    ASSERT(engineInitialized || headlessMode, 'call loadAtlas after engineInit, e.g. in gameInit');

    // json passed in as data may be another atlas each time, only one loaded by its path is kept
    const key = typeof jsonSrc === 'object' ? undefined : textureSheetLoadKey('atlas', imageSrc, jsonSrc, padding);
    if (!headlessMode && textureSheetLoaded.has(key))
        return textureSheetLoaded.get(key);

    /** @type {Object<string, TileInfo>} */
    const atlas = {};
    if (headlessMode) return atlas;
    key && textureSheetLoaded.set(key, atlas);

    // start fetching the json and decoding the image right away, in parallel
    const jsonPromise = typeof jsonSrc === 'object' ? Promise.resolve(jsonSrc) :
        fetch(jsonSrc).then(r=> r.ok && r.json()).catch(()=> undefined);
    const image = new Image;
    const imagePromise = new Promise(resolve =>
    {
        image.onerror = image.onload = resolve;
        image.crossOrigin = 'anonymous';
        image.src = imageSrc;
    });

    // pack through a queue so sheets fill in call order, not decode order
    textureSheetQueueJob('loadAtlas ' + imageSrc, async ()=>
    {
        const data = await jsonPromise;
        await imagePromise;
        if (image.width && data)
        {
            for (const group of parseAtlas(data))
            {
                // reserve a block of full size cells, one per frame
                if (!group.frames.length) continue; // a tag with no frames, the groups after it still load
                const sourceSize = group.frames[0].sourceSize;
                const blockSize = vec2(sourceSize.x*group.frames.length, sourceSize.y);
                const added = textureSheetAdd(blockSize, sourceSize, padding);
                if (!added)
                {
                    console.warn('loadAtlas frames are too large to fit on a texture sheet:', group.name);
                    continue;
                }
                const {sheet, tile} = added;

                // draw each frame untrimmed into its cell
                const context = sheet.context;
                const cellWidth = sourceSize.x + padding*2;
                const cellHeight = sourceSize.y + padding*2;
                group.frames.forEach((f, i)=>
                {
                    const x = tile.pos.x + (i % tile.columns)*cellWidth + f.offset.x;
                    const y = tile.pos.y + (i / tile.columns |0)*cellHeight + f.offset.y;
                    if (f.rotated)
                    {
                        // stored rotated 90 degrees clockwise, draw it back upright
                        context.save();
                        context.translate(x, y);
                        context.rotate(-PI/2);
                        context.drawImage(image, f.pos.x, f.pos.y, f.size.y, f.size.x,
                            -f.size.y, 0, f.size.y, f.size.x);
                        context.restore();
                    }
                    else
                        context.drawImage(image, f.pos.x, f.pos.y, f.size.x, f.size.y,
                            x, y, f.size.x, f.size.y);
                });
                sheet.glDirty = true;
                atlas[group.name] = tile;
            }
        }
        else
        {
            // leave the atlas empty if either file failed to load
            console.warn('loadAtlas failed to load:', imageSrc, jsonSrc);
            textureSheetLoadFailed(key, atlas);
        }
    });

    return atlas;
}

// run a load in the queue: a load that throws is reported and the loads after it carry on, the pending count
// always comes back down, and the sheets upload to webgl once per batch, when the last pending load finishes
function textureSheetQueueJob(name, job)
{
    ++textureSheetPendingCount;
    textureSheetQueue = textureSheetQueue.then(async ()=>
    {
        try { await job(); }
        catch (e) { console.error(name + ' failed:', e); }
        finally
        {
            if (!--textureSheetPendingCount)
                for (const sheet of textureSheets)
                {
                    try { sheet.updateTexture(); }
                    catch (e) { console.error('texture sheet upload failed:', e); }
                }
        }
    });
}

/** Parse atlas json into a list of named frame groups, used by loadAtlas
 *  - Accepts TexturePacker json (hash and array) and Aseprite json
 *  - Frames tagged in Aseprite or named like run_0, run_1 group into animations
 *  @param {Object} data - Parsed atlas json data
 *  @return {Array<Object>} List of {name, frames} groups in atlas order
 *  @memberof TextureSheets */
function parseAtlas(data)
{
    ASSERT(!!data?.frames, 'unrecognized atlas format, expected TexturePacker or Aseprite json');

    // normalize both hash and array frame layouts into a single list
    const frames = (isArray(data.frames) ?
        data.frames.map(f=> [f.filename, f]) : Object.entries(data.frames))
        .map(([name, f])=> ({
            name: name.replace(/\.[^.\\/]+$/, ''), // strip file extension
            pos:        vec2(f.frame.x, f.frame.y),
            size:       vec2(f.frame.w, f.frame.h),
            offset:     vec2(f.spriteSourceSize?.x ?? 0, f.spriteSourceSize?.y ?? 0),
            sourceSize: vec2(f.sourceSize?.w ?? f.frame.w, f.sourceSize?.h ?? f.frame.h),
            rotated:    !!f.rotated,
        }));

    const groups = [];
    const tags = data.meta?.frameTags;
    if (tags?.length)
    {
        // aseprite tags are authoritative, untagged frames stay individual
        const tagged = new Set;
        for (const tag of tags)
        {
            // a tag reaches only frames there are, whatever its numbers say
            const from = max(0, floor(tag.from) || 0), to = min(frames.length - 1, floor(tag.to) || 0);
            groups.push({name: tag.name, frames: frames.slice(from, to + 1)});
            for (let i = from; i <= to; ++i)
                tagged.add(i);
        }
        frames.forEach((f, i)=> tagged.has(i) || groups.push({name: f.name, frames: [f]}));
        return parseAtlasNamesCheck(groups);
    }

    // group frames that share a name stem with contiguous trailing numbers
    // run_0.png and run_1.png become a 2 frame animation named run, and so do the folder style run/0.png and run/1.png
    const stems = new Map;
    for (const f of frames)
    {
        let match = f.name.match(/^(.+?)([-_ /])?(\d+)$/);
        if (match && !match[2] && /\d$/.test(match[1]))
            match = undefined; // all digit tails like 10 are a name, not frame 0 of 1
        const stem = match ? match[1] : f.name;
        f.groupIndex = match ? Number(match[3]) : undefined;
        stems.has(stem) || stems.set(stem, []);
        stems.get(stem).push(f);
    }
    for (const [stem, list] of stems)
    {
        // only group 2 or more frames with contiguous indices and matching sizes
        list.sort((a, b)=> a.groupIndex - b.groupIndex);
        const grouped = list.length > 1 &&
            list.every((f, i)=> f.groupIndex === list[0].groupIndex + i) &&
            list.every(f=> f.sourceSize.x === list[0].sourceSize.x &&
                           f.sourceSize.y === list[0].sourceSize.y);
        if (grouped)
            groups.push({name: stem, frames: list});
        else
            list.forEach(f=> groups.push({name: f.name, frames: [f]}));
    }
    return parseAtlasNamesCheck(groups);
}

// an atlas's groups, with a warning for each name two of them have, as a sprite is looked up by name and the second
// takes the first's place
function parseAtlasNamesCheck(groups)
{
    const names = new Set;
    for (const {name} of groups)
        names.has(name) ? console.warn(`parseAtlas: two sprites are named ${name}, the second takes the first's place`) :
            names.add(name);
    return groups;
}

/** Wait for everything started by loadSprite and loadAtlas to finish packing
 *  @return {Promise}
 *  @example
 *  async function gameInit()
 *  {
 *      playerTile = loadSprite('player.png');
 *      runTile = loadSprite('run.png', vec2(16));
 *      await spritesReady();
 *  }
 *  @memberof TextureSheets */
async function spritesReady()
{
    // keep waiting until the queue drains, more sprites may load while waiting
    while (textureSheetPendingCount)
        await textureSheetQueue;
}

// create a new texture sheet and add it to the list
function textureSheetCreate()
{
    const sheet = new TextureSheet;
    textureSheets.push(sheet);
    return sheet;
}

// use the first sheet with enough space, or make a new one,
// returns undefined if it would not fit even on an empty sheet
function textureSheetAdd(imageSize, frameSize, padding, sourcePadding)
{
    let sheet, tile;
    for (sheet of textureSheets)
        if (tile = sheet.tryAdd(imageSize, frameSize, padding, sourcePadding))
            break;
    if (!tile)
    {
        // probe an empty sheet first, a new one is a canvas and a texture kept for good
        const emptySheet = {size: textureSheetSize, cursor: vec2(), rowHeight: 0};
        if (!TextureSheet.prototype.tryAdd.call(emptySheet, imageSize, frameSize, padding, sourcePadding))
            return;
        sheet = textureSheetCreate();
        tile = sheet.tryAdd(imageSize, frameSize, padding, sourcePadding);
    }
    return {sheet, tile};
}

///////////////////////////////////////////////////////////////////////////////
// Texture sheet setting setters

/** Set width and height in pixels of texture sheets created by loadSprite
 *  @param {number} size
 *  @memberof Settings */
function setTextureSheetSize(size) { textureSheetSize = size; }

/** Set default padding pixels around each frame packed by loadSprite
 *  @param {number} padding
 *  @memberof Settings */
function setTextureSheetPadding(padding) { textureSheetPadding = padding; }

/**
 * LittleJS Tween System Plugin
 * - Lightweight tweens for numbers, Vector2, Color, or any .lerp-able type
 * - Chainable easing, looping, and ping-pong
 * - Property-path helper for the common case of animating an object field
 * - Auto-updates via engineAddPlugin; pauses with the game by default
 * @namespace TweenSystem
 */

///////////////////////////////////////////////////////////////////////////////

// Module-private list of tweens currently running, each with its active flag set while it is in it; a stopped
// one stays listed, inactive, until the next update takes it out, so stopping many is not a search for each
const tweenActive = [];
const tweenUpdateList = []; // the tweens an update moves, the ones active when it began
let tweenUpdatePass = 0; // counts the updates, a tween started during one waits for the next

// put a tween in the active list, or take it out, keeping its flag in step so a check costs nothing
function tweenActivate(tween)
{
    tween.activePass = tweenUpdatePass; // started again, even while active, so this update leaves it alone
    if (tween.active) return;
    tween.active = true;
    tween.listed || tweenActive.push(tween); // one stopped this update is still listed, in its place
    tween.listed = true;
}
function tweenDeactivate(tween) { tween.active = false; }

// True if the value is an instance of a class that exposes a numeric-percent
// `lerp(other, percent)` method (Vector2, Color, or any future class).
function tweenIsLerpable(v) { return v && typeof v.lerp === 'function'; }

///////////////////////////////////////////////////////////////////////////////

/** A tween: drives a callback with a value interpolated between
 *  `start` and `end` over `duration` seconds. Pauses with the game by default.
 *  - In TypeScript it is a `Tween<T>` of the type it tweens, which comes from `start` and `end` or
 *    the callback's parameter, so `(v: number)=> ...` takes a number
 *  @template [T=any]
 *  @memberof TweenSystem
 *  @example
 *  // Animate a fade-out over 2 seconds with an ease-out sine curve.
 *  new Tween((v) => obj.alpha = v, 1, 0, 2, { ease: Ease.OUT(Ease.SINE) });
 */
class Tween
{
    /** Create a new tween. The callback fires immediately with `start` so the
     *  target snaps to the start value on the same frame the tween is created.
     *
     *  `start` and `end` may be numbers, Vector2, Vector3 or Color instances, or
     *  any object exposing a `lerp(other, percent) => sameType` method. The
     *  callback receives the interpolated value (a number, or a fresh instance
     *  for lerp-able types). Both endpoints must be the same type.
     *  @param {function(NonNullable<T>):void} callback - Called with the interpolated value each frame
     *  @param {T} [start] - Starting value
     *  @param {T} [end] - Ending value
     *  @param {number} [duration] - Duration in seconds
     *  @param {Object} [options]
     *  @param {function(number):number} [options.ease] - Easing function (defaults to LINEAR)
     *  @param {boolean} [options.useRealTime=false] - Advance even when the game is paused (matches Timer's useRealTime)
     *  @param {boolean} [options.paused=false] - Start in paused state */
    constructor(callback, start = /** @type {T} */ (0), end = /** @type {T} */ (1), duration = 1, options = {})
    {
        ASSERT(typeof callback === 'function', 'Tween callback must be a function');
        if (tweenIsLerpable(start))
        {
            ASSERT(start.constructor === end.constructor,
                'Tween start and end must be the same type');
        }
        else
        {
            ASSERT(isNumber(start), 'Tween start must be a number or have a .lerp method');
            ASSERT(isNumber(end),   'Tween end must be a number when start is a number');
        }
        ASSERT(isNumber(duration) && duration > 0, 'Tween duration must be > 0');

        // the callback's type is NonNullable<T>, which is T, so that TypeScript takes the type from start and end
        // first: a typed callback like (v: number)=> with start 10 then makes a Tween<number>, not a Tween<0|10>
        /** @property {function(T):void} - Called with the interpolated value each frame
         *  @type {function(T):void} */
        this.callback = callback;
        /** @property {T} - Starting value
         *  @type {T} */
        this.start = start;
        /** @property {T} - Ending value
         *  @type {T} */
        this.end = end;
        /** @property {number} - Total duration in seconds */
        this.duration = duration;
        /** @property {number} - Remaining time in seconds (counts down from duration to 0) */
        this.life = duration;
        /** @property {function(number):number} - Easing curve mapping [0,1] -> [0,1] */
        this.ease = options.ease || Ease.LINEAR;
        /** @property {boolean} - If true, advance even when the game is paused */
        this.useRealTime = !!options.useRealTime;
        /** @property {boolean} - If true, stop advancing until cleared */
        this.paused = !!options.paused;
        /** @property {undefined|function():void} - Called once the tween completes: when its last pass ends,
         *  the last iteration of a loop or pingPong, and again each time a restart plays through; then() sets it
         *  @type {undefined|function():void} */
        this.onComplete = undefined;

        /** Continuation when a pass ends, set by loop() and pingPong() to start the next iteration.
         *  @private */
        this.thenCallback = undefined;
        /** Remaining iterations including the current run (loop/pingPong only).
         *  @private */
        this.loopRemaining = 0;
        /** Whether it is running, see isActive
         *  @private */
        this.active = false;
        /** Whether it is in the active list, which a stopped one leaves at the next update
         *  @private */
        this.listed = false;
        /** The update it was started in, it first moves on the one after
         *  @private */
        this.activePass = 0;
        /** Engine time and real time of its last engine update, it moves by what passed since
         *  @private */
        this.lastTime = time;
        /** @private */
        this.lastTimeReal = timeReal;
        /** @property {Object|undefined} - The object tweenProperty animates, the tween stops once it is destroyed,
         *  even while paused
         *  @type {{destroyed?: boolean}|undefined} */
        this.target = undefined;

        tweenActivate(this);
        // Snap target to start immediately.
        callback(this.interp(duration));
    }

    /** Set the easing curve and return this for chaining.
     *  @param {function(number):number} easeFn
     *  @return {Tween<T>} */
    setEase(easeFn)
    {
        this.ease = easeFn;
        return this;
    }

    /** Set the completion callback, `onComplete`, and return this for chaining.
     *  It is called once the tween completes: when its pass ends, or for a
     *  `loop` or `pingPong` when its last iteration ends, so an endless one
     *  never calls it. Calling `then` again replaces the previous callback.
     *  - It works with `loop` and `pingPong` in either order, neither replaces the other
     *  - It is kept by `restart`, so a restarted tween calls it again when it completes
     *  - `stop` and `tweenStopAll` end a tween without calling it
     *  @param {function():void} callback
     *  @return {Tween<T>} */
    then(callback)
    {
        this.onComplete = callback;
        return this;
    }

    /** Repeat this tween `n` total times. After each iteration finishes, the
     *  same tween starts over, so the handle returned stays good for the whole
     *  loop: pause or stop it to pause or stop every iteration left.
     *  `loop()` with no argument loops forever.
     *
     *  Mutually exclusive with `pingPong`; calling either replaces the other.
     *  A `then` callback, set before or after, is called when the last
     *  iteration ends.
     *  @param {number} [count=Infinity]
     *  @return {Tween<T>} */
    loop(count = Infinity)
    {
        this.loopRemaining = count;
        this.thenCallback = () => tweenLoopContinuation(this);
        return this;
    }

    /** Like `loop`, but swap `start` and `end` between iterations so the value
     *  bounces back and forth. `pingPong()` with no argument bounces forever.
     *
     *  Mutually exclusive with `loop`; calling either replaces the other.
     *  A `then` callback, set before or after, is called when the last
     *  iteration ends.
     *  @param {number} [count=Infinity]
     *  @return {Tween<T>} */
    pingPong(count = Infinity)
    {
        this.loopRemaining = count;
        this.thenCallback = () => tweenPingPongContinuation(this);
        return this;
    }

    /** Pause this tween. While paused, tweenUpdate skips it. */
    pause() { this.paused = true; }

    /** Resume a paused tween. */
    resume() { this.paused = false; }

    /** Reset this tween to the start: life back to duration, pause cleared,
     *  re-added to the active list if previously stopped, and the callback
     *  re-fired with the start value.
     *  It replays one pass: a loop or pingPong that has finished is not started
     *  over, a pingPong that ended on its way back plays that way again, and a
     *  restart mid loop keeps the iterations left. Call loop or pingPong again
     *  after restart to repeat it. The `then` callback is kept and is called
     *  again when it completes. */
    restart()
    {
        this.life = this.duration;
        this.paused = false;
        this.lastTime = time;
        this.lastTimeReal = timeReal;
        tweenActivate(this);
        this.callback(this.interp(this.duration));
    }

    /** True if this tween is in the active list and not paused.
     *  @return {boolean} */
    isActive()
    {
        return !this.paused && this.active;
    }

    /** Get how far this tween has progressed, from 0 (just started) to 1
     *  (completed). Clamped — overshoot past completion still reads 1.
     *  @return {number} */
    getPercent()
    {
        return percent(this.duration - this.life, 0, this.duration);
    }

    /** Get the current interpolated value (the value most recently passed to
     *  the callback). Returns a number, Vector2, Vector3 or Color depending on the
     *  tween's start/end types.
     *  @return {T} */
    getValue()
    {
        return this.interp(this.life);
    }

    /** Compute the interpolated value at the given remaining `life`.
     *  At life === duration the result is `start`; at life === 0 it is `end`.
     *  - At life 0 it is the end value exactly
     *  - A vector goes past its ends as far as the easing does, as a number does; a Color stays between them,
     *    so its channels stay in range, and any other type goes as far as its own lerp takes it
     *  @param {number} life
     *  @return {T} */
    interp(life)
    {
        // the ends of whatever type it tweens, each kind is handled below
        const s = /** @type {any} */ (this.start), e = /** @type {any} */ (this.end);
        if (life <= 0) // the end exactly, an easing curve may land a rounding error short of it
            return typeof e.copy === 'function' ? e.copy() : e;
        const x = this.ease((this.duration - life) / this.duration);
        // the vectors as their lerp does it, which lands on the end exactly, but without its clamp
        const y = 1 - x;
        if (s instanceof Vector2)
            return /** @type {T} */ (vec2(e.x * x + s.x * y, e.y * x + s.y * y));
        if (typeof Vector3 !== 'undefined' && s instanceof Vector3) // a build may leave out the 3D math
            return /** @type {T} */ (vec3(e.x * x + s.x * y, e.y * x + s.y * y, e.z * x + s.z * y));
        if (tweenIsLerpable(s))
            return s.lerp(e, x);
        return s + (e - s) * x;
    }

    /** Remove this tween from the active list, ending a loop or pingPong too, without calling
     *  the then-callback. It keeps the then-callback, so a restart calls it when it completes. */
    stop()
    {
        tweenDeactivate(this);
        this.thenCallback = undefined;
    }
}

/** Library of named easing curves and direction modifiers.
 *  All curves accept `x` in [0,1] and return [0,1] (with possible overshoot
 *  for ELASTIC/BACK/SPRING/BOUNCE). Curves are values you pass to `setEase`
 *  or compose via the IN/OUT/IN_OUT/PIECEWISE/BEZIER modifiers.
 *  @memberof TweenSystem
 *  @example
 *  // Use a basic curve
 *  new Tween(callback, 0, 10, 1).setEase(Ease.SINE);
 *  // Use a modifier on a curve
 *  new Tween(callback, 0, 10, 1).setEase(Ease.OUT(Ease.BACK));
 */
const Ease =
{
    /** Linear (identity) curve.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    LINEAR: (x) => x,

    /** Power curve factory: `Ease.POWER(n)` returns `x => x**n`.
     *  Use n=2 for quadratic, n=3 for cubic, etc.
     *  @param {number} n
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease */
    POWER: (n) => (x) => x ** n,

    /** Sine ease-in curve: starts slow, ends fast.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    SINE: (x) => 1 - cos(x * (PI / 2)),

    /** Circular ease-in curve.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    CIRC: (x) => 1 - (1 - x * x)**.5,

    /** Exponential ease-in curve (`2^(10x-10)`).
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    EXPO: (x) => x === 0 ? 0 : 2 ** (10 * x - 10),

    /** Back ease-in: overshoots backward at the start before snapping forward.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    BACK: (x) => x * x * (2.70158 * x - 1.70158),

    /** Elastic ease-in: oscillations that grow toward the end.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    ELASTIC: (x) =>
        x === 0 ? 0 :
        x === 1 ? 1 :
        -(2 ** (10 * x - 10)) * sin(((37 - 40 * x) * PI) / 6),

    /** Spring ease-in: wobbles around the start before springing to the end;
     *  `Ease.OUT(Ease.SPRING)` overshoots and settles on the target.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease */
    SPRING: (x) =>
        1 -
        (sin(PI * (1 - x) * (0.2 + 2.5 * (1 - x) ** 3)) *
            x ** 2.2 +
            (1 - x)) *
            (1.0 + 1.2 * x),

    /** Bouncing ease-in: small bounces near the start, then a rise to the end.
     *  Symmetric with the other base curves, which are all ease-in. To get the
     *  classic "object falls and hits the ground" shape (bounces near x=1),
     *  wrap with `Ease.OUT`: `Ease.OUT(Ease.BOUNCE)`.
     *  @param {number} x
     *  @return {number}
     *  @memberof TweenSystem.Ease
     *  @example
     *  Ease.BOUNCE                  // ease-in bounce (bouncy at start)
     *  Ease.OUT(Ease.BOUNCE)        // ease-out bounce (object hits ground)
     *  Ease.IN_OUT(Ease.BOUNCE)     // bounces at both ends
     */
    BOUNCE: (x) =>
    {
        // Inverted form of the standard easeOutBounce: 1 - bounceOut(1 - x).
        let t = 1 - x, f;
        if (t < 4 / 11) f = 7.5625 * t * t;
        else if (t < 8 / 11) f = 7.5625 * (t -= 6 / 11) * t + 0.75;
        else if (t < 10 / 11) f = 7.5625 * (t -= 9 / 11) * t + 0.9375;
        else f = 7.5625 * (t -= 10.5 / 11) * t + 0.984375;
        return 1 - f;
    },

    /** Ease-in direction modifier: returns the curve unchanged. Symmetric
     *  with `OUT` and `IN_OUT`. Base curves are already ease-in by
     *  convention, so wrapping a curve in `IN` is a no-op — useful when
     *  picking the direction programmatically.
     *  @param {function(number):number} f - Curve to use as ease-in (returned unchanged)
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease
     *  @example
     *  // Pick direction at runtime
     *  const dir = bouncyMode ? Ease.OUT : Ease.IN;
     *  new Tween(cb, 0, 10, 1).setEase(dir(Ease.BACK));
     */
    IN: (f) => f,

    /** Reverse a curve so it eases out instead of in: `x => 1 - f(1 - x)`.
     *  @param {function(number):number} f
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease
     *  @example
     *  Ease.OUT(Ease.POWER(2)) // ease-out quadratic
     */
    OUT: (f) => (x) => 1 - f(1 - x),

    /** Combine the first half of `f` with `Ease.OUT(f)` for a symmetric curve.
     *  @param {function(number):number} f
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease */
    IN_OUT: (f) => Ease.PIECEWISE(f, Ease.OUT(f)),

    /** Split [0,1] into N equal sections and run a different curve in each.
     *  Each curve is mapped to its section: section i runs over [i/n, (i+1)/n]
     *  and its output is mapped to [i/n, (i+1)/n] of the overall range.
     *  @param {...function(number):number} fns
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease */
    PIECEWISE: (...fns) =>
    {
        const n = fns.length;
        return (x) =>
        {
            const i = (x * n - 1e-9) >> 0;
            return (fns[i]((x - i / n) * n) + i) / n;
        };
    },

    /** Cubic Bezier curve solver in the style of CSS `cubic-bezier`.
     *  Control points (0,0), (x1,y1), (x2,y2), (1,1).
     *  @param {number} x1
     *  @param {number} y1
     *  @param {number} x2
     *  @param {number} y2
     *  @return {function(number):number}
     *  @memberof TweenSystem.Ease
     *  @example
     *  Ease.BEZIER(0.25, 0.1, 0.25, 1) // CSS "ease"
     */
    BEZIER: (x1, y1, x2, y2) =>
    {
        // Parametric cubic Bezier with implicit (0,0) and (1,1) endpoints.
        const curve = (t) =>
        {
            const u = 1 - t;
            const c1 = 3 * u * u * t;
            const c2 = 3 * u * t * t;
            const t3 = t ** 3;
            return [c1 * x1 + c2 * x2 + t3, c1 * y1 + c2 * y2 + t3];
        };
        return (x) =>
        {
            // the ends are exact, a tween starts and ends on its values
            if (x <= 0) return 0;
            if (x >= 1) return 1;

            // binary search for t such that curve(t).x = x, then return curve(t).y; a fixed count, since stopping
            // once x is close can leave y far off where the curve is steep, 32 halvings put t within 1e-9
            let t0 = 0, t1 = 1;
            for (let i = 32; i--;)
            {
                const tMid = (t0 + t1) / 2;
                if (curve(tMid)[0] < x) t0 = tMid; else t1 = tMid;
            }
            return curve((t0 + t1) / 2)[1];
        };
    },
};

/** Tween a property on an object by dot-path. Returns the underlying Tween
 *  so all chaining methods (`setEase`, `then`, `loop`, `pingPong`, etc.)
 *  remain available.
 *
 *  `start` and `end` may be numbers, Vector2, Vector3 or Color instances, or
 *  any object with a `lerp(other, percent) => sameType` method.
 *
 *  It stops on its own once the target is destroyed, so a looping tween on an object ends with it; a tween on a
 *  value inside the object, like `tweenProperty(obj.pos, 'x')`, or a new Tween with its own callback, has to be
 *  stopped by the game.
 *  @template [T=any]
 *  @param {Object} target - The object whose property is being animated
 *  @param {string} propertyPath - Dot-separated path, e.g. `'pos.x'` or `'color'`
 *  @param {T} start - Starting value
 *  @param {T} end - Ending value
 *  @param {number} [duration] - Duration in seconds
 *  @param {Object} [options] - Same options as the Tween constructor
 *  @param {function(number):number} [options.ease] - Easing function (defaults to LINEAR)
 *  @param {boolean} [options.useRealTime=false] - Advance even when the game is paused
 *  @param {boolean} [options.paused=false] - Start in paused state
 *  @return {Tween<T>}
 *  @memberof TweenSystem
 *  @example
 *  // Numeric: slide an object's x with an ease-out sine curve
 *  tweenProperty(player, 'pos.x', 0, 10, 2).setEase(Ease.OUT(Ease.SINE));
 *  // Vector2: animate a position diagonally
 *  tweenProperty(player, 'pos', vec2(-5, 0), vec2(5, 3), 2);
 *  // Color: pulse between two colors
 *  tweenProperty(sprite, 'color', RED, BLUE, 1).pingPong();
 */
function tweenProperty(target, propertyPath, start, end, duration = 1, options = {})
{
    ASSERT(target != null && typeof target === 'object', 'tweenProperty target must be an object');
    ASSERT(isStringLike(propertyPath) && propertyPath.length > 0, 'tweenProperty propertyPath must be a non-empty string');

    const parts = propertyPath.split('.');
    const lastKey = parts.pop();
    let tween;
    const callback = (value) =>
    {
        // a destroyed object ends it, a loop or pingPong would run on it for good and keep it from being freed
        if (target.destroyed) return void tween?.stop();
        let obj = target;
        for (const k of parts)
        {
            obj = obj[k];
            ASSERT(obj != null, 'tweenProperty path does not resolve: ' + propertyPath);
        }
        obj[lastKey] = value;
    };
    tween = new Tween(callback, start, end, duration, options);
    tween.target = target;
    return tween;
}

// Start the next iteration with the time the last one ran over already spent, so a loop keeps its
// pace; an update that ran over by more than a whole iteration lands where the cycle is, not owing it
function tweenCarryOvershoot(tween)
{
    const duration = tween.duration;
    tween.life = duration > 0 ? min(tween.life, 0) % duration + duration : 1e-9;
}

// How many iterations the update that finished one ran through: that one and every whole one after it
function tweenPassed(tween)
{
    const duration = tween.duration;
    return duration > 0 ? 1 + floor(-min(tween.life, 0) / duration) : 1; // no time, or less, is one each update
}

// start the next iteration of a loop or pingPong, the time the last one ran over already spent, true
function tweenNextIteration(tween, passed, continuation)
{
    tween.loopRemaining -= passed;
    tweenCarryOvershoot(tween);
    tween.thenCallback = continuation;
    tweenActivate(tween);
    tween.callback(tween.interp(tween.life)); // snap to where the new iteration is
    return true;
}

// Continuation that schedules the next loop iteration when one finishes, true if it did.
// Reuses the same Tween across iterations, so the handle from `.loop()` pauses or stops the whole loop.
function tweenLoopContinuation(tween)
{
    // count every iteration that went by, a finite loop ends once they run out
    const passed = tweenPassed(tween);
    if (tween.loopRemaining <= passed) return false; // Infinity never runs out
    return tweenNextIteration(tween, passed, () => tweenLoopContinuation(tween));
}

// Continuation for pingPong: swaps start and end on the same tween each iteration, true if it started another.
function tweenPingPongContinuation(tween)
{
    // swap the ends once for each iteration that went by, but when they run out the last one keeps its
    // direction, so it ends on the end it really reached and a restart plays that way again
    const passed = tweenPassed(tween);
    const done = tween.loopRemaining <= passed; // Infinity never runs out
    const swaps = done ? max(tween.loopRemaining - 1, 0) : passed;
    if (swaps & 1)
    {
        const tmp = tween.start;
        tween.start = tween.end;
        tween.end = tmp;
    }
    if (done)
    {
        // the completion gave the other end, give the one it finished on
        if (swaps & 1)
            tween.callback(tween.interp(0));
        return false;
    }
    return tweenNextIteration(tween, passed, () => tweenPingPongContinuation(tween));
}

/** Engine plugin hook: advance every active tween by the appropriate delta.
 *  The engine calls it with no arguments on every fixed update, so it can run
 *  more than once in a rendered frame, and on paused updates too, where only
 *  real time tweens move. May also be called with `(gameDelta, realDelta)` to drive tweens without the engine
 *  loop, for headless tests or an engine in manual step that is not stepped; in a running game such a call adds to
 *  the engine's own update, and a delta of 0 or less does nothing.
 *  @param {number} [gameDelta] - Game-time delta in seconds; default: game time since the tween's last engine update
 *  @param {number} [realDelta] - Real-time delta in seconds; default: real time since the tween's last engine update
 *  @memberof TweenSystem */
function tweenUpdate(gameDelta, realDelta)
{
    // Engine path: each tween moves by the time since its own last update, so one made
    // this update, before or after this call, first moves on the next, like a Timer
    const enginePath = gameDelta === undefined;
    if (!enginePath && realDelta === undefined)
    {
        // Manual path with one arg: real and game advance together.
        realDelta = gameDelta;
    }

    // Move the tweens that were active when this update began, each once: a callback
    // may stop any tween, even all of them, and one that is stopped is skipped; a tween
    // made or started again during the update, like the next turn of a loop, moves on
    // from the next update. Newest first, as the list has always been walked.
    // a callback that calls tweenUpdate itself gets a list of its own, the outer update is still walking this one
    const list = tweenUpdateList.length ? [] : tweenUpdateList, pass = ++tweenUpdatePass;
    let kept = 0;
    for (const t of tweenActive)
        if (t.active)
            list.push(tweenActive[kept++] = t);
        else
            t.listed = false; // stopped since the last update, out of the list now
    tweenActive.length = kept;
    // the list is let go however the walk ends: a callback that throws must not leave it held, or every
    // update after would take it for an update still going and make a list of its own
    try
    {
        for (let i = list.length; i--;)
        {
            const t = list[i];
            // stopped, or started again by a callback this update, or during an update a callback ran inside it, which
            // counts on from this one
            if (!t.active || t.activePass >= pass) continue;
            let dt;
            if (enginePath)
            {
                // a paused tween keeps count too, so it does not jump when resumed
                dt = t.useRealTime ? timeReal - t.lastTimeReal : time - t.lastTime;
                t.lastTime = time;
                t.lastTimeReal = timeReal;
            }
            else
                dt = t.useRealTime ? realDelta : gameDelta;
            if (t.target?.destroyed) { t.stop(); continue; } // its object is gone, paused or not
            if (t.paused || dt <= 0) continue;

            t.life -= dt;
            if (t.life > 1e-9) // the engine's deltas add up a rounding error short of the duration
            {
                t.callback(t.interp(t.life));
            }
            else
            {
                // Completion: fire end value, remove from active, start the next iteration
                // of a loop or pingPong, or when there is none it has completed, fire onComplete
                t.callback(t.interp(0));
                if (!t.active || t.activePass >= pass)
                    continue; // stopped or restarted by its own callback, the run it was on ends without completing
                tweenDeactivate(t);
                const next = t.thenCallback;
                t.thenCallback = undefined;
                if (!(next && next()) && t.onComplete)
                    t.onComplete();
            }
        }
    }
    finally { list.length = 0; }
}

/** Stop every active tween, ending loops too, without calling their then-callbacks.
 *  Useful for resets on level transitions or when changing scenes.
 *  @memberof TweenSystem */
function tweenStopAll()
{
    for (const t of tweenActive)
        t.thenCallback = undefined, t.active = t.listed = false;
    tweenActive.length = 0;
}

// Register with the engine so tweens auto-advance.
engineAddPlugin(tweenUpdate);

/**
 * LittleJS Scene System Plugin
 * - A game's states, like a title, the game and game over, as scene objects
 * - setScene leaves the current scene, destroys the objects and enters the next
 * - Objects with the persistent flag set outlive every switch
 * - Pause is the engine's paused flag, a scene's update stops with gameUpdate
 * @namespace SceneSystem
 */

///////////////////////////////////////////////////////////////////////////////

/** A scene, any object with the hooks it needs, each optional and called as a method so this is the scene
 *  @typedef {Object} Scene
 *  @property {function():void} [enter] - Called when the scene starts, after the old one left and the objects were destroyed
 *  @property {function():void} [leave] - Called before the next scene starts, while the scene is current and its objects are still there
 *  @property {function():void} [update] - Called each update after gameUpdate, not while paused or at time scale 0
 *  @property {function():void} [render] - Called before gameRender, to draw under the objects
 *  @property {function():void} [renderPost] - Called after gameRenderPost, to draw over the game, while paused too; plugins made after the first setScene draw over it
 *  @memberof SceneSystem */

let sceneCurrent, sceneLeaving = false, scenePluginAdded = false;

/** Leave the current scene, destroy every object that is not persistent, and enter the next scene
 *  - Setting the current scene again restarts it, and no scene leaves the game with none
 *  - The switch happens at once, it can be called from anywhere but a scene's leave
 *  @param {Scene} [scene] - The scene to enter
 *  @memberof SceneSystem */
function setScene(scene)
{
    ASSERT(!sceneLeaving, 'setScene can not be called from a scene leave');
    if (!scenePluginAdded)
    {
        scenePluginAdded = true;
        engineAddPlugin(sceneUpdate, sceneRenderPost, undefined, undefined, sceneRender);
    }

    if (sceneCurrent)
    {
        // a leave that throws still lets the next switch through
        sceneLeaving = true;
        try { sceneCurrent.leave?.(); }
        finally { sceneLeaving = false; }
    }
    engineObjectsDestroy();
    sceneCurrent = scene;
    scene?.enter?.();
}

/** Get the current scene
 *  @return {Scene|undefined}
 *  @memberof SceneSystem */
function getScene() { return sceneCurrent; }

// the plugin hooks, update skips the frozen ticks that skip gameUpdate
function sceneUpdate() { paused || !timeScale || sceneCurrent?.update?.(); }
function sceneRender() { sceneCurrent?.render?.(); }
function sceneRenderPost() { sceneCurrent?.renderPost?.(); }

/**
 * LittleJS Parallax Plugin
 * - A background layer that follows the camera by a part of its movement, so it looks far away
 * - Repeats across the view, so a level of any width has a background
 * - Draws mountains by default, or anything a game draws into it
 * @namespace Parallax
 */

///////////////////////////////////////////////////////////////////////////////

/**
 * A background layer with parallax: an image that follows the camera by a part of its movement and repeats across
 * the view, drawn once into a canvas by a function, mountains when none is given
 * - A far layer has a parallax near 1 and a low renderOrder, a near one a smaller parallax and a higher renderOrder
 * - The image should meet itself at its left and right edges to repeat without a seam, as the mountains do
 * @memberof Parallax
 * @extends CanvasLayer
 * @example
 * // three ranges of mountains, the far ones lighter and slower
 * for (let i = 3; i--;)
 *     new ParallaxLayer(vec2(0, i*2), vec2(40, 20), .9 - i*.2, -1e3 + i,
 *         parallaxMountains(hsl(.6, .3, .7 - i*.2), hsl(.6, .5, .2), i));
 *
 * // or draw your own image into the layer
 * new ParallaxLayer(vec2(), vec2(40, 20), .5, -1e3, (context, size)=>
 * {
 *     context.fillStyle = '#fff';
 *     context.fillRect(size.x/2 - 20, size.y/2 - 20, 40, 40);
 * });
 */
class ParallaxLayer extends CanvasLayer
{
    /** Create a parallax layer and draw its image
     *  @param {Vector2} [pos] - Where the middle of the image is in the world when the camera is there too
     *  @param {Vector2} [size] - World size of one copy of the image
     *  @param {number|Vector2} [parallax] - How much of the camera's movement it follows, 0 stays with the world
     *    and 1 with the screen, a Vector2 to follow x and y by different amounts
     *  @param {number} [renderOrder] - Low to draw behind the game, far layers lowest
     *  @param {function(OffscreenCanvasRenderingContext2D, Vector2, ParallaxLayer): void} [drawFunction] - Draws
     *    the image, given the canvas context, its size in pixels and the layer; mountains when not given
     *  @param {Vector2} [canvasSize] - Size of the image in pixels */
    constructor(pos=vec2(), size=vec2(32, 16), parallax=.5, renderOrder=-1e3, drawFunction=parallaxMountains(),
        canvasSize=vec2(512, 256))
    {
        ASSERT(isNumber(parallax) || isVector2(parallax), 'parallax must be a number or a Vector2');
        ASSERT(typeof drawFunction == 'function', 'drawFunction must be a function');
        super(pos, size, 0, renderOrder, canvasSize);

        /** @property {Vector2} - How much of the camera's movement it follows on each axis, 0 stays with the world
         *  and 1 with the screen */
        this.parallax = isVector2(parallax) ? /** @type {Vector2} */ (parallax).copy() :
            vec2(/** @type {number} */ (parallax));
        /** @property {boolean} - Repeat the image across the view, left and right */
        this.wrapX = true;
        /** @property {boolean} - Repeat the image up and down the view */
        this.wrapY = false;
        /** @property {number} - How much the camera's zoom changes its size on the screen: 1 like the world, 0 not
         *  at all, the same on the screen at any zoom as it is at zoomScale */
        this.zoomFollow = 1;
        /** @property {number} - The camera scale its size is given for, used when zoomFollow is under 1 */
        this.zoomScale = cameraScale;
        /** @property {function(OffscreenCanvasRenderingContext2D, Vector2, ParallaxLayer): void} - Draws the
         *  image, redraw() after changing it */
        this.drawFunction = drawFunction;
        this.redraw();
    }

    /** Draw the image again with drawFunction, after changing it or what it draws from */
    redraw()
    {
        const context = this.context;
        if (!context) return; // headless
        const size = vec2(this.canvas.width, this.canvas.height);
        context.clearRect(0, 0, size.x, size.y);
        this.drawFunction(context, size, this);
        this.updateWebGL();
    }

    // how much smaller it is drawn than its size, from the camera's zoom and how much of it the layer follows
    zoomFactor()
    { return this.zoomFollow < 1 && cameraScale > 0 ? (this.zoomScale / cameraScale) ** (1 - this.zoomFollow) : 1; }

    /** World size one copy of the image is drawn at now, its size unless zoomFollow is under 1
     *  @return {Vector2} */
    getDrawSize() { return this.size.scale(this.zoomFactor()); }

    /** Where each copy of the image is drawn now, in the world: one place, or with wrapping every place that
     *  shows in the view
     *  @return {Array<Vector2>} */
    getDrawPositions()
    {
        // its place seen from the camera is cut down by the parallax, and by the zoom it does not follow
        const zoom = this.zoomFactor(), size = this.size.scale(zoom), p = this.parallax;
        const offset = this.pos.subtract(cameraPos);
        const center = cameraPos.add(vec2(offset.x * (1 - p.x) * zoom, offset.y * (1 - p.y) * zoom));

        // the copies that reach into the view; a turned camera sees as far as its corner each way
        const view = mainCanvasSize.scale(.5 / (cameraScale || 1));
        const reach = cameraAngle ? vec2(view.length()) : view;
        const range = (wrap, axis)=>
        {
            if (!wrap || !(size[axis] > 0)) return [0, 0];
            const from = cameraPos[axis] - reach[axis] - size[axis] / 2 - center[axis];
            const to = cameraPos[axis] + reach[axis] + size[axis] / 2 - center[axis];
            const first = ceil(from / size[axis]);
            return [first, min(floor(to / size[axis]), first + 99)]; // a tiny image does not draw without end
        };
        const [x0, x1] = range(this.wrapX, 'x'), [y0, y1] = range(this.wrapY, 'y'), positions = [];
        for (let y = y0; y <= y1; ++y)
        for (let x = x0; x <= x1; ++x)
            positions.push(vec2(center.x + x * size.x, center.y + y * size.y));
        return positions;
    }

    // Render the layer, called automatically by the engine
    render()
    {
        const size = this.getDrawSize();
        for (const pos of this.getDrawPositions())
            this.draw(pos, size, this.color, 0, this.mirror, this.additiveColor, false);
    }
}

///////////////////////////////////////////////////////////////////////////////

// the ridge of a range of mountains: a height for each column of an image and one more, the last the same as the
// first so the image repeats with no step; it wanders about the middle, turning now and then
function parallaxRidge(width, height, random)
{
    const pointiness = .2, levelness = .005, slopeRange = height / 256; // how often it turns, how hard it is
    const ridge = new Float32Array(width + 1), middle = height / 2;     // pulled level, how steep it gets
    let y = middle, slope = random.float(-slopeRange, slopeRange);
    for (let x = 0; x <= width; ++x)
    {
        ridge[x] = y;
        y += slope -= (y - middle) * levelness;
        if (random.float() < pointiness)
            slope = random.float(-slopeRange, slopeRange);
    }
    // take out the difference between its ends, a little from each column, and keep it inside the image
    const drift = ridge[width] - ridge[0];
    for (let x = 0; x <= width; ++x)
        ridge[x] = clamp(ridge[x] - drift * x / width, 0, height);
    return ridge;
}

/** A draw function for a ParallaxLayer: a range of mountains across the image, shaded from the color of their
 *  peaks down to the color of their feet, that repeats with no seam
 *  @param {Color} [topColor] - Color at the peaks
 *  @param {Color} [bottomColor] - Color at the bottom of the image
 *  @param {number} [seed] - The same seed gives the same mountains, random when not given
 *  @return {function(OffscreenCanvasRenderingContext2D, Vector2): void}
 *  @memberof Parallax */
function parallaxMountains(topColor=hsl(.6, .2, .6), bottomColor=hsl(.6, .3, .25), seed)
{
    return (context, size)=>
    {
        const w = size.x, h = size.y;
        const random = new RandomGenerator(seed === undefined ? randInt(1e9) + 1 : seed * 7919 + 1);
        const ridge = parallaxRidge(w, h, random);

        // a strip one pixel wide with the shading, stretched down each column from its peak
        const strip = createCanvasContext(1, h);
        for (let i = h; i--;)
        {
            strip.fillStyle = topColor.lerp(bottomColor, i / h).toString();
            strip.fillRect(0, i, 1, 1);
        }
        for (let x = w; x--;)
            ridge[x] < h && context.drawImage(strip.canvas, 0, 0, 1, h, x, ridge[x], 1, h - ridge[x]);
    };
}

/**
 * LittleJS PathFinder Plugin
 * - Grid-based A* pathfinder with two-pass smoothing for natural-looking paths
 * - Works directly on a TileCollisionLayer, or override isWalkable/getCost for any grid
 * - Debug visualization via engine debug primitives (stripped in release builds)
 * - Port of frankforce.com pathFindingBase.cpp (2018)
 * @namespace PathFinding
 */

///////////////////////////////////////////////////////////////////////////////

// Diagonal step cost — pre-computed for the A* expansion inner loop.
const PATHFINDER_DIAGONAL_COST = Math.SQRT2;

// Shared 1x1 size vector for per-tile debugRect calls. debugRect copies the
// argument internally, so reusing one instance is safe.
const PATHFINDER_TILE_VEC = vec2(1);

///////////////////////////////////////////////////////////////////////////////

/** A single grid cell tracked by the pathfinder. Allocated once per cell at
 *  PathFinder construction; reset (not reallocated) at the start of every
 *  findPath call.
 *  @memberof PathFinding */
class PathFinderNode
{
    /** Make the node of a grid cell, as PathFinder does for each
     *  @param {number} x - Tile x
     *  @param {number} y - Tile y */
    constructor(x, y)
    {
        /** @property {Vector2} - Tile coords (integer) */
        this.pos = vec2(x, y);
        /** @property {Vector2} - World-space center of this tile (set by buildNodeData) */
        this.posWorld = vec2();
        /** @property {boolean} - True if this cell is passable (set by buildNodeData) */
        this.walkable = false;
        /** @property {number} - Extra cost added to A* G-score for stepping on this cell */
        this.cost = 0;
        /** @property {number} - A* G-score: actual cost from start to this node */
        this.g = 0;
        /** @property {number} - A* F-score: G + heuristic */
        this.f = 0;
        /** @property {number} - A* heuristic: the estimated cost left to the goal, breaks ties between equal F */
        this.h = 0;
        /** @property {PathFinderNode|null} - Parent for path reconstruction
         *  @type {PathFinderNode|null} */
        this.parent = null;
        /** @property {boolean} - In the A* open list */
        this.isOpen = false;
        /** @property {boolean} - In the A* closed list */
        this.isClosed = false;
        /** @property {number} - Where it is in the A* open list's heap, while open */
        this.heapIndex = 0;
    }

    /** Clear what a search left on this node, keeping walkable and cost */
    resetSearch()
    {
        this.g = this.f = this.h = 0;
        this.parent = null;
        this.isOpen = this.isClosed = false;
    }

    /** Reset per-search state and walkability (called by buildNodeData). */
    reset() { this.walkable = false; this.cost = 0; this.resetSearch(); }

    /** True if walkable and not blocked by cost.
     *  @return {boolean} */
    isClear()
    {
        return this.walkable && this.cost === 0;
    }
}

///////////////////////////////////////////////////////////////////////////////

/** Grid pathfinder using A* with two optional smoothing passes.
 *  @memberof PathFinding
 *  @example
 *  // Tile-layer driven (most common):
 *  const pf = new PathFinder(myTileCollisionLayer);
 *  const path = pf.findPath(player.pos, mousePos);
 *
 *  // Bare grid with custom walkability:
 *  const gridFinder = new PathFinder(vec2(50, 50));
 *  gridFinder.isWalkable = (x, y) => myGrid[y*50 + x] === 0;
 */
class PathFinder
{
    /** Make a path finder over a tile layer or a grid
     *  @param {TileCollisionLayer|Vector2} source - Either a TileCollisionLayer
     *  (size and walkability auto-derived) or a Vector2 grid size (user
     *  overrides isWalkable). */
    constructor(source)
    {
        // Accept a Vector2 size, or a TileCollisionLayer or any object with its size and getCollisionData
        if (isVector2(source))
        {
            /** @property {Vector2} - Grid dimensions in tiles
             *  @type {Vector2} */
            this.size = /** @type {Vector2} */ (source).floor();
            /** @property {TileCollisionLayer|undefined} - Tile layer driving walkability, if any
             *  @type {TileCollisionLayer|undefined} */
            this.tileLayer = undefined;
        }
        else
        {
            const layer = /** @type {TileCollisionLayer} */ (source);
            ASSERT(layer && isVector2(layer.size) && typeof layer.getCollisionData === 'function',
                'PathFinder requires a Vector2 size or a TileCollisionLayer');
            this.size = layer.size;
            this.tileLayer = layer;
        }

        // Tunables (public, freely re-assignable).
        /** @property {number} - A* heuristic multiplier (1 = admissible, higher = greedier) */
        this.heuristicWeight = 1;
        /** @property {number|undefined} - Most A* expansions before giving up, undefined for the number of cells,
         *  so a search always finishes; a lower one caps the time a search takes, see searchGaveUp
         *  @type {number|undefined} */
        this.maxLoop = undefined;
        /** @property {boolean} - True when the last search stopped at maxLoop with no path, so it gave up rather
         *  than that there is no way through */
        this.searchGaveUp = false;
        /** @property {boolean} - If true, post-process paths with two-pass smoothing */
        this.smoothPath = true;
        /** @property {boolean} - If true, draw debug visualization during findPath */
        this.debug = false;
        /** @property {number} - Debug primitive lifetime in seconds (0 disables drawing) */
        this.debugTime = 1;

        /** @property {Array<PathFinderNode>} - Flat row-major array of size.x*size.y nodes
         *  @type {Array<PathFinderNode>} */
        this.nodes = new Array(this.size.x * this.size.y);
        for (let y = 0; y < this.size.y; ++y)
        for (let x = 0; x < this.size.x; ++x)
            this.nodes[x + y * this.size.x] = new PathFinderNode(x, y);

        // Whether buildNodeData has run, a search without a rebuild builds it the first time.
        /** @private */
        this.nodeDataBuilt = false;

        // Scratch Vector2 reused to avoid allocations in the isWalkable hot path.
        /** @private */
        this.collisionScratch = vec2();

        // The nodes the last search changed, reset before the next one so a
        // search without a rebuild starts as fresh as one after it.
        /** @type {Array<PathFinderNode>}
         *  @private */
        this.searchNodes = [];
    }

    /** Default walkability: if a tile layer was provided, returns true when the
     *  cell has no solid (positive) collision data, so negative data is open
     *  like it is to the engine's collision; otherwise returns true. Override on
     *  the instance or via a subclass.
     *  @param {number} x - Tile x
     *  @param {number} y - Tile y
     *  @return {boolean} */
    isWalkable(x, y)
    {
        if (!this.tileLayer) return true;
        return !(this.tileLayer.getCollisionData(this.collisionScratch.set(x, y)) > 0);
    }

    /** Default extra cost for stepping on a cell. Returns 0 (free) by default.
     *  Override to add cost-weighted terrain (mud, swamp, etc).
     *  @param {number} x - Tile x
     *  @param {number} y - Tile y
     *  @return {number} */
    getCost(x, y)
    {
        return 0;
    }

    /** Get the node at tile coords, or null if out of bounds.
     *  @param {number} x
     *  @param {number} y
     *  @return {PathFinderNode|null} */
    getNode(x, y)
    {
        if (x < 0 || y < 0 || x >= this.size.x || y >= this.size.y) return null;
        return this.nodes[x + y * this.size.x];
    }

    /** Convert a world-space position to integer tile coords (no clamping).
     *  @param {Vector2} worldPos
     *  @return {Vector2} */
    worldToTile(worldPos)
    {
        const ox = this.tileLayer ? this.tileLayer.pos.x : 0;
        const oy = this.tileLayer ? this.tileLayer.pos.y : 0;
        return vec2(floor(worldPos.x - ox), floor(worldPos.y - oy));
    }

    /** Convert integer tile coords to the world-space center of that tile.
     *  @param {number} x
     *  @param {number} y
     *  @return {Vector2} */
    tileToWorld(x, y)
    {
        const ox = this.tileLayer ? this.tileLayer.pos.x : 0;
        const oy = this.tileLayer ? this.tileLayer.pos.y : 0;
        return vec2(x + 0.5 + ox, y + 0.5 + oy);
    }

    /** Reset all nodes and re-populate walkable / cost / posWorld from the
     *  current isWalkable / getCost overrides. Called at the start of
     *  findPath; call it directly before searches made with rebuild=false. */
    buildNodeData()
    {
        this.nodeDataBuilt = true;
        const w = this.size.x;
        const h = this.size.y;
        const ox = this.tileLayer ? this.tileLayer.pos.x : 0;
        const oy = this.tileLayer ? this.tileLayer.pos.y : 0;
        for (let y = 0; y < h; ++y)
        for (let x = 0; x < w; ++x)
        {
            const node = this.nodes[x + y * w];
            node.reset();
            const walkable = !!this.isWalkable(x, y);
            const cost = walkable ? max(0, this.getCost(x, y)) : 0;
            node.walkable = walkable;
            node.cost = cost;
            node.posWorld.set(x + 0.5 + ox, y + 0.5 + oy);

            if (this.debug && this.debugTime > 0)
            {
                if (!walkable)
                    debugRect(node.posWorld, PATHFINDER_TILE_VEC, rgb(1, 0, 0, 0.25), this.debugTime, 0, false, false);
                else if (cost > 0)
                    debugRect(node.posWorld, PATHFINDER_TILE_VEC, rgb(1, 0, 0, min(0.2, cost * 0.05)), this.debugTime, 0, false, false);
            }
        }
    }

    /** Core A* search loop. Expects buildNodeData() to have been called first.
     *  Marks node.parent for path reconstruction. Returns true if endNode was
     *  reached; false on disconnected goal or maxLoop exhaustion, which sets searchGaveUp.
     *  @param {PathFinderNode} startNode
     *  @param {PathFinderNode} endNode
     *  @return {boolean}
     *  @private */
    aStarSearch(startNode, endNode)
    {
        ASSERT(startNode && endNode, 'aStarSearch needs both endpoints');
        ASSERT(startNode !== endNode, 'aStarSearch: start and end must differ — caller should handle trivial case');
        ASSERT(startNode.walkable && endNode.walkable, 'aStarSearch: endpoints must be walkable');

        // Undo what the last search changed, so one without a rebuild starts
        // from the same state; after buildNodeData these are fresh already.
        const searchNodes = this.searchNodes;
        for (const n of searchNodes) n.resetSearch();
        searchNodes.length = 0;
        searchNodes.push(startNode);

        // The open list is a binary heap with the smallest f score on top, so a big map searches quickly.
        // Equal scores go to the node nearer the goal, so open ground is
        // crossed nearly straight instead of widening in a band of ties;
        // the path is just as short, only which of equal paths can change.
        // Scores are sums of diagonals, so equal is within a hair.
        const openList = [];
        const isBetter = (a, b)=> a.f < b.f - 1e-9 || a.f < b.f + 1e-9 && a.h < b.h;
        const siftUp = (node)=>
        {
            // a new node, or one whose score went down, moves up past the ones it now beats
            let i = node.heapIndex;
            while (i)
            {
                const parent = (i - 1) >> 1;
                if (!isBetter(node, openList[parent])) break;
                (openList[i] = openList[parent]).heapIndex = i;
                i = parent;
            }
            (openList[i] = node).heapIndex = i;
        };
        const popBest = ()=>
        {
            // take the top, then the last node sinks down from the top to where it belongs
            const best = openList[0], last = openList.pop();
            if (last !== best)
            {
                let i = 0;
                for (;;)
                {
                    const left = 2*i + 1, right = left + 1;
                    if (left >= openList.length) break;
                    const child = right < openList.length && isBetter(openList[right], openList[left]) ? right : left;
                    if (!isBetter(openList[child], last)) break;
                    (openList[i] = openList[child]).heapIndex = i;
                    i = child;
                }
                (openList[i] = last).heapIndex = i;
            }
            return best;
        };
        startNode.isOpen = true;
        startNode.heapIndex = openList.length;
        siftUp(startNode);
        const maxLoop = this.maxLoop ?? this.size.x * this.size.y;
        let loopCount = 0;
        this.searchGaveUp = false;

        while (openList.length > 0)
        {
            const current = openList[0];
            if (current === endNode) break;
            if (++loopCount > maxLoop)
            {
                // the goal may be found already, waiting its turn, and then the path to it comes back
                this.searchGaveUp = !endNode.parent;
                break;
            }

            // Move current from open to closed.
            popBest();
            current.isOpen = false;
            current.isClosed = true;

            if (this.debug && this.debugTime > 0)
                debugRect(current.posWorld, PATHFINDER_TILE_VEC, rgb(1, 1, 1, 0.05), this.debugTime, 0, false, false);

            // Expand all 8 neighbors.
            for (let dy = -1; dy <= 1; ++dy)
            for (let dx = -1; dx <= 1; ++dx)
            {
                if (dx === 0 && dy === 0) continue;
                const neighbor = this.getNode(current.pos.x + dx, current.pos.y + dy);
                if (!neighbor || !neighbor.walkable || neighbor.isClosed) continue;

                let stepCost = 1;
                if (dx !== 0 && dy !== 0)
                {
                    // Diagonal step: refuse if either cardinal neighbor is
                    // blocked. Prevents cutting through walls at corners.
                    // (Costed-but-walkable cardinals do not block — diagonal
                    // movement around expensive terrain is standard A*.)
                    const card1 = this.getNode(current.pos.x + dx, current.pos.y);
                    if (!card1 || !card1.walkable) continue;
                    const card2 = this.getNode(current.pos.x, current.pos.y + dy);
                    if (!card2 || !card2.walkable) continue;
                    stepCost = PATHFINDER_DIAGONAL_COST;
                }

                const tentativeG = current.g + stepCost + neighbor.cost;
                const wasOpen = neighbor.isOpen;
                if (!wasOpen)
                {
                    neighbor.isOpen = true;
                    neighbor.heapIndex = openList.length;
                    openList.push(neighbor);
                    searchNodes.push(neighbor);
                }
                else if (tentativeG >= neighbor.g)
                {
                    continue;
                }

                // Best path so far through neighbor — record it.
                neighbor.parent = current;
                neighbor.g = tentativeG;
                // Octile heuristic — tightest admissible distance for an
                // 8-connected grid with cardinal cost 1 and diagonal cost √2.
                const adx = abs(endNode.pos.x - neighbor.pos.x);
                const ady = abs(endNode.pos.y - neighbor.pos.y);
                const h = max(adx, ady) + (Math.SQRT2 - 1) * min(adx, ady);
                neighbor.h = h;
                neighbor.f = neighbor.g + h * this.heuristicWeight;
                siftUp(neighbor); // its place in the heap, new or with a lower score now
            }
        }

        return endNode.parent !== null;
    }

    /** Find the clear (walkable, zero-cost) node closest to the given world
     *  position. Spirals outward in expanding boxes until a clear node is
     *  found or the search range is exhausted. Useful for snapping a click
     *  or NPC spawn position to the nearest open tile.
     *
     *  By default, calls `buildNodeData()` first so it works correctly on a
     *  fresh PathFinder. If you're calling it many times in a row with
     *  unchanged walkability, pass `rebuild=false` and call `buildNodeData()`
     *  once externally to avoid redundant work.
     *  @param {Vector2} worldPos
     *  @param {number} [searchRange] - Max box-radius in tiles
     *  @param {boolean} [rebuild] - Whether to call buildNodeData first
     *  @return {PathFinderNode|null} */
    getNearestClearNode(worldPos, searchRange = 10, rebuild = true)
    {
        ASSERT(isVector2(worldPos), 'worldPos must be a Vector2');
        if (rebuild || !this.nodeDataBuilt) this.buildNodeData(); // a grid never built has nothing to walk yet
        return pathFinderNearestNode(this, worldPos, searchRange, (node)=> node.isClear());
    }

    /** Smooth a node path by removing redundant turns and tightening corners
     *  where a grid-aligned diagonal is clear. Modifies the path in place.
     *  Stays on the grid — does not introduce off-tile-center points.
     *  Port of ShortenPath() in pathFinding.cpp.
     *  @param {PathFinderNode[]} path
     *  @private */
    smoothPathCorners(path)
    {
        if (path.length <= 2) return;

        let i = 1;
        while (i < path.length - 1)
        {
            const prev = path[i - 1];
            const node = path[i];
            const next = path[i + 1];

            const dx = next.pos.x - prev.pos.x;
            const dy = next.pos.y - prev.pos.y;
            const lenSq = dx * dx + dy * dy;

            // stepDx,stepDy is the prev-to-node step and stepDxNext,stepDyNext the node-to-next step; the 135°
            // case uses them to tell mostly vertical from mostly horizontal, the straight case to tell a line
            // from a bump
            const stepDx = node.pos.x - prev.pos.x;
            const stepDy = node.pos.y - prev.pos.y;
            const stepDxNext = next.pos.x - node.pos.x;
            const stepDyNext = next.pos.y - node.pos.y;

            if (lenSq === 1)
            {
                // 45° angle — middle node is off the straight line. Drop it.
                if (this.debug && this.debugTime > 0)
                    debugCircle(node.posWorld, 0.3, rgb(0.5, 0, 0.5, 0.5), this.debugTime, false, false);
                path.splice(i, 1);
                i = max(1, i - 1);
                continue;
            }
            else if (lenSq === 2)
            {
                // 90° corner. Check the alternative-diagonal cell.
                if (this.debug && this.debugTime > 0)
                    debugCircle(node.posWorld, 0.3, rgb(1, 0, 0, 0.5), this.debugTime, false, false);

                let sx, sy;
                if (prev.pos.y === node.pos.y && next.pos.x === node.pos.x)
                { sx = prev.pos.x; sy = next.pos.y; }
                else
                { sx = next.pos.x; sy = prev.pos.y; }

                const shortcut = this.getNode(sx, sy);
                if (shortcut && shortcut.isClear())
                {
                    path.splice(i, 1);
                    i = max(1, i - 1);
                    continue;
                }
            }
            else if (lenSq === 5)
            {
                // 135° angle (a knight's-move offset). Try to relocate the
                // middle node to whichever of two candidate cells is closer
                // to prev-of-prev, and only if the corner cut is also clear.
                if (this.debug && this.debugTime > 0)
                    debugCircle(node.posWorld, 0.3, rgb(1, 1, 0, 0.5), this.debugTime, false, false);

                const prevPrev = i >= 2 ? path[i - 2] : prev;
                let s1x, s1y, s2x, s2y;
                if (stepDx === 0 || stepDxNext === 0)
                {
                    // mostly vertical
                    s1x = next.pos.x; s1y = node.pos.y;
                    s2x = prev.pos.x; s2y = node.pos.y;
                }
                else
                {
                    // mostly horizontal
                    s1x = node.pos.x; s1y = next.pos.y;
                    s2x = node.pos.x; s2y = prev.pos.y;
                }
                const dd1x = s1x - prevPrev.pos.x;
                const dd1y = s1y - prevPrev.pos.y;
                const dd2x = s2x - prevPrev.pos.x;
                const dd2y = s2y - prevPrev.pos.y;
                const dist1Sq = dd1x * dd1x + dd1y * dd1y;
                const dist2Sq = dd2x * dd2x + dd2y * dd2y;
                const useFirst = dist1Sq < dist2Sq;
                const sx = useFirst ? s1x : s2x, sy = useFirst ? s1y : s2y;

                const shortcut = this.getNode(sx, sy);
                if (shortcut && shortcut !== node && shortcut.isClear())
                {
                    // Also check the cut-corner cell is clear.
                    const ccx = next.pos.x + s2x - s1x;
                    const ccy = next.pos.y + s2y - s1y;
                    const cutCorner = this.getNode(ccx, ccy);
                    if (cutCorner && cutCorner.isClear())
                    {
                        path[i] = shortcut;
                        i = max(1, i - 1);
                        continue;
                    }
                }
            }
            else if (lenSq === 4 || lenSq === 8)
            {
                // Straight line or a 1-cell bump.
                if (this.debug && this.debugTime > 0)
                    debugCircle(node.posWorld, 0.3, rgb(0, 1, 0, 0.5), this.debugTime, false, false);

                if (stepDx === stepDxNext && stepDy === stepDyNext)
                {
                    // Truly straight — nothing to do, advance.
                    ++i;
                    continue;
                }
                else
                {
                    // Bump — try to flatten via the in-line cell.
                    let sx, sy;
                    if (prev.pos.y === next.pos.y)
                    { sx = node.pos.x; sy = prev.pos.y; }
                    else
                    { sx = prev.pos.x; sy = node.pos.y; }
                    const shortcut = this.getNode(sx, sy);
                    if (shortcut && shortcut.isClear())
                    {
                        path[i] = shortcut;
                        i = max(1, i - 1);
                        continue;
                    }
                }
            }

            ++i;
        }
    }

    /** Smooth a node path via line-of-sight ("string pulling"). Walks the
     *  input path collapsing runs of nodes into straight segments whenever
     *  isLineClear permits, so the result can leave grid centers and cut
     *  cleanly across open spaces.
     *
     *  A node with a cost is kept, and a shortcut only runs between clear
     *  nodes: isLineClear passes only through clear cells, so a straight line
     *  it accepts costs no more than the grid path it replaces.
     *
     *  Replaces the port of ShortenPath2() in pathFinding.cpp, which could
     *  add a segment it had not checked.
     *  @param {PathFinderNode[]} path
     *  @private */
    smoothPathStringPull(path)
    {
        if (path.length <= 2) return;

        // Greedy: from each kept node, jump to the furthest corner with a clear
        // line to it, then on along the straight run past it as far as one is
        // clear, or else the next node. Every segment is one isLineClear
        // accepted or one the path already had, so none can cross a wall.
        // Corners first, so a winding path costs a check per corner and not
        // per cell of it.
        const original = path.slice(), last = original.length - 1;
        const corners = [];
        for (let i = 1; i < last; ++i)
        {
            const a = original[i - 1].pos, b = original[i].pos, c = original[i + 1].pos;
            if ((b.x - a.x) * (c.y - a.y) !== (b.y - a.y) * (c.x - a.x))
                corners.push(i);
        }
        corners.push(last);
        path.length = 0;
        path.push(original[0]);
        for (let k = 0; k < last;)
        {
            let j = k + 1;
            if (original[k].isClear()) // isLineClear needs both ends clear
            {
                const clear = (i)=> original[i].isClear() && this.isLineClear(original[k].pos, original[i].pos);
                let c = corners.length - 1, next = last + 1; // next is the corner past the one found
                while (c >= 0 && corners[c] > k + 1 && !clear(corners[c]))
                    next = corners[c--];
                j = c >= 0 && corners[c] > k + 1 ? corners[c] : k + 1;
                for (let i = next - 1; i > j; --i)
                    if (clear(i)) { j = i; break; }
            }
            path.push(original[j]);
            k = j;
        }
    }

    /** Drop any middle node that lies exactly on the line through its two
     *  neighbors. Backstop for the smoothing passes — the corners pass
     *  intentionally keeps truly-straight runs, and the string-pulling pass
     *  falls back to the next node where no longer line is clear, so it can
     *  leave 3+ collinear nodes in some edge cases.
     *  @param {PathFinderNode[]} path
     *  @private */
    dropCollinearNodes(path)
    {
        // one pass, a node kept only where the way turns from the last one kept
        if (path.length < 3) return;
        let kept = 1;
        for (let i = 1; i < path.length - 1; ++i)
        {
            const a = path[kept - 1], b = path[i], c = path[i + 1];
            if ((b.pos.x - a.pos.x) * (c.pos.y - a.pos.y) !==
                (b.pos.y - a.pos.y) * (c.pos.x - a.pos.x))
                path[kept++] = b;
        }
        path[kept++] = path[path.length - 1];
        path.length = kept;
    }

    /** Lookup helper: true when the node at tile coords (x, y) is in-bounds
     *  and clear (walkable, zero-cost). Used by isLineClear's hot path.
     *  @param {number} x
     *  @param {number} y
     *  @return {boolean}
     *  @private */
    isNodeClear(x, y)
    {
        const n = this.getNode(x, y);
        return n !== null && n.isClear();
    }

    /** Check that the line between two tile-coord endpoints stays entirely
     *  inside walkable, zero-cost cells. Stricter than just sampling along
     *  the line — it also checks the diagonal-corner-adjacent cells so the
     *  line can never "scrape past" a wall corner.
     *
     *  Both endpoints must themselves be clear (asserted in debug). Port of
     *  CheckLine() in pathFinding.cpp.
     *  @param {Vector2} startPos - Tile coords
     *  @param {Vector2} endPos - Tile coords
     *  @return {boolean}
     *  @private */
    isLineClear(startPos, endPos)
    {
        ASSERT(isVector2(startPos) && isVector2(endPos), 'isLineClear needs Vector2 endpoints');
        ASSERT(this.isNodeClear(startPos.x, startPos.y) && this.isNodeClear(endPos.x, endPos.y),
            'isLineClear endpoints must be in-bounds and clear');

        const dx = endPos.x - startPos.x;
        const dy = endPos.y - startPos.y;
        const adx = abs(dx);
        const ady = abs(dy);
        const sx = sign(dx);
        const sy = sign(dy);
        let x = startPos.x;
        let y = startPos.y;

        if (ady === adx)
        {
            // Pure diagonal.
            while (x !== endPos.x)
            {
                if (x !== startPos.x)
                {
                    if (!this.isNodeClear(x, y)) return false;
                    if (!this.isNodeClear(x, y - sy)) return false;
                }
                if (!this.isNodeClear(x, y + sy)) return false;
                x += sx;
                y += sy;
            }
            if (!this.isNodeClear(endPos.x, endPos.y - sy)) return false;
        }
        else if (ady < adx)
        {
            // Mostly horizontal.
            if (dy === 0)
            {
                // Purely horizontal.
                x += sx;
                while (x !== endPos.x)
                {
                    if (!this.isNodeClear(x, y)) return false;
                    x += sx;
                }
            }
            else
            {
                let lastY = startPos.y;
                while (x !== endPos.x)
                {
                    y = startPos.y + Math.trunc((dy * (x - startPos.x)) / dx);
                    if (lastY !== y)
                    {
                        if (!this.isNodeClear(x - sx, y + sy)) return false;
                        if (!this.isNodeClear(x, y - sy)) return false;
                    }
                    lastY = y;
                    if (x !== startPos.x)
                    {
                        if (!this.isNodeClear(x, y)) return false;
                    }
                    y += sy;
                    if (!this.isNodeClear(x, y)) return false;
                    x += sx;
                }
                const finalY = endPos.y - sy;
                if (!this.isNodeClear(endPos.x, finalY)) return false;
            }
        }
        else
        {
            // Mostly vertical.
            if (dx === 0)
            {
                y += sy;
                while (y !== endPos.y)
                {
                    if (!this.isNodeClear(x, y)) return false;
                    y += sy;
                }
            }
            else
            {
                let lastX = startPos.x;
                while (y !== endPos.y)
                {
                    x = startPos.x + Math.trunc((dx * (y - startPos.y)) / dy);
                    if (lastX !== x)
                    {
                        if (!this.isNodeClear(x + sx, y - sy)) return false;
                        if (!this.isNodeClear(x - sx, y)) return false;
                    }
                    lastX = x;
                    if (y !== startPos.y)
                    {
                        if (!this.isNodeClear(x, y)) return false;
                    }
                    x += sx;
                    if (!this.isNodeClear(x, y)) return false;
                    y += sy;
                }
                const finalX = endPos.x - sx;
                if (!this.isNodeClear(finalX, endPos.y)) return false;
            }
        }
        return true;
    }

    /** Find a path from startPos to endPos in world space. Returns an array
     *  of world-space Vector2 points; empty array if no path exists.
     *
     *  Start and end are snapped to the nearest walkable tile (a costed one
     *  counts), within 10 tiles. Intermediate points are tile centers unless the
     *  string-pulling smoothing pass moves them off-grid.
     *
     *  By default, calls `buildNodeData()` first, which asks isWalkable and
     *  getCost about every cell. When finding many paths with unchanged
     *  walkability, pass `rebuild=false` and call `buildNodeData()` once
     *  externally; the paths found are the same.
     *  @param {Vector2} startPos - World-space start
     *  @param {Vector2} endPos - World-space end
     *  @param {boolean} [rebuild] - Whether to call buildNodeData first
     *  @return {Vector2[]} */
    findPath(startPos, endPos, rebuild = true)
    {
        ASSERT(isVector2(startPos) && isVector2(endPos), 'findPath needs Vector2 endpoints');

        this.searchGaveUp = false;
        if (rebuild || !this.nodeDataBuilt) this.buildNodeData(); // a grid never built has nothing to walk yet

        // rebuild=false because we just built — avoid redundant work per snap.
        // the ends go to the nearest cell that can be walked, whatever it costs to cross
        const walkable = (node)=> node.walkable;
        const startNode = pathFinderNearestNode(this, startPos, 10, walkable);
        const endNode = pathFinderNearestNode(this, endPos, 10, walkable);
        if (!startNode || !endNode) return [];

        // Trivial case: start and end snapped to the same tile.
        if (startNode === endNode) return [startNode.posWorld.copy()];

        if (!this.aStarSearch(startNode, endNode)) return [];

        // Walk back from endNode via parent pointers, then reverse — cheaper
        // than unshifting on every step.
        const nodePath = [];
        for (let n = endNode; n; n = n.parent)
            nodePath.push(n);
        nodePath.reverse();

        if (this.smoothPath)
        {
            this.smoothPathCorners(nodePath);
            this.smoothPathStringPull(nodePath);
            this.dropCollinearNodes(nodePath);
        }

        // Convert to world-space Vector2 path. Return copies, not live node
        // references — callers shouldn't be able to mutate the grid.
        const result = nodePath.map(n => n.posWorld.copy());

        if (this.debug && this.debugTime > 0 && result.length > 0)
        {
            for (let i = 1; i < result.length; ++i)
                debugLine(result[i - 1], result[i], RED, 0.1, this.debugTime, false);
            for (const p of result)
                debugCircle(p, 0.5, rgb(1, 0, 0, 0.3), this.debugTime, false, false);
            debugCircle(result[0], 0.5, rgb(0, 1, 0, 0.5), this.debugTime, false, false);
            debugCircle(result[result.length - 1], 0.5, rgb(0, 1, 0, 0.5), this.debugTime, false, false);
        }

        return result;
    }
}

// the node nearest a world position that passes a test, within a range of tiles, or null: the rings of cells around
// the position are searched outward until the next ring cannot hold anything nearer than the best found, since the
// best of one ring is not always the nearest, a cell one ring out can be closer
function pathFinderNearestNode(finder, worldPos, searchRange, test)
{
    const center = finder.worldToTile(worldPos);
    const centerX = center.x, centerY = center.y;

    let nearest = null, nearestDistSq = 0;
    for (let offset = 0; offset <= searchRange; ++offset)
    {
        // every cell of this ring is more than offset - .5 away along one axis
        const bound = max(0, offset - .5);
        if (nearest && bound * bound >= nearestDistSq) break;

        for (let dy = -offset; dy <= offset; ++dy)
        for (let dx = -offset; dx <= offset; ++dx)
        {
            // only the ring itself, the inside was searched already
            if (offset > 0 && abs(dx) !== offset && abs(dy) !== offset)
                continue;

            const node = finder.getNode(centerX + dx, centerY + dy);
            if (!node || !test(node)) continue;

            const ddx = node.posWorld.x - worldPos.x;
            const ddy = node.posWorld.y - worldPos.y;
            const distSq = ddx * ddx + ddy * ddy;
            if (!nearest || distSq < nearestDistSq)
            {
                nearest = node;
                nearestDistSq = distSq;
            }
        }
    }
    return nearest;
}

/**
 * LittleJS 3D Math Plugin
 * - Vector3 and Matrix4 for 3D games and plugins
 * - Right handed, Y up, angles in radians
 * - Used by the Render3D plugin, but has no rendering dependencies
 * @namespace Math3D
 */

///////////////////////////////////////////////////////////////////////////////

/**
 * Create a 3D vector, can take 0, 1, 2 or 3 numbers
 * - vec3() is zero, vec3(s) fills all three, vec3(x, y) sets z to 0
 * @param {number} [x]
 * @param {number} [y]
 * @param {number} [z]
 * @return {Vector3}
 * @memberof Math3D
 */
function vec3(x=0, y, z)
{
    return y === undefined ? new Vector3(x, x, x) : new Vector3(x, y, z === undefined ? 0 : z);
}

/**
 * Check if the object is a valid Vector3
 * @param {any} v
 * @return {boolean}
 * @memberof Math3D
 */
function isVector3(v) { return v instanceof Vector3 && v.isValid(); }

// debug check that a value is a usable Vector3, stripped in release like the 2D one
function ASSERT_VECTOR3_VALID(v) { ASSERT(isVector3(v), 'Vector3 is invalid.', v); }

/**
 * Returns a random Vector3 of a given length, pointing any direction evenly, or within a cone around +Y
 * @param {number} [length]
 * @param {number} [coneAngle] - Half angle of the cone around +Y in radians, PI is every direction
 * @return {Vector3}
 * @memberof Math3D
 */
function randVector3(length=1, coneAngle=PI)
{
    // a random height on the sphere is uniform over its surface, then a random turn around Y
    const y = rand(cos(coneAngle), 1), s = (1 - y * y) ** .5, a = rand(2 * PI);
    return new Vector3(s * cos(a) * length, y * length, s * sin(a) * length);
}

/**
 * Returns a random Vector3 inside a sphere, spread evenly through its volume, the 3D twin of randInCircle
 * @param {number} [radius]
 * @param {number} [minRadius] - Leave a hollow middle this big
 * @return {Vector3}
 * @memberof Math3D
 */
function randInSphere(radius=1, minRadius=0)
{
    // the volume inside a radius grows with its cube, so that is what has to come out even
    if (radius <= 0) return new Vector3;
    const ratio = clamp(minRadius / radius);
    return randVector3(radius * rand(ratio**3, 1) ** (1/3));
}

/**
 * 3D Vector object, right handed with Y up
 * - Methods return new vectors except set and setFrom
 * @memberof Math3D
 * @example
 * const a = vec3(1, 2, 3);
 * const b = a.add(vec3(0, 1, 0)).normalize();
 */
class Vector3
{
    /** Create a 3D vector
     *  @param {number} [x]
     *  @param {number} [y]
     *  @param {number} [z] */
    constructor(x=0, y=0, z=0)
    {
        ASSERT(isNumber(x) && isNumber(y) && isNumber(z), 'Vector3 components must be numbers');
        /** @property {number} - X axis location */
        this.x = x;
        /** @property {number} - Y axis location */
        this.y = y;
        /** @property {number} - Z axis location */
        this.z = z;
    }

    /** Sets values of this vector and returns self
     *  @param {number} [x]
     *  @param {number} [y]
     *  @param {number} [z]
     *  @return {Vector3} */
    set(x=0, y=0, z=0) { this.x = x; this.y = y; this.z = z; ASSERT_VECTOR3_VALID(this); return this; }

    /** Copies the values of another vector into this one and returns self
     *  @param {Vector3} v
     *  @return {Vector3} */
    setFrom(v) { return this.set(v.x, v.y, v.z); }

    /** Returns a new vector that is a copy of this
     *  @return {Vector3} */
    copy() { return new Vector3(this.x, this.y, this.z); }

    /** Returns a copy of this vector plus the vector passed in
     *  @param {Vector3} v
     *  @return {Vector3} */
    add(v) { return new Vector3(this.x + v.x, this.y + v.y, this.z + v.z); }

    /** Returns a copy of this vector minus the vector passed in
     *  @param {Vector3} v
     *  @return {Vector3} */
    subtract(v) { return new Vector3(this.x - v.x, this.y - v.y, this.z - v.z); }

    /** Returns a copy of this vector times the vector passed in
     *  @param {Vector3} v
     *  @return {Vector3} */
    multiply(v) { return new Vector3(this.x * v.x, this.y * v.y, this.z * v.z); }

    /** Returns a copy of this vector divided by the vector passed in
     *  @param {Vector3} v
     *  @return {Vector3} */
    divide(v) { return new Vector3(this.x / v.x, this.y / v.y, this.z / v.z); }

    /** Returns a copy of this vector scaled by the number passed in
     *  @param {number} s
     *  @return {Vector3} */
    scale(s) { return new Vector3(this.x * s, this.y * s, this.z * s); }

    /** Returns the length of this vector
     *  @return {number} */
    length() { return this.lengthSquared()**.5; }

    /** Returns the length of this vector squared
     *  @return {number} */
    lengthSquared() { return this.x**2 + this.y**2 + this.z**2; }

    /** Returns a copy of this vector reflected by a surface normal
     *  @param {Vector3} normal - Surface normal, should be normalized
     *  @param {number} [restitution] - How much to bounce, 1 is a perfect bounce, 0 slides along the surface
     *  @return {Vector3} */
    reflect(normal, restitution=1) { return this.subtract(normal.scale((1 + restitution) * this.dot(normal))); }

    /** Returns the distance from this vector to the vector passed in
     *  @param {Vector3} v
     *  @return {number} */
    distance(v) { return this.distanceSquared(v)**.5; }

    /** Returns the distance squared from this vector to the vector passed in
     *  @param {Vector3} v
     *  @return {number} */
    distanceSquared(v) { return (this.x - v.x)**2 + (this.y - v.y)**2 + (this.z - v.z)**2; }

    /** Returns a new vector in the same direction with the length passed in, zero stays zero
     *  @param {number} [length]
     *  @return {Vector3} */
    normalize(length=1)
    {
        const l = this.length();
        return l ? this.scale(length/l) : new Vector3;
    }

    /** Returns a new vector clamped to the length passed in
     *  @param {number} [length]
     *  @return {Vector3} */
    clampLength(length=1)
    {
        const l = this.length();
        return l > length ? this.scale(length/l) : this.copy();
    }

    /** Returns the dot product of this vector and the vector passed in
     *  @param {Vector3} v
     *  @return {number} */
    dot(v) { return this.x*v.x + this.y*v.y + this.z*v.z; }

    /** Returns a vector at right angles to both this and the one passed in
     *  @param {Vector3} v
     *  @return {Vector3} */
    cross(v)
    {
        return new Vector3(
            this.y*v.z - this.z*v.y,
            this.z*v.x - this.x*v.z,
            this.x*v.y - this.y*v.x);
    }

    /** Returns a new vector interpolated between this and the vector passed in, percent is clamped to 0-1
     *  @param {Vector3} v
     *  @param {number} percent
     *  @return {Vector3} */
    lerp(v, percent)
    {
        ASSERT_VECTOR3_VALID(v);
        return this.add(v.subtract(this).scale(clamp(percent)));
    }

    /** Returns a new vector turned around an axis, counter clockwise when the axis points at you
     *  @param {Vector3} axis - Unit length
     *  @param {number} angle - Radians
     *  @return {Vector3} */
    rotate(axis, angle)
    {
        ASSERT_VECTOR3_VALID(axis); // unlike Vector2.rotate this takes an axis first
        // Rodrigues' formula: the part along the axis stays, the rest turns
        const c = cos(angle), s = sin(angle), d = axis.dot(this) * (1 - c);
        return this.scale(c).add(axis.cross(this).scale(s)).add(axis.scale(d));
    }

    /** Returns a new vector turned around the X axis, the way a positive pitch in rotation3D turns things
     *  @param {number} angle - Radians
     *  @return {Vector3} */
    rotateX(angle)
    {
        const c = cos(angle), s = sin(angle);
        return new Vector3(this.x, this.y*c - this.z*s, this.y*s + this.z*c);
    }

    /** Returns a new vector turned around the Y axis, the way a positive yaw in rotation3D turns things
     *  @param {number} angle - Radians
     *  @return {Vector3} */
    rotateY(angle)
    {
        const c = cos(angle), s = sin(angle);
        return new Vector3(this.x*c + this.z*s, this.y, this.z*c - this.x*s);
    }

    /** Returns a new vector turned around the Z axis, the way a positive roll in rotation3D turns things
     *  @param {number} angle - Radians
     *  @return {Vector3} */
    rotateZ(angle)
    {
        const c = cos(angle), s = sin(angle);
        return new Vector3(this.x*c - this.y*s, this.x*s + this.y*c, this.z);
    }

    /** Returns a new vector with the absolute value of each component
     *  @return {Vector3} */
    abs() { return new Vector3(abs(this.x), abs(this.y), abs(this.z)); }

    /** Returns a new vector with each component floored
     *  @return {Vector3} */
    floor() { return new Vector3(floor(this.x), floor(this.y), floor(this.z)); }

    /** Returns a new vector with each component rounded
     *  @return {Vector3} */
    round() { return new Vector3(round(this.x), round(this.y), round(this.z)); }

    /** Returns a new vector snapped down to a grid, grid is the number of steps per unit like Vector2.snap
     *  @param {number} grid - Snap steps per unit, 2 snaps to halves
     *  @return {Vector3} */
    snap(grid)
    {
        ASSERT_NUMBER_VALID(grid);
        return new Vector3(floor(this.x*grid)/grid, floor(this.y*grid)/grid, floor(this.z*grid)/grid);
    }

    /** Returns this point transformed by a matrix, translation included
     *  @param {Matrix4} matrix
     *  @return {Vector3} */
    transform(matrix) { return matrix.transformPoint(this); }

    /** Returns this direction transformed by a matrix, rotation and scale only
     *  @param {Matrix4} matrix
     *  @return {Vector3} */
    transformDirection(matrix) { return matrix.transformDirection(this); }

    /** Checks if this is a valid vector
     *  @return {boolean} */
    isValid() { return isNumber(this.x) && isNumber(this.y) && isNumber(this.z); }

    /** Returns a string representation of this vector for debugging
     *  @param {number} [digits] - Number of digits to display
     *  @return {string} */
    toString(digits=3)
    {
        if (!this.isValid())
            return `(${this.x},${this.y},${this.z})`; // show the bad values instead of throwing
        const f = (v)=> (v < 0 ? '' : ' ') + v.toFixed(digits);
        return `(${f(this.x)},${f(this.y)},${f(this.z)} )`;
    }
}

///////////////////////////////////////////////////////////////////////////////

// scratch for multiply, nothing keeps a reference to it
const matrix4Scratch = new Float32Array(16);

/**
 * 4x4 transform matrix for moving, rotating and scaling points in 3D
 * - Static builders like Matrix4.translation return a new matrix
 * - Methods on a matrix change it in place and return it, so calls can chain
 * - a.multiply(b) means b happens first, then a
 * - Stored the way WebGL wants it, so it can be sent to a shader as is
 * @memberof Math3D
 * @example
 * const m = buildMatrix(vec3(0, 1, 0), vec3(0, PI/2, 0)); // rotate then move up
 * const p = m.transformPoint(vec3(1, 0, 0));
 */
class Matrix4
{
    /** Create a matrix, identity by default
     *  @param {Float32Array|Array<number>} [m] - 16 column major values */
    constructor(m)
    {
        /** @property {Float32Array} - The 16 column major values */
        this.m = new Float32Array(16);
        ASSERT(!m || m.length == 16, 'Matrix4 takes 16 values, use copy() to duplicate a matrix');
        if (m)
            this.m.set(m);
        else
            this.m[0] = this.m[5] = this.m[10] = this.m[15] = 1;
    }

    /** Returns a new identity matrix
     *  @return {Matrix4} */
    static identity() { return new Matrix4; }

    /** Returns a new translation matrix
     *  @param {Vector3} v
     *  @return {Matrix4} */
    static translation(v)
    {
        ASSERT_VECTOR3_VALID(v);
        const r = new Matrix4;
        r.m[12] = v.x; r.m[13] = v.y; r.m[14] = v.z;
        return r;
    }

    /** Returns a rotation matrix, rolled first, then pitched, then yawed
     *  @param {Vector3} euler - vec3(pitch, yaw, roll) in radians
     *  @param {Matrix4} [matrix] - Written into instead of a new one, for a loop that builds many
     *  @return {Matrix4} */
    static rotation(euler, matrix=new Matrix4)
    {
        ASSERT_VECTOR3_VALID(euler);
        matrix4RotationAt(matrix.m, 0, euler);
        return matrix;
    }

    /** Returns a new scale matrix
     *  @param {Vector3} v
     *  @return {Matrix4} */
    static scaling(v)
    {
        ASSERT_VECTOR3_VALID(v);
        const r = new Matrix4;
        r.m[0] = v.x; r.m[5] = v.y; r.m[10] = v.z;
        return r;
    }

    /** Returns a new perspective projection, camera looks down -Z
     *  @param {number} fov - Vertical field of view in radians
     *  @param {number} aspect - Width divided by height
     *  @param {number} near - Closest visible distance
     *  @param {number} far - Furthest visible distance, Infinity is allowed
     *  @return {Matrix4} */
    static perspective(fov, aspect, near, far)
    {
        ASSERT(near > 0 && far > near, 'a perspective projection needs 0 < near < far, or nothing is visible', near, far);
        const f = 1 / tan(fov/2);
        const r = new Matrix4;
        const m = r.m;
        m[0] = f / aspect;
        m[5] = f;
        m[10] = far == Infinity ? -1 : (far + near) / (near - far); // the infinite case is the limit of the formula
        m[11] = -1;
        m[14] = far == Infinity ? -2 * near : 2 * far * near / (near - far);
        m[15] = 0;
        return r;
    }

    /** Returns a new orthographic projection, camera looks down -Z
     *  @param {number} left - Edge of the visible box
     *  @param {number} right - Edge of the visible box
     *  @param {number} bottom - Edge of the visible box
     *  @param {number} top - Edge of the visible box
     *  @param {number} near - Closest visible distance
     *  @param {number} far - Furthest visible distance, Infinity is not allowed here
     *  @return {Matrix4} */
    static orthographic(left, right, bottom, top, near, far)
    {
        // an infinite far plane has no orthographic form: every depth would land on the near plane,
        // and the formula below works out to NaN, which quietly clips the whole scene away
        ASSERT(far > near && far != Infinity, 'an orthographic projection needs a real far plane past near, Infinity is perspective only', near, far);
        const r = new Matrix4;
        const m = r.m;
        m[0]  = 2 / (right - left);
        m[5]  = 2 / (top - bottom);
        m[10] = -2 / (far - near);
        m[12] = -(right + left) / (right - left);
        m[13] = -(top + bottom) / (top - bottom);
        m[14] = -(far + near) / (far - near);
        return r;
    }

    /** Returns the transform of something at eye turned to face target
     *  - Invert it to get a view matrix for a camera there
     *  @param {Vector3} eye
     *  @param {Vector3} target
     *  @param {Vector3} [up]
     *  @return {Matrix4} */
    static lookAt(eye, target, up=vec3(0, 1, 0))
    {
        let z = eye.subtract(target).normalize();
        if (!z.lengthSquared())
            z = vec3(0, 0, 1); // eye is on the target, face -Z
        let x = up.cross(z).normalize();
        // up is along the view direction, pick another; looking straight down or up keeps +X as the right axis,
        // as three.js does and as a view tilting there from the +Z side ends up
        if (!x.lengthSquared())
            x = (abs(z.y) > .99 ? vec3(0, 0, z.y > 0 ? -1 : 1) : vec3(0, 1, 0)).cross(z).normalize();
        const y = z.cross(x);
        return new Matrix4([x.x, x.y, x.z, 0,  y.x, y.y, y.z, 0,  z.x, z.y, z.z, 0,  eye.x, eye.y, eye.z, 1]);
    }

    /** Returns a new matrix that is a copy of this
     *  @return {Matrix4} */
    copy() { return new Matrix4(this.m); }

    /** Multiply this matrix by another and return this, the other happens first
     *  @param {Matrix4} matrix
     *  @return {Matrix4} */
    multiply(matrix)
    {
        const a = this.m, b = matrix.m, r = matrix4Scratch;
        for (let j = 0; j < 4; ++j)
        for (let i = 0; i < 4; ++i)
            r[j*4 + i] = a[i]*b[j*4] + a[4 + i]*b[j*4 + 1] + a[8 + i]*b[j*4 + 2] + a[12 + i]*b[j*4 + 3];
        this.m.set(r);
        return this;
    }

    /** Append a translation, returns self
     *  @param {Vector3} v
     *  @return {Matrix4} */
    translate(v) { return this.multiply(Matrix4.translation(v)); }

    /** Append a rotation, returns self
     *  @param {Vector3} euler - vec3(pitch, yaw, roll) in radians
     *  @return {Matrix4} */
    rotate(euler) { return this.multiply(Matrix4.rotation(euler)); }

    /** Append a scale, returns self
     *  @param {Vector3} v
     *  @return {Matrix4} */
    scale(v) { return this.multiply(Matrix4.scaling(v)); }

    /** Transpose this matrix in place, returns self
     *  @return {Matrix4} */
    transpose()
    {
        const m = this.m;
        for (let i = 0; i < 4; ++i)
        for (let j = i + 1; j < 4; ++j)
        {
            const t = m[i*4 + j];
            m[i*4 + j] = m[j*4 + i];
            m[j*4 + i] = t;
        }
        return this;
    }

    /** Flip this matrix so it undoes itself, returns this and does nothing if it cannot be inverted
     *  @return {Matrix4} */
    invert()
    {
        const m = this.m;
        const [a00, a01, a02, a03, a10, a11, a12, a13, a20, a21, a22, a23, a30, a31, a32, a33] = m;
        const b00 = a00*a11 - a01*a10, b01 = a00*a12 - a02*a10, b02 = a00*a13 - a03*a10;
        const b03 = a01*a12 - a02*a11, b04 = a01*a13 - a03*a11, b05 = a02*a13 - a03*a12;
        const b06 = a20*a31 - a21*a30, b07 = a20*a32 - a22*a30, b08 = a20*a33 - a23*a30;
        const b09 = a21*a32 - a22*a31, b10 = a21*a33 - a23*a31, b11 = a22*a33 - a23*a32;
        let det = b00*b11 - b01*b10 + b02*b09 + b03*b08 - b04*b07 + b05*b06;
        if (!det)
            return this;
        det = 1 / det;
        m[0]  = (a11*b11 - a12*b10 + a13*b09) * det;
        m[1]  = (a02*b10 - a01*b11 - a03*b09) * det;
        m[2]  = (a31*b05 - a32*b04 + a33*b03) * det;
        m[3]  = (a22*b04 - a21*b05 - a23*b03) * det;
        m[4]  = (a12*b08 - a10*b11 - a13*b07) * det;
        m[5]  = (a00*b11 - a02*b08 + a03*b07) * det;
        m[6]  = (a32*b02 - a30*b05 - a33*b01) * det;
        m[7]  = (a20*b05 - a22*b02 + a23*b01) * det;
        m[8]  = (a10*b10 - a11*b08 + a13*b06) * det;
        m[9]  = (a01*b08 - a00*b10 - a03*b06) * det;
        m[10] = (a30*b04 - a31*b02 + a33*b00) * det;
        m[11] = (a21*b02 - a20*b04 - a23*b00) * det;
        m[12] = (a11*b07 - a10*b09 - a12*b06) * det;
        m[13] = (a00*b09 - a01*b07 + a02*b06) * det;
        m[14] = (a31*b01 - a30*b03 - a32*b00) * det;
        m[15] = (a20*b03 - a21*b01 + a22*b00) * det;
        return this;
    }

    /** Transform a point, translation included
     *  @param {Vector3} v
     *  @return {Vector3} */
    transformPoint(v)
    {
        const m = this.m;
        return new Vector3(
            m[0]*v.x + m[4]*v.y + m[8]*v.z  + m[12],
            m[1]*v.x + m[5]*v.y + m[9]*v.z  + m[13],
            m[2]*v.x + m[6]*v.y + m[10]*v.z + m[14]);
    }

    /** Transform a direction, rotation and scale only
     *  @param {Vector3} v
     *  @return {Vector3} */
    transformDirection(v)
    {
        const m = this.m;
        return new Vector3(
            m[0]*v.x + m[4]*v.y + m[8]*v.z,
            m[1]*v.x + m[5]*v.y + m[9]*v.z,
            m[2]*v.x + m[6]*v.y + m[10]*v.z);
    }

    /** Returns the translation part of this matrix
     *  @return {Vector3} */
    getTranslation() { return new Vector3(this.m[12], this.m[13], this.m[14]); }

    /** Returns the determinant of the rotation and scale part: negative when the matrix mirrors, 0 when it flattens a
     *  shape and has no inverse
     *  @return {number} */
    determinant()
    {
        const m = this.m;
        return m[0]*(m[5]*m[10] - m[6]*m[9]) - m[4]*(m[1]*m[10] - m[2]*m[9]) + m[8]*(m[1]*m[6] - m[2]*m[5]);
    }

    /** Returns the scale part of this matrix, the length of each axis; a mirroring matrix shows as a negative x
     *  @return {Vector3} */
    getScale()
    {
        const m = this.m;
        const x = hypot(m[0], m[1], m[2]), y = hypot(m[4], m[5], m[6]), z = hypot(m[8], m[9], m[10]);
        return new Vector3(this.determinant() < 0 ? -x : x, y, z);
    }

    /** Returns the rotation part of this matrix as vec3(pitch, yaw, roll), the angles Matrix4.rotation builds it from
     *  - The scale is divided out first, so it works on a full transform
     *  - A matrix with shear, from a scaled parent with a turned child, has no exact answer and gets the nearest
     *  @return {Vector3} */
    getRotation()
    {
        // the axes at unit length, see Matrix4.rotation for which element is which
        const m = this.m, s = this.getScale();
        const sx = s.x || 1, sy = s.y || 1, sz = s.z || 1;
        const m1 = m[1] / sx, m5 = m[5] / sy, m8 = m[8] / sz, m9 = m[9] / sz, m10 = m[10] / sz;
        const pitch = Math.asin(clamp(-m9, -1, 1));
        if (abs(m9) < 1 - 1e-6)
            return new Vector3(pitch, atan2(m8, m10), atan2(m1, m5));
        // straight up or down: yaw and roll turn about the same axis, so the roll is zero and yaw takes it all
        return new Vector3(pitch, atan2(m[4] / sy * -m9, m[0] / sx), 0);
    }

    /** Returns a string representation of this matrix for debugging
     *  @return {string} */
    toString()
    {
        const m = this.m, f = (i)=> m[i].toFixed(2).padStart(7);
        let s = '';
        for (let row = 0; row < 4; ++row)
            s += `[${f(row)} ${f(4 + row)} ${f(8 + row)} ${f(12 + row)} ]\n`;
        return s;
    }
}

