            y += w * (m[1]*px + m[5]*py + m[9]*pz + m[13]);
            z += w * (m[2]*px + m[6]*py + m[10]*pz + m[14]);
            nx += w * (n[0]*qx + n[4]*qy + n[8]*qz);
            ny += w * (n[1]*qx + n[5]*qy + n[9]*qz);
